contracts/PrivateAirdrop.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZkIdentity {
    function registerScope(uint256 scope) external;
    function verify(uint256 root, uint256 nullifier, uint256 scope, uint256 signalHash, uint256 minLevel, uint256[8] calldata proof)
        external view returns (bool);
}

/// @title PrivateAirdrop: one claim per person, to an address that is not linked to the person (testnet)
/// @notice docs/future/zk-identity.md. Pays `amount` (native coin) once per nullifier of `scope` to the recipient the
///   proof is bound to. The signal is keccak256(recipient, fee) >> 8, so whoever submits the transaction (the person
///   from a fresh address, or any relayer who is paid `fee`) cannot change where the coins go.
///   Uniqueness is the registry's: one claim per registered identity of level >= minLevel.
contract PrivateAirdrop {
    IZkIdentity public immutable registry;
    uint256 public immutable scope;
    uint256 public immutable minLevel;
    uint256 public immutable amount;
    mapping(uint256 => bool) public nullifierUsed;
    uint256 public claims;

    event Claimed(uint256 indexed nullifier, address indexed recipient, address relayer, uint256 fee);
    event Funded(address from, uint256 value);

    error AlreadyClaimed();
    error BadProof();
    error BadFee();
    error Empty();
    error PayFailed();

    constructor(IZkIdentity registry_, uint256 scope_, uint256 minLevel_, uint256 amount_) payable {
        registry = registry_;
        scope = scope_;
        minLevel = minLevel_;
        amount = amount_;
        registry_.registerScope(scope_);
    }

    receive() external payable {
        emit Funded(msg.sender, msg.value);
    }

    /// The signal a claim's proof must carry.
    function signalOf(address recipient, uint256 fee) public pure returns (uint256) {
        return uint256(keccak256(abi.encode(recipient, fee))) >> 8;
    }

    function claim(address recipient, uint256 fee, uint256 root, uint256 nullifier, uint256[8] calldata proof) external {
        if (nullifierUsed[nullifier]) revert AlreadyClaimed();
        if (fee > amount) revert BadFee();
        if (address(this).balance < amount) revert Empty();
        if (!registry.verify(root, nullifier, scope, signalOf(recipient, fee), minLevel, proof)) revert BadProof();
        nullifierUsed[nullifier] = true;
        claims++;
        emit Claimed(nullifier, recipient, msg.sender, fee);
        (bool ok, ) = recipient.call{value: amount - fee}("");
        if (!ok) revert PayFailed();
        if (fee != 0) {
            (ok, ) = msg.sender.call{value: fee}("");
            if (!ok) revert PayFailed();
        }
    }
}

contracts/PrivatePoll.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IZkIdentityPoll {
    function registerScope(uint256 scope) external;
    function verify(uint256 root, uint256 nullifier, uint256 scope, uint256 signalHash, uint256 minLevel, uint256[8] calldata proof)
        external view returns (bool);
}

/// @title PrivatePoll: one anonymous vote per person per poll (testnet)
/// @notice docs/future/zk-identity.md. Each poll is a scope of ZkIdentityRegistry (chosen by its creator, unique in the
///   registry). A vote carries a proof bound to (scope, option), so a relayer cannot change the choice; the nullifier
///   refuses a second vote by the same identity, and is unrelated to the same person's nullifiers in other polls.
///   Tallies are public as votes come in (no hiding of partial results; see the doc for commit-reveal / MACI).
contract PrivatePoll {
    IZkIdentityPoll public immutable registry;

    struct Poll {
        address creator;
        uint8 options;
        uint8 minLevel;
        uint64 endsAt;
        bytes32 question; // hash of the question text (kept off chain)
    }

    mapping(uint256 => Poll) public polls;
    mapping(uint256 => mapping(uint256 => uint256)) public tally;   // scope => option => votes
    mapping(uint256 => mapping(uint256 => bool)) public nullifierUsed; // scope => nullifier => voted

    event PollCreated(uint256 indexed scope, address indexed creator, bytes32 question, uint8 options, uint8 minLevel, uint64 endsAt);
    event Voted(uint256 indexed scope, uint256 indexed nullifier, uint8 option);

    error BadPoll();
    error NoPoll();
    error Ended();
    error BadOption();
    error AlreadyVoted();
    error BadProof();

    constructor(IZkIdentityPoll registry_) {
        registry = registry_;
    }

    function createPoll(uint256 scope, bytes32 question, uint8 options, uint8 minLevel, uint64 endsAt) external {
        if (options < 2 || minLevel == 0 || endsAt <= block.timestamp) revert BadPoll();
        registry.registerScope(scope); // reverts if the scope is taken
        polls[scope] = Poll({creator: msg.sender, options: options, minLevel: minLevel, endsAt: endsAt, question: question});
        emit PollCreated(scope, msg.sender, question, options, minLevel, endsAt);
    }

    function signalOf(uint256 scope, uint8 option) public pure returns (uint256) {
        return uint256(keccak256(abi.encode(scope, option))) >> 8;
    }

    function vote(uint256 scope, uint8 option, uint256 root, uint256 nullifier, uint256[8] calldata proof) external {
        Poll storage p = polls[scope];
        if (p.creator == address(0)) revert NoPoll();
        if (block.timestamp > p.endsAt) revert Ended();
        if (option >= p.options) revert BadOption();
        if (nullifierUsed[scope][nullifier]) revert AlreadyVoted();
        if (!registry.verify(root, nullifier, scope, signalOf(scope, option), p.minLevel, proof)) revert BadProof();
        nullifierUsed[scope][nullifier] = true;
        tally[scope][option]++;
        emit Voted(scope, nullifier, option);
    }
}

contracts/ProofRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// NeuroJobs' runner record (the bar AuditRunners uses).
interface IPRJobs {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

interface IPRReputation {
    function record(address worker, uint8 kind, bytes32 ref) external;
}

/// AuditCertificate.certificate (AuditCertificate.Cert, same layout). Read only.
interface IPRCertificate {
    struct Cert {
        uint256 requestId;
        uint64 chainId;
        address target;
        bytes32 codeHash;
        bytes32 reportHash;
        bytes32 sourceHash;
        uint8 level;
        uint16 auditors;
        uint16 mutationBps;
        uint64 issuedAt;
        uint64 expiresAt;
        uint64 revokedAt;
        uint256 revokedBy;
    }

    function certificate(uint64 chainId, address target) external view returns (Cert memory c, bool valid);
}

/// A bounty's replay contract: deploys the bountied code afresh, replays `counterexample` (its own
/// encoding, published with the spec) and evaluates property number `property` of the spec.
/// True only when the property is violated. It may change state only inside a call that reverts.
interface IPropertyChecker {
    function replay(bytes32 codeHash, bytes32 specHash, uint32 property, bytes calldata counterexample) external returns (bool violated);
}

/// @title ProofRegistry: the "Proven" level and the proof market (SS6 / A3 / S9)
/// @notice Records, per code hash, that an approved spec (its hash) was PROVEN for that code: the
///         proof artifacts (generated Halmos / forge / SMTChecker files, by hash), the tool versions and
///         a reproducibility recipe (`node audit/spec/cli.js prove <spec>` with the pinned tools of
///         audit/tools/install.sh). A proof counts only when at least 2 of 3 bonded NeuroJobs runners
///         reproduced it and revealed the SAME outcome with every property proven
///             outcome = (resultHash, proven, counterexamples, unknown)
///             commitment = keccak256("zetaphy.proof.run", keccak256(abi.encode(outcome)), runner, salt, proofId)
///         (AuditRunners' commit-reveal and 2-of-3 rule). "Not installed", a timeout or an unknown
///         result is never "proven": a single one rejects the proof.
///
///         Submitting is commit-then-submit (the commitment, from an earlier block, binds the
///         artifacts to the prover), so nobody can copy a published proof and claim it first.
///
///         Proof market: anyone posts a bounty on (codeHash, specHash) with an optional replay
///         contract. It is claimed
///           - by proof: a proof submitted for the bounty and accepted as above (one in flight at a
///             time), paid to its prover; or
///           - by counterexample: commit, then (from the next block on) reveal a counterexample that
///             the bounty's replay contract confirms on-chain. The code's spec is then REFUTED for
///             good: no proof of it counts any more.
///         Unclaimed, the poster takes it back after the deadline. Every payout is pulled (`withdraw`).
///
///         `levelOf(chainId, target)` reports AuditCertificate's level and PROVEN (4) on top of a
///         valid Gold certificate whose code hash has an accepted, unrefuted proof. AuditCertificate
///         itself is unchanged. No owner: governance (the ZetaphyTimelock) only sets bounded windows
///         and the minimum fee. A proof says the code satisfies THAT spec; read the spec.
contract ProofRegistry {
    uint8 public constant SEATS = 3;
    uint8 public constant QUORUM = 2;
    uint8 public constant GOLD = 3;          // AuditCertificate.GOLD
    uint8 public constant PROVEN = 4;        // reported on top of Gold

    uint8 public constant OPEN = 1;          // proofs and bounties
    uint8 public constant ACCEPTED = 2;      // proof: 2 of 3 runners reproduced "all proven"
    uint8 public constant REJECTED = 3;      // proof: anything else
    uint8 public constant PAID = 2;          // bounty: paid to a prover or a counterexample
    uint8 public constant RECLAIMED = 3;     // bounty: returned to its poster

    uint8 internal constant AGREED = 0;
    uint8 internal constant DISAGREED = 1;
    uint8 internal constant MISSED = 2;

    uint256 public constant MAX_ARTIFACTS = 32;
    uint256 public constant MAX_TEXT = 256;
    uint256 public constant MAX_COUNTEREXAMPLE = 16_384;

    struct Params {
        uint32 commitWindow;     // [1 hour, 30 days]: runners commit their outcome
        uint32 revealWindow;     // [1 hour, 7 days]: then reveal it
        uint128 minFee;          // [0, 1000 ether]: the runners' fee per proof
        uint32 minAgreed;        // [0, 10000]: a runner's agreed jobs on NeuroJobs
    }

    struct Submission {
        bytes32 codeHash;        // EXTCODEHASH of the proven code (as deployed)
        bytes32 specHash;        // the approved spec (audit/spec: keccak of its canonical approved part)
        bytes32 sourceHash;      // the source closure it was compiled from
        uint32 properties;       // approved properties in the spec
        bytes32[] artifacts;     // keccak256 of each generated artifact (proof.json "artifacts")
        string tools;            // e.g. "forge 1.2.3; halmos 0.3.3; solc 0.8.26"
        string recipe;           // where the recipe and the bundle are (https / ipfs)
        bytes32 recipeHash;      // keccak of the canonical recipe (proof.json "recipeHash")
        uint256 bountyId;        // 0: none
    }

    struct Outcome {
        bytes32 resultHash;      // keccak of the canonical proof result (proof.json "resultHash")
        uint32 proven;
        uint32 counterexamples;
        uint32 unknown;          // unknown, timed out or not installed
    }

    struct Proof {
        address prover;
        uint64 commitEnd;
        uint64 revealEnd;
        uint8 state;
        uint8 taken;
        uint8 revealed;
        uint32 properties;
        uint128 fee;
        bytes32 codeHash;
        bytes32 specHash;
        bytes32 sourceHash;
        bytes32 artifactsHash;   // keccak256(abi.encode(artifacts))
        bytes32 recipeHash;
        bytes32 resultHash;      // the agreed outcome's result hash (set at settle)
        uint256 bountyId;
    }

    struct Bounty {
        address poster;
        uint64 deadline;
        uint32 properties;
        uint8 state;
        uint128 amount;
        bytes32 codeHash;
        bytes32 specHash;
        address checker;         // zero: claimable by proof only
        uint256 inFlight;        // the proof being verified for it (0: none)
        address winner;
    }

    IPRJobs public immutable jobs;
    IPRReputation public immutable reputation;
    IPRCertificate public immutable certificates;
    address public governance;   // the ZetaphyTimelock
    Params public params;

    Proof[] internal _proofs;                                    // id = index + 1
    Bounty[] internal _bounties;                                 // id = index + 1
    mapping(uint256 => bytes32[]) internal _artifacts;
    mapping(uint256 => string) public toolsOf;
    mapping(uint256 => string) public recipeOf;
    mapping(uint256 => string) public specUriOf;                 // bounty -> where its spec and checker encoding are
    mapping(uint256 => address[]) internal _seats;
    mapping(uint256 => mapping(address => bytes32)) public commitments;
    mapping(uint256 => mapping(address => bytes32)) public revealedKey;
    mapping(bytes32 => Outcome) internal _outcomes;
    mapping(bytes32 => uint256) public submitCommits;            // commitment -> block number
    mapping(bytes32 => uint256) public cexCommits;               // commitment -> block number
    mapping(bytes32 => uint256) public latestProof;              // codeHash -> newest accepted proof id
    mapping(bytes32 => mapping(bytes32 => uint256)) public provenBy;   // codeHash -> specHash -> accepted proof id
    mapping(bytes32 => mapping(bytes32 => bool)) public refuted;       // codeHash -> specHash -> counterexample replayed
    mapping(address => uint256) public owed;
    mapping(address => address) public payoutOf;
    uint256 private _locked = 1;

    event Committed(bytes32 indexed commitment, address indexed by);
    event ProofSubmitted(uint256 indexed id, bytes32 indexed codeHash, bytes32 indexed specHash, address prover, bytes32 artifactsHash, uint32 properties, uint256 bountyId);
    event RunnerCommitted(uint256 indexed id, address indexed runner);
    event RunnerRevealed(uint256 indexed id, address indexed runner, bytes32 resultHash, uint32 proven, uint32 counterexamples, uint32 unknown);
    event ProofSettled(uint256 indexed id, bool accepted, bytes32 resultHash, uint256 agreedSeats, uint256 paidEach);
    event BountyPosted(uint256 indexed id, bytes32 indexed codeHash, bytes32 indexed specHash, address poster, uint256 amount, uint64 deadline, address checker);
    event BountyPaid(uint256 indexed id, address indexed winner, bool byCounterexample, uint256 amount);
    event BountyReclaimed(uint256 indexed id, uint256 amount);
    event Refuted(bytes32 indexed codeHash, bytes32 indexed specHash, uint256 indexed bountyId, uint32 property, address by);
    event Withdrawn(address indexed by, address indexed to, uint256 amount);
    event PayoutSet(address indexed by, address indexed to);
    event ParamsSet();
    event GovernanceSet(address indexed governance);

    error NotGovernance();
    error BadParams();
    error BadSubmission();
    error NoCommitment();
    error NoSuch();
    error Closed();
    error TooEarly();
    error NotRunner();
    error AlreadyIn();
    error BadReveal();
    error Busy();
    error NotViolated();
    error Nothing();
    error Reentrancy();

    modifier nonReentrant() {
        if (_locked != 1) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 1;
    }

    constructor(IPRJobs jobs_, IPRReputation reputation_, IPRCertificate certificates_, address governance_, Params memory p) {
        require(address(jobs_) != address(0) && governance_ != address(0), "zero");
        jobs = jobs_;
        reputation = reputation_;
        certificates = certificates_;
        governance = governance_;
        _setParams(p);
    }

    // ---------------------------------------------------------------- submit a proof

    function submitCommitment(bytes32 codeHash, bytes32 specHash, bytes32 artifactsHash, address prover, bytes32 salt) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.proof.submit", codeHash, specHash, artifactsHash, prover, salt));
    }

    /// Step 1 (any earlier block): commit to the proof you are about to submit.
    function commitSubmission(bytes32 commitment) external {
        if (commitment == bytes32(0) || submitCommits[commitment] != 0) revert AlreadyIn();
        submitCommits[commitment] = block.number;
        emit Committed(commitment, msg.sender);
    }

    /// Step 2: the proof, with the runners' fee. Three runners then reproduce it.
    function submit(Submission calldata s, bytes32 salt) external payable returns (uint256 id) {
        if (s.codeHash == bytes32(0) || s.specHash == bytes32(0) || s.sourceHash == bytes32(0) || s.recipeHash == bytes32(0) || s.properties == 0
            || s.artifacts.length == 0 || s.artifacts.length > MAX_ARTIFACTS || bytes(s.tools).length == 0 || bytes(s.tools).length > MAX_TEXT
            || bytes(s.recipe).length > MAX_TEXT || msg.value < params.minFee || msg.value > type(uint128).max) revert BadSubmission();
        bytes32 artifactsHash = keccak256(abi.encode(s.artifacts));
        bytes32 c = submitCommitment(s.codeHash, s.specHash, artifactsHash, msg.sender, salt);
        uint256 at = submitCommits[c];
        if (at == 0 || at >= block.number) revert NoCommitment();
        delete submitCommits[c];
        id = _proofs.length + 1;
        if (s.bountyId != 0) {
            Bounty storage b = _bounty(s.bountyId);
            if (b.state != OPEN || block.timestamp >= b.deadline) revert Closed();
            if (b.inFlight != 0) revert Busy();
            if (b.codeHash != s.codeHash || b.specHash != s.specHash || b.properties != s.properties) revert BadSubmission();
            b.inFlight = id;
        }
        uint64 commitEnd = uint64(block.timestamp) + params.commitWindow;
        _proofs.push(Proof({
            prover: msg.sender, commitEnd: commitEnd, revealEnd: commitEnd + params.revealWindow, state: OPEN, taken: 0, revealed: 0,
            properties: s.properties, fee: uint128(msg.value), codeHash: s.codeHash, specHash: s.specHash, sourceHash: s.sourceHash,
            artifactsHash: artifactsHash, recipeHash: s.recipeHash, resultHash: bytes32(0), bountyId: s.bountyId
        }));
        _artifacts[id] = s.artifacts;
        toolsOf[id] = s.tools;
        recipeOf[id] = s.recipe;
        emit ProofSubmitted(id, s.codeHash, s.specHash, msg.sender, artifactsHash, s.properties, s.bountyId);
    }

    // ---------------------------------------------------------------- runners: commit, reveal, settle

    function runCommitment(Outcome calldata o, address runner, bytes32 salt, uint256 id) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.proof.run", keccak256(abi.encode(o)), runner, salt, id));
    }

    function eligible(address runner) public view returns (bool) {
        // bonded, active, not leaving (no unbond requested), and with a clean enough record
        (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected) = jobs.workers(runner);
        return active && bond > 0 && unbondAt == 0 && agreed >= params.minAgreed && rejected <= agreed;
    }

    function commit(uint256 id, bytes32 commitment) external {
        Proof storage p = _proof(id);
        if (p.state != OPEN || p.taken >= SEATS || block.timestamp >= p.commitEnd) revert Closed();
        if (!eligible(msg.sender) || msg.sender == p.prover) revert NotRunner();
        if (commitment == bytes32(0) || commitments[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        commitments[id][msg.sender] = commitment;
        _seats[id].push(msg.sender);
        p.taken++;
        emit RunnerCommitted(id, msg.sender);
    }

    function reveal(uint256 id, Outcome calldata o, bytes32 salt) external {
        Proof storage p = _proof(id);
        if (block.timestamp < p.commitEnd) revert TooEarly();
        if (p.state != OPEN || block.timestamp >= p.revealEnd) revert Closed();
        bytes32 c = commitments[id][msg.sender];
        if (c == bytes32(0) || revealedKey[id][msg.sender] != bytes32(0)) revert AlreadyIn();
        if (o.resultHash == bytes32(0) || runCommitment(o, msg.sender, salt, id) != c) revert BadReveal();
        bytes32 k = keccak256(abi.encode(o));
        revealedKey[id][msg.sender] = k;
        _outcomes[k] = o;
        p.revealed++;
        emit RunnerRevealed(id, msg.sender, o.resultHash, o.proven, o.counterexamples, o.unknown);
    }

    /// Anyone, once all 3 seats revealed or the reveal window ended.
    function settle(uint256 id) external {
        Proof storage p = _proof(id);
        if (p.state != OPEN) revert Closed();
        bool allIn = p.taken == SEATS && p.revealed == SEATS && block.timestamp >= p.commitEnd;
        if (!allIn && block.timestamp < p.revealEnd) revert TooEarly();
        address[] memory seats = _seats[id];
        bytes32 k = _majority(id, seats);
        uint256 n = 0;
        for (uint256 i = 0; i < seats.length; i++) if (k != bytes32(0) && revealedKey[id][seats[i]] == k) n++;
        Outcome memory o = _outcomes[k];
        bool accepted = k != bytes32(0) && o.proven == p.properties && o.counterexamples == 0 && o.unknown == 0 && !refuted[p.codeHash][p.specHash];
        p.state = accepted ? ACCEPTED : REJECTED;
        p.resultHash = o.resultHash;
        uint256 each = 0;
        if (n > 0) each = p.fee / n;
        else owed[p.prover] += p.fee; // no agreement: the fee goes back
        if (accepted) {
            latestProof[p.codeHash] = id;
            provenBy[p.codeHash][p.specHash] = id;
        }
        if (p.bountyId != 0) {
            Bounty storage b = _bounties[p.bountyId - 1];
            if (b.inFlight == id) b.inFlight = 0;
            if (accepted && b.state == OPEN) {
                b.state = PAID;
                b.winner = p.prover;
                owed[p.prover] += b.amount;
                emit BountyPaid(p.bountyId, p.prover, false, b.amount);
            }
        }
        uint8[] memory kinds = new uint8[](seats.length);
        for (uint256 i = 0; i < seats.length; i++) {
            bytes32 v = revealedKey[id][seats[i]];
            kinds[i] = v == bytes32(0) ? MISSED : (k != bytes32(0) && v == k ? AGREED : DISAGREED);
            if (kinds[i] == AGREED) owed[seats[i]] += each;
        }
        emit ProofSettled(id, accepted, o.resultHash, n, each);
        // interactions last: the reputation reports
        for (uint256 i = 0; i < seats.length; i++) if (k != bytes32(0) || kinds[i] == MISSED) _rep(seats[i], kinds[i], id);
    }

    // ---------------------------------------------------------------- the proof market

    /// A bounty on proving (or refuting) spec `specHash` for code `codeHash` (`properties` approved
    /// properties). `checker` (optional) replays counterexamples on-chain; `specUri` says where the
    /// spec and the checker's counterexample encoding are published.
    function postBounty(bytes32 codeHash, bytes32 specHash, uint32 properties, uint64 deadline, address checker, string calldata specUri)
        external payable returns (uint256 id)
    {
        if (codeHash == bytes32(0) || specHash == bytes32(0) || properties == 0 || msg.value == 0 || msg.value > type(uint128).max
            || bytes(specUri).length > MAX_TEXT) revert BadParams();
        if (deadline < block.timestamp + uint256(params.commitWindow) + params.revealWindow || deadline > block.timestamp + 365 days) revert BadParams();
        if (checker != address(0) && checker.code.length == 0) revert BadParams();
        _bounties.push(Bounty({ poster: msg.sender, deadline: deadline, properties: properties, state: OPEN, amount: uint128(msg.value),
            codeHash: codeHash, specHash: specHash, checker: checker, inFlight: 0, winner: address(0) }));
        id = _bounties.length;
        specUriOf[id] = specUri;
        emit BountyPosted(id, codeHash, specHash, msg.sender, msg.value, deadline, checker);
    }

    function cexCommitment(uint256 bountyId, uint32 property, bytes calldata counterexample, address claimant, bytes32 salt) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.proof.cex", bountyId, property, keccak256(counterexample), claimant, salt));
    }

    /// Step 1 (any earlier block): commit to the counterexample.
    function commitCounterexample(bytes32 commitment) external {
        if (commitment == bytes32(0) || cexCommits[commitment] != 0) revert AlreadyIn();
        cexCommits[commitment] = block.number;
        emit Committed(commitment, msg.sender);
    }

    /// Step 2 (a later block, before the deadline): reveal it. The bounty's checker replays it on
    /// the bountied code; if the property is violated the claimant is paid and the spec is refuted
    /// for that code. Effects first, then the replay: a replay that does not confirm reverts all.
    function claimByCounterexample(uint256 bountyId, uint32 property, bytes calldata counterexample, bytes32 salt) external nonReentrant {
        Bounty storage b = _bounty(bountyId);
        if (b.state != OPEN || block.timestamp >= b.deadline || b.checker == address(0)) revert Closed();
        if (property >= b.properties || counterexample.length == 0 || counterexample.length > MAX_COUNTEREXAMPLE) revert BadParams();
        bytes32 c = cexCommitment(bountyId, property, counterexample, msg.sender, salt);
        uint256 at = cexCommits[c];
        if (at == 0 || at >= block.number) revert NoCommitment();
        delete cexCommits[c];
        b.state = PAID;
        b.winner = msg.sender;
        refuted[b.codeHash][b.specHash] = true;
        owed[msg.sender] += b.amount;
        emit Refuted(b.codeHash, b.specHash, bountyId, property, msg.sender);
        emit BountyPaid(bountyId, msg.sender, true, b.amount);
        if (!IPropertyChecker(b.checker).replay(b.codeHash, b.specHash, property, counterexample)) revert NotViolated();
    }

    /// The poster, after the deadline, when no proof is being verified for it.
    function reclaimBounty(uint256 bountyId) external {
        Bounty storage b = _bounty(bountyId);
        if (msg.sender != b.poster) revert NotGovernance();
        if (b.state != OPEN) revert Closed();
        if (block.timestamp < b.deadline) revert TooEarly();
        if (b.inFlight != 0) revert Busy();
        b.state = RECLAIMED;
        owed[b.poster] += b.amount;
        emit BountyReclaimed(bountyId, b.amount);
    }

    /// Where withdraw may also send the caller's credit (e.g. a cold wallet); zero: only to itself.
    function setPayout(address to) external {
        payoutOf[msg.sender] = to;
        emit PayoutSet(msg.sender, to);
    }

    /// Pull payment of the caller's credit to itself or to its payout address. The credit is zeroed
    /// before the transfer, and re-entry is refused.
    function withdraw(address to) external nonReentrant {
        if (to != msg.sender && (to == address(0) || to != payoutOf[msg.sender])) revert BadParams();
        uint256 a = owed[msg.sender];
        if (a == 0) revert Nothing();
        owed[msg.sender] = 0;
        emit Withdrawn(msg.sender, to, a);
        (bool ok, ) = to.call{value: a}("");
        if (!ok) revert Nothing();
    }

    // ---------------------------------------------------------------- reads

    /// True while code `codeHash` has an accepted proof of some spec that was never refuted.
    function isProven(bytes32 codeHash) public view returns (bool) {
        uint256 id = latestProof[codeHash];
        return id != 0 && !refuted[codeHash][_proofs[id - 1].specHash];
    }

    /// True while spec `specHash` has an accepted, unrefuted proof for code `codeHash`.
    function isProvenSpec(bytes32 codeHash, bytes32 specHash) external view returns (bool) {
        return provenBy[codeHash][specHash] != 0 && !refuted[codeHash][specHash];
    }

    /// AuditCertificate's level of (chainId, target) right now (0: no valid certificate), and
    /// PROVEN (4) when it is a valid Gold certificate whose code hash is proven.
    function levelOf(uint64 chainId, address target) external view returns (uint8) {
        if (address(certificates) == address(0)) return 0;
        (IPRCertificate.Cert memory c, bool valid) = certificates.certificate(chainId, target);
        if (!valid) return 0;
        if (c.level == GOLD && isProven(c.codeHash)) return PROVEN;
        return c.level;
    }

    function proof(uint256 id) external view returns (Proof memory) {
        return _proof(id);
    }

    function artifactsOf(uint256 id) external view returns (bytes32[] memory) {
        return _artifacts[id];
    }

    function seatsOf(uint256 id) external view returns (address[] memory) {
        return _seats[id];
    }

    /// The agreed outcome of proof `id` (agreed = false: none, or not settled yet).
    function outcome(uint256 id) external view returns (bool agreed, Outcome memory o) {
        Proof storage p = _proof(id);
        if (p.state == OPEN) return (false, o);
        address[] memory seats = _seats[id];
        bytes32 k = _majority(id, seats);
        if (k == bytes32(0)) return (false, o);
        return (true, _outcomes[k]);
    }

    function bounty(uint256 id) external view returns (Bounty memory) {
        return _bounty(id);
    }

    function proofCount() external view returns (uint256) {
        return _proofs.length;
    }

    function bountyCount() external view returns (uint256) {
        return _bounties.length;
    }

    // ---------------------------------------------------------------- governance (the ZetaphyTimelock)

    function setParams(Params calldata p) external {
        if (msg.sender != governance) revert NotGovernance();
        _setParams(p);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert NotGovernance();
        if (g == address(0)) revert BadParams();
        governance = g;
        emit GovernanceSet(g);
    }

    function _setParams(Params memory p) internal {
        if (p.commitWindow < 1 hours || p.commitWindow > 30 days || p.revealWindow < 1 hours || p.revealWindow > 7 days
            || p.minFee > 1000 ether || p.minAgreed > 10_000) revert BadParams();
        params = p;
        emit ParamsSet();
    }

    // ---------------------------------------------------------------- internals

    function _proof(uint256 id) internal view returns (Proof storage) {
        if (id == 0 || id > _proofs.length) revert NoSuch();
        return _proofs[id - 1];
    }

    function _bounty(uint256 id) internal view returns (Bounty storage) {
        if (id == 0 || id > _bounties.length) revert NoSuch();
        return _bounties[id - 1];
    }

    function _majority(uint256 id, address[] memory seats) internal view returns (bytes32) {
        for (uint256 i = 0; i < seats.length; i++) {
            bytes32 v = revealedKey[id][seats[i]];
            if (v == bytes32(0)) continue;
            uint256 n = 0;
            for (uint256 j = 0; j < seats.length; j++) if (revealedKey[id][seats[j]] == v) n++;
            if (n >= QUORUM) return v; // QUORUM > SEATS/2: at most one outcome reaches it
        }
        return bytes32(0);
    }

    function _rep(address w, uint8 kind, uint256 id) internal {
        if (address(reputation) == address(0)) return;
        try reputation.record(w, kind, keccak256(abi.encode("zetaphy.proof.run", id))) {} catch {}
    }
}

contracts/ProvenVerdicts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The model-bound Groth16 verifier (contracts/NeuroScoreVerifier.sol, generated from the zk ceremony; not edited here).
interface IModelProofVerifier {
    function MODEL_HASH() external view returns (bytes32);
    function verifyModelProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256 commitment, uint256 margin)
        external view returns (bool);
}

/// What ProvenVerdicts reads from NeuroScore (contracts/NeuroScore.sol): the pinned model and its evaluator.
interface IPinnedScorer {
    struct Model {
        bytes32 hash;
        bytes32 modelId;
        uint16 nFeatures;
        int64 low;
        int64 medium;
        int64 high;
        uint64 activatedAt;
    }
    function model(uint32 v) external view returns (Model memory);
    function modelBytes(bytes32 hash) external view returns (bytes memory);
    function evaluateAt(uint32 v, bytes calldata features) external view returns (int256 score, uint8 level);
}

/// What ProvenVerdicts reads from NeuroJobs (contracts/NeuroJobs.sol): a settled k-of-n verdict on a feature job.
interface IFeatureJobs {
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain, string memory target,
        uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function assurance(uint256 id) external view returns (uint8 agreedBy, uint8 state, uint64 challengeUntil, bool settled);
}

/// @title ProvenVerdicts: Neuro risk verdicts that come with a zero-knowledge proof of the model run
/// @notice docs/future/proven-verdicts.md. A bonded runner posts, for a token:
///           - the token's feature vector (`features`, 133 x u32, the profile "zfeat/1": every value is a pure
///             function of the token's runtime bytecode, zetaphy-network/src/zkverdict/features.js), and
///           - a Groth16 proof (the existing circuit, zetaphy-neuro/ml/onchain/zk/) that a committed vector yields
///             margin Z under the pinned model H. The verifier supplies H itself (verifyModelProof).
///         The score is computed HERE from the proven margin (score = trunc(calibA * Z / scale) + calibB, the
///         pinned model's calibration), so a runner cannot state another score than the one proven.
///
///         What binds the proof to the posted features and the features to the token (all permissionless):
///           1. the token's code hash (EXTCODEHASH) is recorded when the verdict lands;
///           2. challengeScore(id, features): anyone re-runs the pinned model on the posted features on-chain
///              (NeuroScore.evaluateAt). A different score means the proof was made for other features than the
///              posted ones (or, for an unproven claim, that the claim is wrong): the runner is slashed, the verdict
///              overturned. No trust in anything but the model bytes;
///           3. contest(id) + resolveContest(id, jobId): the posted features are not the token's. Anyone recomputes
///              zfeat/1 from the code with that hash; the dispute is settled by a NeuroJobs k-of-n job on chain
///              "zetaphy" with target featureTarget(id) ("zfeat/1:<token>:<codehash>"), whose verdict is
///              keccak256(the packed features). A settled result different from the posted hash slashes the runner.
///         Proof mode (governance): Optional = unproven claims are accepted with a lower weight; Required = they
///         are refused and old ones read as unknown. A verifier for another model is refused at construction:
///         a new model is a new circuit, a new ceremony, a new verifier and a new ProvenVerdicts.
///         Testnet: until the public phase-2 ceremony is final, the verifier comes from a one-machine rehearsal,
///         whose operator could forge proofs. Score = a statistical estimate, never a finding about a project.
contract ProvenVerdicts {
    enum ProofMode { Optional, Required }
    enum Status { None, Live, Contested, Overturned }

    struct Verdict {
        address token;
        uint64 time;
        uint8 level;      // 0 none, 1 low, 2 medium, 3 high (the pinned model's thresholds)
        bool proven;
        Status status;
        address runner;
        int64 score;      // calibrated logit x 1e7 (p = sigmoid(score / 1e7)), as NeuroScore
        bytes32 featuresHash; // keccak256 of the posted features (packed u32 big-endian)
        bytes32 codeHash;     // EXTCODEHASH of the token when the verdict landed
        bytes32 proofHash;    // keccak256(abi.encode(a, b, c, commitment, margin)); 0 for a claim
    }

    struct Contest {
        address challenger;
        uint64 openedAt;
        uint128 bond;
    }

    struct Runner {
        uint128 bond;
        uint64 unbondAt;  // 0 while active
        uint64 heldUntil; // the bond stays until every verdict it posted is out of its challenge window
        uint32 contested; // open contests on its verdicts (the bond stays while > 0)
        bool active;
    }

    /// One proven verdict (submit / submitBatch).
    struct Proof {
        address token;
        bytes32 modelId;  // must be the pinned model's id
        bytes features;
        uint256[2] a;
        uint256[2][2] b;
        uint256[2] c;
        uint256 commitment;
        uint256 margin;   // Z + 2^40 (the circuit's public output)
    }

    uint16 public constant PROVEN_WEIGHT = 3;
    uint16 public constant CLAIM_WEIGHT = 1;
    /// Share of a runner's bond lost when a verdict of theirs is overturned; half to the challenger, half burned.
    uint16 public constant SLASH_BPS = 5000;
    /// Share of the contest bond the challenger gets back when its contest times out without a settled job.
    uint16 public constant EXPIRE_REFUND_BPS = 8000;
    uint256 public constant MARGIN_OFFSET = 1 << 40;
    bytes32 public constant FEATURE_CHAIN = "zetaphy";
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    address public immutable governance;
    IModelProofVerifier public immutable verifier;
    IPinnedScorer public immutable scorer;
    IFeatureJobs public immutable jobs;
    uint32 public immutable scorerVersion;
    bytes32 public immutable modelHash;
    bytes32 public immutable modelId;
    uint16 public immutable nFeatures;
    int256 public immutable scale;
    int256 public immutable calibA;
    int256 public immutable calibB;
    int64 public immutable levelLow;
    int64 public immutable levelMedium;
    int64 public immutable levelHigh;
    uint256 public immutable runnerBond;
    uint256 public immutable contestBond;
    uint64 public immutable challengeWindow;
    uint64 public immutable contestTimeout;
    uint64 public immutable unbondDelay;

    ProofMode public proofMode;
    Verdict[] private _verdicts;
    mapping(uint256 => Contest) public contests;
    mapping(address => uint256) public latestOf; // token -> newest verdict id + 1 (0 = none)
    mapping(bytes32 => bool) public proofUsed;   // keccak256(token, proofHash)
    mapping(address => Runner) public runners;
    mapping(address => uint256) public credit;

    event ProofModeSet(ProofMode mode);
    event Registered(address indexed runner, uint256 bond);
    event UnbondRequested(address indexed runner, uint64 at);
    event Proven(uint256 indexed id, address indexed token, address indexed runner, int64 score, uint8 level, bytes32 featuresHash, bytes32 codeHash);
    /// The proof and the features of verdict `id` (what a browser re-verifies: zetaphy-hub/zkverdict-core.js).
    event ProofData(uint256 indexed id, address indexed token, uint256[2] a, uint256[2][2] b, uint256[2] c, uint256 commitment, uint256 margin, bytes features);
    event Claimed(uint256 indexed id, address indexed token, address indexed runner, int64 score, uint8 level, bytes32 featuresHash,
        bytes32 codeHash, bytes features);
    event Overturned(uint256 indexed id, address indexed by, uint8 why, int256 trueScore, bytes32 trueFeaturesHash); // why: 1 score, 2 features
    event Slashed(address indexed runner, uint256 amount, address indexed challenger);
    event Contested(uint256 indexed id, address indexed challenger, uint256 bond);
    event ContestUpheld(uint256 indexed id, uint256 jobId);
    event ContestExpired(uint256 indexed id);

    error NotGovernance();
    error ModelMismatch();
    error BadValue();
    error NotRunner();
    error WrongModel(bytes32 modelId);
    error BadFeatures();
    error NoCode(address token);
    error InvalidProof(uint256 index);
    error ProofUsed(uint256 index);
    error ProofRequired();
    error Unknown();
    error NotWrong();
    error Closed();
    error Busy();
    error NotSettled(uint256 jobId);
    error WrongJob(uint256 jobId);
    error TooEarly();
    error Nothing();

    /// @param scorer_ NeuroScore; its model `version_` must be the one `verifier_` was generated for (same hash H).
    constructor(address governance_, IModelProofVerifier verifier_, IPinnedScorer scorer_, uint32 version_, IFeatureJobs jobs_,
        uint256 runnerBond_, uint256 contestBond_, uint64 challengeWindow_, uint64 contestTimeout_, uint64 unbondDelay_) {
        if (governance_ == address(0) || runnerBond_ == 0 || contestBond_ == 0 || challengeWindow_ == 0 || contestTimeout_ == 0
            || unbondDelay_ < challengeWindow_) revert BadValue();
        IPinnedScorer.Model memory m = scorer_.model(version_);
        if (m.hash == bytes32(0) || verifier_.MODEL_HASH() != m.hash) revert ModelMismatch();
        bytes memory b = scorer_.modelBytes(m.hash);
        if (b.length < 24 || keccak256(b) != m.hash) revert ModelMismatch();
        governance = governance_;
        verifier = verifier_;
        scorer = scorer_;
        jobs = jobs_;
        scorerVersion = version_;
        modelHash = m.hash;
        modelId = m.modelId;
        nFeatures = m.nFeatures;
        levelLow = m.low;
        levelMedium = m.medium;
        levelHigh = m.high;
        // NSM1 header: scale u32 at 8, calibA i32 at 16, calibB i32 at 20 (zetaphy-neuro/ml/onchain/fixed.js)
        scale = int256(uint256(_be(b, 8, 4)));
        calibA = int256(int32(uint32(_be(b, 16, 4))));
        calibB = int256(int32(uint32(_be(b, 20, 4))));
        if (scale <= 0) revert ModelMismatch();
        runnerBond = runnerBond_;
        contestBond = contestBond_;
        challengeWindow = challengeWindow_;
        contestTimeout = contestTimeout_;
        unbondDelay = unbondDelay_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- governance ----

    function setProofMode(ProofMode mode) external onlyGov {
        proofMode = mode;
        emit ProofModeSet(mode);
    }

    // ---- runners ----

    function register() external payable {
        Runner storage r = runners[msg.sender];
        uint256 b = uint256(r.bond) + msg.value;
        if (b < runnerBond) revert BadValue();
        r.bond = uint128(b);
        r.active = true;
        r.unbondAt = 0;
        emit Registered(msg.sender, b);
    }

    function requestUnbond() external {
        Runner storage r = runners[msg.sender];
        if (!r.active) revert NotRunner();
        r.active = false;
        r.unbondAt = uint64(block.timestamp) + unbondDelay;
        emit UnbondRequested(msg.sender, r.unbondAt);
    }

    function withdrawBond() external {
        Runner storage r = runners[msg.sender];
        if (r.active || r.unbondAt == 0 || block.timestamp < r.unbondAt || block.timestamp < r.heldUntil || r.contested != 0) revert TooEarly();
        uint256 b = r.bond;
        if (b == 0) revert Nothing();
        r.bond = 0;
        _pay(msg.sender, b);
    }

    function withdraw() external {
        uint256 c = credit[msg.sender];
        if (c == 0) revert Nothing();
        credit[msg.sender] = 0;
        _pay(msg.sender, c);
    }

    // ---- verdicts ----

    /// A proven verdict: the proof is checked by the model-bound verifier, the score is computed from its margin.
    function submit(Proof calldata p) external returns (uint256 id) {
        _runner();
        return _submit(p, 0);
    }

    /// Several proven verdicts in one transaction (one runner). Reverts as a whole if any proof is invalid.
    function submitBatch(Proof[] calldata ps) external returns (uint256 first) {
        _runner();
        if (ps.length == 0) revert BadValue();
        first = _verdicts.length;
        for (uint256 i = 0; i < ps.length; ++i) _submit(ps[i], i);
    }

    /// An unproven verdict (Optional mode only), weighted lower; challengeScore slashes a wrong one.
    function claim(address token, bytes calldata features, int64 score) external returns (uint256 id) {
        _runner();
        if (proofMode == ProofMode.Required) revert ProofRequired();
        if (features.length != uint256(nFeatures) * 4) revert BadFeatures();
        bytes32 codeHash = _codeHash(token);
        bytes32 fh = keccak256(features);
        uint8 level = _level(score);
        id = _push(Verdict(token, uint64(block.timestamp), level, false, Status.Live, msg.sender, score, fh, codeHash, bytes32(0)));
        uint256 cur = latestOf[token];
        // a claim never hides a live proven verdict for the same code
        if (cur == 0 || !_verdicts[cur - 1].proven || _verdicts[cur - 1].status != Status.Live || _verdicts[cur - 1].codeHash != codeHash) {
            latestOf[token] = id + 1;
        }
        emit Claimed(id, token, msg.sender, score, level, fh, codeHash, features);
    }

    function _submit(Proof calldata p, uint256 index) private returns (uint256 id) {
        if (p.modelId != modelId) revert WrongModel(p.modelId);
        if (p.features.length != uint256(nFeatures) * 4) revert BadFeatures();
        if (p.margin >= 2 * MARGIN_OFFSET) revert InvalidProof(index);
        if (!verifier.verifyModelProof(p.a, p.b, p.c, p.commitment, p.margin)) revert InvalidProof(index);
        bytes32 ph = keccak256(abi.encode(p.a, p.b, p.c, p.commitment, p.margin));
        bytes32 key = keccak256(abi.encode(p.token, ph));
        if (proofUsed[key]) revert ProofUsed(index);
        proofUsed[key] = true;
        bytes32 codeHash = _codeHash(p.token);
        int64 score = scoreOfMargin(p.margin);
        uint8 level = _level(score);
        bytes32 fh = keccak256(p.features);
        id = _push(Verdict(p.token, uint64(block.timestamp), level, true, Status.Live, msg.sender, score, fh, codeHash, ph));
        latestOf[p.token] = id + 1;
        emit Proven(id, p.token, msg.sender, score, level, fh, codeHash);
        _emitProof(id, p);
    }

    function _emitProof(uint256 id, Proof calldata p) private {
        emit ProofData(id, p.token, p.a, p.b, p.c, p.commitment, p.margin, p.features);
    }

    // ---- challenges ----

    /// Anyone: re-runs the pinned model on the posted features (their preimage). A different score overturns the
    /// verdict and slashes its runner. For a proven verdict this means the proof was for other features.
    function challengeScore(uint256 id, bytes calldata features) external {
        Verdict storage v = _get(id);
        if (v.status == Status.Overturned) revert Closed();
        if (keccak256(features) != v.featuresHash) revert BadFeatures();
        (int256 s,) = scorer.evaluateAt(scorerVersion, features);
        if (s == int256(v.score)) revert NotWrong();
        _overturn(id, v, msg.sender, 1, s, v.featuresHash);
    }

    /// Anyone, inside the challenge window, with `contestBond`: "the posted features are not the token's".
    /// Settled by resolveContest with a NeuroJobs feature job, or expires after contestTimeout.
    function contest(uint256 id) external payable {
        Verdict storage v = _get(id);
        if (v.status != Status.Live) revert Closed();
        if (block.timestamp >= uint256(v.time) + challengeWindow) revert Closed();
        if (msg.value != contestBond) revert BadValue();
        v.status = Status.Contested;
        contests[id] = Contest(msg.sender, uint64(block.timestamp), uint128(msg.value));
        runners[v.runner].contested += 1;
        emit Contested(id, msg.sender, msg.value);
    }

    /// Anyone: settles a contest with a settled NeuroJobs job on chain "zetaphy" whose target is featureTarget(id).
    /// Its verdict (keccak256 of the zfeat/1 features k-of-n runners computed) decides.
    function resolveContest(uint256 id, uint256 jobId) external {
        Verdict storage v = _get(id);
        if (v.status != Status.Contested) revert Closed();
        if (address(jobs) == address(0)) revert NotSettled(jobId);
        (, , , bool settled) = jobs.assurance(jobId);
        if (!settled) revert NotSettled(jobId);
        (, , uint8 status, bytes32 chain, string memory target, , bytes32 result, , , ) = jobs.getJob(jobId);
        if (status != 2 || chain != FEATURE_CHAIN || keccak256(bytes(target)) != keccak256(bytes(featureTarget(id)))) revert WrongJob(jobId);
        Contest memory c = contests[id];
        delete contests[id];
        runners[v.runner].contested -= 1;
        if (result == v.featuresHash) {
            v.status = Status.Live;
            credit[v.runner] += c.bond; // the contest was wrong: its bond goes to the runner
            emit ContestUpheld(id, jobId);
        } else {
            credit[c.challenger] += c.bond;
            v.status = Status.Live; // the contest is closed above; _overturn only slashes
            _overturn(id, v, c.challenger, 2, 0, result);
        }
    }

    /// Anyone, after contestTimeout without a settled job: the verdict stands, the challenger gets most of its bond back.
    function expireContest(uint256 id) external {
        Verdict storage v = _get(id);
        if (v.status != Status.Contested) revert Closed();
        Contest memory c = contests[id];
        if (block.timestamp < uint256(c.openedAt) + contestTimeout) revert TooEarly();
        delete contests[id];
        runners[v.runner].contested -= 1;
        v.status = Status.Live;
        uint256 back = (uint256(c.bond) * EXPIRE_REFUND_BPS) / 10_000;
        credit[c.challenger] += back;
        credit[v.runner] += c.bond - back;
        emit ContestExpired(id);
    }

    function _overturn(uint256 id, Verdict storage v, address by, uint8 why, int256 trueScore, bytes32 trueFh) private {
        if (v.status == Status.Contested) {
            // a score challenge during a contest: the contest ends, its bond goes back
            Contest memory c = contests[id];
            delete contests[id];
            runners[v.runner].contested -= 1;
            credit[c.challenger] += c.bond;
        }
        v.status = Status.Overturned;
        Runner storage r = runners[v.runner];
        uint256 cut = (uint256(r.bond) * SLASH_BPS) / 10_000;
        r.bond -= uint128(cut);
        if (r.bond < runnerBond) r.active = false;
        uint256 toChallenger = cut / 2;
        credit[by] += toChallenger;
        emit Overturned(id, by, why, trueScore, trueFh);
        emit Slashed(v.runner, cut, by);
        if (cut - toChallenger > 0) _pay(BURN, cut - toChallenger);
    }

    // ---- views ----

    /// The token's newest verdict: known (live or contested, and not an unproven claim in Required mode), score,
    /// level, proven, weight (PROVEN_WEIGHT / CLAIM_WEIGHT / 0), settled (out of its challenge window, no contest),
    /// and its id.
    function verdictOf(address token) external view returns (bool known, int64 score, uint8 level, bool proven, uint16 weight, bool settled, uint256 id) {
        uint256 k = latestOf[token];
        if (k == 0) return (false, 0, 0, false, 0, false, 0);
        id = k - 1;
        Verdict storage v = _verdicts[id];
        if (v.status == Status.Overturned) return (false, 0, 0, v.proven, 0, true, id);
        if (!v.proven && proofMode == ProofMode.Required) return (false, v.score, v.level, false, 0, false, id);
        known = true;
        score = v.score;
        level = v.level;
        proven = v.proven;
        weight = v.proven ? PROVEN_WEIGHT : CLAIM_WEIGHT;
        settled = v.status == Status.Live && block.timestamp >= uint256(v.time) + challengeWindow;
    }

    function verdict(uint256 id) external view returns (Verdict memory) {
        return _get(id);
    }

    function count() external view returns (uint256) {
        return _verdicts.length;
    }

    /// Score from a proven margin (Z + 2^40) with the pinned model's calibration (as NeuroScore._eval).
    function scoreOfMargin(uint256 margin) public view returns (int64) {
        int256 z = int256(margin) - int256(MARGIN_OFFSET);
        int256 s = (calibA * z) / scale + calibB;
        if (s > type(int64).max || s < type(int64).min) revert BadValue();
        return int64(s);
    }

    /// The NeuroJobs target that settles a contest of verdict `id`: "zfeat/1:<token>:<code hash>", lower-case hex.
    function featureTarget(uint256 id) public view returns (string memory) {
        Verdict storage v = _get(id);
        return string.concat("zfeat/1:", _hex(abi.encodePacked(v.token)), ":", _hex(abi.encodePacked(v.codeHash)));
    }

    // ---- internals ----

    function _runner() private {
        Runner storage r = runners[msg.sender];
        if (!r.active) revert NotRunner();
        uint64 until = uint64(block.timestamp) + challengeWindow;
        if (until > r.heldUntil) r.heldUntil = until;
    }

    function _push(Verdict memory v) private returns (uint256 id) {
        _verdicts.push(v);
        return _verdicts.length - 1;
    }

    function _get(uint256 id) private view returns (Verdict storage) {
        if (id >= _verdicts.length) revert Unknown();
        return _verdicts[id];
    }

    function _codeHash(address token) private view returns (bytes32 h) {
        if (token.code.length == 0) revert NoCode(token);
        h = token.codehash;
    }

    function _level(int256 s) private view returns (uint8) {
        if (s >= levelHigh) return 3;
        if (s >= levelMedium) return 2;
        if (s >= levelLow) return 1;
        return 0;
    }

    function _be(bytes memory b, uint256 off, uint256 len) private pure returns (uint256 x) {
        for (uint256 i = 0; i < len; ++i) x = (x << 8) | uint8(b[off + i]);
    }

    function _hex(bytes memory b) private pure returns (string memory) {
        bytes16 h = "0123456789abcdef";
        bytes memory out = new bytes(2 + 2 * b.length);
        out[0] = "0";
        out[1] = "x";
        for (uint256 i = 0; i < b.length; ++i) {
            out[2 + 2 * i] = h[uint8(b[i]) >> 4];
            out[3 + 2 * i] = h[uint8(b[i]) & 0x0f];
        }
        return string(out);
    }

    function _pay(address to, uint256 amount) private {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "pay failed");
    }
}

contracts/QuantumRescue.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The chain's security precompile (0x…0901, zetaphy-chain evmd/zetaphy_secprecompile.go).
interface IZetaphySecurity {
    function qday() external view returns (uint64 height, uint64 revealDelay, bool active);
    function migration(address account) external view
        returns (bool migrated, address controller, address pendingController, uint64 finalHeight, bool exposed);
}

interface IRescueERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title QuantumRescue: a pre-commitment today, a post-quantum rescue after Q-day (testnet)
/// @notice The chain's own Q-day rule (docs/SECURITY-CORE.md) freezes every secp256k1 account that is
///         neither quantum-locked nor "never used" once Q-day passes: a quantum computer could forge
///         its signatures, so the chain stops accepting them. This contract gives such accounts a way
///         out that they prepare TODAY, while their ECDSA key is still trustworthy:
///
///           1. today      commit(c) from the classical address, c = commitmentOf(address, keccak256(pqPublicKey), secret)
///                         (only a hash: nothing about the ML-DSA key or the secret is public)
///           2. after QDAY reveal(address, pqPublicKey, secret, mlDsaSignature) - anyone may relay it;
///                         the address is then "rescued" to the ML-DSA-44 account of that key
///                         (sha256("zetaphy/mldsa44\0" ‖ pk)[0:20], the chain's native PQ address)
///
///         A commitment only counts once it is `maturity` blocks old, and only if it matured before
///         Q-day: someone who breaks the key shortly before Q-day cannot displace an older commitment.
///         Q-day is the chain's (governance-set, read from 0x…0901 qday()), or this contract's own
///         governance-set height if that is earlier or the precompile does not exist (another EVM chain).
///
///         What a rescue gives today, on-chain:
///           - controllerOf(address): any contract can honour it (QDayGuard pattern, see classicalTrusted());
///           - an escrow: protocol payouts to a frozen address (airdrops, bridge releases, refunds) are
///             sent here with depositFor() and the rescued ML-DSA controller claims them;
///         and, as a governance-voted chain step (designed, docs/future/quantum-safe-settlement.md),
///         MsgQDayRescue turns a rescue into the chain's quantum lock (the whole account, its 0x address).
contract QuantumRescue {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint256 public constant PK_BYTES = 1312;   // ML-DSA-44 (native PQ accounts are ML-DSA-44)
    uint64 public constant MIN_NOTICE = 100;   // blocks, like gov.sh qday (QDAY_MIN_NOTICE)

    address public immutable security;         // 0x…0901 on ZETAPHY; anything without code elsewhere
    uint64 public immutable maturity;          // blocks before a (new) commitment counts
    address public governance;                 // a timelock
    uint64 public localQday;                   // 0 = none; the earlier of this and the chain's Q-day applies

    struct Slot {
        bytes32 active;    // the commitment in force
        bytes32 pending;   // a newer one (or 0 = cancel), in force from pendingAt + maturity
        uint64 pendingAt;  // 0 = no pending change
    }
    mapping(address => Slot) private slots;
    mapping(address => address) public controllerOf;   // rescued classical address -> ML-DSA-44 account
    mapping(address => bytes32) public rescueKeyHash;  // keccak256 of the revealed ML-DSA public key
    mapping(address => mapping(address => uint256)) public escrow; // classical => token (0 = native) => amount
    uint256 private locked = 1;

    event Committed(address indexed account, bytes32 commitment, uint64 countsFrom);
    event Rescued(address indexed account, address indexed controller, bytes32 keyHash);
    event Deposited(address indexed account, address indexed token, address indexed from, uint256 amount);
    event Claimed(address indexed account, address indexed token, address to, uint256 amount);
    event LocalQdaySet(uint64 height);
    event GovernanceSet(address governance);

    error QdayPassed();
    error QdayNotYet();
    error AlreadyRescued();
    error NoCommitment();
    error WrongReveal();
    error BadKey();
    error BadSignature();
    error NotAllowed();
    error OnlyGovernance();
    error TooSoon();
    error Insufficient();
    error TransferFailed();
    error Reentrant();
    error BadParams();

    modifier nonReentrant() {
        if (locked != 1) revert Reentrant();
        locked = 2;
        _;
        locked = 1;
    }

    constructor(address security_, address governance_, uint64 maturity_) {
        if (governance_ == address(0) || maturity_ == 0) revert BadParams();
        security = security_;
        governance = governance_;
        maturity = maturity_;
    }

    // ------------------------------------------------------------------ Q-day

    /// The Q-day height in force: the earlier non-zero one of the chain's and this contract's (0 = none).
    function qdayHeight() public view returns (uint64 h) {
        h = localQday;
        if (security != address(0)) {
            // a precompile has no code; an address with neither code nor precompile answers empty
            (bool ok, bytes memory ret) = security.staticcall(abi.encodeWithSelector(IZetaphySecurity.qday.selector));
            if (ok && ret.length >= 96) {
                (uint64 chainH,,) = abi.decode(ret, (uint64, uint64, bool));
                if (chainH != 0 && (h == 0 || chainH < h)) h = chainH;
            }
        }
    }

    function qdayReached() public view returns (bool) {
        uint64 h = qdayHeight();
        return h != 0 && block.number >= h;
    }

    /// Contract-level Q-day for this contract (e.g. on a chain without the chain rule): at least
    /// MIN_NOTICE blocks ahead, or 0 to remove it. The chain's own Q-day still applies if earlier.
    function setLocalQday(uint64 h) external {
        if (msg.sender != governance) revert OnlyGovernance();
        if (h != 0 && h < block.number + MIN_NOTICE) revert TooSoon();
        localQday = h;
        emit LocalQdaySet(h);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert OnlyGovernance();
        if (g == address(0)) revert BadParams();
        governance = g;
        emit GovernanceSet(g);
    }

    /// QDayGuard: may a contract still trust `account`'s own (ECDSA) authority, i.e. msg.sender == account?
    /// Before Q-day yes. After it only if the chain says the account is quantum-locked / migrated (then the
    /// call can only come from its ML-DSA-44 controller through MsgEVMCall as_owner) - on any other chain no.
    function classicalTrusted(address account) public view returns (bool) {
        if (!qdayReached()) return true;
        return _chainMigrated(account);
    }

    function _chainMigrated(address account) private view returns (bool) {
        if (security == address(0)) return false;
        (bool ok, bytes memory ret) = security.staticcall(abi.encodeWithSelector(IZetaphySecurity.migration.selector, account));
        if (!ok || ret.length < 160) return false;
        (bool migrated,,,,) = abi.decode(ret, (bool, address, address, uint64, bool));
        return migrated;
    }

    // ------------------------------------------------------------------ commit (before Q-day)

    /// The commitment for `account`: hides the ML-DSA key and the secret until the reveal.
    function commitmentOf(address account, bytes32 pqKeyHash, bytes32 secret) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumRescue v1", block.chainid, address(this), account, pqKeyHash, secret));
    }

    /// Record (or replace, or with 0 cancel) the caller's commitment. A change counts `maturity` blocks later;
    /// until then the previous commitment stays in force.
    function commit(bytes32 c) external {
        if (qdayReached()) revert QdayPassed();
        if (controllerOf[msg.sender] != address(0)) revert AlreadyRescued();
        Slot storage s = slots[msg.sender];
        _promote(s);
        s.pending = c;
        s.pendingAt = uint64(block.number);
        emit Committed(msg.sender, c, uint64(block.number) + maturity);
    }

    function _promote(Slot storage s) private {
        if (s.pendingAt != 0 && block.number >= uint256(s.pendingAt) + maturity) {
            s.active = s.pending;
            s.pending = bytes32(0);
            s.pendingAt = 0;
        }
    }

    /// The commitment that counts for `account`: the newest one that matured before Q-day (or before now).
    function effectiveCommitment(address account) public view returns (bytes32) {
        Slot storage s = slots[account];
        uint256 bound = block.number;
        if (qdayReached()) bound = qdayHeight();
        if (s.pendingAt != 0 && uint256(s.pendingAt) + maturity <= bound) return s.pending;
        return s.active;
    }

    /// (active, pending, pendingAt) for wallets and the hub.
    function slotOf(address account) external view returns (bytes32, bytes32, uint64) {
        Slot storage s = slots[account];
        return (s.active, s.pending, s.pendingAt);
    }

    // ------------------------------------------------------------------ reveal (after Q-day)

    /// The chain's native ML-DSA-44 account of a public key.
    function pqAddress(bytes calldata pk) public pure returns (address) {
        return address(bytes20(sha256(abi.encodePacked("zetaphy/mldsa44\x00", pk))));
    }

    /// What the ML-DSA key signs to rescue `account` (when it does not send the reveal itself).
    function rescueDigest(address account, address controller) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumRescue reveal", block.chainid, address(this), account, controller));
    }

    /// After Q-day: prove the commitment and that the ML-DSA key is held (a signature, or the native PQ
    /// account sends this itself through MsgEVMCall). Anyone may relay: the controller follows from the key.
    function reveal(address account, bytes calldata pk, bytes32 secret, bytes calldata sig) external {
        if (!qdayReached()) revert QdayNotYet();
        if (controllerOf[account] != address(0)) revert AlreadyRescued();
        if (pk.length != PK_BYTES) revert BadKey();
        bytes32 c = effectiveCommitment(account);
        if (c == bytes32(0)) revert NoCommitment();
        bytes32 kh = keccak256(pk);
        if (c != commitmentOf(account, kh, secret)) revert WrongReveal();
        address ctrl = pqAddress(pk);
        if (msg.sender != ctrl && !_pqValid(rescueDigest(account, ctrl), pk, sig)) revert BadSignature();
        controllerOf[account] = ctrl;
        rescueKeyHash[account] = kh;
        delete slots[account];
        emit Rescued(account, ctrl, kh);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(uint8(44), d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    // ------------------------------------------------------------------ escrow for frozen / rescued accounts

    /// Pay native ZETAPHY to `account` through the rescue escrow (e.g. a payout after Q-day to a frozen address).
    function depositFor(address account) external payable {
        if (account == address(0) || msg.value == 0) revert BadParams();
        escrow[account][address(0)] += msg.value;
        emit Deposited(account, address(0), msg.sender, msg.value);
    }

    /// Pay an ERC-20 to `account` through the escrow (counts what actually arrived).
    function depositTokenFor(address token, address account, uint256 amount) external nonReentrant {
        if (account == address(0) || amount == 0 || token.code.length == 0) revert BadParams();
        uint256 before = IRescueERC20(token).balanceOf(address(this));
        _call(token, abi.encodeWithSelector(IRescueERC20.transferFrom.selector, msg.sender, address(this), amount));
        uint256 got = IRescueERC20(token).balanceOf(address(this)) - before;
        escrow[account][token] += got;
        emit Deposited(account, token, msg.sender, got);
    }

    /// Take escrowed funds out: the rescued ML-DSA controller, or the account itself while its key is still
    /// trusted (before Q-day, or after it when the chain says it is quantum-locked).
    function claim(address account, address token, uint256 amount, address to) external nonReentrant {
        address ctrl = controllerOf[account];
        bool ok = (ctrl != address(0) && msg.sender == ctrl) || (msg.sender == account && classicalTrusted(account));
        if (!ok) revert NotAllowed();
        if (to == address(0)) revert BadParams();
        uint256 bal = escrow[account][token];
        if (amount > bal) revert Insufficient();
        escrow[account][token] = bal - amount;
        emit Claimed(account, token, to, amount);
        if (token == address(0)) {
            (bool sent,) = to.call{value: amount}("");
            if (!sent) revert TransferFailed();
        } else {
            _call(token, abi.encodeWithSelector(IRescueERC20.transfer.selector, to, amount));
        }
    }

    function _call(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length != 32 || abi.decode(ret, (uint256)) != 1))) revert TransferFailed();
    }
}

contracts/QuantumWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title QuantumWallet: a smart wallet a quantum computer cannot drain (stage 5)
/// @notice Every action needs an ML-DSA signature (FIPS 204, post-quantum),
///         checked by ZETAPHY's precompile at 0x…0900. Two modes:
///           - hybrid: ECDSA AND ML-DSA must both sign (today's security, plus
///             protection if ECDSA is ever broken)
///           - post-quantum only: no ECDSA key at all (ecdsaOwner = 0)
///         Anyone may submit a signed action and pay its gas (a relay), so the
///         owner needs no other account. Keys rotate only through the wallet
///         itself, i.e. with the current keys' signatures.
contract QuantumWallet {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;

    address public ecdsaOwner;   // 0 = post-quantum only
    uint8 public variant;        // 44 or 65 (ML-DSA parameter set)
    bytes32 public pqKeyHash;    // keccak256 of the ML-DSA public key (the key itself rides in calldata)
    uint256 public nonce;

    /// The signatures for one action. pqPublicKey must hash to pqKeyHash;
    /// ecdsaSig is ignored in post-quantum-only mode.
    struct Auth {
        bytes pqPublicKey;
        bytes pqSig;
        bytes ecdsaSig;
    }

    event Executed(uint256 indexed nonce, address indexed to, uint256 value);
    event KeysChanged(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    error Expired();
    error BadEcdsa();
    error BadPq();
    error WrongKey();
    error BadVariant();
    error OnlySelf();
    error CallFailed(bytes reason);

    constructor(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) payable {
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    receive() external payable {}

    /// The 32 bytes both keys sign for one action.
    function digest(address to, uint256 value, bytes calldata data, uint256 deadline) public view returns (bytes32) {
        return keccak256(abi.encode("ZETAPHY QuantumWallet", block.chainid, address(this), nonce, to, value, keccak256(data), deadline));
    }

    function execute(address to, uint256 value, bytes calldata data, uint256 deadline, Auth calldata auth)
        external returns (bytes memory)
    {
        if (block.timestamp > deadline) revert Expired();
        _authorize(digest(to, value, data, deadline), auth);
        uint256 n = nonce++;
        (bool ok, bytes memory ret) = to.call{value: value}(data);
        if (!ok) revert CallFailed(ret);
        emit Executed(n, to, value);
        return ret;
    }

    function _authorize(bytes32 d, Auth calldata auth) private view {
        if (ecdsaOwner != address(0) && _recover(d, auth.ecdsaSig) != ecdsaOwner) revert BadEcdsa();
        if (keccak256(auth.pqPublicKey) != pqKeyHash) revert WrongKey();
        if (!_pqValid(d, auth.pqPublicKey, auth.pqSig)) revert BadPq();
    }

    /// Rotate keys or switch mode; callable only by execute() on this wallet.
    function setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) external {
        if (msg.sender != address(this)) revert OnlySelf();
        _setKeys(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _setKeys(address ecdsaOwner_, uint8 variant_, bytes32 pqKeyHash_) private {
        if ((variant_ != 44 && variant_ != 65) || pqKeyHash_ == bytes32(0)) revert BadVariant();
        ecdsaOwner = ecdsaOwner_;
        variant = variant_;
        pqKeyHash = pqKeyHash_;
        emit KeysChanged(ecdsaOwner_, variant_, pqKeyHash_);
    }

    function _pqValid(bytes32 d, bytes calldata pk, bytes calldata sig) private view returns (bool) {
        (bool ok, bytes memory ret) = MLDSA.staticcall(abi.encodePacked(variant, d, pk, sig));
        return ok && ret.length == 32 && uint256(bytes32(ret)) == 1;
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) return address(0);
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) return address(0);
        return ecrecover(d, v, r, s);
    }
}

/// @title QuantumWalletFactory: wallets at an address known before they exist
/// @notice The address depends only on the keys, so funds can be sent to a
///         wallet before it is deployed, and anyone can deploy it later.
contract QuantumWalletFactory {
    event Created(address indexed wallet, address ecdsaOwner, uint8 variant, bytes32 pqKeyHash);

    function create(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external returns (address w) {
        w = address(new QuantumWallet{salt: _salt(ecdsaOwner, variant, pqKeyHash)}(ecdsaOwner, variant, pqKeyHash));
        emit Created(w, ecdsaOwner, variant, pqKeyHash);
    }

    function predict(address ecdsaOwner, uint8 variant, bytes32 pqKeyHash) external view returns (address) {
        bytes32 h = keccak256(abi.encodePacked(bytes1(0xff), address(this), _salt(ecdsaOwner, variant, pqKeyHash),
            keccak256(abi.encodePacked(type(QuantumWallet).creationCode, abi.encode(ecdsaOwner, variant, pqKeyHash)))));
        return address(uint160(uint256(h)));
    }

    function _salt(address e, uint8 v, bytes32 k) private pure returns (bytes32) {
        return keccak256(abi.encode(e, v, k));
    }
}

contracts/RedBlueArena.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title RedBlueArena: an open red-vs-blue round for Neuro (testnet sandbox)
/// @notice TESTNET ONLY, and the "scams" never leave a sandbox: red entries are deployed
///         only on the runners' throwaway in-memory devnet, never on a public chain.
///
///         Red submits a scam token (a manifest: Solidity source + the owner's trap steps)
///         that should get past Neuro; blue submits a detector (a rule spec). Both commit
///         keccak256(arena, round, side, author, contentHash, salt) before `commitEnd`, so
///         neither side can tailor its entry to the other's, and reveal the content hash,
///         salt and a URI after it.
///
///         Judging needs no single trusted runner:
///           - k-of-n: up to `seats` runners (governance-approved AND bonded with `runnerBond`)
///             take a seat by committing keccak256(arena, round, runner, resultKey, salt) before
///             `resultCommitEnd`, so nobody can copy another runner's result; they reveal the
///             full result (bitmaps + blue scores) before `judgeEnd`;
///           - the sandbox is pinned: the round names `sandbox`, the hash of the runner
///             environment (zetaphy-neuro/ml/redteam/sandbox.js: the EVM interpreter and solc
///             versions, the fixed block environment, Neuro's model, the benign reference set),
///             and every runner's result commits to it, so honest runners agree byte for byte;
///           - `finalize` (anyone, after judgeEnd): the result `quorum` (more than half the
///             seats) runners revealed is the round's result. Runners that revealed another
///             result or never revealed lose `slashBps` of their bond to the runners who agreed.
///             No quorum: the round is void (unrevealed seats are still slashed);
///           - a challenge window follows: anyone may `challenge` with `challengeBond`, naming the
///             result it says is right. Governance (the timelock) re-runs the deterministic sandbox
///             and decides: upheld -> the challenger's result replaces it, the runners who posted
///             the wrong one are slashed and the challenger gets its bond back plus half of that;
///             rejected -> the challenge bond goes to the round's agreeing runners. A challenge
///             governance never answers lapses after `appealWindow`: the bond comes back.
///         Then `settle` pays:
///           - red: every valid evading entry gets an equal share of the red pool; valid
///             entries get their bond back; invalid or unrevealed entries lose it;
///           - blue: entries with a positive score share the blue pool by score; revealed
///             entries get their bond back; unrevealed ones lose it;
///           - runners: `runnerFeeBps` of the pools, plus the slashed bonds, split among the
///             runners whose revealed result is the final one.
///         Lost bonds and unpaid pools carry over to the next round. If the round is void,
///         revealed entries get their bonds back.
contract RedBlueArena {
    uint256 public constant MAX_RED = 128;
    uint256 public constant MAX_BLUE = 32;
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_SEATS = 9;

    struct Round {
        uint64 commitEnd;
        uint64 revealEnd;
        uint64 judgeEnd;     // end of the runners' result reveals
        bool judged;
        bool settled;
        uint128 redPool;
        uint128 bluePool;
        uint256 redValid;    // bit i: red entry i is a working scam
        uint256 redEvaded;   // bit i: ...and Neuro missed it
    }

    /// The runners' side of a round (kept apart from Round so both getters stay small).
    struct Judging {
        uint64 resultCommitEnd;
        uint64 challengeEnd;
        bool finalized;
        bool challenged;
        bool challengeResolved;
        uint8 seated;
        address challenger;
        bytes32 sandbox;     // hash of the pinned runner environment
        bytes32 resultKey;   // the final result's key
        bytes32 challengeKey;
        uint128 slashPool;   // slashed runner bonds of this round, for the agreeing runners
    }

    struct Entry {
        address author;
        bool revealed;
        bytes32 commitment;
        bytes32 contentHash;
        string uri;
    }

    struct Result {
        bool known;
        uint256 redValid;
        uint256 redEvaded;
        int32[] blueScore;
    }

    struct RunnerStake {
        uint128 bond;
        uint64 unbondAt;     // 0: bonded; else when the bond can be withdrawn
    }

    address public governance;
    uint128 public redBond = 1 ether;
    uint128 public blueBond = 1 ether;
    uint8 public quorum = 2;               // k: agreeing runners needed (> seats / 2)
    uint8 public seats = 3;                // n: runner seats per round
    uint128 public runnerBond = 10 ether;
    uint16 public slashBps = 5_000;        // of runnerBond, per wrong / missing result
    uint16 public runnerFeeBps = 500;      // of the round's pools, for the agreeing runners
    uint128 public challengeBond = 5 ether;
    uint32 public challengeWindow = 1 days;
    uint32 public appealWindow = 7 days;
    uint32 public unbondDelay = 14 days;
    uint256 public carry;          // lost bonds and unpaid pools, for the next round
    uint256 public roundCount;

    mapping(address => bool) public runners;
    mapping(address => RunnerStake) public stakes;
    mapping(address => uint256) public activeSeats; // open rounds a runner sits in (cannot unbond meanwhile)
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => Judging) public judging;
    mapping(uint256 => Entry[]) private _red;
    mapping(uint256 => Entry[]) private _blue;
    mapping(uint256 => int32[]) private _blueScore;
    mapping(uint256 => address[]) private _seats;
    mapping(uint256 => mapping(address => bytes32)) public resultCommitments;
    mapping(uint256 => mapping(address => bytes32)) public revealedKey;
    mapping(uint256 => mapping(bytes32 => uint8)) public votes;
    mapping(uint256 => mapping(bytes32 => Result)) private _results;
    mapping(address => uint256) public owed;

    event RoundOpened(uint256 indexed round, uint64 commitEnd, uint64 revealEnd, uint64 judgeEnd, uint256 redPool, uint256 bluePool);
    event RoundSandbox(uint256 indexed round, uint64 resultCommitEnd, bytes32 sandbox);
    event Committed(uint256 indexed round, uint8 side, uint256 index, address indexed author);
    event Revealed(uint256 indexed round, uint8 side, uint256 index, bytes32 contentHash, string uri);
    event ResultCommitted(uint256 indexed round, address indexed runner);
    event ResultRevealed(uint256 indexed round, address indexed runner, bytes32 key, uint8 votes);
    event Judged(uint256 indexed round, uint256 redValid, uint256 redEvaded, int32[] blueScore);
    event RunnerSlashed(uint256 indexed round, address indexed runner, uint256 amount, bool revealed);
    event Challenged(uint256 indexed round, address indexed challenger, bytes32 key);
    event ChallengeResolved(uint256 indexed round, bool upheld, bytes32 key);
    event Settled(uint256 indexed round, bool void, uint256 redPaid, uint256 bluePaid, uint256 carried);
    event RunnerSet(address indexed runner, bool on);
    event RunnerBonded(address indexed runner, uint256 bond);
    event RunnerUnbonding(address indexed runner, uint64 at);
    event ParamsSet(uint128 redBond, uint128 blueBond, uint8 quorum);
    event RunnerParamsSet(uint8 seats, uint128 runnerBond, uint16 slashBps, uint16 runnerFeeBps, uint128 challengeBond, uint32 challengeWindow, uint32 appealWindow);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error BadInput();
    error WrongPhase();
    error Full();
    error BadReveal();
    error AlreadyPosted();
    error NothingOwed();
    error SendFailed();
    error LowBond();
    error Busy();

    constructor(address governance_) {
        governance = governance_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov { governance = g; emit GovernanceSet(g); }
    function setRunner(address r, bool on) external onlyGov { runners[r] = on; emit RunnerSet(r, on); }
    function setParams(uint128 rb, uint128 bb, uint8 q) external onlyGov {
        if (q == 0 || uint256(q) * 2 <= seats || q > seats) revert BadInput();
        (redBond, blueBond, quorum) = (rb, bb, q);
        emit ParamsSet(rb, bb, q);
    }
    /// n seats, the runner bond, the slash, the runners' fee and the challenge rules. quorum must stay > n/2.
    function setRunnerParams(uint8 n, uint128 bond, uint16 slash, uint16 fee, uint128 cBond, uint32 cWindow, uint32 aWindow) external onlyGov {
        if (n == 0 || n > MAX_SEATS || uint256(quorum) * 2 <= n || quorum > n || slash > 10_000 || fee > 2_000 || cWindow == 0 || aWindow == 0) revert BadInput();
        (seats, runnerBond, slashBps, runnerFeeBps, challengeBond, challengeWindow, appealWindow) = (n, bond, slash, fee, cBond, cWindow, aWindow);
        emit RunnerParamsSet(n, bond, slash, fee, cBond, cWindow, aWindow);
    }

    /// Opens a round with msg.value (+ the carry) as bounties; redShareBps of it for red. `sandbox` is the
    /// hash of the runner environment every result must be computed in.
    function openRound(uint64 commitEnd, uint64 revealEnd, uint64 resultCommitEnd, uint64 judgeEnd, uint16 redShareBps, bytes32 sandbox)
        external payable onlyGov returns (uint256 id)
    {
        if (commitEnd <= block.timestamp || revealEnd <= commitEnd || resultCommitEnd <= revealEnd || judgeEnd <= resultCommitEnd || redShareBps > 10_000 || sandbox == bytes32(0)) revert BadInput();
        uint256 total = msg.value + carry;
        carry = 0;
        uint128 red = uint128((total * redShareBps) / 10_000);
        id = ++roundCount;
        Round storage r = rounds[id];
        (r.commitEnd, r.revealEnd, r.judgeEnd) = (commitEnd, revealEnd, judgeEnd);
        (r.redPool, r.bluePool) = (red, uint128(total - red));
        (judging[id].resultCommitEnd, judging[id].sandbox) = (resultCommitEnd, sandbox);
        emit RoundOpened(id, commitEnd, revealEnd, judgeEnd, red, total - red);
        emit RoundSandbox(id, resultCommitEnd, sandbox);
    }

    // ------------------------------------------------------------------ runner bonds

    function bondRunner() external payable {
        RunnerStake storage s = stakes[msg.sender];
        s.bond += uint128(msg.value);
        s.unbondAt = 0;
        emit RunnerBonded(msg.sender, s.bond);
    }

    function requestUnbond() external {
        if (activeSeats[msg.sender] != 0) revert Busy();
        uint64 at = uint64(block.timestamp) + unbondDelay;
        stakes[msg.sender].unbondAt = at;
        emit RunnerUnbonding(msg.sender, at);
    }

    function withdrawBond() external {
        RunnerStake storage s = stakes[msg.sender];
        if (s.unbondAt == 0 || block.timestamp < s.unbondAt || activeSeats[msg.sender] != 0) revert WrongPhase();
        uint256 a = s.bond;
        if (a == 0) revert NothingOwed();
        s.bond = 0;
        s.unbondAt = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }

    // ------------------------------------------------------------------ entries

    function commitmentOf(uint256 round, uint8 side, address author, bytes32 contentHash, bytes32 salt) public view returns (bytes32) {
        return keccak256(abi.encode(address(this), round, side, author, contentHash, salt));
    }

    /// side 0 = red (a scam token), 1 = blue (a detector). The bond is the side's bond.
    function commit(uint256 round, uint8 side, bytes32 commitment) external payable returns (uint256 index) {
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || block.timestamp >= r.commitEnd) revert WrongPhase();
        if (side > 1 || commitment == bytes32(0) || msg.value != (side == 0 ? redBond : blueBond)) revert BadInput();
        Entry[] storage list = side == 0 ? _red[round] : _blue[round];
        if (list.length >= (side == 0 ? MAX_RED : MAX_BLUE)) revert Full();
        list.push(Entry(msg.sender, false, commitment, bytes32(0), ""));
        index = list.length - 1;
        emit Committed(round, side, index, msg.sender);
    }

    function reveal(uint256 round, uint8 side, uint256 index, bytes32 contentHash, bytes32 salt, string calldata uri) external {
        Round storage r = rounds[round];
        if (block.timestamp < r.commitEnd || block.timestamp >= r.revealEnd) revert WrongPhase();
        if (side > 1 || bytes(uri).length == 0 || bytes(uri).length > MAX_URI) revert BadInput();
        Entry storage e = (side == 0 ? _red[round] : _blue[round])[index];
        if (e.revealed || e.author != msg.sender || e.commitment != commitmentOf(round, side, msg.sender, contentHash, salt)) revert BadReveal();
        e.revealed = true;
        e.contentHash = contentHash;
        e.uri = uri;
        emit Revealed(round, side, index, contentHash, uri);
    }

    function counts(uint256 round) external view returns (uint256 red, uint256 blue) {
        return (_red[round].length, _blue[round].length);
    }

    function entry(uint256 round, uint8 side, uint256 index) external view returns (address author, bool revealed, bytes32 contentHash, string memory uri) {
        Entry storage e = (side == 0 ? _red[round] : _blue[round])[index];
        return (e.author, e.revealed, e.contentHash, e.uri);
    }

    function blueScores(uint256 round) external view returns (int32[] memory) {
        return _blueScore[round];
    }

    function seatsOf(uint256 round) external view returns (address[] memory) {
        return _seats[round];
    }

    function resultOf(uint256 round, bytes32 key) external view returns (bool known, uint256 redValid, uint256 redEvaded, int32[] memory blueScore) {
        Result storage x = _results[round][key];
        return (x.known, x.redValid, x.redEvaded, x.blueScore);
    }

    // ------------------------------------------------------------------ judging: k-of-n commit-reveal

    /// The key of a result: the sandbox it was computed in, the bitmaps and the blue scores.
    function resultKey(bytes32 sandbox, uint256 redValid, uint256 redEvaded, int32[] memory blueScore) public pure returns (bytes32) {
        return keccak256(abi.encode(sandbox, redValid, redEvaded, blueScore));
    }

    function resultCommitmentOf(uint256 round, address runner, bytes32 key, bytes32 salt) public view returns (bytes32) {
        return keccak256(abi.encode(address(this), round, runner, key, salt));
    }

    /// A bonded, approved runner takes one of the round's seats with its sealed result.
    function commitResult(uint256 round, bytes32 commitment) external {
        if (!runners[msg.sender]) revert NotRunner();
        RunnerStake storage s = stakes[msg.sender];
        if (s.bond < runnerBond || s.unbondAt != 0) revert LowBond();
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || block.timestamp < r.revealEnd || block.timestamp >= judging[round].resultCommitEnd) revert WrongPhase();
        if (resultCommitments[round][msg.sender] != bytes32(0)) revert AlreadyPosted();
        if (judging[round].seated >= seats) revert Full();
        if (commitment == bytes32(0)) revert BadInput();
        resultCommitments[round][msg.sender] = commitment;
        _seats[round].push(msg.sender);
        judging[round].seated++;
        activeSeats[msg.sender]++;
        emit ResultCommitted(round, msg.sender);
    }

    function revealResult(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore, bytes32 salt) external {
        Round storage r = rounds[round];
        if (block.timestamp < judging[round].resultCommitEnd || block.timestamp >= r.judgeEnd) revert WrongPhase();
        bytes32 c = resultCommitments[round][msg.sender];
        if (c == bytes32(0) || revealedKey[round][msg.sender] != bytes32(0)) revert BadReveal();
        _checkResult(round, redValid, redEvaded, blueScore);
        bytes32 key = resultKey(judging[round].sandbox, redValid, redEvaded, blueScore);
        if (resultCommitmentOf(round, msg.sender, key, salt) != c) revert BadReveal();
        revealedKey[round][msg.sender] = key;
        Result storage x = _results[round][key];
        if (!x.known) (x.known, x.redValid, x.redEvaded, x.blueScore) = (true, redValid, redEvaded, blueScore);
        uint8 v = ++votes[round][key];
        emit ResultRevealed(round, msg.sender, key, v);
    }

    function _checkResult(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore) private view {
        Entry[] storage reds = _red[round];
        Entry[] storage blues = _blue[round];
        if (blueScore.length != blues.length || (redEvaded & ~redValid) != 0) revert BadInput();
        uint256 revealedMask;
        for (uint256 i; i < reds.length; i++) if (reds[i].revealed) revealedMask |= (uint256(1) << i);
        if ((redValid & ~revealedMask) != 0) revert BadInput();
        for (uint256 i; i < blues.length; i++) if (!blues[i].revealed && blueScore[i] > 0) revert BadInput();
    }

    /// Anyone, after the reveals: the result `quorum` runners revealed wins; the others are slashed.
    function finalize(uint256 round) external {
        Round storage r = rounds[round];
        if (r.commitEnd == 0 || judging[round].finalized || block.timestamp < r.judgeEnd) revert WrongPhase();
        judging[round].finalized = true;
        address[] storage list = _seats[round];
        bytes32 best;
        uint8 bestVotes;
        for (uint256 i; i < list.length; i++) {
            bytes32 k = revealedKey[round][list[i]];
            if (k != bytes32(0) && votes[round][k] > bestVotes) (best, bestVotes) = (k, votes[round][k]);
        }
        bool judged = bestVotes >= quorum;
        for (uint256 i; i < list.length; i++) {
            address a = list[i];
            activeSeats[a]--;
            bytes32 k = revealedKey[round][a];
            // never revealed: always slashed; revealed another result: slashed only when a quorum agreed
            if (k == bytes32(0) || (judged && k != best)) _slash(round, a, k != bytes32(0));
        }
        if (judged) {
            _adopt(round, best);
            judging[round].challengeEnd = uint64(block.timestamp) + challengeWindow;
        }
    }

    function _adopt(uint256 round, bytes32 key) private {
        Round storage r = rounds[round];
        Result storage x = _results[round][key];
        (r.judged, judging[round].resultKey, r.redValid, r.redEvaded) = (true, key, x.redValid, x.redEvaded);
        _blueScore[round] = x.blueScore;
        emit Judged(round, x.redValid, x.redEvaded, x.blueScore);
    }

    function _slash(uint256 round, address runner, bool revealed) private {
        RunnerStake storage s = stakes[runner];
        uint256 cut = (uint256(runnerBond) * slashBps) / 10_000;
        if (cut > s.bond) cut = s.bond;
        s.bond -= uint128(cut);
        judging[round].slashPool += uint128(cut);
        emit RunnerSlashed(round, runner, cut, revealed);
    }

    // ------------------------------------------------------------------ the challenge path

    /// Anyone, during the challenge window: says the judged result is wrong and names the right one.
    function challenge(uint256 round, uint256 redValid, uint256 redEvaded, int32[] calldata blueScore) external payable {
        Round storage r = rounds[round];
        if (!r.judged || judging[round].challenged || block.timestamp >= judging[round].challengeEnd) revert WrongPhase();
        if (msg.value != challengeBond) revert BadInput();
        _checkResult(round, redValid, redEvaded, blueScore);
        bytes32 key = resultKey(judging[round].sandbox, redValid, redEvaded, blueScore);
        if (key == judging[round].resultKey) revert BadInput();
        Result storage x = _results[round][key];
        if (!x.known) (x.known, x.redValid, x.redEvaded, x.blueScore) = (true, redValid, redEvaded, blueScore);
        Judging storage j = judging[round];
        (j.challenged, j.challenger, j.challengeKey) = (true, msg.sender, key);
        emit Challenged(round, msg.sender, key);
    }

    /// Governance (the timelock), after re-running the pinned sandbox: upheld replaces the result.
    function resolveChallenge(uint256 round, bool upheld) external onlyGov {
        Round storage r = rounds[round];
        if (!judging[round].challenged || judging[round].challengeResolved || r.settled) revert WrongPhase();
        judging[round].challengeResolved = true;
        if (upheld) {
            bytes32 wrong = judging[round].resultKey;
            address[] storage list = _seats[round];
            uint256 before = judging[round].slashPool;
            for (uint256 i; i < list.length; i++) if (revealedKey[round][list[i]] == wrong) _slash(round, list[i], true);
            uint256 half = (judging[round].slashPool - before) / 2;
            judging[round].slashPool -= uint128(half);
            owed[judging[round].challenger] += challengeBond + half;
            _adopt(round, judging[round].challengeKey);
        } else {
            judging[round].slashPool += challengeBond;
        }
        emit ChallengeResolved(round, upheld, judging[round].resultKey);
    }

    /// A challenge governance did not answer within appealWindow lapses: the bond comes back, the result stands.
    function expireChallenge(uint256 round) external {
        if (!judging[round].challenged || judging[round].challengeResolved || block.timestamp < uint256(judging[round].challengeEnd) + appealWindow) revert WrongPhase();
        judging[round].challengeResolved = true;
        owed[judging[round].challenger] += challengeBond;
        emit ChallengeResolved(round, false, judging[round].resultKey);
    }

    // ------------------------------------------------------------------ payout

    function settle(uint256 round) external {
        Round storage r = rounds[round];
        Judging storage j = judging[round];
        if (!j.finalized || r.settled) revert WrongPhase();
        if (r.judged && (block.timestamp < j.challengeEnd || (j.challenged && !j.challengeResolved))) revert WrongPhase();
        r.settled = true;
        uint256 left = uint256(r.redPool) + r.bluePool;
        uint256 redPaid;
        uint256 bluePaid;
        if (!r.judged) {
            Entry[] storage reds = _red[round];
            Entry[] storage blues = _blue[round];
            for (uint256 i; i < reds.length; i++) _back(reds[i], redBond, reds[i].revealed);
            for (uint256 i; i < blues.length; i++) _back(blues[i], blueBond, blues[i].revealed);
            carry += j.slashPool;
        } else {
            // the agreeing runners' fee comes off the top of both pools
            uint256 feeRed = (uint256(r.redPool) * runnerFeeBps) / 10_000;
            uint256 feeBlue = (uint256(r.bluePool) * runnerFeeBps) / 10_000;
            redPaid = _payRed(round, r.redPool - feeRed);
            bluePaid = _payBlue(round, r.bluePool - feeBlue);
            _payRunners(round, feeRed + feeBlue + j.slashPool);
            left -= feeRed + feeBlue;
        }
        left -= redPaid + bluePaid;
        carry += left;
        emit Settled(round, !r.judged, redPaid, bluePaid, left);
    }

    function _payRed(uint256 round, uint256 pool) private returns (uint256 paid) {
        Round storage r = rounds[round];
        Entry[] storage reds = _red[round];
        uint256 evaders = _popcount(r.redEvaded);
        for (uint256 i; i < reds.length; i++) {
            _back(reds[i], redBond, (r.redValid >> i) & 1 == 1);
            if ((r.redEvaded >> i) & 1 == 1) {
                uint256 share = pool / evaders;
                owed[reds[i].author] += share;
                paid += share;
            }
        }
    }

    function _payBlue(uint256 round, uint256 pool) private returns (uint256 paid) {
        Entry[] storage blues = _blue[round];
        int32[] storage sc = _blueScore[round];
        uint256 total;
        for (uint256 i; i < sc.length; i++) if (sc[i] > 0) total += uint256(int256(sc[i]));
        for (uint256 i; i < blues.length; i++) {
            _back(blues[i], blueBond, blues[i].revealed);
            if (total > 0 && sc[i] > 0) {
                uint256 share = (pool * uint256(int256(sc[i]))) / total;
                owed[blues[i].author] += share;
                paid += share;
            }
        }
    }

    /// Splits `amount` (the runners' fee + the slashed bonds) among the runners whose revealed result is the
    /// final one; nobody agreeing: it carries over.
    function _payRunners(uint256 round, uint256 amount) private {
        address[] storage list = _seats[round];
        uint256 n;
        for (uint256 i; i < list.length; i++) if (revealedKey[round][list[i]] == judging[round].resultKey) n++;
        if (n == 0) { carry += amount; return; }
        uint256 each = amount / n;
        for (uint256 i; i < list.length; i++) if (revealedKey[round][list[i]] == judging[round].resultKey) owed[list[i]] += each;
        carry += amount - each * n;
    }

    function _back(Entry storage e, uint256 bond, bool ok) private {
        if (ok) owed[e.author] += bond;
        else carry += bond;
    }

    function _popcount(uint256 x) private pure returns (uint256 c) {
        for (; x != 0; x &= x - 1) c++;
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingOwed();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }
}

contracts/RewardVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IFundable {
    function fund() external payable;
}

/// @title RewardVault: releases the ZETAPHY reward pool at 10% a year
/// @notice The 500,000,000 ZETAPHY set aside for runners and validators sit
///         here instead of in a key-holder's account. Every day, anyone can
///         call `release()`, which pays out the share of the remaining pool
///         that has vested: 10% of what is left per year, in daily steps
///         (0.9^(1/365) is kept each day), so the pool lasts for decades.
///
///         There is NO withdraw function. Governance can only choose who
///         receives the releases (e.g. NeuroJobs' reward pool, a validator
///         rewards contract), and a change only takes effect DELAY after it
///         is announced, so everyone can see it coming. Nobody can make the
///         vault pay faster than the schedule.
///
///         Money vests from when it arrives (RV-1): the vault keeps the balance
///         that has been vesting since the last checkpoint (`_vesting`) and what
///         has vested but is not paid yet (`_due`). Every deposit through
///         `receive()` and every release first moves what vested since the last
///         checkpoint into `_due`, then counts the new balance as vesting from
///         today. Coins that arrive without `receive()` (selfdestruct) start
///         vesting at the next checkpoint. Fund the vault with a call that
///         forwards gas (receive() does a checkpoint), not a 2300-gas transfer.
contract RewardVault {
    uint256 private constant RAY = 1e27;
    /// 0.9^(1/365) in RAY: keep^365 = 0.9 (to 1e-25)
    uint256 public constant DAILY_KEEP = 999711382710977687364396358;
    uint256 public constant DELAY = 7 days;
    uint256 public constant MAX_SHARES = 8;

    struct Share {
        address to;
        uint16 bps;      // out of 10,000
        bool callFund;   // pay through `fund()` (NeuroJobs, ComputeMarket) instead of a plain transfer
    }

    uint64 public immutable start;
    uint64 public releasedDays;
    address public governance;
    Share[] private _shares;
    Share[] private _pending;
    uint64 public pendingAt; // 0 = nothing pending
    uint256 private _vesting; // balance vesting since day `releasedDays` (excludes _due)
    uint256 private _due;     // vested, not paid out yet
    bool private _paying;     // inside release(): recipients are being called

    event Released(uint256 day, uint256 amount);
    event Paid(address indexed to, uint256 amount, bool ok);
    event SharesProposed(uint64 effectiveAt);
    event SharesApplied();
    event GovernanceChanged(address governance);

    error NotGovernance();
    error BadShares();
    error TooEarly();

    constructor(address governance_, Share[] memory shares_) {
        governance = governance_;
        start = uint64(block.timestamp);
        _check(shares_);
        for (uint256 i = 0; i < shares_.length; i++) _shares.push(shares_[i]);
    }

    /// Deposits start vesting today, not at the last release (RV-1).
    receive() external payable {
        if (!_paying) _checkpoint();
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    // ---- schedule ----

    function daysElapsed() public view returns (uint256) {
        return (block.timestamp - start) / 1 days;
    }

    /// What `release()` would pay right now.
    function releasable() public view returns (uint256) {
        if (_paying) return 0;
        uint256 n = daysElapsed() - releasedDays;
        return _due + (n == 0 ? 0 : _vested(_vesting, n));
    }

    /// Pays out everything vested since the last release. Anyone may call it.
    function release() public returns (uint256 amount) {
        if (_paying) return 0; // a recipient re-entering: nothing more
        _checkpoint();         // before any external call
        amount = _due;
        if (amount == 0) return 0;
        _due = 0;
        _paying = true;
        emit Released(releasedDays, amount);
        uint256 left = amount;
        for (uint256 i = 0; i < _shares.length; i++) {
            Share memory s = _shares[i];
            uint256 part = i + 1 == _shares.length ? left : (amount * s.bps) / 10_000;
            left -= part;
            bool ok;
            if (s.callFund) {
                (ok, ) = s.to.call{value: part}(abi.encodeCall(IFundable.fund, ()));
            } else {
                (ok, ) = s.to.call{value: part}("");
            }
            // A recipient that refuses keeps nothing: the amount stays in the
            // vault (and keeps vesting); a broken recipient cannot block others.
            emit Paid(s.to, ok ? part : 0, ok);
        }
        _paying = false;
        // what a recipient refused (or sent back) is still here: it vests again from today
        _vesting = address(this).balance;
    }

    // ---- recipients ----

    function shares() external view returns (Share[] memory) {
        return _shares;
    }

    function pendingShares() external view returns (Share[] memory) {
        return _pending;
    }

    /// Announces new recipients; they apply DELAY later.
    function proposeShares(Share[] calldata next) external onlyGovernance {
        _check(next);
        delete _pending;
        for (uint256 i = 0; i < next.length; i++) _pending.push(next[i]);
        pendingAt = uint64(block.timestamp + DELAY);
        emit SharesProposed(pendingAt);
    }

    function cancelShares() external onlyGovernance {
        delete _pending;
        pendingAt = 0;
    }

    /// After the delay, anyone may switch to the announced recipients.
    /// What vested before the switch is paid to the old ones first.
    function applyShares() external {
        // not from inside release() (a recipient): the list being paid never changes under it
        if (_paying || pendingAt == 0 || block.timestamp < pendingAt) revert TooEarly();
        // Take the pending list first: a recipient called during release()
        // must not be able to apply it a second time.
        Share[] memory next = _pending;
        delete _pending;
        pendingAt = 0;
        release();
        delete _shares;
        for (uint256 i = 0; i < next.length; i++) _shares.push(next[i]);
        emit SharesApplied();
    }

    function setGovernance(address next) external onlyGovernance {
        governance = next;
        emit GovernanceChanged(next);
    }

    // ---- internals ----

    function _vested(uint256 bal, uint256 n) private pure returns (uint256) {
        return bal - (bal * _rpow(DAILY_KEEP, n)) / RAY;
    }

    /// Moves what vested since the last checkpoint into _due; everything else held (including money that
    /// just arrived) vests from today.
    function _checkpoint() private {
        uint256 today = daysElapsed();
        uint256 n = today - releasedDays;
        if (n != 0) {
            _due += _vested(_vesting, n);
            releasedDays = uint64(today);
        }
        _vesting = address(this).balance - _due;
    }

    function _check(Share[] memory s) private pure {
        if (s.length == 0 || s.length > MAX_SHARES) revert BadShares();
        uint256 total;
        for (uint256 i = 0; i < s.length; i++) {
            if (s[i].to == address(0) || s[i].bps == 0) revert BadShares();
            total += s[i].bps;
        }
        if (total != 10_000) revert BadShares();
    }

    /// x^n in RAY fixed point (exponentiation by squaring, rounding half up).
    function _rpow(uint256 x, uint256 n) private pure returns (uint256 z) {
        z = n % 2 != 0 ? x : RAY;
        for (n /= 2; n != 0; n /= 2) {
            x = (x * x + RAY / 2) / RAY;
            if (n % 2 != 0) z = (z * x + RAY / 2) / RAY;
        }
    }
}

contracts/RiskForecasts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRiskPair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
}

interface IRiskFlags {
    function isAddressFlagged(uint256 chainId, address who) external view returns (bool, uint8);
    function isContractFlagged(address who) external view returns (bool, uint8);
}

interface IForesightResolver {
    function openEvent(bytes32 topic, uint64 commitEnd, uint64 revealEnd) external returns (uint256);
    function closeCommits(uint256 id) external;
    function resolve(uint256 id, uint8 outcome) external;
}

/// @title RiskForecasts: testnet risk forecasts on tokens, resolved from on-chain facts
/// @notice TESTNET ONLY. Stakes are testnet ZETAPHY, which has no value; this is a
///         forecasting tool that turns people's and models' judgement into labelled
///         data for Neuro, not a product to make money with.
///
///         A forecast question is one of:
///           - LiquidityDrop: "the other side of token X's pool loses at least N% of
///             what it held when the question was opened, before the deadline"
///           - Flagged: "token X is flagged in the ThreatRegistry before the deadline"
///         Forecasters back Yes or No with a testnet stake until the question closes
///         (and never while the condition already holds). The answer comes only from
///         chain state: anyone may `poke` a question, which reads the pair's reserves or
///         the ThreatRegistry; a drop counts once it has held for `confirmDelay` (so a
///         flash swap or a single-block dip is not enough). `propose` then states the
///         answer the facts give, and a dispute window lets anyone post a bond to send it
///         to governance (e.g. the pool moved for an honest migration, or the flag was a
///         mistake). Accurate forecasters share the stakes of the inaccurate side; a void
///         question refunds everyone.
///
///         When a ForesightRegistry is set, every question is also a Foresight event, so
///         models' committed probabilities are scored (Brier) against the same answer.
contract RiskForecasts {
    enum Kind { LiquidityDrop, Flagged }
    enum Status { None, Open, Proposed, Disputed, Final }
    enum Answer { None, No, Yes, Void }

    struct Question {
        address token;
        address pair;
        Kind kind;
        uint16 dropBps;       // LiquidityDrop: the drop that makes the answer Yes
        uint64 createdAt;
        uint64 closeAt;       // forecasts until
        uint64 deadline;      // the condition must be seen by then
        uint112 baseReserve;  // the pool's other side when opened
        address creator;
    }

    struct State {
        Status status;
        Answer proposed;
        Answer answer;
        uint64 seenAt;        // first poke that saw the condition (0: not holding)
        bool confirmed;       // seen again at least confirmDelay later, before the deadline (+ confirmDelay)
        uint64 proposedAt;
        address disputer;
        uint128 yes;
        uint128 no;
        uint256 foresightId;
    }

    uint256 public constant BPS = 10_000;
    uint64 public constant MIN_HORIZON = 1 hours;
    uint64 public constant MAX_HORIZON = 180 days;

    address public governance;
    IRiskFlags public threats;
    IForesightResolver public foresight;
    uint64 public confirmDelay = 1 hours;
    uint64 public disputeWindow = 1 days;
    uint64 public revealWindow = 1 days;      // Foresight reveal period after forecasts close
    uint128 public disputeBond = 10 ether;
    uint128 public minStake = 0.01 ether;
    uint112 public minReserve = 1 ether;      // smaller pools are too easy to move

    uint256 public count;
    mapping(uint256 => Question) public questions;
    mapping(uint256 => State) public states;
    mapping(uint256 => mapping(address => uint128)) public yesOf;
    mapping(uint256 => mapping(address => uint128)) public noOf;
    mapping(uint256 => mapping(address => bool)) public claimed;
    mapping(address => uint256) public owed;

    event Opened(uint256 indexed id, address indexed token, address pair, Kind kind, uint16 dropBps, uint64 closeAt, uint64 deadline, uint112 baseReserve, uint256 foresightId);
    event Forecast(uint256 indexed id, address indexed who, bool yes, uint256 amount);
    event Seen(uint256 indexed id, bool holding, bool confirmed, uint256 reserve);
    event Proposed(uint256 indexed id, Answer answer);
    event Disputed(uint256 indexed id, address indexed by, uint256 bond);
    event Finalized(uint256 indexed id, Answer answer, bool byGovernance);
    event Claimed(uint256 indexed id, address indexed who, uint256 amount);
    event ParamsSet(uint64 confirmDelay, uint64 disputeWindow, uint64 revealWindow, uint128 disputeBond, uint128 minStake, uint112 minReserve);
    event GovernanceSet(address governance);

    error NotGovernance();
    error BadParams();
    error BadPair();
    error AlreadyTrue();
    error WrongStatus();
    error ForecastsClosed();
    error StakeTooSmall();
    error NotYet();
    error TooLate();
    error BadBond();
    error NothingToClaim();
    error SendFailed();

    constructor(address governance_, IRiskFlags threats_, IForesightResolver foresight_) {
        governance = governance_;
        threats = threats_;
        foresight = foresight_;
    }

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    function setGovernance(address g) external onlyGov {
        governance = g;
        emit GovernanceSet(g);
    }

    function setParams(uint64 confirm, uint64 disputeFor, uint64 reveal, uint128 bond, uint128 stake, uint112 reserve) external onlyGov {
        if (disputeFor < 1 hours || disputeFor > 30 days || confirm > 7 days || reveal < 1 hours || reveal > 30 days || stake == 0) revert BadParams();
        (confirmDelay, disputeWindow, revealWindow, disputeBond, minStake, minReserve) = (confirm, disputeFor, reveal, bond, stake, reserve);
        emit ParamsSet(confirm, disputeFor, reveal, bond, stake, reserve);
    }

    // ------------------------------------------------------------------ open

    /// @param horizon  seconds from now to the deadline
    /// @param window   seconds from now during which forecasts are taken (<= horizon)
    function open(address token, address pair, Kind kind, uint16 dropBps, uint64 horizon, uint64 window) external returns (uint256 id) {
        if (horizon < MIN_HORIZON || horizon > MAX_HORIZON || window == 0 || window > horizon || token == address(0)) revert BadParams();
        uint112 base;
        if (kind == Kind.LiquidityDrop) {
            if (dropBps < 1000 || dropBps > BPS) revert BadParams();
            base = _otherReserve(token, pair);
            if (base < minReserve) revert BadPair();
        } else {
            if (address(threats) == address(0)) revert BadParams();
            if (_flagged(token)) revert AlreadyTrue();
            dropBps = 0;
        }
        id = ++count;
        uint64 nowT = uint64(block.timestamp);
        questions[id] = Question(token, pair, kind, dropBps, nowT, nowT + window, nowT + horizon, base, msg.sender);
        State storage s = states[id];
        s.status = Status.Open;
        if (address(foresight) != address(0)) {
            s.foresightId = foresight.openEvent(keccak256(abi.encode(address(this), id)), nowT + window, nowT + window + revealWindow);
        }
        emit Opened(id, token, pair, kind, dropBps, nowT + window, nowT + horizon, base, s.foresightId);
    }

    // ------------------------------------------------------------------ forecast

    function forecast(uint256 id, bool yes) external payable {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open || block.timestamp >= q.closeAt) revert ForecastsClosed();
        if (msg.value < minStake || msg.value > type(uint128).max) revert StakeTooSmall();
        // never while the answer is already being decided
        if (s.seenAt != 0 || _holds(q)) revert AlreadyTrue();
        if (yes) { yesOf[id][msg.sender] += uint128(msg.value); s.yes += uint128(msg.value); }
        else { noOf[id][msg.sender] += uint128(msg.value); s.no += uint128(msg.value); }
        emit Forecast(id, msg.sender, yes, msg.value);
    }

    // ------------------------------------------------------------------ resolve from chain facts

    /// Reads the chain for a question (anyone; a keeper runs it on a schedule).
    function poke(uint256 id) public {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open || s.confirmed) return;
        uint64 nowT = uint64(block.timestamp);
        bool holding = _holds(q);
        uint256 reserve = q.kind == Kind.LiquidityDrop ? _otherReserve(q.token, q.pair) : 0;
        if (holding) {
            if (s.seenAt == 0) {
                if (nowT <= q.deadline) {
                    s.seenAt = nowT;
                    // forecasts and Foresight commits stop the moment it is seen
                    if (s.foresightId != 0 && nowT < q.closeAt) foresight.closeCommits(s.foresightId);
                    if (nowT < q.closeAt) q.closeAt = nowT;
                }
            }
            if (s.seenAt != 0 && nowT >= s.seenAt + _confirmFor(q)) s.confirmed = true;
        } else if (s.seenAt != 0) {
            s.seenAt = 0; // it did not hold: start again
        }
        emit Seen(id, holding, s.confirmed, reserve);
    }

    /// States the answer the facts give: Yes once confirmed, No once the deadline (+ confirm time) passed without it.
    function propose(uint256 id) external {
        Question storage q = questions[id];
        State storage s = states[id];
        if (s.status != Status.Open) revert WrongStatus();
        poke(id);
        Answer a;
        if (s.confirmed) a = Answer.Yes;
        else if (block.timestamp > q.deadline + _confirmFor(q) && s.seenAt == 0) a = Answer.No;
        else revert NotYet(); // (past that time, the poke above either confirmed a holding condition or reset it)
        s.status = Status.Proposed;
        s.proposed = a;
        s.proposedAt = uint64(block.timestamp);
        emit Proposed(id, a);
    }

    function dispute(uint256 id) external payable {
        State storage s = states[id];
        if (s.status != Status.Proposed) revert WrongStatus();
        if (block.timestamp >= s.proposedAt + disputeWindow) revert TooLate();
        if (msg.value != disputeBond) revert BadBond();
        s.status = Status.Disputed;
        s.disputer = msg.sender;
        emit Disputed(id, msg.sender, msg.value);
    }

    /// Governance answers a disputed question. The bond goes back if the proposed answer changed, else to governance.
    function settleDispute(uint256 id, Answer a) external onlyGov {
        State storage s = states[id];
        if (s.status != Status.Disputed) revert WrongStatus();
        if (a == Answer.None) revert BadParams();
        owed[a != s.proposed ? s.disputer : governance] += disputeBond;
        _final(id, a, true);
    }

    function finalize(uint256 id) external {
        State storage s = states[id];
        if (s.status != Status.Proposed) revert WrongStatus();
        if (block.timestamp < s.proposedAt + disputeWindow) revert NotYet();
        _final(id, s.proposed, false);
    }

    function _final(uint256 id, Answer a, bool byGov) private {
        State storage s = states[id];
        s.status = Status.Final;
        s.answer = a;
        if (s.foresightId != 0) foresight.resolve(s.foresightId, uint8(a));
        emit Finalized(id, a, byGov);
    }

    // ------------------------------------------------------------------ pay out

    /// What `who` gets back from a final question.
    function payoutOf(uint256 id, address who) public view returns (uint256) {
        State storage s = states[id];
        if (s.status != Status.Final || claimed[id][who]) return 0;
        uint256 y = yesOf[id][who];
        uint256 n = noOf[id][who];
        uint256 total = uint256(s.yes) + s.no;
        if (s.answer == Answer.Void) return y + n;
        uint256 winStake = s.answer == Answer.Yes ? y : n;
        uint256 winTotal = s.answer == Answer.Yes ? s.yes : s.no;
        if (winTotal == 0) return y + n; // nobody was right: everyone gets their stake back
        return (winStake * total) / winTotal;
    }

    function claim(uint256 id, address who) external {
        uint256 amount = payoutOf(id, who);
        if (amount == 0) revert NothingToClaim();
        claimed[id][who] = true;
        owed[who] += amount;
        emit Claimed(id, who, amount);
    }

    function withdraw() external {
        uint256 a = owed[msg.sender];
        if (a == 0) revert NothingToClaim();
        owed[msg.sender] = 0;
        (bool ok,) = msg.sender.call{value: a}("");
        if (!ok) revert SendFailed();
    }

    // ------------------------------------------------------------------ facts

    function _confirmFor(Question storage q) private view returns (uint64) {
        return q.kind == Kind.Flagged ? 0 : confirmDelay; // a flag already took a quorum of runners
    }

    function _holds(Question storage q) private view returns (bool) {
        if (q.kind == Kind.Flagged) return _flagged(q.token);
        uint256 r = _otherReserve(q.token, q.pair);
        return r * BPS <= uint256(q.baseReserve) * (BPS - q.dropBps);
    }

    function _flagged(address token) private view returns (bool) {
        if (address(threats) == address(0)) return false;
        (bool a,) = threats.isAddressFlagged(block.chainid, token);
        if (a) return true;
        (bool c,) = threats.isContractFlagged(token);
        return c;
    }

    /// The reserve of the pool's other token (the liquidity a holder of `token` can sell into).
    function _otherReserve(address token, address pair) private view returns (uint112) {
        if (pair.code.length == 0) revert BadPair();
        address t0 = IRiskPair(pair).token0();
        address t1 = IRiskPair(pair).token1();
        if (t0 != token && t1 != token) revert BadPair();
        (uint112 r0, uint112 r1,) = IRiskPair(pair).getReserves();
        return t0 == token ? r1 : r0;
    }

    /// The other side's reserve now (for pages and keepers).
    function reserveNow(uint256 id) external view returns (uint256) {
        Question storage q = questions[id];
        return q.kind == Kind.LiquidityDrop ? _otherReserve(q.token, q.pair) : 0;
    }

    function holdsNow(uint256 id) external view returns (bool) {
        return _holds(questions[id]);
    }
}

contracts/SaphanAccounts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan accounts: one account address on every Saphan chain, controlled from ZETAPHY
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited.
///
///         SaphanAccountFactory sits at the same address on every Saphan chain (deployed by one fresh key as its
///         first transaction there, so CREATE gives the same address whatever its constructor arguments). Each user
///         (an address on ZETAPHY, the "owner") has one SaphanAccount per chain, made with CREATE2 (salt = owner,
///         init code = SaphanAccount + owner): the same factory and the same init code give the same address on every
///         chain. src/saphanaccounts.js derives it off-chain. Anyone may deploy it (deploy(owner)); it is the
///         owner's either way.
///
///         Who controls it:
///           - on ZETAPHY (the home chain): the owner, directly (execute);
///           - on any other chain: only the owner's calls from ZETAPHY through that chain's Saphan Gateway:
///             ZetaphyGateway.withdrawAndCall(target = the account, data = abi.encode(Call[])). The SaphanSourceGateway
///             there calls account.onSaphanCall(77390, owner, data) with the ETH, after the route's checks; the
///             account checks the Gateway, the chain and the owner, then runs the calls (all or none: a failure makes
///             the Gateway refund the ETH to revertTo, normally the account itself).
///         The owner's key is never used on the other chains: a contract owner on ZETAPHY (a multisig, a
///         QuantumWallet) controls its accounts everywhere the same way, and the same address on another chain
///         controlled by someone else has no power over them.

interface IAccountFactory {
    function homeChainId() external view returns (uint256);
    function gateway() external view returns (address);
}

/// SaphanSourceGateway.claim: ETH of failed calls, paid to the caller.
interface IAccountGateway {
    function claim() external;
}

contract SaphanAccount {
    struct Call {
        address target;
        uint256 value;
        bytes data;
    }

    address public immutable factory;
    address public immutable owner;   // on ZETAPHY
    uint256 private entered;

    event Executed(uint256 calls, uint256 srcChainId);
    event Received(uint256 srcChainId, address sender, address token, uint256 amount);

    error NotOwner();
    error NotGateway();
    error CallFailed(uint256 index, bytes reason);
    error Reentered();

    constructor(address owner_) {
        factory = msg.sender;
        owner = owner_;
    }

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    /// On ZETAPHY: the owner runs calls from the account.
    function execute(Call[] calldata calls) external payable nonReentrant {
        if (msg.sender != owner || block.chainid != IAccountFactory(factory).homeChainId()) revert NotOwner();
        _run(calls);
        emit Executed(calls.length, block.chainid);
    }

    /// On another chain: the owner's calls from ZETAPHY, through this chain's SaphanSourceGateway (ISaphanReceiver).
    function onSaphanCall(uint256 srcChainId, address sender, bytes calldata data) external payable nonReentrant {
        address gw = IAccountFactory(factory).gateway();
        if (gw == address(0) || msg.sender != gw) revert NotGateway();
        if (srcChainId != IAccountFactory(factory).homeChainId() || sender != owner) revert NotOwner();
        _run(abi.decode(data, (Call[])));
        emit Executed(0, srcChainId);
    }

    /// Anyone: ETH the Gateway keeps for this account (a failed call with revertTo = this account) comes into the
    /// account. It cannot happen inside a Gateway call (the Gateway is locked then), so it is its own transaction.
    function pullRefunds() external nonReentrant {
        address gw = IAccountFactory(factory).gateway();
        if (gw == address(0)) revert NotGateway();
        IAccountGateway(gw).claim();
    }

    /// A refund of a call this account made through the Gateway (ISaphanReceiver): the ETH stays here.
    function onSaphanRevert(address, uint256, bytes calldata) external payable {
        address gw = IAccountFactory(factory).gateway();
        if (gw == address(0) || msg.sender != gw) revert NotGateway();
    }

    /// On ZETAPHY, money sent here from another chain through a ZetaphyGateway (ISaphanCallee): the tokens stay
    /// here; no call runs (only the owner runs calls).
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256 amount, bytes calldata) external {
        emit Received(srcChainId, sender, token, amount);
    }

    /// The callers checked who asks (owner on ZETAPHY, owner through the Gateway elsewhere); checked again here.
    function _run(Call[] memory calls) private {
        if (msg.sender != owner && msg.sender != IAccountFactory(factory).gateway()) revert NotOwner();
        for (uint256 i = 0; i < calls.length; i++) {
            (bool ok, bytes memory reason) = calls[i].target.call{value: calls[i].value}(calls[i].data);
            if (!ok) revert CallFailed(i, reason);
        }
    }

    receive() external payable {}
}

/// @title SaphanAccountFactory: makes SaphanAccounts at their derived address (the same on every chain)
contract SaphanAccountFactory is IAccountFactory {
    uint256 public immutable homeChainId;   // ZETAPHY (77390 on testnet)
    address public immutable gateway;       // this chain's SaphanSourceGateway (zero on ZETAPHY)

    event Deployed(address indexed owner, address account);

    constructor(uint256 homeChainId_, address gateway_) {
        require(homeChainId_ != 0 && (block.chainid == homeChainId_) == (gateway_ == address(0)), "config");
        homeChainId = homeChainId_;
        gateway = gateway_;
    }

    /// keccak256 of the account's init code: SaphanAccount's creation code followed by abi.encode(owner).
    function accountCodeHash(address owner) public pure returns (bytes32) {
        return keccak256(bytes.concat(type(SaphanAccount).creationCode, abi.encode(owner)));
    }

    /// The owner's account on this chain (and on every chain with this factory address).
    function accountOf(address owner) public view returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), address(this), bytes32(uint256(uint160(owner))), accountCodeHash(owner))))));
    }

    /// Anyone: deploys the owner's account here (once; afterwards it returns the address).
    function deploy(address owner) external returns (address account) {
        require(owner != address(0), "owner");
        account = accountOf(owner);
        if (account.code.length > 0) return account;
        address made = address(new SaphanAccount{salt: bytes32(uint256(uint160(owner)))}(owner));
        require(made == account, "derive");
        emit Deployed(owner, account);
    }
}

contracts/SaphanAggLane.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// The airlock calls this lane makes (BridgeAirlock).
interface IAggAirlock {
    function attest(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
}

/// @title SaphanAggLane: one aggregated post-quantum proof instead of one transaction per attester (Saphan PR 4, S1)
/// @notice Testnet only, not audited (docs/SAPHAN-PR4.md).
///
///   A committee of n attesters (e.g. the Neuro runners that watch a route's lockbox) each hold an ML-DSA-44 key.
///   Instead of n transactions per transfer (NeuroLane: one vote each), they sign ONE digest off chain and anyone
///   brings the certificate on chain in one call, checked once:
///
///     certificate = threshold x [public key (1312) | signature (2420)], keys sorted by keccak256(key), strictly
///                   increasing (each member counts once), every key a member of the current committee,
///                   every signature checked by ZETAPHY's ML-DSA precompile (0x...0900), like PQMultisigIsm.
///
///   What they sign is a Merkle ROOT of transfers (src/saphanagg.js): one transfer (root = its leaf, no path) or a
///   batch of many, each later attested with its Merkle path. A batch costs one certificate for all its transfers.
///     leaf   = keccak256(bytes.concat(keccak256(abi.encode(transferId))))   (BridgeAirlock.transferId)
///     node   = keccak256(min(a, b) | max(a, b))
///     digest = keccak256(abi.encode(TAG, block.chainid, this lane, epoch, root))
///
///   This contract is ONE lane of a BridgeAirlock (its own controller): the airlock still needs another independent
///   lane (e.g. HyperlaneLane), its quarantine, vetoes, marks, Neuro flags and BridgeGuard's daily limits. A root
///   counts only in the committee epoch that signed it: a new committee (governance) retires every root of the old one.
///   No admin key: governance is the ZetaphyTimelock, and the committee it sets is bounded (2 <= t, 2t > n, n <= 32).
contract SaphanAggLane {
    address public constant MLDSA = 0x0000000000000000000000000000000000000900;
    uint256 public constant PK_BYTES = 1312;
    uint256 public constant SIG_BYTES = 2420;
    uint256 public constant ENTRY = PK_BYTES + SIG_BYTES;
    uint256 public constant MAX_MEMBERS = 32;
    uint256 public constant MAX_DEPTH = 24;      // a batch of up to 2^24 transfers
    bytes32 public constant TAG = keccak256("saphan/agg/v1");

    struct Transfer {
        uint256 srcChainId;
        address srcContract;
        uint256 srcNonce;
        address sender;
        address to;
        uint256 amount;
    }

    IAggAirlock public immutable airlock;
    address public governance;                   // the ZetaphyTimelock
    uint64 public epoch;                         // bumped by every committee change
    uint8 public threshold;
    bytes32[] private _members;                  // keccak256 of the members' ML-DSA-44 keys, increasing
    mapping(bytes32 => uint64) public memberEpoch;   // key hash => the epoch it is a member in
    mapping(bytes32 => uint64) public rootEpoch;     // root => the epoch whose committee certified it (0: none)
    /// BridgeAirlock.Twice(): the airlock already counts this lane's attestation of a transfer (it alone knows
    /// whether a lane removed and added again may attest again, so the lane keeps no record of its own).
    bytes4 private constant AIRLOCK_TWICE = bytes4(keccak256("Twice()"));

    event CommitteeSet(uint64 indexed epoch, bytes32[] members, uint8 threshold);
    event GovernanceSet(address governance);
    event RootCertified(bytes32 indexed root, uint64 indexed epoch, address by);
    event LaneAttested(bytes32 indexed id, bytes32 indexed root);

    error OnlyGovernance();
    error BadCommittee();
    error BadCertificate(uint256 entry);
    error Known();
    error UnknownRoot();
    error BadProof();
    error Twice();
    error Length();

    constructor(IAggAirlock airlock_, address governance_, bytes32[] memory members_, uint8 threshold_) {
        if (address(airlock_) == address(0) || governance_ == address(0)) revert BadCommittee();
        airlock = airlock_;
        governance = governance_;
        _setCommittee(members_, threshold_);
    }

    /// BridgeAirlock.independentLanes: this committee is its own controller (one lane).
    function laneController() external view returns (address) { return address(this); }

    function committee() external view returns (bytes32[] memory members, uint8 t, uint64 e) {
        return (_members, threshold, epoch);
    }

    // ---- governance (the ZetaphyTimelock) ----

    /// A new committee: key hashes strictly increasing, 2 <= t, more than half must sign (2t > n), at most 32 keys.
    /// Every root the old committee certified stops counting.
    function setCommittee(bytes32[] calldata members_, uint8 t) external {
        if (msg.sender != governance) revert OnlyGovernance();
        _setCommittee(members_, t);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert OnlyGovernance();
        if (g == address(0)) revert BadCommittee();
        governance = g;
        emit GovernanceSet(g);
    }

    function _setCommittee(bytes32[] memory m, uint8 t) private {
        uint256 n = m.length;
        if (n > MAX_MEMBERS || t < 2 || t > n || 2 * uint256(t) <= n) revert BadCommittee();
        uint64 e = epoch + 1;
        bytes32 last = bytes32(0);
        for (uint256 i = 0; i < n; ++i) {
            if (m[i] <= last) revert BadCommittee();   // nonzero, increasing, no repeats
            last = m[i];
            memberEpoch[m[i]] = e;
        }
        epoch = e;
        threshold = t;
        _members = m;
        emit CommitteeSet(e, m, t);
    }

    // ---- certificates ----

    /// What the committee signs for `root` now (src/saphanagg.js certDigest).
    function certDigest(bytes32 root) public view returns (bytes32) {
        return keccak256(abi.encode(TAG, block.chainid, address(this), epoch, root));
    }

    /// Anyone: brings the committee's certificate of `root` (threshold entries, keys hash-sorted).
    function certify(bytes32 root, bytes calldata cert) public {
        if (root == bytes32(0)) revert UnknownRoot();
        uint64 e = epoch;
        if (rootEpoch[root] == e) revert Known();
        _verify(certDigest(root), cert);
        rootEpoch[root] = e;
        emit RootCertified(root, e, msg.sender);
    }

    function _verify(bytes32 d, bytes calldata cert) private view {
        uint256 t = threshold;
        if (cert.length != t * ENTRY) revert Length();
        uint64 e = epoch;
        bytes32 last = bytes32(0);
        for (uint256 i = 0; i < t; ++i) {
            bytes32 h = _entry(d, cert[i * ENTRY:(i + 1) * ENTRY]);
            if (h <= last || memberEpoch[h] != e) revert BadCertificate(i);
            last = h;
        }
    }

    /// One certificate entry: the key's hash, after its signature of `d` passed the precompile (else zero).
    function _entry(bytes32 d, bytes calldata x) private view returns (bytes32) {
        bytes calldata pk = x[:PK_BYTES];
        (bool ok, bytes memory ret) = MLDSA.staticcall(bytes.concat(bytes1(uint8(44)), d, pk, x[PK_BYTES:]));
        if (!ok || ret.length != 32 || uint256(bytes32(ret)) != 1) return bytes32(0);
        return keccak256(pk);
    }

    // ---- attesting ----

    /// The airlock's id of a transfer (BridgeAirlock.transferId, same encoding) and its leaf here.
    function transferId(Transfer calldata x) public pure returns (bytes32) {
        return keccak256(abi.encode(x.srcChainId, x.srcContract, x.srcNonce, x.sender, x.to, x.amount));
    }

    function leaf(bytes32 id) public pure returns (bytes32) { return keccak256(bytes.concat(keccak256(abi.encode(id)))); }

    /// Anyone: one transfer of a certified root, with its Merkle path, attested to the airlock.
    function attest(Transfer calldata x, bytes32 root, bytes32[] calldata proof) external {
        if (!_attest(x, root, proof)) revert Twice();
    }

    /// Anyone: many transfers of one certified root. Transfers already attested are skipped; a bad path reverts.
    function attestMany(Transfer[] calldata xs, bytes32 root, bytes32[][] calldata proofs) external returns (uint256 n) {
        if (xs.length != proofs.length) revert Length();
        for (uint256 i = 0; i < xs.length; ++i) if (_attest(xs[i], root, proofs[i])) ++n;
    }

    /// Anyone, one call: certify `root` (unless it already is, in this epoch) and attest `x` under it. With a
    /// one-transfer root (root = leaf, empty path) this is "one aggregated proof per message".
    function certifyAndAttest(Transfer calldata x, bytes32 root, bytes32[] calldata proof, bytes calldata cert) external {
        if (rootEpoch[root] != epoch) certify(root, cert);
        if (!_attest(x, root, proof)) revert Twice();
    }

    function _attest(Transfer calldata x, bytes32 root, bytes32[] calldata proof) private returns (bool) {
        if (root == bytes32(0) || rootEpoch[root] != epoch) revert UnknownRoot();
        if (proof.length > MAX_DEPTH) revert BadProof();
        bytes32 id = transferId(x);
        bytes32 h = leaf(id);
        for (uint256 i = 0; i < proof.length; ++i) {
            bytes32 p = proof[i];
            h = h < p ? keccak256(abi.encode(h, p)) : keccak256(abi.encode(p, h));
        }
        if (h != root) revert BadProof();
        try airlock.attest(x.srcChainId, x.srcContract, x.srcNonce, x.sender, x.to, x.amount) {
            emit LaneAttested(id, root);
            return true;
        } catch (bytes memory err) {
            if (err.length == 4 && bytes4(err) == AIRLOCK_TWICE) return false;
            assembly { revert(add(err, 32), mload(err)) }
        }
    }
}

contracts/SaphanBitVM.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// BtcLightClient as this contract sees it (contracts/BtcLightClient.sol: proof of work, heaviest chain, confirmations).
interface IBitVMSpvClient {
    function verifyTx(bytes calldata rawTx, bytes32 blockHash, uint256 index, bytes32[] calldata siblings, uint256 minConfirmations)
        external view returns (bytes32 txid);
}

/// The BTC route's bridged token on ZETAPHY (BridgedToken: 18 decimals, 1 sat = 10^10 units).
interface IBitVMToken {
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanBtcWithdrawals: optimistic BTC withdrawals, a BitVM2-style claim / challenge / slash game
/// @notice PROTOTYPE, testnet only, not audited (docs/SAPHAN-PR6.md, item S7). There is NO Bitcoin script here and no
///         peg-out on Bitcoin: the game runs on ZETAPHY, and the "disprove" step is simplified to "prove the payment
///         by SPV or lose the bond". What it shows is the shape of BitVM2's operator flow:
///
///           1. request(amount, btcScript): a holder of the bridged BTC token escrows it here and names where the BTC
///              should go on Bitcoin (a scriptPubKey).
///           2. An operator (anyone who bonded ZTPHY here) FRONTS the BTC from its own coins: a Bitcoin transaction
///              with an output paying btcScript at least the requested sats, and an OP_RETURN that commits to the
///              withdrawal and to itself: "ZTPHYW" || withdrawal id (8 bytes, big-endian) || operator (20 bytes).
///              Then claim(id, txid, vout): it asks to be reimbursed with the escrowed tokens.
///           3. During CHALLENGE_WINDOW anyone who sees that txid:vout does not exist, does not pay the script, or
///              does not carry that commitment may challenge(id), posting challengeBond.
///           4. A challenged operator answers within RESPONSE_WINDOW with prove(): the raw transaction, its block and
///              Merkle branch; BtcLightClient checks the proof of work and minConfirmations. Proven: the operator is
///              reimbursed and takes the challenger's bond. Not proven in time: slash(id) by anyone: the holder gets
///              the escrow back plus half the operator's per-claim bond, the challenger its bond plus the other half.
///           5. Not challenged: finalize(id) after the window reimburses the operator.
///
///         Safety properties (tests: test/saphanbitvm.test.js):
///           - a holder either gets the escrow back or the operator had to be able to prove the BTC payment (or no
///             watcher looked: the optimistic assumption, ONE honest watcher is enough);
///           - the OP_RETURN binds the payment to one withdrawal AND one operator: another operator cannot claim a
///             payment it did not make, and one payment serves one withdrawal (paymentUsed);
///           - each claim locks bondPerClaim of the operator's bond until it is settled: an operator cannot withdraw
///             a bond that a pending claim could still lose; unlocked bond can be withdrawn at once.
///         Payouts are pulled (withdraw()); every parameter is fixed at deploy; there is no owner, admin or pause.
///         What a real BitVM2 adds: the reimbursement comes from a Bitcoin peg UTXO through pre-signed transactions,
///         and the disprove runs as a Bitcoin script (the SNARK verifier split into chunks). Not here.
contract SaphanBtcWithdrawals {
    enum State { None, Requested, Claimed, Challenged, Paid, Slashed, Cancelled }

    struct Withdrawal {
        address holder;
        uint64 sats;
        uint64 requestedAt;
        State state;
        address operator;
        uint64 claimEnds;     // end of the challenge window
        uint64 respondBy;     // end of the response window (when challenged)
        uint32 vout;
        address challenger;
        bytes32 scriptHash;   // keccak256 of the destination scriptPubKey
        bytes32 txid;         // the claimed payment (internal byte order, as BtcLightClient returns it)
        uint256 amount;       // escrowed token units (sats x 10^10)
    }

    uint256 public constant SATS_TO_WEI = 1e10;
    bytes6 public constant TAG = "ZTPHYW";

    IBitVMSpvClient public immutable client;
    IBitVMToken public immutable token;
    uint256 public immutable minConfirmations;
    uint256 public immutable bondPerClaim;      // native ZTPHY locked per open claim
    uint256 public immutable challengeBond;     // native ZTPHY a challenger posts
    uint64 public immutable claimTtl;           // after this, an unclaimed request can be cancelled
    uint64 public immutable challengeWindow;
    uint64 public immutable responseWindow;
    uint64 public immutable minSats;

    Withdrawal[] internal ws;
    mapping(address => uint256) public bonded;       // native, per operator
    mapping(address => uint256) public lockedBond;   // part of bonded held by open claims
    mapping(address => uint256) public owedNative;   // pull payouts
    mapping(address => uint256) public owedToken;    // pull payouts
    mapping(bytes32 => bool) public paymentUsed;     // keccak256(txid, vout)
    uint256 public escrowed;                         // tokens held for open requests
    uint256 public tokenLiabilities;                 // escrowed + every owedToken: what the token balance must cover
    uint256 private unlocked = 1;

    event Requested(uint256 indexed id, address indexed holder, uint256 amount, uint64 sats, bytes btcScript);
    event Cancelled(uint256 indexed id);
    event Bonded(address indexed operator, uint256 amount);
    event Unbonded(address indexed operator, uint256 amount);
    event Claimed(uint256 indexed id, address indexed operator, bytes32 txid, uint32 vout, uint64 claimEnds);
    event Challenged(uint256 indexed id, address indexed challenger, uint64 respondBy);
    event Proven(uint256 indexed id, address indexed operator);
    event Reimbursed(uint256 indexed id, address indexed operator, uint256 amount);
    event Slashed(uint256 indexed id, address indexed operator, address indexed challenger, uint256 bond);
    event Withdrawn(address indexed who, uint256 native, uint256 tokens);

    error BadAmount();
    error BadScript();
    error BadState(State s);
    error NotHolder();
    error TooEarly(uint64 at);
    error TooLate(uint64 at);
    error NoBond(uint256 free);
    error BadBond();
    error PaymentUsed();
    error BadPayment(uint256 code); // 1 truncated 2 vout 3 wrong script 4 too little 5 no commitment 6 txid
    error TokenFailed();
    error PayFailed();
    error Reentrancy();
    error Nothing();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(IBitVMSpvClient client_, IBitVMToken token_, uint256 minConfirmations_, uint256 bondPerClaim_, uint256 challengeBond_,
        uint64 claimTtl_, uint64 challengeWindow_, uint64 responseWindow_, uint64 minSats_)
    {
        require(address(client_) != address(0) && address(token_) != address(0) && minConfirmations_ >= 1 && bondPerClaim_ > 0
            && challengeBond_ > 0 && claimTtl_ > 0 && challengeWindow_ >= 1 hours && responseWindow_ >= 1 hours && minSats_ > 0, "config");
        client = client_;
        token = token_;
        minConfirmations = minConfirmations_;
        bondPerClaim = bondPerClaim_;
        challengeBond = challengeBond_;
        claimTtl = claimTtl_;
        challengeWindow = challengeWindow_;
        responseWindow = responseWindow_;
        minSats = minSats_;
    }

    // ---------------------------------------------------------------- holders

    /// Escrows `amount` of the bridged BTC token (a whole number of sats) for BTC sent to `btcScript` on Bitcoin.
    function request(uint256 amount, bytes calldata btcScript) external nonReentrant returns (uint256 id) {
        if (amount == 0 || amount % SATS_TO_WEI != 0 || amount / SATS_TO_WEI < minSats || amount / SATS_TO_WEI > type(uint64).max) revert BadAmount();
        if (btcScript.length == 0 || btcScript.length > 80 || btcScript[0] == 0x6a) revert BadScript(); // never an OP_RETURN
        id = ws.length;
        ws.push(Withdrawal({ holder: msg.sender, sats: uint64(amount / SATS_TO_WEI), requestedAt: uint64(block.timestamp), state: State.Requested,
            operator: address(0), claimEnds: 0, respondBy: 0, vout: 0, challenger: address(0), scriptHash: keccak256(btcScript),
            txid: bytes32(0), amount: amount }));
        escrowed += amount;
        tokenLiabilities += amount;
        emit Requested(id, msg.sender, amount, uint64(amount / SATS_TO_WEI), btcScript);
        // the whole amount must arrive (no fee-on-transfer): the balance covers every liability after the pull
        if (!token.transferFrom(msg.sender, address(this), amount) || token.balanceOf(address(this)) < tokenLiabilities) revert TokenFailed();
    }

    /// The holder, when no operator claimed within claimTtl: the escrow comes back (withdraw()).
    function cancel(uint256 id) external {
        Withdrawal storage w = ws[id];
        if (w.holder != msg.sender) revert NotHolder();
        if (w.state != State.Requested) revert BadState(w.state);
        if (block.timestamp < uint256(w.requestedAt) + claimTtl) revert TooEarly(w.requestedAt + claimTtl);
        w.state = State.Cancelled;
        escrowed -= w.amount;
        owedToken[msg.sender] += w.amount;
        emit Cancelled(id);
    }

    // ---------------------------------------------------------------- operators

    function bond() external payable {
        if (msg.value == 0) revert BadBond();
        bonded[msg.sender] += msg.value;
        emit Bonded(msg.sender, msg.value);
    }

    /// Takes back bond that no open claim holds (to owedNative; withdraw()).
    function unbond(uint256 amount) external {
        uint256 free = bonded[msg.sender] - lockedBond[msg.sender];
        if (amount == 0 || amount > free) revert NoBond(free);
        bonded[msg.sender] -= amount;
        owedNative[msg.sender] += amount;
        emit Unbonded(msg.sender, amount);
    }

    /// The operator says it paid withdrawal `id` on Bitcoin in txid:vout (with the OP_RETURN commitment). Locks
    /// bondPerClaim of its bond and opens the challenge window.
    function claim(uint256 id, bytes32 txid, uint32 vout) external {
        Withdrawal storage w = ws[id];
        if (w.state != State.Requested) revert BadState(w.state);
        uint256 free = bonded[msg.sender] - lockedBond[msg.sender];
        if (free < bondPerClaim) revert NoBond(free);
        bytes32 p = keccak256(abi.encode(txid, vout));
        if (paymentUsed[p]) revert PaymentUsed();
        paymentUsed[p] = true;
        lockedBond[msg.sender] += bondPerClaim;
        w.state = State.Claimed;
        w.operator = msg.sender;
        w.txid = txid;
        w.vout = vout;
        w.claimEnds = uint64(block.timestamp) + challengeWindow;
        emit Claimed(id, msg.sender, txid, vout, w.claimEnds);
    }

    // ---------------------------------------------------------------- watchers

    /// Anyone, during the challenge window, posting exactly challengeBond.
    function challenge(uint256 id) external payable {
        Withdrawal storage w = ws[id];
        if (w.state != State.Claimed) revert BadState(w.state);
        if (block.timestamp >= w.claimEnds) revert TooLate(w.claimEnds);
        if (msg.value != challengeBond) revert BadBond();
        w.state = State.Challenged;
        w.challenger = msg.sender;
        w.respondBy = uint64(block.timestamp) + responseWindow;
        emit Challenged(id, msg.sender, w.respondBy);
    }

    /// Anyone (usually the operator): the payment, proven by SPV. Allowed while claimed (it settles at once) or
    /// challenged before respondBy. The operator is reimbursed; a challenger's bond goes to the operator.
    function prove(uint256 id, bytes calldata rawTx, bytes32 blockHash, uint256 index, bytes32[] calldata siblings) external {
        Withdrawal storage w = ws[id];
        if (w.state == State.Challenged) {
            if (block.timestamp > w.respondBy) revert TooLate(w.respondBy);
        } else if (w.state != State.Claimed) revert BadState(w.state);
        checkPayment(rawTx, w.vout, w.sats, w.scriptHash, id, w.operator);
        address op = w.operator;
        if (w.state == State.Challenged) owedNative[op] += challengeBond;
        emit Proven(id, op);
        _reimburse(id, w);
        // the SPV proof last (a view of the immutable light client; a wrong proof reverts everything above)
        if (client.verifyTx(rawTx, blockHash, index, siblings, minConfirmations) != w.txid) revert BadPayment(6);
    }

    /// Anyone, after the challenge window of an unchallenged claim: the operator is reimbursed.
    function finalize(uint256 id) external {
        Withdrawal storage w = ws[id];
        if (w.state != State.Claimed) revert BadState(w.state);
        if (block.timestamp < w.claimEnds) revert TooEarly(w.claimEnds);
        _reimburse(id, w);
    }

    /// Anyone, after an unanswered challenge: the operator loses bondPerClaim (half to the challenger, half to the
    /// holder), the challenger gets its bond back, the holder gets the escrow back.
    function slash(uint256 id) external {
        Withdrawal storage w = ws[id];
        if (w.state != State.Challenged) revert BadState(w.state);
        if (block.timestamp <= w.respondBy) revert TooEarly(w.respondBy);
        w.state = State.Slashed;
        address op = w.operator;
        uint256 b = bondPerClaim;
        lockedBond[op] -= b;
        bonded[op] -= b;
        escrowed -= w.amount;
        owedToken[w.holder] += w.amount;
        owedNative[w.holder] += b - b / 2;
        owedNative[w.challenger] += challengeBond + b / 2;
        emit Slashed(id, op, w.challenger, b);
    }

    function _reimburse(uint256 id, Withdrawal storage w) private {
        w.state = State.Paid;
        address op = w.operator;
        lockedBond[op] -= bondPerClaim;
        escrowed -= w.amount;
        owedToken[op] += w.amount;
        emit Reimbursed(id, op, w.amount);
    }

    /// Pays the caller everything it is owed (native and tokens).
    function withdraw() external nonReentrant {
        uint256 n = owedNative[msg.sender];
        uint256 t = owedToken[msg.sender];
        if (n == 0 && t == 0) revert Nothing();
        owedNative[msg.sender] = 0;
        owedToken[msg.sender] = 0;
        tokenLiabilities -= t;
        emit Withdrawn(msg.sender, n, t);
        if (t != 0 && !token.transfer(msg.sender, t)) revert TokenFailed();
        if (n != 0) {
            (bool ok, ) = msg.sender.call{value: n}("");
            if (!ok) revert PayFailed();
        }
    }

    // ---------------------------------------------------------------- views

    function count() external view returns (uint256) { return ws.length; }

    function withdrawal(uint256 id) external view returns (Withdrawal memory) { return ws[id]; }

    /// The OP_RETURN payload an operator's payment must carry for withdrawal `id`.
    function commitment(uint256 id, address operator) public pure returns (bytes memory) {
        return abi.encodePacked(TAG, bytes8(bytes32(id << 192)), operator); // the low 8 bytes of id, big-endian (ids < 2^64)
    }

    /// Checks a raw (non-witness) Bitcoin transaction: output `vout` pays the script with keccak256 `scriptHash`
    /// at least `sats`, and some output is OP_RETURN <commitment(id, operator)> (34 bytes). Reverts with BadPayment.
    function checkPayment(bytes calldata t, uint32 vout, uint64 sats, bytes32 scriptHash, uint256 id, address operator) public pure {
        (uint64 value, bytes32 h, bool committed) = _scan(t, vout, keccak256(abi.encodePacked(bytes2(0x6a22), commitment(id, operator))));
        if (h != scriptHash) revert BadPayment(3);
        if (value < sats) revert BadPayment(4);
        if (!committed) revert BadPayment(5);
    }

    /// Output `vout`'s value and script hash, and whether another output's script hashes to `want`.
    function _scan(bytes calldata t, uint32 vout, bytes32 want) private pure returns (uint64 value, bytes32 h, bool committed) {
        uint256 p = _skipInputs(t);
        uint256 outs;
        (outs, p) = _varint(t, p);
        if (vout >= outs) revert BadPayment(2);
        for (uint256 i = 0; i < outs; i++) {
            (uint64 v, bytes32 sh, uint256 next) = _output(t, p);
            p = next;
            if (i == vout) { value = v; h = sh; }
            else if (sh == want) committed = true;
        }
        if (p + 4 != t.length) revert BadPayment(1);      // locktime, nothing after
    }

    /// Where the outputs start (after the version and the inputs).
    function _skipInputs(bytes calldata t) private pure returns (uint256 p) {
        uint256 n;
        (n, p) = _varint(t, 4);                           // version, then the input count
        for (uint256 i = 0; i < n; i++) {
            uint256 len;
            (len, p) = _varint(t, p + 36);                // outpoint, then the script length
            p += len + 4;                                 // script, sequence
        }
    }

    /// One output at `p`: its value, the keccak256 of its script, where the next output starts.
    function _output(bytes calldata t, uint256 p) private pure returns (uint64 value, bytes32 h, uint256 next) {
        if (p + 8 > t.length) revert BadPayment(1);
        value = _le64(t, p);
        uint256 len;
        (len, p) = _varint(t, p + 8);
        if (p + len > t.length) revert BadPayment(1);
        h = keccak256(t[p:p + len]);
        next = p + len;
    }

    function _varint(bytes calldata t, uint256 p) private pure returns (uint256 v, uint256 q) {
        if (p >= t.length) revert BadPayment(1);
        uint8 f = uint8(t[p]);
        if (f < 0xfd) return (f, p + 1);
        uint256 size = f == 0xfd ? 2 : f == 0xfe ? 4 : 8;
        if (p + 1 + size > t.length) revert BadPayment(1);
        for (uint256 i = 0; i < size; i++) v = v | (uint256(uint8(t[p + 1 + i])) << (8 * i));
        q = p + 1 + size;
    }

    function _le64(bytes calldata t, uint256 p) private pure returns (uint64 v) {
        for (uint256 i = 0; i < 8; i++) v = v | (uint64(uint8(t[p + i])) << uint64(8 * i));
    }
}

contracts/SaphanBundles.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan bundles: calls across several routes that all run, or are all refunded
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited.
///
///         A bundle gathers money from several chains on ZETAPHY, then runs every step in ONE ZETAPHY transaction:
///           1. create(legs, plan, deadline): each leg is money the bundle waits for, from a source chain through its
///              ZetaphyGateway (depositAndCall with target = this contract, data = abi.encode(id, leg)), or on ZETAPHY
///              itself (fund). The plan is fixed now (its hash is stored): calls on ZETAPHY (tokens to a target, then
///              target.onSaphanBundle) and calls to other chains (ZetaphyGateway.withdrawAndCall). It must spend
///              exactly what the legs bring, token by token.
///           2. Each leg's delivery is proven by the route itself: a Gateway call is attested by the route's lanes
///              (its deposit address is the call's hash), and the tokens must really be here (balance check), so a
///              fake "gateway" cannot fund a leg.
///           3. execute(id, plan): anyone, once every leg is in and before the deadline. Every step runs or none does
///              (a failing step reverts the whole transaction; the bundle stays funded and can be run again).
///              Calls to other chains carry the Gateway's call hash (event OutSent): track or refund them there.
///           4. Past the deadline without execute: refund(id); each funded leg is owed back to its refundTo on
///              ZETAPHY (claim, a pull). A leg that arrives too late is refused, so the Gateway refunds it on its chain.
///         No signer, no admin: the escrow follows the bundle's own rules.

interface IBundleToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function approve(address spender, uint256 v) external returns (bool);
}

interface IBundleGateway {
    function token() external view returns (address);
    function withdrawAndCall(address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo)
        external payable returns (bytes32);
}

/// What a contract on ZETAPHY implements to be a step of a bundle (it must check msg.sender is SaphanBundles).
interface ISaphanBundleTarget {
    function onSaphanBundle(bytes32 id, address creator, address token, uint256 amount, bytes calldata data) external;
}

contract SaphanBundles {
    struct Leg {
        uint256 srcChainId;   // where the money comes from (block.chainid for a leg funded here)
        address gateway;      // ZetaphyGateway of that route; zero: funded here with fund()
        address token;        // what arrives on ZETAPHY (token(X) for a route)
        address sender;       // who must send it (on its chain; zero: anyone)
        uint256 amount;       // what the leg brings (more is owed back to refundTo)
        address refundTo;     // on ZETAPHY: who gets the leg back when the bundle does not run
    }

    /// A step on ZETAPHY: `amount` of `token` to `target`, then target.onSaphanBundle(id, creator, token, amount, data).
    struct Action {
        address target;
        address token;
        uint256 amount;
        uint64 gasLimit;
        bytes data;
    }

    /// A step to another chain: ZetaphyGateway.withdrawAndCall with data = abi.encode(id, creator, data).
    struct Out {
        address gateway;
        address token;        // must be the Gateway's token
        address target;
        uint256 amount;
        uint256 maxFee;
        uint64 gasLimit;
        address revertTo;     // on that chain: who gets the money when the call fails there
        bytes data;
    }

    struct Plan {
        Action[] actions;
        Out[] outs;
    }

    enum Status { None, Open, Funded, Executed, Refunded }

    struct Bundle {
        address creator;
        uint64 deadline;
        Status status;
        uint8 legCount;
        uint8 fundedCount;
        bytes32 planHash;
    }

    bytes32 public constant TAG = keccak256("saphan/bundle/v1");
    uint256 public constant MAX_LEGS = 8;
    uint256 public constant MAX_STEPS = 8;
    uint64 public constant MAX_DURATION = 30 days;

    mapping(bytes32 => Bundle) public bundles;
    mapping(bytes32 => mapping(uint256 => Leg)) public legs;
    mapping(bytes32 => mapping(uint256 => bool)) public legFunded;
    /// Tokens this contract holds for bundles and refunds (what arrives beyond it is a new leg's money).
    mapping(address => uint256) public accounted;
    /// token -> who -> refunds and excess, taken with claim(token).
    mapping(address => mapping(address => uint256)) public owed;
    uint256 public nonce;
    uint256 private entered;

    event Created(bytes32 indexed id, address indexed creator, uint64 deadline, Leg[] legs, Plan plan);
    event LegFunded(bytes32 indexed id, uint256 indexed leg, uint256 srcChainId, address sender, uint256 received);
    event Executed(bytes32 indexed id, address indexed executor);
    event OutSent(bytes32 indexed id, uint256 indexed step, bytes32 callHash);
    event Refunded(bytes32 indexed id);
    event Claimed(address indexed who, address indexed token, uint256 amount);

    error BadBundle(uint256 code);
    error NotOpen();
    error TooLate();
    error TooEarly();
    error WrongLeg();
    error Short(uint256 have, uint256 need);
    error WrongPlan();
    error Fee();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    function planHash(Plan calldata plan) public pure returns (bytes32) { return keccak256(abi.encode(TAG, plan)); }

    /// Opens a bundle. Every token the legs bring is spent exactly by the plan.
    function create(Leg[] calldata legs_, Plan calldata plan, uint64 deadline) external returns (bytes32 id) {
        if (legs_.length == 0 || legs_.length > MAX_LEGS) revert BadBundle(0);
        uint256 steps = plan.actions.length + plan.outs.length;
        if (steps == 0 || steps > MAX_STEPS) revert BadBundle(1);
        if (deadline <= block.timestamp || deadline > block.timestamp + MAX_DURATION) revert BadBundle(2);
        for (uint256 i = 0; i < legs_.length; i++) {
            Leg calldata l = legs_[i];
            if (l.amount == 0 || l.token == address(0) || l.refundTo == address(0)) revert BadBundle(10 + i);
            if (l.gateway == address(0) && l.srcChainId != block.chainid) revert BadBundle(10 + i);
            _spentEqualsBrought(legs_, plan, l.token);
        }
        for (uint256 i = 0; i < plan.actions.length; i++) {
            Action calldata a = plan.actions[i];
            if (a.target == address(0) || a.target == address(this) || a.amount == 0) revert BadBundle(20 + i);
            _spentEqualsBrought(legs_, plan, a.token);
        }
        for (uint256 i = 0; i < plan.outs.length; i++) {
            Out calldata o = plan.outs[i];
            if (o.gateway == address(0) || o.target == address(0) || o.revertTo == address(0) || o.amount == 0 || o.maxFee > o.amount) revert BadBundle(30 + i);
            _spentEqualsBrought(legs_, plan, o.token);
        }
        id = keccak256(abi.encode(TAG, block.chainid, address(this), msg.sender, nonce++));
        bundles[id] = Bundle(msg.sender, deadline, Status.Open, uint8(legs_.length), 0, planHash(plan));
        for (uint256 i = 0; i < legs_.length; i++) legs[id][i] = legs_[i];
        emit Created(id, msg.sender, deadline, legs_, plan);
    }

    function _spentEqualsBrought(Leg[] calldata legs_, Plan calldata plan, address token) private pure {
        uint256 brought = 0;
        uint256 spent = 0;
        for (uint256 i = 0; i < legs_.length; i++) if (legs_[i].token == token) brought += legs_[i].amount;
        for (uint256 i = 0; i < plan.actions.length; i++) if (plan.actions[i].token == token) spent += plan.actions[i].amount;
        for (uint256 i = 0; i < plan.outs.length; i++) if (plan.outs[i].token == token) spent += plan.outs[i].amount;
        if (brought != spent) revert BadBundle(40);
    }

    /// A leg from another chain: called by that route's ZetaphyGateway, after it handed this contract the tokens.
    /// data = abi.encode(bundle id, leg index). Reverting (late, already funded, wrong leg) makes the Gateway refund it.
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256, bytes calldata data) external nonReentrant {
        (bytes32 id, uint256 i) = abi.decode(data, (bytes32, uint256));
        Leg storage l = _openLeg(id, i);
        if (l.gateway == address(0) || msg.sender != l.gateway || l.srcChainId != srcChainId || token != l.token
            || (l.sender != address(0) && l.sender != sender)) revert WrongLeg();
        // the tokens must be here: what this contract holds beyond what it owes is this leg's
        uint256 received = IBundleToken(token).balanceOf(address(this)) - accounted[token];
        _funded(id, i, l, received, srcChainId, sender);
    }

    /// A leg funded on ZETAPHY: its sender (or anyone, when the leg names none) pays it (approve this contract first).
    function fund(bytes32 id, uint256 i) external nonReentrant {
        Leg storage l = _openLeg(id, i);
        if (l.gateway != address(0) || (l.sender != address(0) && l.sender != msg.sender)) revert WrongLeg();
        IBundleToken t = IBundleToken(l.token);
        uint256 need = accounted[l.token] + l.amount;
        _funded(id, i, l, l.amount, block.chainid, msg.sender);
        if (!t.transferFrom(msg.sender, address(this), l.amount)) revert PayFailed();
        uint256 have = t.balanceOf(address(this));
        if (have < need) revert Short(have, need); // a token that delivers less than it says
    }

    function _openLeg(bytes32 id, uint256 i) private view returns (Leg storage) {
        Bundle storage b = bundles[id];
        if (b.status != Status.Open) revert NotOpen();
        if (block.timestamp > b.deadline) revert TooLate();
        if (i >= b.legCount || legFunded[id][i]) revert WrongLeg();
        return legs[id][i];
    }

    function _funded(bytes32 id, uint256 i, Leg storage l, uint256 received, uint256 srcChainId, address sender) private {
        if (received < l.amount) revert Short(received, l.amount);
        legFunded[id][i] = true;
        accounted[l.token] += received;
        if (received > l.amount) owed[l.token][l.refundTo] += received - l.amount;
        Bundle storage b = bundles[id];
        b.fundedCount += 1;
        if (b.fundedCount == b.legCount) b.status = Status.Funded;
        emit LegFunded(id, i, srcChainId, sender, received);
    }

    /// Anyone, once every leg is in and before the deadline: runs the whole plan, all or nothing.
    /// msg.value: the Mailbox fees of the calls to other chains (fees[i] for outs[i], ZetaphyGateway.quoteWithdraw);
    /// what the Gateways give back comes back to the caller.
    function execute(bytes32 id, Plan calldata plan, uint256[] calldata fees) external payable nonReentrant {
        Bundle storage b = bundles[id];
        if (b.status != Status.Funded) revert NotOpen();
        if (block.timestamp > b.deadline) revert TooLate();
        if (planHash(plan) != b.planHash || fees.length != plan.outs.length) revert WrongPlan();
        uint256 total = 0;
        for (uint256 i = 0; i < fees.length; i++) total += fees[i];
        uint256 paid = msg.value;
        if (paid != total) revert Fee();
        // effects first: the bundle is spent
        b.status = Status.Executed;
        _spend(id, b.legCount);
        address creator = b.creator;
        uint256 before = address(this).balance - paid;
        _actions(id, creator, plan.actions);
        for (uint256 i = 0; i < plan.outs.length; i++) {
            Out calldata o = plan.outs[i];
            if (IBundleGateway(o.gateway).token() != o.token) revert WrongPlan();
            if (!IBundleToken(o.token).approve(o.gateway, o.amount)) revert PayFailed();
            // fees[i], written as its share of what the caller paid (paid == total): only the caller's own ether
            // ever goes to a Gateway; this contract holds none of its own
            bytes32 h = IBundleGateway(o.gateway).withdrawAndCall{value: paid * fees[i] / (total == 0 ? 1 : total)}(o.target,
                abi.encode(id, creator, o.data), o.amount, o.maxFee, o.gasLimit, o.revertTo);
            emit OutSent(id, i, h);
        }
        emit Executed(id, msg.sender);
        uint256 change = address(this).balance - before;
        if (change > 0) {
            (bool ok, ) = msg.sender.call{value: change}("");
            if (!ok) revert PayFailed();
        }
    }

    /// The legs' tokens leave the escrow (the plan spends exactly them).
    function _spend(bytes32 id, uint256 legCount) private {
        for (uint256 i = 0; i < legCount; i++) {
            Leg storage l = legs[id][i];
            accounted[l.token] -= l.amount;
        }
    }

    /// The steps on ZETAPHY: tokens to each target, then its call (a revert undoes the whole execute).
    function _actions(bytes32 id, address creator, Action[] calldata actions) private {
        for (uint256 i = 0; i < actions.length; i++) {
            Action calldata a = actions[i];
            if (!IBundleToken(a.token).transfer(a.target, a.amount)) revert PayFailed();
            ISaphanBundleTarget(a.target).onSaphanBundle{gas: a.gasLimit}(id, creator, a.token, a.amount, a.data);
        }
    }

    /// Anyone, after the deadline of a bundle that did not run: each funded leg is owed back to its refundTo.
    function refund(bytes32 id) external {
        Bundle storage b = bundles[id];
        if (b.status != Status.Open && b.status != Status.Funded) revert NotOpen();
        if (block.timestamp <= b.deadline) revert TooEarly();
        b.status = Status.Refunded;
        for (uint256 i = 0; i < b.legCount; i++) {
            if (!legFunded[id][i]) continue;
            Leg storage l = legs[id][i];
            owed[l.token][l.refundTo] += l.amount;
        }
        emit Refunded(id);
    }

    /// The caller's refunds and excess in `token`.
    function claim(address token) external nonReentrant {
        uint256 v = owed[token][msg.sender];
        if (v == 0) revert WrongLeg();
        owed[token][msg.sender] = 0;
        accounted[token] -= v;
        emit Claimed(msg.sender, token, v);
        if (!IBundleToken(token).transfer(msg.sender, v)) revert PayFailed();
    }

    /// The Gateways give back what the Mailbox did not take.
    receive() external payable {}
}

contracts/SaphanChallenges.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SaphanChallenges: anyone can stop a bad bridge transfer before it mints, and the lanes that vouched for it pay
/// @notice One per route (its BridgeAirlock), on ZETAPHY. Testnet only, not audited (docs/SAPHAN-SAFETY.md).
///
///         Challenge  anyone, with a bond, names a transfer that is not released yet. The airlock HOLDS it (its release
///                    waits; the airlock's challenger role can only delay, like a marker).
///         Vote       Neuro runners (NeuroJobs workers that are active, with a clean track record) vote uphold or reject
///                    within votingPeriod.
///         Upheld     (quorum of uphold votes) the airlock VETOES the transfer for good: nothing mints. The challenger
///                    gets the bond back, and the bonds of the lanes that attested the transfer are slashed: half to the
///                    challenger, half to the reserve (insurance).
///         Rejected   (quorum of reject votes, or the period ends without an upheld quorum) the hold is lifted and the
///                    challenger's bond goes to the transfer's ZETAPHY recipient, for the delay.
///
///         Lane bonds: the operator of a lane (the key behind lane2, or a NeuroLane's controller) bonds it here; a bond
///         leaves only after UNBOND_DELAY (longer than any open challenge), and can be slashed until then.
///         Every payout is pulled by its owner (claim); governance moves the reserve to an insurance pool.

interface IChallengeAirlock {
    function transfers(bytes32 id) external view returns (uint64 readyFrom, uint8 attestations, bool released, bool vetoed, uint64 readyEpoch, bool held);
    function attestedBy(bytes32 id, address lane) external view returns (bool);
    function lanes() external view returns (address[] memory);
    function isLane(address lane) external view returns (bool);
    function hold(bytes32 id) external;
    function unhold(bytes32 id) external;
    function veto(bytes32 id, string calldata reason) external;
}

interface IChallengeRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

contract SaphanChallenges {
    enum State { None, Open, Upheld, Rejected }

    struct Challenge {
        address challenger;
        address recipient;      // the transfer's ZETAPHY recipient (gets the bond when the challenge fails)
        uint128 bond;
        uint64 deadline;
        uint16 upheld;
        uint16 rejected;
        State state;
    }

    struct LaneBond {
        address operator;
        uint128 amount;
        uint64 unlockAt;        // 0: bonded; else when the operator may take it
    }

    IChallengeAirlock public immutable airlock;
    IChallengeRunners public immutable runners;
    address public governance;
    uint256 public challengeBond;
    uint64 public votingPeriod;
    uint16 public quorum;
    uint32 public minAgreed;
    uint64 public constant UNBOND_DELAY = 14 days;
    uint64 public constant MAX_VOTING = 7 days;

    mapping(bytes32 => Challenge) public challenges;
    mapping(bytes32 => mapping(address => bool)) public voted;
    mapping(address => LaneBond) public laneBonds;
    /// What each address may take (claim): returned bonds, rewards, compensation.
    mapping(address => uint256) public credit;
    /// Slashed bonds kept for insurance (moved by governance, e.g. into HackInsurance).
    uint256 public reserve;
    uint256 public openCount;

    event Opened(bytes32 indexed id, address indexed challenger, address indexed recipient, uint256 bond, uint64 deadline, string reason);
    event Voted(bytes32 indexed id, address indexed runner, bool uphold);
    event Resolved(bytes32 indexed id, bool upheld, uint256 slashed);
    event Slashed(bytes32 indexed id, address indexed lane, uint256 amount);
    event LaneBonded(address indexed lane, address indexed operator, uint256 amount);
    event UnbondRequested(address indexed lane, uint64 unlockAt);
    event LaneUnbonded(address indexed lane, uint256 amount);
    event Claimed(address indexed who, uint256 amount);
    event ReservePaid(address indexed to, uint256 amount);
    event ParamsSet(uint256 challengeBond, uint64 votingPeriod, uint16 quorum, uint32 minAgreed);
    event GovernanceSet(address governance);

    error NotGovernance();
    error NotRunner();
    error Bond(uint256 needed);
    error WrongState();
    error TooLate();
    error TooEarly();
    error Twice();
    error NotOperator();
    error NotLane();
    error Nothing();
    error PayFailed();
    error Params();

    uint256 private entered;
    modifier nonReentrant() { require(entered == 0, "reentered"); entered = 1; _; entered = 0; }
    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    constructor(IChallengeAirlock airlock_, IChallengeRunners runners_, address governance_, uint256 bond_, uint64 votingPeriod_, uint16 quorum_, uint32 minAgreed_) {
        require(address(airlock_) != address(0) && address(runners_) != address(0) && governance_ != address(0), "config");
        airlock = airlock_;
        runners = runners_;
        governance = governance_;
        _setParams(bond_, votingPeriod_, quorum_, minAgreed_);
    }

    function _setParams(uint256 bond_, uint64 votingPeriod_, uint16 quorum_, uint32 minAgreed_) private {
        if (bond_ == 0 || votingPeriod_ < 1 hours || votingPeriod_ > MAX_VOTING || quorum_ == 0) revert Params();
        challengeBond = bond_;
        votingPeriod = votingPeriod_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        emit ParamsSet(bond_, votingPeriod_, quorum_, minAgreed_);
    }

    /// Governance; never while a challenge is open (the rules of an open challenge do not change under it).
    function setParams(uint256 bond_, uint64 votingPeriod_, uint16 quorum_, uint32 minAgreed_) external onlyGov {
        if (openCount != 0) revert WrongState();
        _setParams(bond_, votingPeriod_, quorum_, minAgreed_);
    }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    // ---------------------------------------------------------------- challenges

    /// Anyone: holds a transfer that lanes attested but the airlock has not released, with the bond (msg.value).
    function open(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount, string calldata reason)
        external payable returns (bytes32 id)
    {
        if (msg.value != challengeBond) revert Bond(challengeBond);
        id = keccak256(abi.encode(srcChainId, srcContract, srcNonce, sender, to, amount)); // = BridgeAirlock.transferId
        Challenge storage c = challenges[id];
        if (c.state != State.None) revert Twice(); // one challenge per transfer, ever
        uint64 deadline = uint64(block.timestamp) + votingPeriod;
        challenges[id] = Challenge(msg.sender, to, uint128(msg.value), deadline, 0, 0, State.Open);
        openCount += 1;
        // last: the airlock refuses (and this whole call reverts) unless lanes attested it and it is not released or vetoed
        airlock.hold(id);
        emit Opened(id, msg.sender, to, msg.value, deadline, reason);
    }

    /// A Neuro runner's vote (active, at least minAgreed agreed jobs, no more rejected than agreed); once per challenge.
    function vote(bytes32 id, bool uphold) external {
        Challenge storage c = challenges[id];
        if (c.state != State.Open) revert WrongState();
        if (block.timestamp > c.deadline) revert TooLate();
        if (msg.sender == c.challenger) revert NotRunner();
        if (voted[id][msg.sender]) revert Twice();
        voted[id][msg.sender] = true;
        if (uphold) c.upheld += 1; else c.rejected += 1;
        emit Voted(id, msg.sender, uphold);
        // who may vote, checked last (a read of NeuroJobs; a vote from anyone else reverts whole)
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    /// Anyone: settles a challenge once a quorum agrees, or after its deadline (no upheld quorum then = rejected).
    function resolve(bytes32 id) external nonReentrant {
        Challenge storage c = challenges[id];
        if (c.state != State.Open) revert WrongState();
        bool upheld = c.upheld >= quorum;
        bool rejected = !upheld && (c.rejected >= quorum || block.timestamp > c.deadline);
        if (!upheld && !rejected) revert TooEarly();
        openCount -= 1;
        uint256 slashed;
        if (upheld) {
            c.state = State.Upheld;
            credit[c.challenger] += c.bond;
            // the lanes that vouched for it lose their bonds: half to the challenger, half to the reserve
            address[] memory ls = airlock.lanes();
            for (uint256 i = 0; i < ls.length; i++) {
                if (!airlock.attestedBy(id, ls[i])) continue;
                LaneBond storage b = laneBonds[ls[i]];
                uint256 v = b.amount;
                if (v == 0) continue;
                b.amount = 0;
                slashed += v;
                emit Slashed(id, ls[i], v);
            }
            credit[c.challenger] += slashed / 2;
            reserve += slashed - slashed / 2;
            emit Resolved(id, true, slashed);
            airlock.veto(id, "Saphan challenge upheld");
        } else {
            c.state = State.Rejected;
            credit[c.recipient] += c.bond;
            emit Resolved(id, false, 0);
            airlock.unhold(id);
        }
    }

    // ---------------------------------------------------------------- lane bonds

    /// A lane's operator bonds it (the first bonder of a lane is its operator; only the operator adds).
    function bondLane(address lane) external payable {
        if (msg.value == 0) revert Nothing();
        LaneBond storage b = laneBonds[lane];
        if (b.operator == address(0)) b.operator = msg.sender;
        if (b.operator != msg.sender) revert NotOperator();
        b.amount += uint128(msg.value);
        b.unlockAt = 0;
        emit LaneBonded(lane, msg.sender, msg.value);
        if (!airlock.isLane(lane)) revert NotLane(); // checked last (a read of the airlock): not a lane, the whole call reverts
    }

    /// The operator starts leaving: the bond can still be slashed until UNBOND_DELAY has passed.
    function requestUnbond(address lane) external {
        LaneBond storage b = laneBonds[lane];
        if (b.operator != msg.sender) revert NotOperator();
        b.unlockAt = uint64(block.timestamp) + UNBOND_DELAY;
        emit UnbondRequested(lane, b.unlockAt);
    }

    function unbond(address lane) external nonReentrant {
        LaneBond storage b = laneBonds[lane];
        if (b.operator != msg.sender) revert NotOperator();
        if (b.unlockAt == 0 || block.timestamp < b.unlockAt) revert TooEarly();
        uint256 v = b.amount;
        if (v == 0) revert Nothing();
        b.amount = 0;
        b.unlockAt = 0;
        credit[msg.sender] += v;
        emit LaneUnbonded(lane, v);
    }

    // ---------------------------------------------------------------- payouts

    /// What the caller is owed (bonds back, rewards, compensation, unbonded lane bonds).
    function claim() external nonReentrant {
        uint256 v = credit[msg.sender];
        if (v == 0) revert Nothing();
        credit[msg.sender] = 0;
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
        emit Claimed(msg.sender, v);
    }

    /// Governance moves slashed bonds to insurance (e.g. HackInsurance's pool): credited there, taken with claim().
    function payReserve(address to, uint256 amount) external onlyGov {
        if (amount == 0 || amount > reserve) revert Nothing();
        reserve -= amount;
        credit[to] += amount;
        emit ReservePaid(to, amount);
    }
}

contracts/SaphanCheckpointer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface ICheckpointToken {
    function totalSupply() external view returns (uint256);
}

interface ICheckpointMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
}

/// @title SaphanCheckpointer: ZETAPHY's heartbeat to one route's lockbox (the escape hatch's clock)
/// @notice On ZETAPHY, one per route. Anyone calls beat() (at most once per MIN_INTERVAL, paying the Mailbox fee):
///         it sends HyperlaneLockBoxV2 a heartbeat through ZETAPHY's Mailbox (our validators sign it like a release).
///         While heartbeats arrive, the lockbox stays out of escape; if ZETAPHY stops (halted, censored, cut off) for
///         the lockbox's ESCAPE_AFTER, holders can leave on the source chain (docs/SAPHAN-SAFETY.md).
///         No admin; everything it may do is fixed at deploy. Testnet only, not audited.
contract SaphanCheckpointer {
    bytes32 public constant HEARTBEAT_TAG = keccak256("saphan/heartbeat/v1");
    uint64 public constant MIN_INTERVAL = 1 hours;

    ICheckpointMailbox public immutable mailbox;   // ZETAPHY's Mailbox
    uint32 public immutable destinationDomain;     // the source chain's Hyperlane domain
    bytes32 public immutable recipient;            // the route's HyperlaneLockBoxV2 there
    ICheckpointToken public immutable token;       // token(X): its supply rides on every heartbeat (proof of reserves)
    uint64 public seq;
    uint64 public lastAt;

    event Beat(uint64 indexed seq, bytes32 messageId);

    error TooSoon(uint64 next);
    error Fee(uint256 needed);

    constructor(ICheckpointMailbox mailbox_, uint32 destinationDomain_, bytes32 recipient_, ICheckpointToken token_) {
        require(address(mailbox_) != address(0) && recipient_ != bytes32(0) && address(token_) != address(0), "config");
        token = token_;
        mailbox = mailbox_;
        destinationDomain = destinationDomain_;
        recipient = recipient_;
    }

    /// The heartbeat body (192 bytes), as the lockbox reads it: with token(X)'s total supply now.
    function body(uint64 n) public view returns (bytes memory) {
        return abi.encode(HEARTBEAT_TAG, block.chainid, address(this), n, uint64(block.timestamp), token.totalSupply());
    }

    function quote() external view returns (uint256) { return mailbox.quoteDispatch(destinationDomain, recipient, body(seq + 1)); }

    /// Anyone: one heartbeat. msg.value: exactly the Mailbox fee (quote()).
    function beat() external payable returns (bytes32 messageId) {
        if (block.timestamp < uint256(lastAt) + MIN_INTERVAL) revert TooSoon(lastAt + MIN_INTERVAL);
        uint64 n = seq + 1;
        seq = n;
        lastAt = uint64(block.timestamp);
        bytes memory b = body(n);
        uint256 fee = mailbox.quoteDispatch(destinationDomain, recipient, b);
        if (msg.value != fee) revert Fee(fee);
        messageId = mailbox.dispatch{value: fee}(destinationDomain, recipient, b);
        emit Beat(n, messageId);
    }
}

contracts/SaphanGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan Gateway: call contracts across chains in one transaction, with automatic refunds
/// @notice Two contracts per source chain X, on top of the existing route (HyperlaneLockBoxV2 on X; HyperlaneLane,
///         BridgeAirlock, BridgeGuard and HyperlaneOutbox on ZETAPHY), none of which changes:
///
///         X -> ZETAPHY  SaphanSourceGateway.depositAndCall(target, data, ...) locks ETH in the route's lockbox
///                       to a DEPOSIT ADDRESS that is derived from the whole call (CREATE2 of ZetaphyGateway,
///                       salt = the call's hash). The route mints token(X) to that address after its usual checks
///                       (two independent lanes, quarantine, Neuro, threat registry, daily limits). Anyone then
///                       hands the call to ZetaphyGateway.execute, which empties the address (a one-shot CREATE2,
///                       so each call runs once), pays the executor its fee in token(X) and calls
///                       target.onSaphanCall. If the call fails, the tokens go back to X (to revertTo, optionally
///                       calling its onSaphanRevert), or stay on ZETAPHY for abortTo when the way back is closed.
///         ZETAPHY -> X  ZetaphyGateway.withdrawAndCall(target, data, ...) burns token(X) through the route's
///                       outbox toward a deposit address of SaphanSourceGateway on X. After the lockbox's delay
///                       and checks it is paid ETH (anyone claims the release); anyone then runs
///                       SaphanSourceGateway.execute: executor fee in
///                       ETH, then target.onSaphanCall; if that fails, the ETH is kept for revertTo (claim()).
///
///         Why a derived address and not a second message: the lanes that attest the transfer attest the address,
///         and so the call itself (its hash). A call cannot be swapped or replayed without breaking keccak256, and
///         the Gateway adds no new signer, relayer or admin to trust.
///
///         Gas: the executor's fee (maxFee, set by the caller) comes out of the amount, in what moved (token(X) on
///         ZETAPHY, ETH on X): the user needs no gas coin on the destination chain.
///         Testnet only, not audited.

interface ISaphanToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

interface ISaphanLockBox {
    function lock(address to, uint256 amount) external payable returns (bytes32);
    function quoteLock(address to, uint256 amount) external view returns (uint256);
    function claim(bytes32 id) external;
}

interface ISaphanOutbox {
    function send(address to, uint256 amount) external payable returns (bytes32);
    function quoteSend(address to, uint256 amount) external view returns (uint256);
}

interface ISaphanAirlock {
    function release(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to, uint256 amount) external;
}

/// What a contract on ZETAPHY implements to be called from another chain (it must check msg.sender is the Gateway).
interface ISaphanCallee {
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256 amount, bytes calldata data) external;
}

/// What a contract on a source chain implements to be called from ZETAPHY (it must check msg.sender is the Gateway).
interface ISaphanReceiver {
    function onSaphanCall(uint256 srcChainId, address sender, bytes calldata data) external payable;
    function onSaphanRevert(address sender, uint256 nonce, bytes calldata message) external payable;
}

/// @notice The deposit address of one call: deployed once (CREATE2, salt = the call's hash) by the Gateway that owns
///         it; its constructor hands everything it holds (`token`, or ETH when token is zero) to that Gateway.
///         Once deployed it accepts nothing more, so a call can never run twice.
contract SaphanDepositAddress {
    constructor(address token) {
        if (token == address(0)) {
            (bool ok, ) = msg.sender.call{value: address(this).balance}("");
            require(ok, "sweep");
        } else {
            uint256 b = ISaphanToken(token).balanceOf(address(this));
            if (b > 0) require(ISaphanToken(token).transfer(msg.sender, b), "sweep");
        }
    }
}

/// Shared by both Gateways: the call formats, their hashes and deposit addresses.
abstract contract SaphanCalls {
    /// X -> ZETAPHY: a call made on X (depositAndCall).
    struct InCall {
        uint256 srcChainId;   // X
        address srcGateway;   // SaphanSourceGateway on X
        uint256 nonce;        // its count of calls
        address sender;       // who called on X
        address target;       // the contract on ZETAPHY
        uint256 amount;       // ETH locked = token(X) minted to the deposit address
        uint256 maxFee;       // the executor's fee, in token(X)
        uint64 gasLimit;      // gas the target gets
        address revertTo;     // on X: who gets the refund when the call fails (zero: no way back, abortTo keeps it)
        bool callOnRevert;    // the refund calls revertTo.onSaphanRevert(sender, nonce, revertMessage)
        address abortTo;      // on ZETAPHY: who may claim the tokens when the refund cannot be sent
        bytes data;
        bytes revertMessage;
    }

    /// ZETAPHY -> X: a call made on ZETAPHY (withdrawAndCall), or the refund of a failed InCall (kind REVERT).
    struct OutCall {
        uint256 dstChainId;   // X
        address dstGateway;   // SaphanSourceGateway on X
        address srcGateway;   // ZetaphyGateway
        uint256 nonce;        // ZetaphyGateway's count of out calls
        address sender;       // who called on ZETAPHY (for a refund: who called on X)
        address target;       // the contract on X (for a refund: revertTo)
        uint256 amount;       // token(X) burned = ETH paid to the deposit address on X
        uint256 maxFee;       // the executor's fee, in ETH
        uint64 gasLimit;
        address revertTo;     // on X: who gets the ETH when the call fails
        uint8 kind;           // CALL or REVERT
        bytes data;           // CALL: the call's data; REVERT: abi.encode(the InCall's nonce, its revertMessage)
    }

    uint8 internal constant CALL = 0;
    uint8 internal constant REVERT = 1;
    bytes32 public constant IN_TAG = keccak256("saphan/gateway/in/v1");
    bytes32 public constant OUT_TAG = keccak256("saphan/gateway/out/v1");
    /// Gas kept back for what follows the target's call (fee transfer, refund, events).
    uint256 internal constant RESERVE = 120_000;

    uint256 private entered;

    error Reentered();
    error WrongGateway();
    error NotFunded(uint256 have, uint256 need);
    error LowGas(uint256 need);
    error NotSelf();
    error BadCall();
    error PayFailed();
    error Fee(uint256 needed);

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    function hashIn(InCall calldata p) public pure returns (bytes32) { return keccak256(abi.encode(IN_TAG, p)); }
    function hashOut(OutCall memory p) public pure returns (bytes32) { return keccak256(abi.encode(OUT_TAG, p)); }

    /// The deposit address `gateway` derives for a call hash, for a token (zero = ETH). The init code is the creation
    /// code followed by the token as one 32-byte word (= abi.encode(token), the constructor's argument).
    function depositAddressOf(address gateway, bytes32 callHash, address token) public pure returns (address) {
        bytes32 code = keccak256(abi.encodePacked(type(SaphanDepositAddress).creationCode, uint256(uint160(token))));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), gateway, callHash, code)))));
    }

    /// Empties this Gateway's deposit address of a call into the Gateway (once: a second time reverts).
    function _sweep(bytes32 callHash, address token) internal {
        bytes memory code = abi.encodePacked(type(SaphanDepositAddress).creationCode, uint256(uint160(token)));
        address at;
        assembly { at := create2(0, add(code, 0x20), mload(code), callHash) }
        if (at == address(0)) revert BadCall(); // used already
    }

    /// The executor cannot starve the target: enough gas for it and what follows, checked before it runs.
    function _gasFor(uint64 gasLimit) internal view {
        uint256 need = uint256(gasLimit) + uint256(gasLimit) / 63 + RESERVE;
        if (gasleft() < need) revert LowGas(need);
    }

    /// ETH to the caller (its change, its fee, what it claims): the Gateways pay no one else directly.
    function _payCaller(uint256 v) internal {
        if (v == 0) return;
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
    }
}

/// @title ZetaphyGateway: the ZETAPHY side, one per source chain X (its token, airlock and outbox)
contract ZetaphyGateway is SaphanCalls {
    ISaphanToken public immutable token;     // token(X), minted by the route's BridgeGuard
    ISaphanOutbox public immutable outbox;   // HyperlaneOutbox(X): burns token(X), releases ETH on X
    ISaphanAirlock public immutable airlock; // BridgeAirlock(X)
    address public immutable lockbox;        // HyperlaneLockBoxV2 on X (the airlock's source contract)
    uint256 public immutable remoteChainId;  // X
    address public immutable deployer;
    address public remote;                   // SaphanSourceGateway on X (set once, then fixed)
    uint256 public outNonce;
    /// Tokens kept on ZETAPHY for whoever a failed call names as abortTo (claimAborted).
    mapping(address => uint256) public aborted;

    event RemoteSet(address remote);
    event Executed(bytes32 indexed callHash, uint256 indexed nonce, address indexed target, uint256 amount, uint256 fee, address executor);
    event CallFailed(bytes32 indexed callHash, bytes reason);
    event Reverted(bytes32 indexed callHash, address indexed revertTo, uint256 amount, bool withCall, bytes32 outHash);
    event Aborted(bytes32 indexed callHash, address indexed abortTo, uint256 amount);
    event AbortClaimed(address indexed who, uint256 amount);
    event OutCallDispatched(bytes32 indexed callHash, bytes32 messageId);
    /// Every call toward X (a withdrawAndCall, or a refund that calls revertTo back): what the executor on X runs.
    event OutCallSent(bytes32 indexed callHash, uint256 indexed nonce, address indexed sender, address depositAddress, OutCall call);

    constructor(ISaphanToken token_, ISaphanOutbox outbox_, ISaphanAirlock airlock_, address lockbox_, uint256 remoteChainId_) {
        require(address(token_) != address(0) && address(outbox_) != address(0) && address(airlock_) != address(0)
            && lockbox_ != address(0) && remoteChainId_ != 0, "config");
        token = token_;
        outbox = outbox_;
        airlock = airlock_;
        lockbox = lockbox_;
        remoteChainId = remoteChainId_;
        deployer = msg.sender;
    }

    /// Once, by the deployer: the Gateway on X (deployed after this one, it names this one).
    function setRemote(address r) external {
        require(msg.sender == deployer && remote == address(0) && r != address(0), "remote");
        remote = r;
        emit RemoteSet(r);
    }

    function depositAddress(InCall calldata p) external view returns (address) { return depositAddressOf(address(this), hashIn(p), address(token)); }

    /// Anyone, once the route minted the call's tokens to its deposit address: runs the call. With `release`, it first
    /// asks the airlock to release the lock (the lockbox's nonce `lockNonce`, from its Locked event) when nobody did yet;
    /// the airlock reverts unless every check of the route passes (a wrong nonce names a transfer that is not there).
    /// msg.value: only for a refund to X (the Mailbox fee, in ZTPHY); the rest comes back to the executor.
    function execute(InCall calldata p, bool release, uint256 lockNonce) external payable nonReentrant returns (bool ok) {
        if (remote == address(0) || p.srcChainId != remoteChainId || p.srcGateway != remote) revert WrongGateway();
        if (p.target == address(0) || p.amount == 0 || p.maxFee > p.amount) revert BadCall();
        bytes32 h = hashIn(p);
        address at = depositAddressOf(address(this), h, address(token));
        if (release && token.balanceOf(at) < p.amount) airlock.release(p.srcChainId, lockbox, lockNonce, p.srcGateway, at, p.amount);
        uint256 have = token.balanceOf(at);
        if (have < p.amount) revert NotFunded(have, p.amount); // never deploy (and burn) an address before its tokens came
        _gasFor(p.gasLimit);
        _sweep(h, address(token));
        uint256 extra = have - p.amount;              // tokens someone else sent to the address go with the call's own
        uint256 fee = p.maxFee;
        uint256 rest = p.amount - fee + extra;
        if (fee > 0 && !token.transfer(msg.sender, fee)) revert PayFailed();
        uint256 before = address(this).balance - msg.value;
        try this.deliverIn(p, rest) {
            ok = true;
            emit Executed(h, p.nonce, p.target, rest, fee, msg.sender);
        } catch (bytes memory reason) {
            emit CallFailed(h, reason);
            _refund(p, h, rest, address(this).balance - before);
        }
        _payCaller(address(this).balance - before); // what the Mailbox did not take
    }

    /// Only the Gateway itself (so a failing call undoes its token transfer): tokens to the target, then its call.
    function deliverIn(InCall calldata p, uint256 amount) external {
        if (msg.sender != address(this)) revert NotSelf();
        if (!token.transfer(p.target, amount)) revert PayFailed();
        ISaphanCallee(p.target).onSaphanCall{gas: p.gasLimit}(p.srcChainId, p.sender, address(token), amount, p.data);
    }

    /// A failed InCall: back to X through the outbox (plainly, or as a REVERT call to revertTo's onSaphanRevert);
    /// kept for abortTo when there is no way back (no revertTo, or the outbound route refuses: closed, paused, limit).
    function _refund(InCall calldata p, bytes32 h, uint256 amount, uint256 value) private {
        address abortTo = p.abortTo == address(0) ? p.sender : p.abortTo;
        if (p.revertTo != address(0)) {
            address to = p.revertTo;
            bytes32 oh = bytes32(0);
            if (p.callOnRevert) {
                OutCall memory o = OutCall(remoteChainId, remote, address(this), outNonce++, p.sender, p.revertTo, amount, 0, p.gasLimit,
                    p.revertTo, REVERT, abi.encode(p.nonce, p.revertMessage));
                oh = hashOut(o);
                to = depositAddressOf(remote, oh, address(0));
                emit OutCallSent(oh, o.nonce, p.sender, to, o);
            }
            uint256 fee = outbox.quoteSend(to, amount);
            if (value < fee) revert Fee(fee); // the executor pays the way back; run again with it
            try outbox.send{value: fee}(to, amount) returns (bytes32) {
                emit Reverted(h, p.revertTo, amount, p.callOnRevert, oh);
                return;
            } catch {} // the outbound route refused: keep the tokens here
        }
        aborted[abortTo] += amount;
        emit Aborted(h, abortTo, amount);
    }

    /// Tokens kept for the caller by failed calls.
    function claimAborted() external nonReentrant {
        uint256 v = aborted[msg.sender];
        require(v > 0, "nothing");
        aborted[msg.sender] = 0;
        if (!token.transfer(msg.sender, v)) revert PayFailed();
        emit AbortClaimed(msg.sender, v);
    }

    /// ZETAPHY -> X: burns `amount` of token(X) from the caller (approve this Gateway first) and has the lockbox on X
    /// pay a deposit address of the Gateway there, which then calls `target` (or pays revertTo when that fails).
    /// msg.value: the Mailbox fee in ZTPHY (quoteWithdraw); the rest comes back.
    function withdrawAndCall(address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo)
        external payable nonReentrant returns (bytes32 h)
    {
        if (remote == address(0)) revert WrongGateway();
        if (target == address(0) || revertTo == address(0) || amount == 0 || maxFee > amount) revert BadCall();
        OutCall memory o = OutCall(remoteChainId, remote, address(this), outNonce++, msg.sender, target, amount, maxFee, gasLimit, revertTo, CALL, data);
        h = hashOut(o);
        address at = depositAddressOf(remote, h, address(0));
        if (!token.transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        uint256 before = address(this).balance - msg.value;
        bytes32 messageId = outbox.send{value: msg.value}(at, amount); // burns this Gateway's tokens through the guard's outbound route
        emit OutCallSent(h, o.nonce, msg.sender, at, o);
        emit OutCallDispatched(h, messageId);
        _payCaller(address(this).balance - before); // the outbox's change
    }

    /// The Mailbox fee of a withdrawAndCall.
    function quoteWithdraw(uint256 amount) external view returns (uint256) { return outbox.quoteSend(address(1), amount); }

    /// The OutCall a withdrawAndCall made (what the executor on X needs), rebuilt from its event and inputs.
    function outCall(uint256 nonce, address sender, address target, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo,
        uint8 kind, bytes calldata data) external view returns (OutCall memory)
    {
        return OutCall(remoteChainId, remote, address(this), nonce, sender, target, amount, maxFee, gasLimit, revertTo, kind, data);
    }

    receive() external payable {}
}

/// @title SaphanSourceGateway: the side on a source chain X (its HyperlaneLockBoxV2)
contract SaphanSourceGateway is SaphanCalls {
    ISaphanLockBox public immutable lockbox;
    address public immutable remote;          // ZetaphyGateway(X) on ZETAPHY
    address public immutable remoteToken;     // token(X) on ZETAPHY
    uint256 public immutable zetaphyChainId;  // 77390
    uint256 public nonce;
    /// ETH of failed calls, kept for their revertTo (claim).
    mapping(address => uint256) public owed;

    event DepositAndCall(bytes32 indexed callHash, uint256 indexed nonce, address indexed sender, address depositAddress, InCall call);
    event Executed(bytes32 indexed callHash, address indexed target, uint256 amount, uint256 fee, address executor);
    event CallFailed(bytes32 indexed callHash, bytes reason);
    event Owed(address indexed to, uint256 amount);
    event Dispatched(address indexed depositAddress, bytes32 messageId);

    constructor(ISaphanLockBox lockbox_, address remote_, address remoteToken_, uint256 zetaphyChainId_) {
        require(address(lockbox_) != address(0) && remote_ != address(0) && remoteToken_ != address(0) && zetaphyChainId_ != 0, "config");
        lockbox = lockbox_;
        remote = remote_;
        remoteToken = remoteToken_;
        zetaphyChainId = zetaphyChainId_;
    }

    /// The InCall a depositAndCall with these inputs makes now (for quotes and wallets).
    function inCall(address sender, address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit,
        address revertTo, bool callOnRevert, address abortTo, bytes calldata revertMessage) public view returns (InCall memory)
    {
        return InCall(block.chainid, address(this), nonce, sender, target, amount, maxFee, gasLimit, revertTo, callOnRevert, abortTo, data, revertMessage);
    }

    function _hashInMem(InCall memory p) private pure returns (bytes32) { return keccak256(abi.encode(IN_TAG, p)); }

    /// The lockbox's Mailbox fee for a depositAndCall of `amount` (pay amount + this).
    function quoteDeposit(uint256 amount) external view returns (uint256) { return lockbox.quoteLock(address(1), amount); }

    /// X -> ZETAPHY: locks `amount` of ETH for a call of `target` on ZETAPHY. msg.value = amount + the Mailbox fee
    /// (quoteDeposit); the rest comes back. revertTo defaults to the caller; abortTo (on ZETAPHY) too.
    function depositAndCall(address target, bytes calldata data, uint256 amount, uint256 maxFee, uint64 gasLimit, address revertTo,
        bool callOnRevert, address abortTo, bytes calldata revertMessage) external payable nonReentrant returns (bytes32 h)
    {
        if (target == address(0) || amount == 0 || maxFee > amount) revert BadCall();
        InCall memory p = InCall(block.chainid, address(this), nonce++, msg.sender, target, amount, maxFee, gasLimit,
            revertTo == address(0) ? msg.sender : revertTo, callOnRevert, abortTo == address(0) ? msg.sender : abortTo, data, revertMessage);
        h = _hashInMem(p);
        address at = depositAddressOf(remote, h, remoteToken);
        _lock(at, amount);
        emit DepositAndCall(h, p.nonce, msg.sender, at, p);
    }

    /// Locks `amount` to `at` (the Mailbox fee from msg.value); the caller gets its change, never ETH owed to others.
    function _lock(address at, uint256 amount) private {
        uint256 fee = lockbox.quoteLock(at, amount);
        if (msg.value < amount + fee) revert Fee(amount + fee);
        uint256 before = address(this).balance - msg.value;
        bytes32 messageId = lockbox.lock{value: amount + fee}(at, amount);
        emit Dispatched(at, messageId);
        _payCaller(address(this).balance - before);
    }

    function depositAddress(OutCall calldata o) external view returns (address) { return depositAddressOf(address(this), hashOut(o), address(0)); }

    /// Anyone, once the lockbox paid the call's deposit address (anyone claims the queued release from the lockbox
    /// first, once it is due): runs the call. When it fails, the ETH waits for revertTo (claim()).
    /// Effects before interactions: the refund is recorded first, and the delivered call cancels it as its own first
    /// step; a failing call undoes that cancel with the rest of itself, so the refund stands.
    function execute(OutCall calldata o) external nonReentrant returns (bool ok) {
        if (o.dstChainId != block.chainid || o.dstGateway != address(this) || o.srcGateway != remote) revert WrongGateway();
        if (o.target == address(0) || o.revertTo == address(0) || o.amount == 0 || o.maxFee > o.amount || o.kind > REVERT) revert BadCall();
        bytes32 h = hashOut(o);
        address at = depositAddressOf(address(this), h, address(0));
        uint256 have = at.balance;
        if (have < o.amount) revert NotFunded(have, o.amount);
        _gasFor(o.gasLimit);
        uint256 fee = o.maxFee;
        uint256 rest = have - fee;            // all of the address's ETH moves (the sweep below takes `have`)
        owed[o.revertTo] += rest;             // the refund, unless the call goes through
        _sweep(h, address(0));
        _payCaller(fee);
        try this.deliverOut{value: rest}(o) {
            ok = true;
            emit Executed(h, o.target, rest, fee, msg.sender);
        } catch (bytes memory reason) {
            emit CallFailed(h, reason);
            emit Owed(o.revertTo, rest);
        }
    }

    /// Only the Gateway itself: cancels the call's refund, then the target's call with the ETH (a failure undoes both).
    function deliverOut(OutCall calldata o) external payable {
        if (msg.sender != address(this)) revert NotSelf();
        owed[o.revertTo] -= msg.value;
        if (o.kind == CALL) {
            ISaphanReceiver(o.target).onSaphanCall{value: msg.value, gas: o.gasLimit}(zetaphyChainId, o.sender, o.data);
        } else {
            (uint256 n, bytes memory m) = abi.decode(o.data, (uint256, bytes));
            ISaphanReceiver(o.target).onSaphanRevert{value: msg.value, gas: o.gasLimit}(o.sender, n, m);
        }
    }

    /// ETH of failed calls, kept for their revertTo.
    function claim() external nonReentrant {
        uint256 v = owed[msg.sender];
        require(v > 0, "nothing");
        owed[msg.sender] = 0;
        _payCaller(v);
    }

    receive() external payable {}
}

contracts/SaphanIntents.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan intents: "I give A, I want at least B on chain Y by time T", filled by solvers, gated by Neuro
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited.
///
///   SaphanIntents (ZETAPHY) holds the A of every intent in escrow (token(X) of a route, or any ERC-20 on ZETAPHY).
///     open(order) on ZETAPHY, or from chain X in one transaction: SaphanSourceGateway.depositAndCall with
///     target = this contract and data = abi.encode(order).
///   A solver pays the recipient B from its own money on chain Y (SaphanFillRelay.fill: the ETH goes to the recipient
///     at once) and is repaid the A on ZETAPHY once the fill is proven:
///       - by the fill's own message: SaphanFillRelay sends it through Y's Hyperlane Mailbox; the Mailbox on ZETAPHY
///         checks the ISM (the Hyperlane validators that already attest the routes' transfers) before handle();
///       - or optimistically, faster: claimFill with a bond; with no challenge within challengeWindow, settle() repays.
///         A challenge (with its own bond) leaves only the fill's message to decide: if it does not come within
///         disputePeriod the claim was false and the solver's bond goes to the challenger.
///     Fills on ZETAPHY itself (Y = ZETAPHY, B an ERC-20) are atomic: fillLocal pays the recipient and repays the
///     solver in one transaction.
///   Neuro gates fills: when the intent opens, the recipient is looked up in NeuroScore (Neuro's on-chain risk model)
///     and the ThreatRegistry. High risk, held or enforced: the intent is refused (from X the Gateway refunds it).
///     Medium risk: fills count only after riskDelay (notBefore), so watchers and guardians get time. A solver the
///     ThreatRegistry holds cannot fill or claim.
///   Unfilled past deadline + grace: refund() owes A back to refundTo (pull). The grace lets a fill made just before
///     the deadline still arrive.
///   Every payout is a pull (claim / withdrawBonds); no admin; the deployer only names each chain's relay, once.

interface IIntentToken {
    function balanceOf(address) external view returns (uint256);
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

/// NeuroScore.scoreOf: level 1 low, 2 medium, 3 high (thresholds set with the model by governance).
interface IIntentScores {
    function scoreOf(address who) external view returns (bool known, int256 score, uint8 level);
}

/// ThreatRegistry's views (Reason as its uint8 value).
interface IIntentThreats {
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
}

interface IIntentMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256);
}

contract SaphanIntents {
    struct Order {
        address tokenIn;      // what the user gives, on ZETAPHY (token(X) when it came from chain X)
        uint256 amountIn;     // A
        uint32 dstDomain;     // chain Y (its Hyperlane domain = its chain id); ZETAPHY's own id: filled here
        address tokenOut;     // Y = ZETAPHY: the ERC-20 wanted; another chain: zero (its native coin)
        address recipient;    // on Y
        uint256 minOut;       // B
        uint64 deadline;      // T (a fill must happen by then)
        address refundTo;     // on ZETAPHY: who gets A back when nobody fills
    }

    enum Status { None, Open, Claimed, Filled, Refunded }

    struct Intent {
        Order order;
        Status status;
        uint64 notBefore;     // risk delay: fills count from then on
        address solver;       // an optimistic claim: who claims to have filled
        address repayTo;
        uint64 claimedAt;
        address challenger;
    }

    bytes32 public constant TAG = keccak256("saphan/intent/v1");
    uint64 public constant MAX_DURATION = 30 days;
    uint8 public constant MEDIUM = 2;
    uint8 public constant HIGH = 3;

    IIntentScores public immutable scores;     // NeuroScore (zero: no score check)
    IIntentThreats public immutable threats;   // ThreatRegistry (zero: no flag check)
    address public immutable mailbox;          // the Mailbox on ZETAPHY
    /// Hyperlane reads it: the ISM for fill messages (e.g. a routing ISM over each chain's Hyperlane validators).
    address public immutable interchainSecurityModule;
    uint256 public immutable claimBond;        // ZTPHY a solver puts up per optimistic claim
    uint256 public immutable challengeBond;    // ZTPHY a challenger puts up
    uint64 public immutable challengeWindow;
    uint64 public immutable disputePeriod;     // how long a challenged claim waits for the fill's message
    uint64 public immutable grace;             // after the deadline, before a refund
    uint64 public immutable riskDelay;         // medium risk: fills count only after this
    address public immutable deployer;

    mapping(uint32 => bytes32) public relays;  // SaphanFillRelay per chain (set once each)
    mapping(bytes32 => Intent) private _intents;
    uint256 public nonce;
    mapping(address => uint256) public accounted;                    // tokens held for intents and payouts
    mapping(address => mapping(address => uint256)) public owed;     // token -> who -> amount (claim)
    mapping(address => uint256) public bonds;                        // ZTPHY owed (withdrawBonds)
    uint256 private entered;

    event RelaySet(uint32 indexed domain, bytes32 relay);
    event Opened(bytes32 indexed id, address indexed owner, uint256 srcChainId, Order order, uint64 notBefore);
    event Filled(bytes32 indexed id, address indexed solver, address repayTo, uint256 amountOut, bool proven);
    event FillRejected(bytes32 indexed id, address indexed solver, uint32 origin);
    event ClaimMade(bytes32 indexed id, address indexed solver, address repayTo);
    event Challenged(bytes32 indexed id, address indexed challenger);
    event Slashed(bytes32 indexed id, address indexed solver, address indexed to, uint256 amount);
    event Refunded(bytes32 indexed id, address refundTo, uint256 amount);
    event Claimed(address indexed who, address indexed token, uint256 amount);

    error BadOrder(uint256 code);
    error Risky(uint8 level);
    error SolverHeld();
    error WrongStatus();
    error TooEarly();
    error TooLate();
    error Bond(uint256 needed);
    error NotMailbox();
    error NoValue();
    error WrongSender();
    error Short(uint256 have, uint256 need);
    error Nothing();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    constructor(IIntentScores scores_, IIntentThreats threats_, address mailbox_, address ism_, uint256 claimBond_, uint256 challengeBond_,
        uint64 challengeWindow_, uint64 disputePeriod_, uint64 grace_, uint64 riskDelay_)
    {
        require(mailbox_ != address(0) && claimBond_ > 0 && challengeBond_ > 0 && challengeWindow_ > 0 && disputePeriod_ > challengeWindow_, "config");
        scores = scores_;
        threats = threats_;
        mailbox = mailbox_;
        interchainSecurityModule = ism_;
        claimBond = claimBond_;
        challengeBond = challengeBond_;
        challengeWindow = challengeWindow_;
        disputePeriod = disputePeriod_;
        grace = grace_;
        riskDelay = riskDelay_;
        deployer = msg.sender;
    }

    /// Once per chain, by the deployer: the SaphanFillRelay there (deployed after this contract, it names this one).
    function setRelay(uint32 domain, address relay) external {
        require(msg.sender == deployer && relays[domain] == bytes32(0) && relay != address(0) && domain != uint32(block.chainid), "relay");
        relays[domain] = bytes32(uint256(uint160(relay)));
        emit RelaySet(domain, relays[domain]);
    }

    function intentOf(bytes32 id) external view returns (Intent memory) { return _intents[id]; }

    // ---- risk (Neuro) ----

    /// When fills to `recipient` on `domain` may count: now, now + riskDelay (medium risk), or never (reverts Risky).
    function riskGate(address recipient, uint32 domain) public view returns (uint64 notBefore) {
        if (address(threats) != address(0)) {
            (bool held, ) = threats.isAddressHeld(domain, recipient);
            (bool enforced, ) = threats.isAddressEnforced(domain, recipient);
            if (held || enforced) revert Risky(HIGH);
        }
        notBefore = uint64(block.timestamp);
        if (address(scores) != address(0)) {
            (bool known, , uint8 level) = scores.scoreOf(recipient);
            if (known && level >= HIGH) revert Risky(level);
            if (known && level == MEDIUM) notBefore += riskDelay;
        }
    }

    function _solverOk(address solver) private view {
        if (address(threats) == address(0)) return;
        (bool held, ) = threats.isAddressHeld(block.chainid, solver);
        if (held) revert SolverHeld();
    }

    // ---- opening ----

    /// Opens an intent with the caller's tokens (approve this contract for amountIn of tokenIn first).
    function open(Order calldata o) external nonReentrant returns (bytes32 id) {
        uint64 notBefore = _check(o);
        uint256 need = accounted[o.tokenIn] + o.amountIn;
        id = _open(o, notBefore, msg.sender, block.chainid, o.amountIn);
        if (!IIntentToken(o.tokenIn).transferFrom(msg.sender, address(this), o.amountIn)) revert PayFailed();
        uint256 have = IIntentToken(o.tokenIn).balanceOf(address(this));
        if (have < need) revert Short(have, need);
    }

    /// From chain X through its ZetaphyGateway (data = abi.encode(order)), after the Gateway handed over the tokens.
    /// Reverting (risky recipient, bad order, tokens missing) makes the Gateway refund the user on X.
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256, bytes calldata data) external nonReentrant {
        Order memory o = abi.decode(data, (Order));
        if (token != o.tokenIn) revert BadOrder(0);
        uint64 notBefore = _check(o);
        uint256 received = IIntentToken(token).balanceOf(address(this)) - accounted[token];
        if (received < o.amountIn) revert Short(received, o.amountIn);
        _open(o, notBefore, sender, srcChainId, received);
    }

    /// The checks of an order and its risk gate: when fills may count (reverts when the order cannot open).
    function check(Order calldata o) external view returns (uint64 notBefore) { return _check(o); }

    function _check(Order memory o) private view returns (uint64) {
        if (o.tokenIn == address(0) || o.amountIn == 0 || o.recipient == address(0) || o.minOut == 0 || o.refundTo == address(0)) revert BadOrder(1);
        if (o.deadline <= block.timestamp || o.deadline > block.timestamp + MAX_DURATION) revert BadOrder(2);
        if (o.dstDomain == uint32(block.chainid)) { if (o.tokenOut == address(0)) revert BadOrder(3); }
        else if (o.tokenOut != address(0) || relays[o.dstDomain] == bytes32(0)) revert BadOrder(4);
        return riskGate(o.recipient, o.dstDomain);
    }

    function _open(Order memory o, uint64 notBefore, address owner, uint256 srcChainId, uint256 received) private returns (bytes32 id) {
        id = keccak256(abi.encode(TAG, block.chainid, address(this), nonce++));
        Intent storage it = _intents[id];
        it.order = o;
        it.status = Status.Open;
        it.notBefore = notBefore;
        accounted[o.tokenIn] += received;
        if (received > o.amountIn) owed[o.tokenIn][o.refundTo] += received - o.amountIn;
        emit Opened(id, owner, srcChainId, o, notBefore);
    }

    // ---- fills ----

    /// Y = ZETAPHY: the solver pays the recipient `amountOut` (>= minOut) of tokenOut and is owed A at once.
    function fillLocal(bytes32 id, uint256 amountOut, address repayTo) external nonReentrant {
        Intent storage it = _intents[id];
        Order storage o = it.order;
        if (it.status != Status.Open || o.dstDomain != uint32(block.chainid)) revert WrongStatus();
        if (block.timestamp < it.notBefore) revert TooEarly();
        if (block.timestamp > o.deadline) revert TooLate();
        if (amountOut < o.minOut || repayTo == address(0)) revert BadOrder(5);
        _solverOk(msg.sender);
        riskGate(o.recipient, o.dstDomain); // still not risky now
        _repay(id, it, repayTo);
        emit Filled(id, msg.sender, repayTo, amountOut, true);
        if (!IIntentToken(o.tokenOut).transferFrom(msg.sender, o.recipient, amountOut)) revert PayFailed();
    }

    /// The Mailbox, after the ISM checked it: a fill made on chain `origin` by its SaphanFillRelay.
    /// A fill that does not match an open intent is consumed and rejected (it never blocks the Mailbox).
    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (sender == bytes32(0) || sender != relays[origin]) revert WrongSender();
        (bytes32 id, address recipient, uint256 amount, uint64 filledAt, address solver, address repayTo) =
            abi.decode(body, (bytes32, address, uint256, uint64, address, address));
        Intent storage it = _intents[id];
        Order storage o = it.order;
        bool ok = (it.status == Status.Open || it.status == Status.Claimed) && o.dstDomain == origin && o.recipient == recipient
            && amount >= o.minOut && filledAt <= o.deadline && filledAt >= it.notBefore && repayTo != address(0);
        if (!ok) { emit FillRejected(id, solver, origin); return; }
        if (it.status == Status.Claimed) {
            if (it.solver == solver) {
                bonds[solver] += claimBond;                                  // the claim was true
                if (it.challenger != address(0)) bonds[solver] += challengeBond; // and the challenge was not
            } else _slash(id, it, it.challenger != address(0) ? it.challenger : solver); // someone else filled: the claim was false
        }
        _repay(id, it, repayTo);
        emit Filled(id, solver, repayTo, amount, true);
    }

    function _repay(bytes32, Intent storage it, address repayTo) private {
        it.status = Status.Filled;
        it.solver = address(0);
        it.challenger = address(0);
        owed[it.order.tokenIn][repayTo] += it.order.amountIn;
    }

    /// The claimer's bond goes to `to` (with its own challenge bond back when `to` is the challenger).
    function _slash(bytes32 id, Intent storage it, address to) private {
        uint256 v = claimBond + (to == it.challenger ? challengeBond : 0);
        bonds[to] += v;
        emit Slashed(id, it.solver, to, claimBond);
    }

    // ---- optimistic claims ----

    /// A solver that filled on chain Y claims it now, with `claimBond` (msg.value, exactly), instead of waiting for
    /// the fill's message. Repaid by settle() after challengeWindow unless someone challenges.
    function claimFill(bytes32 id, address repayTo) external payable {
        Intent storage it = _intents[id];
        if (msg.value != claimBond) revert Bond(claimBond);
        if (it.status != Status.Open || it.order.dstDomain == uint32(block.chainid) || repayTo == address(0)) revert WrongStatus();
        if (block.timestamp < it.notBefore) revert TooEarly();
        if (block.timestamp > uint256(it.order.deadline) + grace) revert TooLate();
        _solverOk(msg.sender);
        it.status = Status.Claimed;
        it.solver = msg.sender;
        it.repayTo = repayTo;
        it.claimedAt = uint64(block.timestamp);
        emit ClaimMade(id, msg.sender, repayTo);
    }

    /// Anyone, within challengeWindow, with `challengeBond`: "this claim is false". Only the fill's message can then
    /// repay the solver.
    function challenge(bytes32 id) external payable {
        Intent storage it = _intents[id];
        if (msg.value != challengeBond) revert Bond(challengeBond);
        if (it.status != Status.Claimed || it.challenger != address(0)) revert WrongStatus();
        if (block.timestamp > uint256(it.claimedAt) + challengeWindow) revert TooLate();
        it.challenger = msg.sender;
        emit Challenged(id, msg.sender);
    }

    /// Anyone, after an unchallenged window: the claim stands; the solver is repaid and gets its bond back.
    function settle(bytes32 id) external {
        Intent storage it = _intents[id];
        if (it.status != Status.Claimed || it.challenger != address(0)) revert WrongStatus();
        if (block.timestamp <= uint256(it.claimedAt) + challengeWindow) revert TooEarly();
        bonds[it.solver] += claimBond;
        emit Filled(id, it.solver, it.repayTo, 0, false);
        _repay(id, it, it.repayTo);
    }

    /// Anyone, when a challenged claim saw no fill message within disputePeriod: the claim was false. The solver's
    /// bond goes to the challenger, and the intent is open again.
    function timeout(bytes32 id) external {
        Intent storage it = _intents[id];
        if (it.status != Status.Claimed || it.challenger == address(0)) revert WrongStatus();
        if (block.timestamp <= uint256(it.claimedAt) + disputePeriod) revert TooEarly();
        _slash(id, it, it.challenger);
        it.status = Status.Open;
        it.solver = address(0);
        it.challenger = address(0);
    }

    // ---- refunds and payouts ----

    /// Anyone, after deadline + grace with no fill: A is owed back to refundTo.
    function refund(bytes32 id) external {
        Intent storage it = _intents[id];
        if (it.status != Status.Open) revert WrongStatus();
        if (block.timestamp <= uint256(it.order.deadline) + grace) revert TooEarly();
        it.status = Status.Refunded;
        owed[it.order.tokenIn][it.order.refundTo] += it.order.amountIn;
        emit Refunded(id, it.order.refundTo, it.order.amountIn);
    }

    /// The caller's repayments and refunds in `token`.
    function claim(address token) external nonReentrant {
        uint256 v = owed[token][msg.sender];
        if (v == 0) revert Nothing();
        owed[token][msg.sender] = 0;
        accounted[token] -= v;
        emit Claimed(msg.sender, token, v);
        if (!IIntentToken(token).transfer(msg.sender, v)) revert PayFailed();
    }

    /// The caller's bonds (back, or won) in ZTPHY.
    function withdrawBonds() external nonReentrant {
        uint256 v = bonds[msg.sender];
        if (v == 0) revert Nothing();
        bonds[msg.sender] = 0;
        emit Claimed(msg.sender, address(0), v);
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
    }
}

/// @title SaphanFillRelay: on chain Y, a solver pays an intent's recipient and tells SaphanIntents through Hyperlane
contract SaphanFillRelay {
    IIntentMailbox public immutable mailbox;  // Y's Mailbox
    uint32 public immutable zetaphyDomain;
    bytes32 public immutable intents;         // SaphanIntents on ZETAPHY
    mapping(bytes32 => address) public filledBy; // each intent is filled once here

    event Fill(bytes32 indexed id, address indexed solver, address indexed recipient, uint256 amount, address repayTo, bytes32 messageId);

    error Filled();
    error Fee(uint256 needed);
    error PayFailed();

    constructor(IIntentMailbox mailbox_, uint32 zetaphyDomain_, address intents_) {
        require(address(mailbox_) != address(0) && intents_ != address(0), "config");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        intents = bytes32(uint256(uint160(intents_)));
    }

    function body(bytes32 id, address recipient, uint256 amount, address solver, address repayTo) public view returns (bytes memory) {
        return abi.encode(id, recipient, amount, uint64(block.timestamp), solver, repayTo);
    }

    /// The Mailbox fee of a fill (pay amount + this).
    function quote(bytes32 id, address recipient, uint256 amount, address repayTo) external view returns (uint256) {
        return mailbox.quoteDispatch(zetaphyDomain, intents, body(id, recipient, amount, msg.sender, repayTo));
    }

    /// The solver: pays `recipient` `amount` now (msg.value = amount + the Mailbox fee, exactly) and sends the
    /// proof of it to ZETAPHY, where `repayTo` will be owed the intent's A. Check the intent first (intentOf on
    /// ZETAPHY: open, this recipient, amount >= minOut, before its deadline and after notBefore): a fill that does
    /// not match is rejected there and not repaid.
    function fill(bytes32 id, address recipient, uint256 amount, address repayTo) external payable returns (bytes32 messageId) {
        if (filledBy[id] != address(0)) revert Filled();
        filledBy[id] = msg.sender;
        bytes memory b = body(id, recipient, amount, msg.sender, repayTo);
        uint256 fee = mailbox.quoteDispatch(zetaphyDomain, intents, b);
        if (msg.value != amount + fee) revert Fee(amount + fee);
        messageId = mailbox.dispatch{value: fee}(zetaphyDomain, intents, b);
        emit Fill(id, msg.sender, recipient, amount, repayTo, messageId);
        (bool ok, ) = recipient.call{value: msg.value - fee}("");
        if (!ok) revert PayFailed();
    }
}

contracts/SaphanLiquidity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// HyperlaneLockBoxV2 as this contract sees it: its daily release limit, which a guardian may only lower.
interface ILiquidityLockbox {
    function dailyLimit() external view returns (uint256);
    function lowerDailyLimit(uint256 v) external;
}

/// @title SaphanLiquidityBounds: route limits that follow observed flows, inside bounds governance set
/// @notice Saphan PR 6, item S9 (docs/SAPHAN-PR6.md). Testnet only, not audited.
///
///         Governance (the chain's ZetaphyTimelock: every change waits its delay) sets, per route, the band a route's
///         daily release limit may move in: [min, max], the largest step per update (maxStepBps of the current
///         target) and the shortest time between updates (minInterval). The rebalancer (a key governance names: the
///         off-chain policy in src/saphanliquidity.js runs with it; an LLM may only hint, the policy is deterministic)
///         moves the route's TARGET inside that band, one bounded step at a time. Whatever the rebalancer's key does,
///         the target stays in [min, max] and moves at most maxStepBps per minInterval.
///
///         What the target does on chain: this contract is a GUARDIAN of the route's lockbox, and guardians can only
///         reduce risk. applyDown(route) (anyone) lowers the lockbox's daily limit to the target when the target is
///         lower. Raising a limit stays with the lockbox's governance (its timelock, 48 h): the policy prints the
///         proposal (src/saphanliquidity.js raiseProposal), and governance never has to accept it.
///         The rebalancer may also drop a target to `min` at once (an incident: emergencyMin), never raise it at once.
///
///         No other power: this contract calls nothing but lowerDailyLimit, holds no money, has no upgrade.
contract SaphanLiquidityBounds {
    struct Bounds {
        address lockbox;      // the route's HyperlaneLockBoxV2 (this contract must be one of its guardians)
        uint128 min;          // wei per day
        uint128 max;
        uint16 maxStepBps;    // largest change per update, in bps of the current target
        uint32 minInterval;   // seconds between updates
    }

    struct Target {
        uint128 value;
        uint64 updatedAt;
        bytes32 hint;         // hash of the policy input (flows, LLM hint) that produced it: anyone can recompute it
    }

    uint16 public constant MAX_STEP_BPS = 5000;
    uint32 public constant MIN_INTERVAL = 1 hours;

    address public immutable governance;
    address public rebalancer;
    mapping(bytes32 => Bounds) public bounds;
    mapping(bytes32 => Target) public target;

    event BoundsSet(bytes32 indexed route, address lockbox, uint128 min, uint128 max, uint16 maxStepBps, uint32 minInterval);
    event RebalancerSet(address rebalancer);
    event TargetSet(bytes32 indexed route, uint128 from, uint128 to, bytes32 hint);
    event AppliedDown(bytes32 indexed route, uint256 from, uint256 to);

    error NotGovernance();
    error NotRebalancer();
    error NoRoute();
    error BadBounds();
    error OutOfBounds(uint128 min, uint128 max);
    error StepTooBig(uint256 most);
    error TooSoon(uint64 at);
    error NothingToLower();

    constructor(address governance_) {
        require(governance_ != address(0), "governance");
        governance = governance_;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyRebalancer() { if (msg.sender != rebalancer) revert NotRebalancer(); _; }

    /// Governance: a route's band. The target is pulled into the new band at once.
    function setBounds(bytes32 route, address lockbox, uint128 min, uint128 max, uint16 maxStepBps, uint32 minInterval) external onlyGov {
        if (lockbox == address(0) || min > max || max == 0 || maxStepBps == 0 || maxStepBps > MAX_STEP_BPS || minInterval < MIN_INTERVAL) revert BadBounds();
        bounds[route] = Bounds(lockbox, min, max, maxStepBps, minInterval);
        Target storage t = target[route];
        uint128 v = t.value < min ? min : t.value > max ? max : t.value;
        if (v != t.value) { emit TargetSet(route, t.value, v, bytes32(0)); t.value = v; }
        emit BoundsSet(route, lockbox, min, max, maxStepBps, minInterval);
    }

    /// Governance: who runs the policy (zero: nobody; the targets stay as they are).
    function setRebalancer(address r) external onlyGov {
        rebalancer = r;
        emit RebalancerSet(r);
    }

    /// The rebalancer: a new target for `route`, inside the band, at most one step from the current one.
    function propose(bytes32 route, uint128 value, bytes32 hint) external onlyRebalancer {
        Bounds memory b = bounds[route];
        if (b.lockbox == address(0)) revert NoRoute();
        Target storage t = target[route];
        if (t.updatedAt != 0 && block.timestamp < uint256(t.updatedAt) + b.minInterval) revert TooSoon(t.updatedAt + b.minInterval);
        if (value < b.min || value > b.max) revert OutOfBounds(b.min, b.max);
        uint256 step = maxStep(route);
        uint256 diff = value > t.value ? value - t.value : t.value - value;
        if (diff > step) revert StepTooBig(step);
        emit TargetSet(route, t.value, value, hint);
        t.value = value;
        t.updatedAt = uint64(block.timestamp);
        t.hint = hint;
    }

    /// The rebalancer, in an incident: the target drops to the band's minimum at once (no step, no interval).
    function emergencyMin(bytes32 route) external onlyRebalancer {
        Bounds memory b = bounds[route];
        if (b.lockbox == address(0)) revert NoRoute();
        Target storage t = target[route];
        emit TargetSet(route, t.value, b.min, keccak256("emergency"));
        t.value = b.min;
        t.updatedAt = uint64(block.timestamp);
    }

    /// Anyone: when the target is below the lockbox's daily limit, lowers the limit to it (a guardian call).
    function applyDown(bytes32 route) external {
        Bounds memory b = bounds[route];
        if (b.lockbox == address(0)) revert NoRoute();
        uint256 cur = ILiquidityLockbox(b.lockbox).dailyLimit();
        uint256 v = target[route].value;
        if (v >= cur) revert NothingToLower();
        emit AppliedDown(route, cur, v);
        ILiquidityLockbox(b.lockbox).lowerDailyLimit(v);
    }

    /// The largest change the next propose() may make (a target of 0 may move up to maxStepBps of max).
    function maxStep(bytes32 route) public view returns (uint256) {
        Bounds memory b = bounds[route];
        uint256 v = target[route].value;
        uint256 base = v > 0 ? v : b.max;
        return base * b.maxStepBps / 10000;
    }
}

contracts/SaphanOffline.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// HyperlaneOutbox (contracts/HyperlaneLockBoxV2.sol): burns the route's token from the caller through the guard and
/// sends the release to the source chain's lockbox.
interface IOfflineOutbox {
    function guard() external view returns (address);
    function quoteSend(address to, uint256 amount) external view returns (uint256);
    function send(address to, uint256 amount) external payable returns (bytes32 messageId);
}

interface IOfflineGuard {
    function token() external view returns (address);
}

interface IOfflineToken {
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function transfer(address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanOfflineTransfers: a bridge transfer signed offline, relayed by anyone later
/// @notice Saphan PR 6, item H (docs/SAPHAN-PR6.md). Testnet only, not audited. The pattern of ZetaphyOfflineOrders
///         (EIP-712, a QR code or text payload, a nonce bitmap, the relayer paid a fee the signer chose), for the
///         way out of ZETAPHY: "send `amount` of route R's token to `to` on R's source chain".
///
///         Online once: the holder approves this contract for the route's token (token(X) on ZETAPHY).
///         Offline: it signs Transfer{from, outbox, to, amount, relayerFee, nonce, deadline} (no network; the hub or
///         `node scripts/saphan.js offline sign`), and hands the text / QR (src/saphanoffline.js, "ZSPH1:...") to
///         anyone. Later, whoever is online calls relay(): this contract pulls amount + relayerFee from the signer,
///         pays the relayer its fee in the token, and calls the outbox's send(to, amount) with the Mailbox fee the
///         relayer pays in ZTPHY (anything above the quote is returned to the relayer). From there it is an ordinary
///         transfer: the guard's limits, pause and vaccine, the lockbox's delay, veto and daily limit all apply.
///
///         The relayer cannot change anything signed (outbox = the route and so the chain, recipient, amount, fee);
///         a nonce is spent before any call out; cancel(nonce) burns one. The token is the outbox guard's token
///         (read on chain, not trusted from the payload). No owner, no fee of its own, no upgrade; nonReentrant.
contract SaphanOfflineTransfers {
    struct Transfer {
        address from;
        address outbox;       // the route (HyperlaneOutbox on ZETAPHY): which source chain and which token
        address to;           // the receiver on the source chain
        uint256 amount;       // token units that arrive (burned here, released there)
        uint256 relayerFee;   // token units to whoever relays, on top of amount
        uint256 nonce;
        uint256 deadline;
    }

    bytes32 public constant TRANSFER_TYPEHASH = keccak256(
        "Transfer(address from,address outbox,address to,uint256 amount,uint256 relayerFee,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH = keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)");
    uint256 private constant HALF_N = 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0;

    mapping(address => mapping(uint256 => uint256)) public nonceBitmap;
    uint256 private unlocked = 1;

    /// The amount, receiver and chain are in the outbox's Sent event of the same transaction (messageId).
    event Relayed(address indexed from, uint256 indexed nonce, address indexed outbox, address relayer, uint256 relayerFee, bytes32 messageId);
    event NonceCancelled(address indexed from, uint256 wordPos, uint256 mask);

    error Expired();
    error NonceUsed();
    error BadSignature();
    error BadTransfer();
    error Fee(uint256 needed);
    error TokenFailed();
    error PayFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    function domainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, keccak256("ZETAPHY Saphan Offline"), keccak256("1"), block.chainid, address(this)));
    }

    function transferHash(Transfer calldata t) public pure returns (bytes32) {
        return keccak256(abi.encode(TRANSFER_TYPEHASH, t.from, t.outbox, t.to, t.amount, t.relayerFee, t.nonce, t.deadline));
    }

    function digest(Transfer calldata t) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", domainSeparator(), transferHash(t)));
    }

    function isNonceUsed(address from, uint256 nonce) public view returns (bool) {
        return nonceBitmap[from][nonce >> 8] & (1 << (nonce & 0xff)) != 0;
    }

    function cancel(uint256 nonce) external {
        uint256 mask = 1 << (nonce & 0xff);
        nonceBitmap[msg.sender][nonce >> 8] |= mask;
        emit NonceCancelled(msg.sender, nonce >> 8, mask);
    }

    /// The Mailbox fee relay() needs for `t` now (msg.value of relay).
    function quote(Transfer calldata t) external view returns (uint256) {
        return IOfflineOutbox(t.outbox).quoteSend(t.to, t.amount);
    }

    /// Anyone online: carries a signed transfer to its route. msg.value >= quote(t); the rest comes back.
    function relay(Transfer calldata t, bytes calldata sig) external payable nonReentrant returns (bytes32 messageId) {
        if (block.timestamp > t.deadline) revert Expired();
        if (t.amount == 0 || t.to == address(0) || t.outbox.code.length == 0) revert BadTransfer();
        if (_recover(digest(t), sig) != t.from) revert BadSignature();
        uint256 bit = 1 << (t.nonce & 0xff);
        uint256 word = nonceBitmap[t.from][t.nonce >> 8];
        if (word & bit != 0) revert NonceUsed();
        nonceBitmap[t.from][t.nonce >> 8] = word | bit;

        IOfflineOutbox outbox = IOfflineOutbox(t.outbox);
        uint256 fee = outbox.quoteSend(t.to, t.amount);
        if (msg.value < fee) revert Fee(fee);
        _pull(t);

        // exactly the quote (the outbox quotes the same body in the same transaction, so it returns no change; this
        // contract has no receive(): a change would revert the whole relay)
        messageId = outbox.send{value: fee}(t.to, t.amount); // burns `amount` from this contract (the guard's outbound route): nothing is kept here
        emit Relayed(t.from, t.nonce, t.outbox, msg.sender, t.relayerFee, messageId);
        uint256 change = msg.value - fee;
        if (change != 0) {
            (bool ok, ) = msg.sender.call{value: change}("");
            if (!ok) revert PayFailed();
        }
    }

    /// Pulls amount + relayerFee from the signer and pays the relayer its fee. The token is the outbox guard's
    /// BridgedToken (no fee on transfer); if less arrived, the fee transfer or the guard's burn of `amount` reverts.
    function _pull(Transfer calldata t) private {
        IOfflineToken token = IOfflineToken(IOfflineGuard(IOfflineOutbox(t.outbox).guard()).token());
        if (!token.transferFrom(t.from, address(this), t.amount + t.relayerFee)) revert TokenFailed();
        if (t.relayerFee != 0 && !token.transfer(msg.sender, t.relayerFee)) revert TokenFailed();
    }

    function _recover(bytes32 d, bytes calldata sig) private pure returns (address got) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > HALF_N || (v != 27 && v != 28)) revert BadSignature();
        got = ecrecover(d, v, r, s);
        if (got == address(0)) revert BadSignature();
    }
}

contracts/SaphanPrivacy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IPrivacyPoseidon {
    function poseidon(uint256[2] calldata x) external pure returns (uint256);
}

/// ZkIdentityVerifier (Groth16, the identity circuit zetaphy-network/zkid/circuits/identity.circom; DEV setup).
interface IPrivacyVerifier {
    function verifyProof(uint256[2] calldata a, uint256[2][2] calldata b, uint256[2] calldata c, uint256[5] calldata pub)
        external view returns (bool);
}

interface IPrivacyToken {
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanPrivacyPool: optional private transfers of a bridged token, one fixed denomination per pool
/// @notice Saphan PR 6, item F (docs/SAPHAN-PR6.md). Testnet only, not audited. A REAL zero-knowledge proof, with a
///         DEV trusted setup: the Groth16 key of ZkIdentityVerifier was made by one party on one machine
///         (zetaphy-network/zkid/setup.js), who could forge proofs and drain every pool. Mainnet would need a public
///         multi-party phase-2 ceremony first.
///
///         It reuses the private-identity circuit unchanged (a Semaphore-style membership + nullifier proof):
///           deposit:  the depositor makes a note (secret, nullifierKey) offline and deposits its commitment
///                     C = Poseidon(secret, nullifierKey) with exactly `denomination` of `token` (e.g. 0.01 sepETH).
///                     The pool appends the leaf Poseidon(C, 1) to its own Poseidon Merkle tree (depth 20).
///           withdraw: later, from any address, a Groth16 proof that "some leaf of a root this pool had is
///                     Poseidon(Poseidon(secret, nullifierKey), level >= 1)", revealing only
///                     nullifier = Poseidon(nullifierKey, scope) (one withdrawal per note) and binding
///                     signal = keccak256(recipient, fee) >> 8 (a proof copied from the mempool cannot redirect the
///                     coins). The recipient gets denomination - fee, whoever submits gets fee (a relayer, so the
///                     recipient needs no gas and no link to the depositor).
///         Every pool has its own scope (from the chain id and its address), so a note's nullifier differs per pool.
///         What is hidden: which deposit a withdrawal spends (among all deposits of this pool). What is not: that an
///         address deposited, amounts (all equal), timing. The anonymity set is the pool's deposits: small on a testnet.
///         No owner, no fee of its own, no upgrade, no pause: it cannot be frozen or drained by anyone but note holders
///         (and the DEV key holder, see above).
contract SaphanPrivacyPool {
    uint256 public constant SNARK_FIELD = 21888242871839275222246405745257275088548364400416034343698204186575808495617;
    uint256 public constant DEPTH = 20;
    uint256 public constant LEVEL = 1;

    IPrivacyPoseidon public immutable poseidon;
    IPrivacyVerifier public immutable verifier;
    IPrivacyToken public immutable token;
    uint256 public immutable denomination;
    uint256 public immutable scope;

    uint256 public root;
    uint256 public leafCount;
    mapping(uint256 => bool) public rootSeen;          // every root this pool ever had (the tree only grows)
    mapping(uint256 => bool) public nullifierUsed;
    mapping(uint256 => bool) public commitmentUsed;
    uint256 public spent;                               // withdrawals so far (the pool owes (leafCount - spent) notes)
    uint256[21] private zeros;
    uint256[20] private filled;                         // the left node last written at each height
    uint256 private unlocked = 1;

    event Deposit(uint256 indexed commitment, uint256 leaf, uint256 index, uint256 root);
    event Withdrawal(uint256 indexed nullifier, address indexed recipient, address relayer, uint256 fee);

    error BadCommitment();
    error TreeFull();
    error UnknownRoot();
    error Spent();
    error BadFee();
    error BadProof();
    error TokenFailed();
    error Reentrancy();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(IPrivacyPoseidon poseidon_, IPrivacyVerifier verifier_, IPrivacyToken token_, uint256 denomination_) {
        require(address(poseidon_) != address(0) && address(verifier_) != address(0) && address(token_) != address(0) && denomination_ > 0, "config");
        poseidon = poseidon_;
        verifier = verifier_;
        token = token_;
        denomination = denomination_;
        scope = uint256(keccak256(abi.encode("saphan/privacy-pool/v1", block.chainid, address(this)))) >> 8;
        uint256 z = 0;
        for (uint256 h = 0; h <= DEPTH; h++) {
            zeros[h] = z;
            if (h < DEPTH) filled[h] = z;
            z = poseidon_.poseidon([z, z]);
        }
        root = zeros[DEPTH];
        rootSeen[root] = true;
    }

    /// The signal a withdrawal's proof must carry (as PrivateAirdrop's).
    function signalOf(address recipient, uint256 fee) public pure returns (uint256) {
        return uint256(keccak256(abi.encode(recipient, fee))) >> 8;
    }

    function zeroAt(uint256 h) external view returns (uint256) { return zeros[h]; }

    /// Deposits one note: exactly `denomination` of the token (approve first).
    function deposit(uint256 commitment) external nonReentrant {
        if (commitment == 0 || commitment >= SNARK_FIELD || commitmentUsed[commitment]) revert BadCommitment();
        uint256 index = leafCount;
        if (index >= (1 << DEPTH)) revert TreeFull();
        commitmentUsed[commitment] = true;
        leafCount = index + 1;
        uint256 leaf = poseidon.poseidon([commitment, LEVEL]);
        uint256 node = leaf;
        uint256 i = index;
        for (uint256 h = 0; h < DEPTH; h++) {
            if (i & 1 == 0) {
                filled[h] = node;
                node = poseidon.poseidon([node, zeros[h]]);
            } else {
                node = poseidon.poseidon([filled[h], node]);
            }
            i >>= 1;
        }
        root = node;
        rootSeen[node] = true;
        emit Deposit(commitment, leaf, index, node);
        // the whole denomination must arrive (no fee-on-transfer): the balance covers every unspent note after the pull
        if (!token.transferFrom(msg.sender, address(this), denomination) || token.balanceOf(address(this)) < (leafCount - spent) * denomination) revert TokenFailed();
    }

    /// Withdraws one note to `recipient` (denomination - fee), paying `fee` to the caller.
    /// proof = [a0, a1, b00, b01, b10, b11, c0, c1] (zetaphy-hub/zkid-core.js proofWords).
    function withdraw(address recipient, uint256 fee, uint256 root_, uint256 nullifier, uint256[8] calldata proof) external nonReentrant {
        if (!rootSeen[root_]) revert UnknownRoot();
        if (nullifierUsed[nullifier]) revert Spent();
        if (fee > denomination || recipient == address(0)) revert BadFee();
        nullifierUsed[nullifier] = true;
        spent += 1;
        emit Withdrawal(nullifier, recipient, msg.sender, fee);
        // the proof (a view of the immutable verifier) before any token moves; a bad one reverts the marks above
        if (!verifier.verifyProof([proof[0], proof[1]], [[proof[2], proof[3]], [proof[4], proof[5]]], [proof[6], proof[7]],
            [root_, nullifier, scope, signalOf(recipient, fee), LEVEL])) revert BadProof();
        if (!token.transfer(recipient, denomination - fee)) revert TokenFailed();
        if (fee != 0 && !token.transfer(msg.sender, fee)) revert TokenFailed();
    }
}

contracts/SaphanProofs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan, proven releases: ZETAPHY -> source chain without trusting any validator
/// @notice Two contracts (docs/SAPHAN-PROOFS.md), testnet only, not audited:
///
///         ZETAPHY       SaphanProvableOutbox(X) sits in front of the route's HyperlaneOutbox (same send / quoteSend):
///                       it takes the tokens, has the outbox burn them and send the usual Hyperlane release, AND writes
///                       the very same release body into ZetaphyOutbox (the Merkle outbox whose root lives in ZETAPHY's
///                       state). The Gateway and wallets use it instead of the outbox.
///         source X      SaphanReleaseVerifier checks a release body against ZETAPHY's state: the ZetaphyOutbox root at
///                       a ZETAPHY block that StarkLightClient finalized (a STARK proof of > 2/3 of ZETAPHY's validators,
///                       ML-DSA-44 votes counted by its pq modes), the IAVL / multistore path to that block's app_hash,
///                       and the leaf's Merkle path. Then HyperlaneLockBoxV2.queueProven(body) queues it exactly as a
///                       Hyperlane message would (same id: whichever path comes first; the other is a replay).
///
///         With the lockbox's requireProof on (governance), the Hyperlane path no longer releases anything: outbound
///         money then moves on math alone (hash-based STARK, ML-DSA finality), no ECDSA signer anywhere in the way.

interface IProofOutbox {
    function send(address to, uint256 amount) external payable returns (bytes32);
    function quoteSend(address to, uint256 amount) external view returns (uint256);
    function body(uint256 n, address sender, address to, uint256 amount) external view returns (bytes memory);
    function nonce() external view returns (uint256);
    function destinationChainId() external view returns (uint256);
    function recipient() external view returns (bytes32);
}

interface IMerkleOutbox {
    function send(uint256 dstChainId, address receiver, bytes calldata payload) external returns (uint64);
}

interface IProofToken {
    function transferFrom(address from, address to, uint256 v) external returns (bool);
}

contract SaphanProvableOutbox {
    IProofOutbox public immutable outbox;        // the route's HyperlaneOutbox
    IMerkleOutbox public immutable merkleOutbox; // ZetaphyOutbox (provable from ZETAPHY's state)
    IProofToken public immutable token;          // token(X)
    address public immutable lockbox;            // HyperlaneLockBoxV2 on X (the receiver in every leaf)
    uint256 public immutable destinationChainId;

    event ProvableSent(uint256 indexed outboxNonce, uint64 indexed merkleNonce, address indexed from, address to, uint256 amount, bytes32 bodyHash);

    error PayFailed();
    error Fee(uint256 required);

    /// lockbox_ and destinationChainId_ must be the outbox's own (checked last, against the outbox).
    constructor(IProofOutbox outbox_, IMerkleOutbox merkleOutbox_, IProofToken token_, address lockbox_, uint256 destinationChainId_) {
        outbox = outbox_;
        merkleOutbox = merkleOutbox_;
        token = token_;
        lockbox = lockbox_;
        destinationChainId = destinationChainId_;
        require(lockbox_ != address(0) && outbox_.recipient() == bytes32(uint256(uint160(lockbox_)))
            && outbox_.destinationChainId() == destinationChainId_, "config");
    }

    function quoteSend(address to, uint256 amount) external view returns (uint256) { return outbox.quoteSend(to, amount); }

    /// Like HyperlaneOutbox.send (approve this contract for `amount` of token(X) first). msg.value: exactly the
    /// Mailbox fee (quoteSend); all of it goes on to the outbox, so this contract never holds ether.
    function send(address to, uint256 amount) external payable returns (bytes32 messageId) {
        uint256 fee = outbox.quoteSend(to, amount);
        if (msg.value != fee) revert Fee(fee);
        uint256 n = outbox.nonce();
        bytes memory b = outbox.body(n, address(this), to, amount); // the body the outbox is about to send
        uint64 m = merkleOutbox.send(destinationChainId, lockbox, b);
        emit ProvableSent(n, m, msg.sender, to, amount, keccak256(b));
        if (!token.transferFrom(msg.sender, address(this), amount)) revert PayFailed();
        messageId = outbox.send{value: fee}(to, amount);  // burns this contract's tokens; the same nonce n
    }
}


interface IProofLightClient {
    function appHashAt(uint64 height) external view returns (bytes32);
}

/// The pure proof functions of ZetaphyBridgeInbox (any deployed instance: they read no state).
interface IZetaphyProofs {
    struct InnerOp { bytes prefix; bytes suffix; }
    function outboxRoot(bytes32 leaf, uint64 index, bytes32[32] calldata sib, uint64 count) external pure returns (bytes32);
    function iavlRoot(bytes memory key, bytes32 value, bytes calldata leafPrefix, InnerOp[] calldata path) external pure returns (bytes32);
    function storeRoot(bytes memory name, bytes32 root, InnerOp[] calldata path) external pure returns (bytes32);
}

interface IProvenLockbox {
    function queueProven(bytes calldata body) external;
}

/// @title SaphanReleaseVerifier: on the source chain X, a release proven from ZETAPHY's state (see above)
contract SaphanReleaseVerifier {
    struct StateProof {
        bytes32 outboxRoot;                  // ZetaphyOutbox's slot 0 at that block
        bytes iavlLeafPrefix;
        IZetaphyProofs.InnerOp[] iavlPath;   // evm store, leaf to root
        IZetaphyProofs.InnerOp[] storePath;  // multistore, evm store root to app hash
    }

    bytes32 public constant LEAF_TAG = keccak256("zetaphy/outbox/v1");
    IProofLightClient public immutable lightClient;  // StarkLightClient: ZETAPHY finality on this chain
    IZetaphyProofs public immutable proofs;
    uint256 public immutable zetaphyChainId;
    address public immutable merkleOutbox;            // ZetaphyOutbox on ZETAPHY
    address public immutable provableSender;          // SaphanProvableOutbox(X) on ZETAPHY: the only sender it accepts
    IProvenLockbox public immutable lockbox;          // HyperlaneLockBoxV2 here

    event Proven(uint64 indexed merkleNonce, uint64 height, bytes32 bodyHash);

    error BadStateProof(uint256 step);
    error BadMessage();

    constructor(IProofLightClient lc, IZetaphyProofs proofs_, uint256 zetaphyChainId_, address merkleOutbox_, address provableSender_, IProvenLockbox lockbox_) {
        require(address(lc) != address(0) && address(proofs_) != address(0) && merkleOutbox_ != address(0) && provableSender_ != address(0)
            && address(lockbox_) != address(0), "config");
        lightClient = lc;
        proofs = proofs_;
        zetaphyChainId = zetaphyChainId_;
        merkleOutbox = merkleOutbox_;
        provableSender = provableSender_;
        lockbox = lockbox_;
    }

    /// Anyone: proves the release `body` (the leaf `nonce` of ZetaphyOutbox, sent by the provable outbox to this lockbox)
    /// at ZETAPHY block `height`, then queues it in the lockbox (each body once there).
    function prove(uint64 height, StateProof calldata sp, uint64 nonce, bytes calldata body, bytes32[32] calldata siblings, uint64 count) external {
        if (body.length != 256) revert BadMessage();
        bytes32 app = lightClient.appHashAt(height);
        if (app == bytes32(0)) revert BadStateProof(0);
        bytes32 evmRoot = proofs.iavlRoot(abi.encodePacked(uint8(2), merkleOutbox, bytes32(0)), sp.outboxRoot, sp.iavlLeafPrefix, sp.iavlPath);
        if (proofs.storeRoot("evm", evmRoot, sp.storePath) != app) revert BadStateProof(2);
        bytes32 leaf = sha256(abi.encode(LEAF_TAG, zetaphyChainId, merkleOutbox, nonce, provableSender, block.chainid, address(lockbox), sha256(body)));
        if (nonce >= count || proofs.outboxRoot(leaf, nonce, siblings, count) != sp.outboxRoot) revert BadStateProof(4);
        emit Proven(nonce, height, keccak256(body));
        lockbox.queueProven(body);
    }
}

contracts/SaphanReads.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title ZETAPHY Saphan cross-chain reads: "what is value V on chain X at block B"
/// @notice Saphan PR 5 (docs/SAPHAN-PR5.md), testnet only, not audited. Three contracts and a library:
///
///   SaphanReads (ZETAPHY, one per source chain X) keeps the newest known answer to each question about X, with the
///     X block it is from. Answers come two ways, both without a new signer:
///       - lane answers: SaphanReadResponder on X runs a view call on X and sends the result, its block number and
///         time through X's Hyperlane Mailbox; the Mailbox on ZETAPHY checks the route's ISM (the Hyperlane
///         validators that already attest every transfer from X) before handle() records it;
///       - proven answers: a storage slot or account of X checked against X's state root at block B, given by a
///         light client of X (`stateRoots`), with the Merkle-Patricia proofs of eth_getProof (SaphanMpt). No light
///         client of an EVM chain runs on ZETAPHY yet: until one does, `stateRoots` is zero and only lane answers
///         are used (the verifier itself is complete and tested against an EVM's own proofs).
///     The caller pays: request*() posts a bounty in ZTPHY for an answer at block >= minBlock before a deadline;
///     whoever brought that answer collects it (pull). read*() refuses an answer older than the caller allows
///     (block below minBlock, or time older than maxAge): stale answers are never served.
///   SaphanReadResponder (source chain X): anyone asks it to answer a view call; the answerer pays the Mailbox fee.
///     It gives the call a fixed gas budget and checks it is there first, so nobody can make a call fail on purpose.
///   SaphanZetaphyReads (source chain X): the other way round, a storage slot of any ZETAPHY contract verified from
///     ZETAPHY's state at a height the STARK light client finalized (the SaphanReleaseVerifier pattern: IAVL path to
///     the evm store, multistore path to the app hash); a view a contract on X calls with the proof.

/// What a light client of chain X tells: X's state root (and block time) at a block it accepted. Zero: unknown.
interface IReadsStateRoots {
    function stateRootAt(uint64 blockNumber) external view returns (bytes32 stateRoot, uint64 timestamp);
}

interface IReadsMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256);
}

/// @notice Ethereum Merkle-Patricia proofs (the `accountProof` / `storageProof` of eth_getProof), checked in memory.
///         Proofs of absence (a path that ends in an empty branch slot or a diverging leaf / extension) give an empty
///         value. Nodes shorter than 32 bytes embedded in their parent are refused: with keccak-hashed 32-byte keys
///         they do not occur in practice, and refusing them keeps the walk simple.
library SaphanMpt {
    bytes32 internal constant EMPTY_TRIE = 0x56e81f171bcc55a6ff8345e692c0f86e5b48e01b996cadc001622fb5e363b421; // keccak256(0x80)
    bytes32 internal constant EMPTY_CODE = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470; // keccak256("")

    error BadProof(uint256 step);

    /// The value at `key` (already hashed) under `root`; empty when the proof shows there is none.
    function get(bytes32 root, bytes32 key, bytes[] memory proof) internal pure returns (bytes memory) {
        bytes32 want = root;
        uint256 pos = 0;
        for (uint256 i = 0; i < proof.length; i++) {
            bytes memory node = proof[i];
            if (keccak256(node) != want) revert BadProof(i);
            (bool done, bytes memory value, bytes32 next, uint256 npos) = _step(node, key, pos, i);
            if (done) {
                if (i + 1 != proof.length) revert BadProof(i); // an answer must end the proof
                return value;
            }
            (want, pos) = (next, npos);
        }
        revert BadProof(proof.length); // the proof stops before an answer
    }

    /// One node of the walk: the answer (done), or the next node's hash and the key position after this node.
    function _step(bytes memory node, bytes32 key, uint256 pos, uint256 i)
        private pure returns (bool done, bytes memory value, bytes32 next, uint256 npos)
    {
        (uint256[2][17] memory it, uint256 n) = _node(node);
        if (n == 17) { // branch
            if (pos >= 64) revert BadProof(i);
            uint256[2] memory child = it[_nibble(key, pos)];
            if (child[1] == 0) return (true, "", 0, 0);   // an empty slot: no value
            if (child[1] != 32) revert BadProof(i);
            return (false, "", _word(node, child[0]), pos + 1);
        }
        if (n != 2) revert BadProof(i);
        (bool matched, uint256 plen, bool leaf) = _path(node, it[0][0], it[0][1], key, pos, i);
        if (!matched) return (true, "", 0, 0);            // the path leaves the key: no value
        if (leaf) return (true, pos + plen == 64 ? _slice(node, it[1][0], it[1][1]) : bytes(""), 0, 0);
        if (it[1][1] != 32) revert BadProof(i);           // extension: a hash
        return (false, "", _word(node, it[1][0]), pos + plen);
    }

    /// A leaf / extension path (hex-prefix encoded at node[p..p+l]) against the key from nibble `pos`.
    function _path(bytes memory node, uint256 p, uint256 l, bytes32 key, uint256 pos, uint256 i)
        private pure returns (bool matched, uint256 plen, bool leaf)
    {
        if (l == 0) revert BadProof(i);
        uint8 flag = uint8(node[p]) >> 4;
        if (flag > 3) revert BadProof(i);
        leaf = flag >= 2;
        uint256 skip = flag & 1 == 1 ? 1 : 2;
        plen = l * 2 - skip;
        for (uint256 j = 0; j < plen; j++) {
            uint256 k = j + skip;
            uint8 pn = k % 2 == 0 ? uint8(node[p + k / 2]) >> 4 : uint8(node[p + k / 2]) & 0x0f;
            if (pos + j >= 64 || pn != _nibble(key, pos + j)) return (false, plen, leaf);
        }
        matched = true;
    }

    /// An account of the state trie: (exists, nonce, balance, storage root, code hash).
    function account(bytes32 stateRoot, address who, bytes[] memory proof)
        internal pure returns (bool exists, uint256 nonce, uint256 balance, bytes32 storageRoot, bytes32 codeHash)
    {
        bytes memory v = get(stateRoot, keccak256(abi.encodePacked(who)), proof);
        if (v.length == 0) return (false, 0, 0, EMPTY_TRIE, EMPTY_CODE);
        (uint256[2][17] memory it, uint256 n) = _node(v);
        if (n != 4 || it[2][1] != 32 || it[3][1] != 32 || it[0][1] > 32 || it[1][1] > 32) revert BadProof(100);
        return (true, _uint(v, it[0][0], it[0][1]), _uint(v, it[1][0], it[1][1]), _word(v, it[2][0]), _word(v, it[3][0]));
    }

    /// A storage slot under an account's storage root (zero when absent).
    function slot(bytes32 storageRoot, bytes32 key, bytes[] memory proof) internal pure returns (uint256) {
        if (storageRoot == EMPTY_TRIE) { if (proof.length != 0) revert BadProof(200); return 0; }
        bytes memory v = get(storageRoot, keccak256(abi.encode(key)), proof);
        if (v.length == 0) return 0;
        (uint256 p, uint256 l, bool list) = _item(v, 0);
        if (list || l > 32 || p + l != v.length) revert BadProof(201);
        return _uint(v, p, l);
    }

    // ---- RLP ----

    /// The items of the list that is the whole of `b`: (payload offset, payload length) each; lists inside are refused.
    function _node(bytes memory b) private pure returns (uint256[2][17] memory it, uint256 n) {
        (uint256 p, uint256 l, bool list) = _item(b, 0);
        if (!list || p + l != b.length) revert BadProof(300);
        uint256 end = p + l;
        while (p < end) {
            if (n == 17) revert BadProof(301);
            (uint256 ip, uint256 il, bool inner) = _item(b, p);
            if (inner) revert BadProof(302); // an embedded node
            it[n] = [ip, il];
            n += 1;
            p = ip + il;
        }
        if (p != end) revert BadProof(303);
    }

    function _item(bytes memory b, uint256 off) private pure returns (uint256 p, uint256 len, bool list) {
        if (off >= b.length) revert BadProof(400);
        uint8 x = uint8(b[off]);
        if (x < 0x80) return (off, 1, false);
        if (x < 0xb8) { len = x - 0x80; p = off + 1; }
        else if (x < 0xc0) { uint256 ll = x - 0xb7; len = _be(b, off + 1, ll); p = off + 1 + ll; }
        else if (x < 0xf8) { len = x - 0xc0; p = off + 1; list = true; }
        else { uint256 ll = x - 0xf7; len = _be(b, off + 1, ll); p = off + 1 + ll; list = true; }
        if (p + len > b.length) revert BadProof(401);
    }

    function _be(bytes memory b, uint256 off, uint256 n) private pure returns (uint256 v) {
        if (n > 4 || off + n > b.length) revert BadProof(402);
        for (uint256 i = 0; i < n; i++) v = (v << 8) | uint8(b[off + i]);
    }

    function _uint(bytes memory b, uint256 p, uint256 l) private pure returns (uint256 v) {
        for (uint256 i = 0; i < l; i++) v = (v << 8) | uint8(b[p + i]);
    }

    function _word(bytes memory b, uint256 p) private pure returns (bytes32 w) {
        assembly { w := mload(add(add(b, 0x20), p)) }
    }

    function _slice(bytes memory b, uint256 p, uint256 l) private pure returns (bytes memory out) {
        out = new bytes(l);
        for (uint256 i = 0; i < l; i++) out[i] = b[p + i];
    }

    function _nibble(bytes32 key, uint256 i) private pure returns (uint8) {
        uint8 byt = uint8(key[i / 2]);
        return i % 2 == 0 ? byt >> 4 : byt & 0x0f;
    }
}

/// @title SaphanReads: answers about source chain X on ZETAPHY, each with the X block it is from
contract SaphanReads {
    bytes32 public constant CALL_TAG = keccak256("saphan/reads/call/v1");
    bytes32 public constant SLOT_TAG = keccak256("saphan/reads/slot/v1");
    bytes32 public constant ACCOUNT_TAG = keccak256("saphan/reads/account/v1");
    /// An answer may be at most this far ahead of ZETAPHY's clock (clocks of two chains differ a little).
    uint64 public constant MAX_SKEW = 5 minutes;
    /// The longest a request waits for its answer.
    uint64 public constant MAX_TTL = 7 days;
    /// The longest result kept (SaphanReadResponder sends no longer one).
    uint256 public constant MAX_RESULT = 1024;

    struct Answer {
        uint64 blockNumber;  // the X block the answer is from
        uint64 timestamp;    // that block's time
        uint64 arrivedAt;    // when it reached ZETAPHY
        bool ok;             // a view call: it did not revert
        address by;          // who brought it (the answerer on X, or the prover here): collects bounties
        bytes result;        // a view call: its return data; a slot: abi.encode(value); an account: abi.encode(nonce, balance, storageRoot, codeHash)
    }

    struct Request {
        address requester;
        uint64 minBlock;
        uint64 expires;
        bool done;
        bytes32 query;
        uint256 bounty;
    }

    uint256 public immutable remoteChainId;     // X
    uint32 public immutable originDomain;       // X's Hyperlane domain
    address public immutable mailbox;           // the Mailbox on ZETAPHY
    /// Hyperlane reads it (ISpecifiesInterchainSecurityModule): the route's ISM of Hyperlane's validators for X.
    address public immutable interchainSecurityModule;
    IReadsStateRoots public immutable stateRoots; // a light client of X; zero: no proven answers yet
    address public immutable deployer;
    bytes32 public responder;                   // SaphanReadResponder on X (set once, then fixed)

    mapping(bytes32 => Answer) private _answers;
    mapping(uint256 => Request) public requests;
    uint256 public requestCount;
    mapping(address => uint256) public credit;  // bounties collected, taken with claim()
    uint256 private entered;

    event ResponderSet(bytes32 responder);
    event Answered(bytes32 indexed query, uint64 blockNumber, uint64 timestamp, bool ok, address by, bool proven);
    event Ignored(bytes32 indexed query, uint64 blockNumber);
    event Requested(uint256 indexed id, bytes32 indexed query, uint64 minBlock, uint64 expires, uint256 bounty, uint8 kind, address target, bytes data);
    event Collected(uint256 indexed id, address indexed by, uint256 bounty);
    event Cancelled(uint256 indexed id);
    event Claimed(address indexed who, uint256 amount);

    error NotMailbox();
    error NoValue();
    error WrongOrigin();
    error WrongSender();
    error NoLightClient();
    error UnknownBlock();
    error Older();
    error BadAnswer();
    error NoAnswer();
    error Stale(uint64 blockNumber, uint64 timestamp);
    error CallReverted();
    error BadRequest();
    error NotReady();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    constructor(uint256 remoteChainId_, address mailbox_, uint32 originDomain_, address ism_, IReadsStateRoots stateRoots_) {
        require(remoteChainId_ != 0 && mailbox_ != address(0), "config");
        remoteChainId = remoteChainId_;
        mailbox = mailbox_;
        originDomain = originDomain_;
        interchainSecurityModule = ism_;
        stateRoots = stateRoots_;
        deployer = msg.sender;
    }

    /// Once, by the deployer: the responder on X (deployed after this contract, it names this one).
    function setResponder(address r) external {
        require(msg.sender == deployer && responder == bytes32(0) && r != address(0), "responder");
        responder = bytes32(uint256(uint160(r)));
        emit ResponderSet(responder);
    }

    // ---- questions ----

    function callQuery(address target, bytes calldata data) public view returns (bytes32) { return _callQuery(target, keccak256(data)); }
    function slotQuery(address account, bytes32 slot_) public view returns (bytes32) { return keccak256(abi.encode(SLOT_TAG, remoteChainId, account, slot_)); }
    function accountQuery(address account) public view returns (bytes32) { return keccak256(abi.encode(ACCOUNT_TAG, remoteChainId, account)); }
    function _callQuery(address target, bytes32 dataHash) private view returns (bytes32) { return keccak256(abi.encode(CALL_TAG, remoteChainId, target, dataHash)); }

    // ---- answers ----

    /// The Mailbox, after the ISM checked the message: a view call answered on X by the responder.
    /// A message that cannot be used (older than what is known, too far in the future) is consumed and ignored,
    /// so it never blocks the Mailbox.
    function handle(uint32 origin, bytes32 sender, bytes calldata body) external payable {
        if (msg.sender != mailbox) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != originDomain) revert WrongOrigin();
        if (sender != responder || sender == bytes32(0)) revert WrongSender();
        (address target, bytes32 dataHash, uint64 blockNumber, uint64 timestamp, bool ok, bytes memory result, address by) =
            abi.decode(body, (address, bytes32, uint64, uint64, bool, bytes, address));
        bytes32 q = _callQuery(target, dataHash);
        if (!_record(q, blockNumber, timestamp, ok, result, by, false)) emit Ignored(q, blockNumber);
    }

    /// Anyone: a storage slot of `account` on X at `blockNumber`, proven against the light client's state root.
    function proveSlot(uint64 blockNumber, address account, bytes32 slot_, bytes[] calldata accountProof, bytes[] calldata storageProof)
        external returns (uint256 value)
    {
        (bytes32 root, uint64 ts) = _root(blockNumber);
        (, , , bytes32 storageRoot, ) = SaphanMpt.account(root, account, accountProof);
        value = SaphanMpt.slot(storageRoot, slot_, storageProof);
        if (!_record(slotQuery(account, slot_), blockNumber, ts, true, abi.encode(value), msg.sender, true)) revert Older();
    }

    /// Anyone: an account of X (nonce, balance, storage root, code hash) at `blockNumber`, proven the same way.
    function proveAccount(uint64 blockNumber, address account, bytes[] calldata accountProof) external {
        (bytes32 root, uint64 ts) = _root(blockNumber);
        (, uint256 nonce, uint256 balance, bytes32 storageRoot, bytes32 codeHash) = SaphanMpt.account(root, account, accountProof);
        if (!_record(accountQuery(account), blockNumber, ts, true, abi.encode(nonce, balance, storageRoot, codeHash), msg.sender, true)) revert Older();
    }

    function _root(uint64 blockNumber) private view returns (bytes32 root, uint64 ts) {
        if (address(stateRoots) == address(0)) revert NoLightClient();
        (root, ts) = stateRoots.stateRootAt(blockNumber);
        if (root == bytes32(0)) revert UnknownBlock();
    }

    /// Keeps an answer when it is newer than the one known (answers never go back in time).
    function _record(bytes32 q, uint64 blockNumber, uint64 timestamp, bool ok, bytes memory result, address by, bool proven) private returns (bool) {
        Answer storage a = _answers[q];
        if (a.arrivedAt != 0 && blockNumber <= a.blockNumber) return false;
        if (timestamp > block.timestamp + MAX_SKEW || result.length > MAX_RESULT) return false;
        _answers[q] = Answer(blockNumber, timestamp, uint64(block.timestamp), ok, by, result);
        emit Answered(q, blockNumber, timestamp, ok, by, proven);
        return true;
    }

    // ---- reading (stale answers refused) ----

    /// The newest answer, if it is from block >= minBlock and its time is at most maxAge seconds old.
    function read(bytes32 query, uint64 minBlock, uint64 maxAge) public view returns (bool ok, bytes memory result, uint64 blockNumber, uint64 timestamp) {
        Answer storage a = _answers[query];
        if (a.arrivedAt == 0) revert NoAnswer();
        if (a.blockNumber < minBlock || uint256(a.timestamp) + maxAge < block.timestamp) revert Stale(a.blockNumber, a.timestamp);
        return (a.ok, a.result, a.blockNumber, a.timestamp);
    }

    /// A view call's return data (reverts CallReverted when the call reverted on X).
    function readCall(address target, bytes calldata data, uint64 minBlock, uint64 maxAge) external view returns (bytes memory result, uint64 blockNumber, uint64 timestamp) {
        bool ok;
        (ok, result, blockNumber, timestamp) = read(callQuery(target, data), minBlock, maxAge);
        if (!ok) revert CallReverted();
    }

    function readSlot(address account, bytes32 slot_, uint64 minBlock, uint64 maxAge) external view returns (uint256 value, uint64 blockNumber, uint64 timestamp) {
        bytes memory r;
        (, r, blockNumber, timestamp) = read(slotQuery(account, slot_), minBlock, maxAge);
        value = abi.decode(r, (uint256));
    }

    function readBalance(address account, uint64 minBlock, uint64 maxAge) external view returns (uint256 balance, uint64 blockNumber, uint64 timestamp) {
        bytes memory r;
        (, r, blockNumber, timestamp) = read(accountQuery(account), minBlock, maxAge);
        (, balance, , ) = abi.decode(r, (uint256, uint256, bytes32, bytes32));
    }

    /// The newest answer as stored (no age check), for explorers.
    function answerOf(bytes32 query) external view returns (Answer memory) { return _answers[query]; }

    // ---- requests: the caller pays ----

    uint8 internal constant KIND_CALL = 0;
    uint8 internal constant KIND_SLOT = 1;
    uint8 internal constant KIND_ACCOUNT = 2;

    /// A bounty (msg.value) for an answer of `target.call(data)` on X at block >= minBlock, within ttl seconds.
    function requestCall(address target, bytes calldata data, uint64 minBlock, uint64 ttl) external payable returns (uint256) {
        return _request(callQuery(target, data), minBlock, ttl, KIND_CALL, target, data);
    }

    function requestSlot(address account, bytes32 slot_, uint64 minBlock, uint64 ttl) external payable returns (uint256) {
        return _request(slotQuery(account, slot_), minBlock, ttl, KIND_SLOT, account, abi.encode(slot_));
    }

    function requestAccount(address account, uint64 minBlock, uint64 ttl) external payable returns (uint256) {
        return _request(accountQuery(account), minBlock, ttl, KIND_ACCOUNT, account, "");
    }

    function _request(bytes32 q, uint64 minBlock, uint64 ttl, uint8 kind, address target, bytes memory data) private returns (uint256 id) {
        if (msg.value == 0 || ttl == 0 || ttl > MAX_TTL) revert BadRequest();
        id = requestCount++;
        uint64 expires = uint64(block.timestamp) + ttl;
        requests[id] = Request(msg.sender, minBlock, expires, false, q, msg.value);
        emit Requested(id, q, minBlock, expires, msg.value, kind, target, data);
    }

    /// Anyone, once an answer from block >= minBlock arrived before the request expired: its bringer gets the bounty.
    function collect(uint256 id) external {
        Request storage r = requests[id];
        Answer storage a = _answers[r.query];
        if (r.requester == address(0) || r.done) revert BadRequest();
        if (a.arrivedAt == 0 || a.blockNumber < r.minBlock || a.arrivedAt > r.expires) revert NotReady();
        r.done = true;
        credit[a.by] += r.bounty;
        emit Collected(id, a.by, r.bounty);
    }

    /// The requester, after an unanswered request expired: the bounty back (credited, then claim()).
    function cancel(uint256 id) external {
        Request storage r = requests[id];
        if (r.requester != msg.sender || r.done) revert BadRequest();
        if (block.timestamp <= r.expires) revert NotReady();
        r.done = true;
        credit[msg.sender] += r.bounty;
        emit Cancelled(id);
    }

    /// What the caller collected or got back.
    function claim() external nonReentrant {
        uint256 v = credit[msg.sender];
        if (v == 0) revert NotReady();
        credit[msg.sender] = 0;
        emit Claimed(msg.sender, v);
        (bool ok, ) = msg.sender.call{value: v}("");
        if (!ok) revert PayFailed();
    }
}

/// @title SaphanReadResponder: on source chain X, answers view calls to SaphanReads on ZETAPHY through Hyperlane
contract SaphanReadResponder {
    /// The gas every view call gets (fixed, so an answerer cannot make a call fail by giving it less).
    uint256 public constant READ_GAS = 500_000;
    uint256 public constant MAX_RESULT = 1024;

    IReadsMailbox public immutable mailbox;   // X's Mailbox
    uint32 public immutable zetaphyDomain;
    bytes32 public immutable reads;           // SaphanReads(X) on ZETAPHY

    event Answer(bytes32 indexed messageId, address indexed target, bytes32 dataHash, uint64 blockNumber, address by);

    error Fee(uint256 needed);
    error LowGas();

    constructor(IReadsMailbox mailbox_, uint32 zetaphyDomain_, address reads_) {
        require(address(mailbox_) != address(0) && reads_ != address(0), "config");
        mailbox = mailbox_;
        zetaphyDomain = zetaphyDomain_;
        reads = bytes32(uint256(uint160(reads_)));
    }

    /// The message an answer of `target.call(data)` made now by `by` would carry (a result longer than MAX_RESULT
    /// counts as a failed call, so every answer fits).
    function body(address target, bytes calldata data, address by) public view returns (bytes memory) {
        if (gasleft() < READ_GAS + READ_GAS / 63 + 30_000) revert LowGas();
        (bool ok, bytes memory result) = target.staticcall{gas: READ_GAS}(data);
        if (result.length > MAX_RESULT) { ok = false; result = ""; }
        return abi.encode(target, keccak256(data), uint64(block.number), uint64(block.timestamp), ok, result, by);
    }

    function quote(address target, bytes calldata data) external view returns (uint256) {
        return mailbox.quoteDispatch(zetaphyDomain, reads, body(target, data, msg.sender));
    }

    /// Anyone: answers `target.call(data)` at this block. msg.value: exactly the Mailbox fee (quote).
    function answer(address target, bytes calldata data) external payable returns (bytes32 messageId) {
        bytes memory b = body(target, data, msg.sender);
        uint256 fee = mailbox.quoteDispatch(zetaphyDomain, reads, b);
        if (msg.value != fee) revert Fee(fee);
        messageId = mailbox.dispatch{value: fee}(zetaphyDomain, reads, b);
        emit Answer(messageId, target, keccak256(data), uint64(block.number), msg.sender);
    }
}

interface IReadsLightClient {
    function appHashAt(uint64 height) external view returns (bytes32);
}

/// ZetaphyBridgeInbox's pure proof functions (any deployed instance).
interface IReadsZetaphyProofs {
    struct InnerOp { bytes prefix; bytes suffix; }
    function iavlRoot(bytes memory key, bytes32 value, bytes calldata leafPrefix, InnerOp[] calldata path) external pure returns (bytes32);
    function storeRoot(bytes memory name, bytes32 root, InnerOp[] calldata path) external pure returns (bytes32);
}

/// @title SaphanZetaphyReads: on a source chain, a storage slot of a ZETAPHY contract proven from ZETAPHY's state
/// @notice A view: a contract on this chain calls verify() inside its own transaction with the proof (nothing is
///         stored, so every reader checks its own proof and decides how recent it must be).
contract SaphanZetaphyReads {
    IReadsLightClient public immutable lightClient; // StarkLightClient: ZETAPHY finality on this chain
    IReadsZetaphyProofs public immutable proofs;

    error BadStateProof(uint256 step);
    error Stale(uint64 height, uint64 minHeight);

    constructor(IReadsLightClient lc, IReadsZetaphyProofs proofs_) {
        require(address(lc) != address(0) && address(proofs_) != address(0), "config");
        lightClient = lc;
        proofs = proofs_;
    }

    /// Returns `value` when `account`'s storage `slot` holds it at ZETAPHY height `height` (final in the light client)
    /// and height >= minHeight; reverts otherwise. An existence proof: a slot never written cannot be shown this way.
    function verify(uint64 height, uint64 minHeight, address account, bytes32 slot, bytes32 value, bytes calldata leafPrefix,
        IReadsZetaphyProofs.InnerOp[] calldata iavlPath, IReadsZetaphyProofs.InnerOp[] calldata storePath) external view returns (bytes32)
    {
        if (height < minHeight) revert Stale(height, minHeight);
        bytes32 app = lightClient.appHashAt(height);
        if (app == bytes32(0)) revert BadStateProof(0);
        bytes32 evmRoot = proofs.iavlRoot(abi.encodePacked(uint8(2), account, slot), value, leafPrefix, iavlPath);
        if (proofs.storeRoot("evm", evmRoot, storePath) != app) revert BadStateProof(1);
        return value;
    }
}

contracts/SaphanRecovery.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRecoveryToken {
    function transfer(address to, uint256 v) external returns (bool);
    function transferFrom(address from, address to, uint256 v) external returns (bool);
    function balanceOf(address who) external view returns (uint256);
}

/// @title SaphanRecoveryClaims: pay back what an incident owed, from a Merkle root of owed balances
/// @notice Saphan PR 6, item S10 (docs/SAPHAN-PR6.md). Testnet only, not audited.
///
///         The guided recovery after an incident (`node scripts/saphan.js recovery ...`):
///           1. pause      guardians pause the route (lockbox, guard), as today;
///           2. snapshot   who is owed what, rebuilt by anyone from public events (src/saphanrecovery.js: balances of
///                         token(X) at the incident block, releases queued and not paid, locks never minted, minus
///                         what the attacker took if governance decides so). The SAME leaf and tree as the lockbox's
///                         escape hatch (src/saphansafety.js exitTree): leaf = keccak256(keccak256(abi.encode(account,
///                         owed))), sorted-pair Merkle tree;
///           3. claims     governance (the ZetaphyTimelock: its delay gives everyone time to check the root against
///                         their own rebuild) deploys this contract and calls start(root, total) once; anyone funds it
///                         (insurance, treasury, recovered funds); each account claims its line once, in full when the
///                         pool covers the total, else pro rata; after `claimPeriod`, sweep() sends what is left to
///                         `sweepTo` (e.g. the HackInsurance pool);
///           4. resume     governance unpauses the route (the CLI checks that the root was set and lists the calls).
///
///         The pool is fixed at start(): coins that arrive later are swept, so the order of claims never changes
///         anyone's share. Pull payment to the caller only; nonReentrant; no admin besides the one start() call.
contract SaphanRecoveryClaims {
    address public immutable governance;   // ZetaphyTimelock
    address public immutable token;        // address(0): the native coin
    address public immutable sweepTo;
    uint64 public immutable claimPeriod;

    bytes32 public root;
    uint256 public total;                  // the sum the root owes
    uint256 public pool;                   // what this contract held at start()
    uint256 public paid;
    uint64 public deadline;
    bool public swept;
    mapping(address => bool) public claimed;
    uint256 private unlocked = 1;

    event Funded(address indexed from, uint256 amount);
    event Started(bytes32 root, uint256 total, uint256 pool, uint64 deadline);
    event Claimed(address indexed account, uint256 owed, uint256 paid);
    event Swept(address to, uint256 amount);

    error NotGovernance();
    error AlreadyStarted();
    error NotStarted();
    error BadRoot();
    error AlreadyClaimed();
    error BadProof();
    error Closed();
    error StillOpen(uint64 deadline);
    error PayFailed();
    error Reentrancy();
    error WrongAsset();

    modifier nonReentrant() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    constructor(address governance_, address token_, address sweepTo_, uint64 claimPeriod_) {
        require(governance_ != address(0) && sweepTo_ != address(0) && claimPeriod_ >= 7 days, "config");
        governance = governance_;
        token = token_;
        sweepTo = sweepTo_;
        claimPeriod = claimPeriod_;
    }

    receive() external payable {
        if (token != address(0)) revert WrongAsset();
        emit Funded(msg.sender, msg.value);
    }

    /// Funds a token pool (approve first).
    function fund(uint256 amount) external nonReentrant {
        if (token == address(0)) revert WrongAsset();
        emit Funded(msg.sender, amount);
        if (!IRecoveryToken(token).transferFrom(msg.sender, address(this), amount)) revert PayFailed();
    }

    /// Governance, once: the root of what is owed and its total. The pool is what this contract holds now.
    function start(bytes32 root_, uint256 total_) external {
        if (msg.sender != governance) revert NotGovernance();
        if (root != bytes32(0)) revert AlreadyStarted();
        if (root_ == bytes32(0) || total_ == 0) revert BadRoot();
        root = root_;
        total = total_;
        pool = _held();
        deadline = uint64(block.timestamp) + claimPeriod;
        emit Started(root_, total_, pool, deadline);
    }

    /// What `owed` pays now: in full when the pool covers the total, else owed x pool / total.
    function payout(uint256 owed) public view returns (uint256) {
        return total <= pool ? owed : owed * pool / total;
    }

    /// The caller's line of the root, once, before the deadline.
    function claim(uint256 owed, bytes32[] calldata proof) external nonReentrant {
        if (root == bytes32(0)) revert NotStarted();
        if (block.timestamp > deadline || swept) revert Closed();
        if (claimed[msg.sender]) revert AlreadyClaimed();
        bytes32 node = keccak256(bytes.concat(keccak256(abi.encode(msg.sender, owed))));
        for (uint256 i = 0; i < proof.length; i++) {
            bytes32 p = proof[i];
            node = node < p ? keccak256(abi.encode(node, p)) : keccak256(abi.encode(p, node));
        }
        if (node != root) revert BadProof();
        claimed[msg.sender] = true;
        uint256 amount = payout(owed);
        paid += amount;
        emit Claimed(msg.sender, owed, amount);
        if (token != address(0)) {
            if (!IRecoveryToken(token).transfer(msg.sender, amount)) revert PayFailed();
        } else {
            (bool ok, ) = msg.sender.call{value: amount}("");
            if (!ok) revert PayFailed();
        }
    }

    /// Anyone, after the deadline: what is left goes to sweepTo. Once.
    function sweep() external nonReentrant {
        if (root == bytes32(0)) revert NotStarted();
        if (block.timestamp <= deadline) revert StillOpen(deadline);
        if (swept) revert Closed();
        swept = true;
        uint256 left = _held();
        emit Swept(sweepTo, left);
        if (token != address(0)) {
            if (!IRecoveryToken(token).transfer(sweepTo, left)) revert PayFailed();
        } else {
            (bool ok, ) = sweepTo.call{value: left}("");
            if (!ok) revert PayFailed();
        }
    }

    function _held() private view returns (uint256) {
        return token == address(0) ? address(this).balance : IRecoveryToken(token).balanceOf(address(this));
    }

}

contracts/SaphanSealedOrders.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// SaphanIntents (docs/SAPHAN-PR5.md): the calls made here. Order is SaphanIntents.Order, field for field.
interface ISealedIntents {
    struct Order {
        address tokenIn;
        uint256 amountIn;
        uint32 dstDomain;
        address tokenOut;
        address recipient;
        uint256 minOut;
        uint64 deadline;
        address refundTo;
    }
    function open(Order calldata o) external returns (bytes32 id);
    function fillLocal(bytes32 id, uint256 amountOut, address repayTo) external;
    function threats() external view returns (address);
}

interface ISealedThreats {
    function isAddressHeld(uint256 chainId, address who) external view returns (bool, uint8);
}

interface ISealedToken {
    function balanceOf(address) external view returns (uint256);
}

/// @title SaphanSealedOrders: cross-chain orders encrypted to a solver's ML-KEM-768 key (Saphan PR 4, S6)
/// @notice Testnet only, not audited (docs/SAPHAN-PR4.md).
///
///   An intent (SaphanIntents.Order: where to, for whom, at least how much, by when) is public the moment it is
///   opened, so anyone can trade ahead of it. Here the user first SEALS it:
///
///   1. A solver (one key, or a group of solvers sharing one key behind one address) publishes its post-quantum
///      encryption key: setSolverKey(X-Wing key = ML-KEM-768 (1184 bytes) + X25519 (32), as the encrypted mempool).
///   2. The user escrows the input tokens and posts commit(solver, token, amount, refundTo, window, commitment,
///      ciphertext). ciphertext = the order and a random 32-byte salt, encrypted to the solver's key
///      (src/saphansealed.js); commitment = keccak256(abi.encode(TAG, chainid, this, solver, order, salt)).
///      On chain everyone sees the token, the amount, refundTo and the solver; nobody but the solver can read where
///      the money goes, to whom, the minimum and the deadline. From another chain: SaphanSourceGateway.depositAndCall
///      with target = this contract and data = abi.encode(solver, refundTo, window, commitment, ciphertext).
///   3. Within the window, only that solver reveals (order, salt). The commitment binds them: a solver cannot change
///      one field. The order must spend exactly the escrow (same token, amount, refundTo). The reveal opens it as an
///      ordinary SaphanIntents intent (Neuro gates, bonds, proofs as there); an order SaphanIntents refuses (expired,
///      risky recipient, ...) cannot be revealed and is refunded after the window. For a fill on ZETAPHY itself, revealAndFillLocal reveals and
///      fills in one transaction, so the order is never public before it is done.
///   4. Not revealed in time: anyone calls refund(id); refundTo claims the escrow (pull).
///
///   The contract cannot check that the ciphertext really holds the committed order (that needs the solver's
///   secret key): a user who seals garbage only locks its own tokens until the window ends. A solver that does not
///   reveal costs the user only time. No admin, no parameter to govern: every bound is a constant.
contract SaphanSealedOrders {
    enum Status { None, Sealed, Revealed, Refunded }

    struct Sealed {
        address solver;
        uint64 revealBy;
        Status status;
        address token;
        uint256 amount;
        address refundTo;
        bytes32 commitment;
        bytes32 keyHash;        // keccak256 of the solver key the order was sealed to
        bytes32 ciphertextHash;
    }

    bytes32 public constant TAG = keccak256("saphan/sealed/v1");
    uint256 public constant KEY_BYTES = 1216;          // X-Wing public key: ML-KEM-768 1184 + X25519 32
    /// X-Wing ciphertext (1120) + abi.encode(order, salt) (9 words, 288) + AES-256-GCM tag (16): every sealed order
    /// has the same length, so the length says nothing about it.
    uint256 public constant CIPHERTEXT_BYTES = 1424;
    uint64 public constant MIN_WINDOW = 1 minutes;
    uint64 public constant MAX_WINDOW = 1 days;

    ISealedIntents public immutable intents;

    mapping(address => bytes32) public solverKey;      // solver => keccak256(its X-Wing key); zero: none
    mapping(bytes32 => Sealed) private _sealed;
    uint256 public nonce;
    mapping(address => uint256) public accounted;      // tokens held for sealed orders and payouts
    mapping(address => mapping(address => uint256)) public owed;  // token => who => amount (claim)
    uint256 private entered;

    event SolverKeySet(address indexed solver, bytes32 keyHash, bytes publicKey);
    event Committed(bytes32 indexed id, address indexed owner, uint256 srcChainId, address indexed solver, address token,
        uint256 amount, address refundTo, uint64 revealBy, bytes32 commitment, bytes32 keyHash, bytes ciphertext);
    event Revealed(bytes32 indexed id, ISealedIntents.Order order, bytes32 salt);
    event IntentOpened(bytes32 indexed id, bytes32 indexed intentId);
    event Refunded(bytes32 indexed id, address refundTo, uint256 amount);
    event Claimed(address indexed who, address indexed token, uint256 amount);

    error BadKey();
    error BadSeal(uint256 code);
    error NotSolver();
    error WrongStatus();
    error TooLate();
    error TooEarly();
    error Mismatch(uint256 code);
    error Short(uint256 have, uint256 need);
    error SolverHeld();
    error Nothing();
    error PayFailed();
    error Reentered();

    modifier nonReentrant() {
        if (entered == 1) revert Reentered();
        entered = 1;
        _;
        entered = 0;
    }

    constructor(ISealedIntents intents_) {
        require(address(intents_) != address(0), "intents");
        intents = intents_;
    }

    function sealedOf(bytes32 id) external view returns (Sealed memory) { return _sealed[id]; }

    /// The caller's encryption key (X-Wing, 1216 bytes); empty removes it. Orders already sealed keep the key they
    /// were sealed to, so keep the old secret key until they are revealed or expired.
    function setSolverKey(bytes calldata publicKey) external {
        if (publicKey.length != 0 && publicKey.length != KEY_BYTES) revert BadKey();
        bytes32 h = publicKey.length == 0 ? bytes32(0) : keccak256(publicKey);
        solverKey[msg.sender] = h;
        emit SolverKeySet(msg.sender, h, publicKey);
    }

    /// What a sealed order commits to (src/saphansealed.js commitment).
    function commitmentOf(address solver, ISealedIntents.Order calldata o, bytes32 salt) public view returns (bytes32) {
        return keccak256(abi.encode(TAG, block.chainid, address(this), solver, o, salt));
    }

    // ---- sealing ----

    /// Seals an order with the caller's tokens (approve this contract for `amount` of `token` first).
    function commit(address solver, address token, uint256 amount, address refundTo, uint64 window, bytes32 commitment,
        bytes calldata ciphertext) external nonReentrant returns (bytes32 id)
    {
        uint256 need = accounted[token] + amount;
        id = _seal(msg.sender, block.chainid, solver, token, amount, refundTo, window, commitment, ciphertext);
        _pay(token, abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, address(this), amount));
        uint256 have = ISealedToken(token).balanceOf(address(this));
        if (have < need) revert Short(have, need);
    }

    /// From chain X through its ZetaphyGateway, after it handed over the tokens:
    /// data = abi.encode(solver, refundTo, window, commitment, ciphertext). Reverting makes the Gateway refund on X.
    function onSaphanCall(uint256 srcChainId, address sender, address token, uint256, bytes calldata data) external nonReentrant {
        (address solver, address refundTo, uint64 window, bytes32 commitment, bytes memory ciphertext) =
            abi.decode(data, (address, address, uint64, bytes32, bytes));
        if (token == address(0) || token.code.length == 0) revert BadSeal(1);
        uint256 received = ISealedToken(token).balanceOf(address(this)) - accounted[token];
        _sealMem(sender, srcChainId, solver, token, received, refundTo, window, commitment, ciphertext);
    }

    function _seal(address owner, uint256 srcChainId, address solver, address token, uint256 amount, address refundTo,
        uint64 window, bytes32 commitment, bytes calldata ciphertext) private returns (bytes32)
    {
        if (token.code.length == 0) revert BadSeal(1);
        return _sealMem(owner, srcChainId, solver, token, amount, refundTo, window, commitment, ciphertext);
    }

    function _sealMem(address owner, uint256 srcChainId, address solver, address token, uint256 amount, address refundTo,
        uint64 window, bytes32 commitment, bytes memory ciphertext) private returns (bytes32 id)
    {
        bytes32 key = solverKey[solver];
        if (key == bytes32(0)) revert BadKey();
        if (amount == 0 || refundTo == address(0) || commitment == bytes32(0)) revert BadSeal(2);
        if (window < MIN_WINDOW || window > MAX_WINDOW) revert BadSeal(3);
        if (ciphertext.length != CIPHERTEXT_BYTES) revert BadSeal(4);
        id = keccak256(abi.encode(TAG, block.chainid, address(this), nonce++));
        uint64 revealBy = uint64(block.timestamp) + window;
        _sealed[id] = Sealed(solver, revealBy, Status.Sealed, token, amount, refundTo, commitment, key, keccak256(ciphertext));
        accounted[token] += amount;
        emit Committed(id, owner, srcChainId, solver, token, amount, refundTo, revealBy, commitment, key, ciphertext);
    }

    // ---- revealing ----

    /// The chosen solver, within the window: the plaintext, bound by the commitment. Opens the intent in
    /// SaphanIntents (its Opened event, and IntentOpened here, give the intent's id). An order SaphanIntents refuses
    /// (expired, risky recipient, ...) cannot be revealed: the user gets the escrow back after the window (refund).
    function reveal(bytes32 id, ISealedIntents.Order calldata o, bytes32 salt) external nonReentrant returns (bytes32 intentId) {
        Sealed storage s = _revealable(id, o, salt);
        s.status = Status.Revealed;
        accounted[s.token] -= s.amount;
        emit Revealed(id, o, salt);
        _pay(s.token, abi.encodeWithSignature("approve(address,uint256)", address(intents), s.amount));
        intentId = intents.open(o);
        emit IntentOpened(id, intentId);
    }

    /// The chosen solver, for an order filled on ZETAPHY (dstDomain = this chain): reveals, opens and fills in one
    /// transaction, so the order is never public before it is filled. The solver pays `amountOut` of tokenOut
    /// (approve this contract) and `repayTo` is owed the input in SaphanIntents (claim there).
    function revealAndFillLocal(bytes32 id, ISealedIntents.Order calldata o, bytes32 salt, uint256 amountOut, address repayTo)
        external nonReentrant returns (bytes32 intentId)
    {
        Sealed storage s = _revealable(id, o, salt);
        s.status = Status.Revealed;
        accounted[s.token] -= s.amount;
        // the solver's tokenOut passes through here: never the escrow of other orders
        uint256 floor = accounted[o.tokenOut];
        emit Revealed(id, o, salt);
        address t = intents.threats();
        if (t != address(0)) {
            (bool held, ) = ISealedThreats(t).isAddressHeld(block.chainid, msg.sender);
            if (held) revert SolverHeld();
        }
        _pay(s.token, abi.encodeWithSignature("approve(address,uint256)", address(intents), s.amount));
        intentId = intents.open(o);
        emit IntentOpened(id, intentId);
        _pay(o.tokenOut, abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, address(this), amountOut));
        uint256 have = ISealedToken(o.tokenOut).balanceOf(address(this));
        if (have < floor + amountOut) revert Short(have, floor + amountOut);
        // exactly amountOut may leave (the allowance): fillLocal pays the recipient from it
        _pay(o.tokenOut, abi.encodeWithSignature("approve(address,uint256)", address(intents), amountOut));
        intents.fillLocal(intentId, amountOut, repayTo);
    }

    function _revealable(bytes32 id, ISealedIntents.Order calldata o, bytes32 salt) private view returns (Sealed storage s) {
        s = _sealed[id];
        if (s.status != Status.Sealed) revert WrongStatus();
        if (msg.sender != s.solver) revert NotSolver();
        if (block.timestamp > s.revealBy) revert TooLate();
        if (commitmentOf(s.solver, o, salt) != s.commitment) revert Mismatch(0);
        if (o.tokenIn != s.token || o.amountIn != s.amount || o.refundTo != s.refundTo) revert Mismatch(1);
    }

    // ---- refunds and payouts ----

    /// Anyone, after the window with no reveal: the escrow is owed to refundTo.
    function refund(bytes32 id) external {
        Sealed storage s = _sealed[id];
        if (s.status != Status.Sealed) revert WrongStatus();
        if (block.timestamp <= s.revealBy) revert TooEarly();
        s.status = Status.Refunded;
        owed[s.token][s.refundTo] += s.amount;
        emit Refunded(id, s.refundTo, s.amount);
    }

    /// The caller's refunds in `token`.
    function claim(address token) external nonReentrant {
        uint256 v = owed[token][msg.sender];
        if (v == 0) revert Nothing();
        owed[token][msg.sender] = 0;
        accounted[token] -= v;
        emit Claimed(msg.sender, token, v);
        _pay(token, abi.encodeWithSignature("transfer(address,uint256)", msg.sender, v));
    }

    /// A token call that must succeed (tokens that return nothing are accepted).
    function _pay(address token, bytes memory data) private {
        (bool ok, bytes memory ret) = token.call(data);
        if (!ok || (ret.length != 0 && (ret.length < 32 || !abi.decode(ret, (bool))))) revert PayFailed();
    }
}

contracts/SaphanTokens.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY Saphan, token routes: tokens BORN on ZETAPHY go out to an EVM chain and come back
// (the reverse of the v2 ETH routes in HyperlaneLockBoxV2.sol). docs/SAPHAN-TOKENS.md.
//
//   ZETAPHY                                                     destination chain X (Sepolia, Base Sepolia, ...)
//   ZetaphyTokenVault(token, X) --lock: Hyperlane message---->  SaphanSyntheticToken(token, X) queues a mint,
//     escrows the token             (ISM on X: OUR validators   mints after the delay (veto, daily cap, supply cap, pause)
//                                    for origin ZETAPHY)
//     queues a release <-----------burn: Hyperlane message----- sendBack(): burns, dispatches
//     pays after the delay          (ISM on ZETAPHY: Hyperlane's validator(s) for origin X)
//     (veto, daily limit, pause, never more than it locked for X)
//
// One vault per (token, destination) and one synthetic per (token, destination): a hole on chain X (or in X's
// synthetic, or X's validators) can only ask vault(token, X) for a release, and that vault pays at most what was
// locked in it for X. It cannot reach another token's vault or another destination's escrow.
//
// Local copies of the Hyperlane v3 interfaces, checked against hyperlane-xyz/hyperlane-monorepo at commit
// 1aadbba0696ecf96ed4c06f78c978d08db22c0ad (as HyperlaneLockBoxV2.sol): IMailbox dispatch / quoteDispatch,
// IMessageRecipient.handle, ISpecifiesInterchainSecurityModule.interchainSecurityModule. Named apart from the
// other files' copies (the build compiles every file in one unit and names artifacts by contract).

interface ISaphanTokenMailbox {
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody) external view returns (uint256 fee);
    function dispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external payable returns (bytes32 messageId);
    function quoteDispatch(uint32 destinationDomain, bytes32 recipientAddress, bytes calldata messageBody, bytes calldata customHookMetadata, address customHook) external view returns (uint256 fee);
}

interface ISaphanTokenIsm {
    function moduleType() external view returns (uint8);
    function verify(bytes calldata metadata, bytes calldata message) external returns (bool);
}

/// ThreatRegistry's hold view for ZETAPHY addresses (as BridgeGuard uses it).
interface ISaphanTokenThreats {
    function isContractHeld(address who) external view returns (bool, uint8);
}

/// @title SaphanTokenEndpoint: what both ends of a token route share
/// @notice Sending: the subclass takes the tokens (_take: the vault escrows, the synthetic burns), then this
///         dispatches a 288-byte body through the local Mailbox to the one remote contract:
///           abi.encode(uint256 srcChainId, address srcContract, uint256 srcNonce, address sender, address to,
///                      uint256 amount, uint256 dstChainId, address dstContract, address originToken)
///         `originToken` is the token's address on ZETAPHY (the same on both ends), so a message of token A can
///         never be taken by token B's endpoint even if every other field matched.
///         Receiving: handle() takes a message only from the Mailbox (after the ISM this contract names, never the
///         Mailbox default, never zero), from the remote domain and the remote contract (sender), whose body names
///         the remote chain and contract as the source, this chain and contract as the destination, and this
///         route's origin token; each message once. It never pays at once: the payout is queued (Queued) and anyone
///         claims it after `delay`, while not vetoed, not paused and within the daily limit (over it, it waits for
///         the next UTC day); the subclass adds its own bound (_pay: the vault's backing, the synthetic's supply
///         cap). A message is never refused for a limit or a pause, so nothing depends on the relayer retrying.
///         Starts PAUSED (deployed closed): opening is governance's unpause, on both ends.
///         Roles: governance (a timelock: 48 h) unpauses, lifts vetoes, raises limits, changes the ISM; guardians
///         (a multisig) only reduce risk, at once: pause, veto, lower the daily limit, lengthen the delay.
abstract contract SaphanTokenEndpoint {
    struct Pending {
        address to;
        uint64 readyAt;      // zero: no such message
        bool done;
        bool vetoed;
        uint256 amount;
    }

    /// The message body (288 bytes, abi.encode of these fields in this order).
    struct Body {
        uint256 srcChainId;
        address srcContract;
        uint256 srcNonce;
        address sender;
        address to;
        uint256 amount;
        uint256 dstChainId;
        address dstContract;
        address originToken;
    }

    ISaphanTokenMailbox public immutable mailbox;
    uint32 public immutable remoteDomain;     // the other end's Hyperlane domain
    uint256 public immutable remoteChainId;   // the other end's EVM chain id, as it writes it into bodies
    bytes32 public immutable remote;          // the other end's contract (the only sender, the only recipient)
    address public immutable hook;            // zero = the Mailbox default hook
    address public immutable originToken;     // the token's address on ZETAPHY

    uint64 public constant MAX_DELAY = 30 days;
    uint256 public constant BODY_LENGTH = 288;

    address public governance;
    mapping(address => bool) public guardian;
    /// Hyperlane reads this (ISpecifiesInterchainSecurityModule). Never zero.
    ISaphanTokenIsm public interchainSecurityModule;
    bool public paused;
    uint256 public dailyLimit;                // token units paid out (released / minted) per UTC day
    uint256 public paidToday;
    uint64 public day;
    uint64 public delay;                      // seconds between a message and its claim

    uint256 public nonce;                     // messages sent
    uint256 public received;                  // messages recorded (the relayer workflow compares it with the other end's nonce)
    mapping(bytes32 => Pending) public pending; // by keccak256(body)
    uint256 private entered = 1;

    event Sent(uint256 indexed nonce, address indexed sender, address indexed to, uint256 amount, bytes32 messageId);
    event Queued(bytes32 indexed id, uint256 indexed srcNonce, address sender, address indexed to, uint256 amount, uint64 readyAt);
    event Paid(bytes32 indexed id, address indexed to, uint256 amount);
    event Vetoed(bytes32 indexed id, address indexed by);
    event VetoLifted(bytes32 indexed id);
    event Paused(address indexed by);
    event Unpaused();
    event IsmSet(address ism);
    event GovernanceSet(address governance);
    event GuardianSet(address indexed who, bool on);
    event DailyLimitSet(uint256 limit);
    event DelaySet(uint64 delay);

    error NotGovernance();
    error NotGuardian();
    error NotMailbox();
    error WrongOrigin(uint32 origin);
    error WrongSender(bytes32 sender);
    error WrongSource();
    error WrongDestination();
    error WrongToken(address token);
    error BadBody();
    error Replay(bytes32 id);
    error NoValue();
    error IsPaused();
    error NoMessage();
    error AlreadyDone();
    error IsVetoed();
    error NotReady(uint64 readyAt);
    error OverLimit(uint256 remaining);
    error PayFailed();
    error Fee(uint256 needed);
    error Reentered();

    /// Deploy settings shared by both ends (one tuple: fewer constructor arguments).
    struct Config {
        ISaphanTokenMailbox mailbox;
        uint32 remoteDomain;
        uint256 remoteChainId;
        bytes32 remote;
        address hook;
        address originToken;
        ISaphanTokenIsm ism;
        address governance;
        address guardian;
        uint256 dailyLimit;
        uint64 delay;
    }

    constructor(Config memory c) {
        require(address(c.mailbox) != address(0) && c.remote != bytes32(0) && c.remoteChainId != 0 && c.originToken != address(0)
            && address(c.ism) != address(0) && c.governance != address(0) && c.delay <= MAX_DELAY, "config");
        mailbox = c.mailbox;
        remoteDomain = c.remoteDomain;
        remoteChainId = c.remoteChainId;
        remote = c.remote;
        hook = c.hook;
        originToken = c.originToken;
        interchainSecurityModule = c.ism;
        governance = c.governance;
        dailyLimit = c.dailyLimit;
        delay = c.delay;
        paused = true;
        emit IsmSet(address(c.ism));
        emit GovernanceSet(c.governance);
        emit DailyLimitSet(c.dailyLimit);
        emit DelaySet(c.delay);
        emit Paused(msg.sender);
        if (c.guardian != address(0)) { guardian[c.guardian] = true; emit GuardianSet(c.guardian, true); }
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }
    modifier onlyGuardian() { if (!guardian[msg.sender] && msg.sender != governance) revert NotGuardian(); _; }
    modifier nonReentrant() { if (entered != 1) revert Reentered(); entered = 2; _; entered = 1; }

    // ---------------------------------------------------------------- what the two ends do differently

    /// Takes `amount` from msg.sender for a send (the vault escrows it, the synthetic burns it).
    function _take(address from, uint256 amount) internal virtual;
    /// Pays a claimed message (the vault releases within its backing, the synthetic mints within its cap).
    function _pay(address to, uint256 amount) internal virtual;

    // ---------------------------------------------------------------- sending

    function body(uint256 n, address sender, address to, uint256 amount) public view returns (bytes memory) {
        return abi.encode(block.chainid, address(this), n, sender, to, amount, remoteChainId, address(uint160(uint256(remote))), originToken);
    }

    /// The Mailbox fee for the next send (msg.value of the send).
    function quote(address to, uint256 amount) public view returns (uint256) {
        return _quote(body(nonce, msg.sender, to, amount));
    }

    function _send(address to, uint256 amount) internal returns (bytes32 messageId) {
        if (paused) revert IsPaused();
        require(amount > 0 && to != address(0), "send");
        uint256 n = nonce++;
        bytes memory b = body(n, msg.sender, to, amount);
        uint256 fee = _quote(b);
        if (msg.value < fee) revert Fee(fee);
        _take(msg.sender, amount);
        messageId = hook == address(0)
            ? mailbox.dispatch{value: fee}(remoteDomain, remote, b)
            : mailbox.dispatch{value: fee}(remoteDomain, remote, b, "", hook);
        emit Sent(n, msg.sender, to, amount, messageId);
        if (msg.value > fee) {
            (bool ok, ) = msg.sender.call{value: msg.value - fee}("");
            if (!ok) revert PayFailed();
        }
    }

    function _quote(bytes memory b) private view returns (uint256) {
        return hook == address(0) ? mailbox.quoteDispatch(remoteDomain, remote, b) : mailbox.quoteDispatch(remoteDomain, remote, b, "", hook);
    }

    // ---------------------------------------------------------------- receiving

    /// Called by the Mailbox after interchainSecurityModule verified the message.
    function handle(uint32 origin, bytes32 sender, bytes calldata b) external payable {
        if (msg.sender != address(mailbox)) revert NotMailbox();
        if (msg.value != 0) revert NoValue();
        if (origin != remoteDomain) revert WrongOrigin(origin);
        if (sender != remote) revert WrongSender(sender);
        if (b.length != BODY_LENGTH) revert BadBody();
        Body memory m = abi.decode(b, (Body));
        if (m.srcChainId != remoteChainId || bytes32(uint256(uint160(m.srcContract))) != remote) revert WrongSource();
        if (m.dstChainId != block.chainid || m.dstContract != address(this)) revert WrongDestination();
        if (m.originToken != originToken) revert WrongToken(m.originToken);
        if (m.to == address(0) || m.amount == 0) revert BadBody();
        bytes32 id = keccak256(b);
        if (pending[id].readyAt != 0) revert Replay(id);
        uint64 readyAt = uint64(block.timestamp) + delay;
        pending[id] = Pending(m.to, readyAt, false, false, m.amount);
        received += 1;
        emit Queued(id, m.srcNonce, m.sender, m.to, m.amount, readyAt);
    }

    /// Anyone: pays a queued message to its receiver once every check passes.
    function claim(bytes32 id) external nonReentrant {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        if (p.vetoed) revert IsVetoed();
        if (paused) revert IsPaused();
        if (block.timestamp < p.readyAt) revert NotReady(p.readyAt);
        uint64 today = uint64(block.timestamp / 1 days);
        if (day != today) { day = today; paidToday = 0; }
        uint256 amount = p.amount;
        if (paidToday + amount > dailyLimit) revert OverLimit(dailyLimit > paidToday ? dailyLimit - paidToday : 0);
        p.done = true;
        paidToday += amount;
        emit Paid(id, p.to, amount);
        _pay(p.to, amount);
    }

    /// What can still be paid out today.
    function remainingToday() external view returns (uint256) {
        uint256 used = day == uint64(block.timestamp / 1 days) ? paidToday : 0;
        return dailyLimit > used ? dailyLimit - used : 0;
    }

    // ---------------------------------------------------------------- guardians: only reduce risk, at once

    function pause() external onlyGuardian { paused = true; emit Paused(msg.sender); }

    /// Stops a queued payout that is not paid yet (during its delay, or while it waits for a limit).
    function veto(bytes32 id) external onlyGuardian {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        if (p.done) revert AlreadyDone();
        p.vetoed = true;
        emit Vetoed(id, msg.sender);
    }

    function lowerDailyLimit(uint256 v) external onlyGuardian {
        require(v < dailyLimit, "lower only");
        dailyLimit = v;
        emit DailyLimitSet(v);
    }

    function raiseDelay(uint64 d) external onlyGuardian {
        require(d > delay && d <= MAX_DELAY, "raise only");
        delay = d;
        emit DelaySet(d);
    }

    // ---------------------------------------------------------------- governance (a timelock)

    function unpause() external onlyGov { paused = false; emit Unpaused(); }

    function liftVeto(bytes32 id) external onlyGov {
        Pending storage p = pending[id];
        if (p.readyAt == 0) revert NoMessage();
        p.vetoed = false;
        emit VetoLifted(id);
    }

    function setDailyLimit(uint256 v) external onlyGov { dailyLimit = v; emit DailyLimitSet(v); }

    function setDelay(uint64 d) external onlyGov {
        require(d <= MAX_DELAY, "delay");
        delay = d;
        emit DelaySet(d);
    }

    /// A new ISM (e.g. more validators, a higher threshold). Never zero.
    function setInterchainSecurityModule(ISaphanTokenIsm ism) external onlyGov {
        require(address(ism) != address(0), "ism");
        interchainSecurityModule = ism;
        emit IsmSet(address(ism));
    }

    function setGuardian(address who, bool on) external onlyGov { guardian[who] = on; emit GuardianSet(who, on); }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }
}

/// @title ZetaphyTokenVault: the ZETAPHY side of one token to one destination chain
/// @notice lock(to, amount) escrows `amount` of `originToken` (msg.value = quote(): the Mailbox fee) and sends a
///         mint to that destination's SaphanSyntheticToken. A release (a burn on the destination) is paid from this
///         vault only, after the delay, and never more than `locked` (everything locked here minus everything
///         released here): a compromise of one destination drains at most its own escrow, never another
///         destination's or another token's.
///         The token: any ERC-20 on ZETAPHY that governance adds (deploys a vault for), including the native coin
///         through its ERC-20 precompile (0xEeee…EEeE: approve, then lock). Refused: tokens that deliver less than
///         asked (fee-on-transfer: OddToken), that return false, or whose decimals() differ from the chain table's.
///         Not supported (governance must not add them): rebasing tokens, tokens with blocklists or admin
///         transfers (a vault's balance must only move through this contract). Transfers with no return value
///         (USDT style) are accepted.
///         Extra safety: `lockCap` bounds everything ever outstanding to this destination (and so the synthetic
///         supply that can exist); a ThreatRegistry (optional) holds a flagged sender (no lock) or receiver (the
///         release waits until the hold ends, as BridgeGuard's vaccine does).
contract ZetaphyTokenVault is SaphanTokenEndpoint {
    uint8 public immutable decimals;          // the token's, checked at deploy (the synthetic has the same)
    uint256 public locked;                    // backing: locked minus released
    uint256 public lockCap;                   // `locked` may never exceed this (governance raises, guardians lower)
    ISaphanTokenThreats public threats;       // zero: no hold check

    event LockCapSet(uint256 cap);
    event ThreatsSet(address registry);
    event ExcessRecovered(address indexed to, uint256 amount);

    error OddToken(uint256 received);
    error TransferFailed();
    error OverCap(uint256 cap);
    error OverBacking(uint256 locked);
    error Held(address who);

    /// `c.remote`: the destination's SaphanSyntheticToken; `c.originToken`: the token on ZETAPHY.
    constructor(Config memory c, uint8 decimals_, uint256 lockCap_, ISaphanTokenThreats threats_) SaphanTokenEndpoint(c) {
        address token_ = c.originToken;
        require(token_.code.length > 0 || token_ == 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE, "token");
        (bool ok, bytes memory ret) = token_.staticcall(abi.encodeWithSignature("decimals()"));
        require(ok && ret.length == 32 && abi.decode(ret, (uint256)) == decimals_, "decimals");
        decimals = decimals_;
        lockCap = lockCap_;
        threats = threats_;
        emit LockCapSet(lockCap_);
        emit ThreatsSet(address(threats_));
    }

    /// Escrows `amount` here and sends a mint of the same amount (same decimals) to `to` on the destination.
    function lock(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        if (_held(from)) revert Held(from);
        if (locked + amount > lockCap) revert OverCap(lockCap);
        uint256 before = _balance();
        _call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, address(this), amount));
        uint256 got = _balance() - before;
        if (got != amount) revert OddToken(got);
        locked += amount;
    }

    function _pay(address to, uint256 amount) internal override {
        if (_held(to)) revert Held(to);
        if (amount > locked) revert OverBacking(locked);
        locked -= amount;
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
    }

    function _balance() private view returns (uint256) {
        (bool ok, bytes memory ret) = originToken.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        if (!ok || ret.length < 32) revert TransferFailed();
        return abi.decode(ret, (uint256));
    }

    /// A token call that must succeed and, if it returns anything, return true.
    function _call(bytes memory data) private {
        (bool ok, bytes memory ret) = originToken.call(data);
        if (!ok || (ret.length != 0 && (ret.length < 32 || !abi.decode(ret, (bool))))) revert TransferFailed();
    }

    function _held(address who) private view returns (bool h) {
        ISaphanTokenThreats t = threats;
        if (address(t) == address(0)) return false;
        (h, ) = t.isContractHeld(who);
    }

    function lowerLockCap(uint256 v) external onlyGuardian {
        require(v < lockCap, "lower only");
        lockCap = v;
        emit LockCapSet(v);
    }

    function setLockCap(uint256 v) external onlyGov { lockCap = v; emit LockCapSet(v); }

    function setThreats(ISaphanTokenThreats r) external onlyGov { threats = r; emit ThreatsSet(address(r)); }

    /// Tokens sent here without lock() are not backing; governance may send them on. Never touches `locked`.
    function recoverExcess(address to) external onlyGov nonReentrant {
        uint256 b = _balance();
        require(to != address(0) && b > locked, "no excess");
        _call(abi.encodeWithSignature("transfer(address,uint256)", to, b - locked));
        if (_balance() < locked) revert OverBacking(locked);
        emit ExcessRecovered(to, b - locked);
    }
}

/// @title SaphanSyntheticToken: a ZETAPHY token on one destination chain (e.g. zZETAPHY on Base Sepolia)
/// @notice An ERC-20 that exists only through its vault on ZETAPHY: minted only for messages from ZETAPHY's
///         domain and that vault (verified by a multisig ISM of OUR validators for origin ZETAPHY), after the mint
///         delay, within the daily mint limit and the supply cap, while not vetoed or paused. sendBack(to, amount)
///         burns the caller's tokens and sends the release to the vault (msg.value = quote()).
///         Its value is exactly the vault's safety: one synthetic is a claim on one token locked in
///         ZetaphyTokenVault(token, this chain); if that vault, our validators or ZETAPHY fail, it can be worth
///         less or nothing.
contract SaphanSyntheticToken is SaphanTokenEndpoint {
    string public name;
    string public symbol;
    uint8 public immutable decimals;          // the origin token's
    uint256 public totalSupply;
    uint256 public supplyCap;                 // totalSupply may never exceed this (governance raises, guardians lower)
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event SupplyCapSet(uint256 cap);

    error OverCap(uint256 cap);

    /// `c.remote`: the ZetaphyTokenVault on ZETAPHY (domain c.remoteDomain, chain c.remoteChainId).
    constructor(string memory name_, string memory symbol_, uint8 decimals_, Config memory c, uint256 supplyCap_) SaphanTokenEndpoint(c) {
        require(bytes(name_).length > 0 && bytes(symbol_).length > 0 && decimals_ <= 36, "token");
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        supplyCap = supplyCap_;
        emit SupplyCapSet(supplyCap_);
    }

    /// Burns `amount` of the caller's tokens and sends their release on ZETAPHY to `to`.
    function sendBack(address to, uint256 amount) external payable nonReentrant returns (bytes32 messageId) {
        messageId = _send(to, amount);
    }

    function _take(address from, uint256 amount) internal override {
        require(balanceOf[from] >= amount, "balance");
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function _pay(address to, uint256 amount) internal override {
        if (totalSupply + amount > supplyCap) revert OverCap(supplyCap);
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; emit Approval(msg.sender, s, v); return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        uint256 a = allowance[f][msg.sender];
        if (a != type(uint256).max) { require(a >= v, "allowance"); allowance[f][msg.sender] = a - v; }
        _move(f, to, v);
        return true;
    }
    function _move(address f, address to, uint256 v) private {
        require(to != address(0) && balanceOf[f] >= v, "transfer");
        balanceOf[f] -= v;
        balanceOf[to] += v;
        emit Transfer(f, to, v);
    }

    function lowerSupplyCap(uint256 v) external onlyGuardian {
        require(v < supplyCap, "lower only");
        supplyCap = v;
        emit SupplyCapSet(v);
    }

    function setSupplyCap(uint256 v) external onlyGov { supplyCap = v; emit SupplyCapSet(v); }
}

contracts/SecurityScore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// A live security score per contract, 0..1000, readable by any DeFi contract (docs/future/immune-score.md, S10/SS7).
// TESTNET ONLY: an input to risk limits, never a guarantee that code is safe.
//
// NOBODY POSTS A SCORE. It is computed at every call from what other contracts already hold, each written by its own
// accountable process; this contract only reads them (sources are fixed at deploy, any may be zero = not used):
//   source                      read here                                   who writes it there
//   AuditCertificate            certificate(chainId, target): level, issue,  AuditCertificate.certify (all audit rules),
//                               expiry, revoked                              revokeFor (judged valid critical/high)
//   AuditNetwork                the certificate's post-certificate findings  bonded auditors (commit-reveal); judges
//                               revealed, undecided, claimed high/critical
//   CircuitBreaker              registered (monitored), tripped now, the     the protocol's own governance (register);
//                               last trip's start (unless proven false)      bonded runners / invariants (trips)
//   NeuroScore                  scoreOf(target): the model's risk level      governance-appointed feeders (vectors),
//                                                                            the active model (timelock)
//   ImmuneVaccines              exploitsOf(chainId, target), matchOf(target)  confirmed exploits only (audit, revoked
//                                                                            certificate, approved insurance claim)
//   ThreatRegistry              flagged / enforced / held pending review     a quorum of bonded runners; ImmuneVaccines
//   ImmuneRegistry/Mirror       isFlagged(chainId, target), isCodeFlagged    k-of-n NeuroJobs runner agreement
//
// The formula (fixed in code; governance cannot change it):
//   points  certificate  valid: Bronze 250 / Silver 325 / Gold 400, times (1/2 + 1/2 x remaining validity)   <= 400
//           neuro        known level 0: 200, 1: 150, 2: 60, 3: 0; unknown or another chain: 100              <= 200
//           monitoring   registered with the CircuitBreaker: 150                                              <= 150
//           history      250 - 125 per confirmed exploit (ImmuneVaccines) in the last 365 days, floor 0         <= 250
//   minus   open findings  100 per revealed, undecided post-certificate finding claiming high/critical (max 3)
//           breaker        300 while tripped; else 100 when the last trip began within 30 days (not proven false)
//           suspect        150 when the contract matches most selectors of an active vaccine
//   capped  0    ThreatRegistry enforces a flag, or the immune feed says critical (4)
//           100  ThreatRegistry flags it, the immune feed says high (3), or an active vaccine's exact/body match
//           150  an exploit confirmed within the last 30 days
//           200  its certificate (or the certified code) was revoked
//           300  held pending review in ThreatRegistry
//           400  the immune feed says suspicious (2)
//           500  a configured source could not be read (degraded: never better than average)
// Every read is gas-capped and caught: a source that reverts or runs out of gas lowers the score (degraded) instead of
// blocking a protocol. Sources are our own contracts, fixed at deploy (their return shapes are known).

interface ISSCertificate {
    struct Cert {
        uint256 requestId;
        uint64 chainId;
        address target;
        bytes32 codeHash;
        bytes32 reportHash;
        bytes32 sourceHash;
        uint8 level;
        uint16 auditors;
        uint16 mutationBps;
        uint64 issuedAt;
        uint64 expiresAt;
        uint64 revokedAt;
        uint256 revokedBy;
    }
    function certificate(uint64 chainId, address target) external view returns (Cert memory c, bool valid);
    function revokedCode(bytes32 codeHash) external view returns (uint256);
}

interface ISSNetwork {
    function findingsOf(uint256 id) external view returns (uint256[] memory);
    function getFinding(uint256 fid) external view returns (ISSFinding.Finding memory);
}

interface ISSFinding {
    struct Finding {
        uint64 req;
        uint64 committedAt;
        uint64 commitBlock;
        uint64 revealedAt;
        uint64 decidedAt;
        address auditor;
        uint8 status;
        uint8 claimed;
        uint8 sev;
        bool late;
        bool paid;
        bool appealOpen;
        uint64 group;
        uint128 slashed;
        bytes32 commitment;
        bytes32 findingHash;
        bytes32 evidenceHash;
    }
}

interface ISSBreaker {
    function policyGovernance(address protocol) external view returns (address);
    function isTripped(address protocol) external view returns (bool);
    function lastTrip(address protocol) external view returns (uint256);
    function tripOf(uint256 id) external view returns (ISSTrip.Trip memory);
}

interface ISSTrip {
    struct Trip {
        address protocol;
        uint8 kind;
        uint8 claim;
        uint16 mask;
        uint64 start;
        uint64 until;
        uint64 fromBlock;
        uint64 toBlock;
        uint64 claimedAt;
        bytes32 evidenceHash;
        bytes32 detectorId;
        uint256 claimBond;
        address[] runners;
    }
}

interface ISSNeuro {
    function scoreOf(address token) external view returns (bool known, int256 score, uint8 level);
}

interface ISSVaccines {
    function exploitsOf(uint64 chainId, address target) external view returns (uint32 n, uint64 last);
    function matchOf(address c) external view returns (bytes32 vaccine, uint8 strength, bool held, uint64 at, address owner, bool active);
}

interface ISSThreats {
    function isAddressFlagged(uint256 chainId, address who) external view returns (bool, uint8);
    function isAddressEnforced(uint256 chainId, address who) external view returns (bool, uint8);
    function isCodeFlagged(bytes32 codeHash) external view returns (bool, uint8);
    function isCodeEnforced(bytes32 codeHash) external view returns (bool, uint8);
    function underReview(bytes32 key) external view returns (bool held, bytes32 vaccine, uint64 until);
}

interface ISSImmune {
    function isFlagged(uint256 chainId, address subject) external view returns (bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
    function isCodeFlagged(bytes32 codeHash) external view returns (bool flagged, uint8 severity, uint64 since, bytes32 evidenceHash);
}

/// @title SecurityScore: a live 0..1000 security score per contract, from on-chain facts only
contract SecurityScore {
    uint16 public constant MAX_SCORE = 1000;
    uint256 internal constant READ_GAS = 120_000;   // per source read (a hostile or broken source cannot eat the caller's gas)
    uint256 internal constant MAX_FINDINGS = 16;    // newest post-certificate findings looked at
    uint256 internal constant OPEN_COUNTED = 3;
    uint8 internal constant F_REVEALED = 2;
    uint8 internal constant SEV_HIGH = 4;
    uint8 internal constant CLAIM_PROVEN_FALSE = 2; // CircuitBreaker.Claim.ProvenFalse
    uint8 internal constant MATCH_SELECTORS = 1;
    uint8 internal constant MATCH_BODY = 2;

    struct Breakdown {
        uint16 score;
        uint16 certificate;   // points
        uint16 neuro;
        uint16 monitoring;
        uint16 history;
        uint16 penalty;       // subtracted
        uint16 cap;           // MAX_SCORE when nothing capped it
        uint8 level;          // certificate level (0 none)
        uint64 certExpires;
        uint8 openFindings;
        uint32 exploits;      // confirmed exploits in the last 365 days
        uint8 vaccineMatch;   // 0 none, 1 selectors (suspect), 2 body, 3 exact
        bool flagged;         // ThreatRegistry or the immune feed (severity >= 3)
        bool held;            // held pending review
        bool tripped;
        bool degraded;        // a configured source could not be read
    }

    ISSCertificate public immutable certificates;
    ISSNetwork public immutable network;
    ISSBreaker public immutable breaker;
    ISSNeuro public immutable neuro;
    ISSVaccines public immutable vaccines;
    ISSThreats public immutable threats;
    ISSImmune public immutable immune;

    struct Cached { uint16 score; uint64 at; }
    mapping(bytes32 => Cached) private _cached;

    event ScoreUpdated(uint64 indexed chainId, address indexed target, uint16 score, uint16 cap);

    constructor(ISSCertificate certificates_, ISSNetwork network_, ISSBreaker breaker_, ISSNeuro neuro_, ISSVaccines vaccines_,
        ISSThreats threats_, ISSImmune immune_) {
        certificates = certificates_;
        network = network_;
        breaker = breaker_;
        neuro = neuro_;
        vaccines = vaccines_;
        threats = threats_;
        immune = immune_;
    }

    /// The live score of contract `target` on chain `chainId` (this chain: block.chainid).
    function score(uint64 chainId, address target) external view returns (uint16) {
        return breakdown(chainId, target).score;
    }

    /// The live score with every part of it (what the explorer shows).
    function breakdown(uint64 chainId, address target) public view returns (Breakdown memory b) {
        b.cap = MAX_SCORE;
        bool local = chainId == block.chainid;
        _certificate(b, chainId, target);
        _neuro(b, local, target);
        _monitoring(b, local, target);
        _history(b, chainId, target);
        if (local) _match(b, target);
        _flags(b, chainId, target, local);
        if (b.degraded) _capAt(b, 500);
        uint256 pts = uint256(b.certificate) + b.neuro + b.monitoring + b.history;
        pts = pts > b.penalty ? pts - b.penalty : 0;
        if (pts > b.cap) pts = b.cap;
        b.score = uint16(pts);
    }

    /// Anyone: stores the live score (an event for indexers, a cheap read for protocols that accept its age).
    function refresh(uint64 chainId, address target) external returns (uint16 s) {
        Breakdown memory b = breakdown(chainId, target);
        s = b.score;
        _cached[keccak256(abi.encode(chainId, target))] = Cached(s, uint64(block.timestamp));
        emit ScoreUpdated(chainId, target, s, b.cap);
    }

    function cached(uint64 chainId, address target) external view returns (uint16 s, uint64 at) {
        Cached storage c = _cached[keccak256(abi.encode(chainId, target))];
        return (c.score, c.at);
    }

    // ---------------------------------------------------------------- parts

    function _capAt(Breakdown memory b, uint16 c) internal pure {
        if (c < b.cap) b.cap = c;
    }

    function _certificate(Breakdown memory b, uint64 chainId, address target) internal view {
        if (address(certificates) == address(0)) return;
        try certificates.certificate{gas: READ_GAS}(chainId, target) returns (ISSCertificate.Cert memory c, bool valid) {
            if (c.issuedAt == 0) return;
            if (c.revokedAt != 0) { _capAt(b, 200); return; }
            if (!valid) {
                // expired or the code changed: no points; a revoked code hash also caps
                try certificates.revokedCode{gas: READ_GAS}(c.codeHash) returns (uint256 r) { if (r != 0) _capAt(b, 200); } catch { b.degraded = true; }
                return;
            }
            b.level = c.level;
            b.certExpires = c.expiresAt;
            uint256 base = c.level >= 3 ? 400 : c.level == 2 ? 325 : 250;
            uint256 span = c.expiresAt > c.issuedAt ? c.expiresAt - c.issuedAt : 1;
            uint256 left = c.expiresAt > block.timestamp ? c.expiresAt - block.timestamp : 0;
            if (left > span) left = span;
            b.certificate = uint16(base / 2 + (base * left) / (2 * span));
            _openFindings(b, c.requestId);
        } catch { b.degraded = true; }
    }

    function _openFindings(Breakdown memory b, uint256 requestId) internal view {
        if (address(network) == address(0)) return;
        uint256[] memory fids;
        try network.findingsOf{gas: READ_GAS * 4}(requestId) returns (uint256[] memory f) { fids = f; } catch { b.degraded = true; return; }
        uint256 open;
        uint256 seen;
        for (uint256 i = fids.length; i > 0 && seen < MAX_FINDINGS && open < OPEN_COUNTED; --i) {
            ++seen;
            try network.getFinding{gas: READ_GAS}(fids[i - 1]) returns (ISSFinding.Finding memory f) {
                if (f.late && f.status == F_REVEALED && f.claimed >= SEV_HIGH) ++open;
            } catch { b.degraded = true; return; }
        }
        b.openFindings = uint8(open);
        b.penalty += uint16(100 * open);
    }

    function _neuro(Breakdown memory b, bool local, address target) internal view {
        b.neuro = 100;
        if (!local || address(neuro) == address(0)) return;
        try neuro.scoreOf{gas: READ_GAS}(target) returns (bool known, int256, uint8 level) {
            if (!known) return;
            b.neuro = level == 0 ? 200 : level == 1 ? 150 : level == 2 ? 60 : 0;
        } catch { b.degraded = true; }
    }

    function _monitoring(Breakdown memory b, bool local, address target) internal view {
        if (!local || address(breaker) == address(0)) return;
        try breaker.policyGovernance{gas: READ_GAS}(target) returns (address g) {
            if (g != address(0)) b.monitoring = 150;
        } catch { b.degraded = true; return; }
        try breaker.isTripped{gas: READ_GAS}(target) returns (bool t) {
            if (t) { b.tripped = true; b.penalty += 300; return; }
        } catch { b.degraded = true; return; }
        try breaker.lastTrip{gas: READ_GAS}(target) returns (uint256 id) {
            if (id == 0) return;
            try breaker.tripOf{gas: READ_GAS * 2}(id - 1) returns (ISSTrip.Trip memory t) {
                if (t.claim != CLAIM_PROVEN_FALSE && block.timestamp < uint256(t.start) + 30 days) b.penalty += 100;
            } catch { b.degraded = true; }
        } catch { b.degraded = true; }
    }

    function _history(Breakdown memory b, uint64 chainId, address target) internal view {
        b.history = 250;
        if (address(vaccines) == address(0)) return;
        try vaccines.exploitsOf{gas: READ_GAS}(chainId, target) returns (uint32 n, uint64 last) {
            if (n == 0 || block.timestamp >= uint256(last) + 365 days) return;
            b.exploits = n;
            b.history = n >= 2 ? 0 : 125;
            if (block.timestamp < uint256(last) + 30 days) _capAt(b, 150);
        } catch { b.degraded = true; }
    }

    function _match(Breakdown memory b, address target) internal view {
        if (address(vaccines) == address(0)) return;
        try vaccines.matchOf{gas: READ_GAS}(target) returns (bytes32, uint8 strength, bool, uint64, address, bool active) {
            if (!active || strength == 0) return;
            b.vaccineMatch = strength;
            if (strength >= MATCH_BODY) _capAt(b, 100);
            else if (strength == MATCH_SELECTORS) b.penalty += 150;
        } catch { b.degraded = true; }
    }

    function _flags(Breakdown memory b, uint64 chainId, address target, bool local) internal view {
        if (address(threats) != address(0)) {
            try threats.isAddressFlagged{gas: READ_GAS}(chainId, target) returns (bool f, uint8) { if (f) { b.flagged = true; _capAt(b, 100); } } catch { b.degraded = true; }
            try threats.isAddressEnforced{gas: READ_GAS}(chainId, target) returns (bool f, uint8) { if (f) _capAt(b, 0); } catch { b.degraded = true; }
            if (local) {
                bytes32 h = target.codehash;
                try threats.isCodeFlagged{gas: READ_GAS}(h) returns (bool f, uint8) { if (f) { b.flagged = true; _capAt(b, 100); } } catch { b.degraded = true; }
                try threats.isCodeEnforced{gas: READ_GAS}(h) returns (bool f, uint8) { if (f) _capAt(b, 0); } catch { b.degraded = true; }
            }
            try threats.underReview{gas: READ_GAS}(keccak256(abi.encode("zetaphy.threat.address", uint256(chainId), target))) returns (bool held, bytes32, uint64) {
                if (held) { b.held = true; _capAt(b, 300); }
            } catch { b.degraded = true; }
        }
        if (address(immune) != address(0)) {
            try immune.isFlagged{gas: READ_GAS}(chainId, target) returns (bool f, uint8 sev, uint64, bytes32) { _immuneCap(b, f, sev); } catch { b.degraded = true; }
            if (local) {
                try immune.isCodeFlagged{gas: READ_GAS}(target.codehash) returns (bool f, uint8 sev, uint64, bytes32) { _immuneCap(b, f, sev); } catch { b.degraded = true; }
            }
        }
    }

    function _immuneCap(Breakdown memory b, bool f, uint8 sev) internal pure {
        if (!f) return;
        if (sev >= 4) { b.flagged = true; _capAt(b, 0); }
        else if (sev == 3) { b.flagged = true; _capAt(b, 100); }
        else if (sev == 2) _capAt(b, 400);
    }
}

/// @title ScoredCollateral: a collateral factor and a per-pool limit that follow SecurityScore
/// @notice The example DeFi integration (TESTNET ONLY). A lending market asks `collateralFactorBps(asset)` before it
///         values collateral, and `poolLimit(pool, baseLimit)` before it lets a pool (or a vault, a bridge route)
///         take more: both read the LIVE score, so a revoked certificate, a confirmed exploit, a vaccine match or a
///         flag lowers them in the same block. Tiers are governance's (the ZetaphyTimelock), inside fixed bounds:
///         at most 4 tiers, minimum scores strictly increasing and the lowest above 300 (so anything flagged, held,
///         recently exploited or revoked — all capped at 300 or below — is worth nothing as collateral), factors
///         non-decreasing and at most 8500 bps. No other key.
contract ScoredCollateral {
    uint256 public constant MAX_TIERS = 4;
    uint16 public constant MAX_FACTOR_BPS = 8500;
    uint16 public constant MIN_TIER_SCORE = 301;
    uint16 public constant LIMIT_FLOOR = 300; // poolLimit is 0 at or below this score

    struct Tier { uint16 minScore; uint16 factorBps; }

    SecurityScore public immutable scores;
    address public governance;
    Tier[] private _tiers;

    event TiersSet(Tier[] tiers);
    event GovernanceSet(address governance);

    error NotGovernance();
    error BadTiers();

    constructor(SecurityScore scores_, address governance_, Tier[] memory tiers_) {
        require(address(scores_) != address(0) && governance_ != address(0), "zero");
        scores = scores_;
        governance = governance_;
        _setTiers(tiers_);
    }

    function setTiers(Tier[] calldata t) external {
        if (msg.sender != governance) revert NotGovernance();
        _setTiers(t);
    }

    function setGovernance(address g) external {
        if (msg.sender != governance) revert NotGovernance();
        if (g == address(0)) revert BadTiers();
        governance = g;
        emit GovernanceSet(g);
    }

    function _setTiers(Tier[] memory t) internal {
        if (t.length == 0 || t.length > MAX_TIERS) revert BadTiers();
        for (uint256 i = 0; i < t.length; ++i) {
            if (t[i].factorBps > MAX_FACTOR_BPS || t[i].minScore > 1000) revert BadTiers();
            if (i == 0 ? t[i].minScore < MIN_TIER_SCORE : (t[i].minScore <= t[i - 1].minScore || t[i].factorBps < t[i - 1].factorBps)) revert BadTiers();
        }
        delete _tiers;
        for (uint256 i = 0; i < t.length; ++i) _tiers.push(t[i]);
        emit TiersSet(t);
    }

    function tiers() external view returns (Tier[] memory) { return _tiers; }

    /// The collateral factor (bps of value) of `asset` (a token contract on this chain) right now.
    function collateralFactorBps(address asset) public view returns (uint16 bps) {
        return factorFor(scores.score(uint64(block.chainid), asset));
    }

    function factorFor(uint16 s) public view returns (uint16 bps) {
        for (uint256 i = 0; i < _tiers.length; ++i) if (s >= _tiers[i].minScore) bps = _tiers[i].factorBps;
    }

    /// How much may be borrowed against `value` of `asset` collateral.
    function maxBorrow(address asset, uint256 value) external view returns (uint256) {
        return (value * collateralFactorBps(asset)) / 10_000;
    }

    /// The limit a pool / vault / route `pool` gets: baseLimit scaled linearly from 0 (score <= 300) to all of it
    /// (score 1000).
    function poolLimit(address pool, uint256 baseLimit) external view returns (uint256) {
        uint16 s = scores.score(uint64(block.chainid), pool);
        if (s <= LIMIT_FLOOR) return 0;
        return (baseLimit * (s - LIMIT_FLOOR)) / (1000 - LIMIT_FLOOR);
    }
}

contracts/SignalBoard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SignalBoard: browsers find each other on the ZETAPHY chain itself (testnet)
/// @notice A public notice board for WebRTC signaling, so two browsers that hold
///         (or want) the same model can connect with no server of ours and no
///         third-party tracker: a browser posts a short-lived message under a
///         topic (e.g. sha256 of "zetaphy-signal/1|chunks|<manifest hash>"), others
///         read the board with eth_getLogs, and the offer/answer go to one
///         recipient, ENCRYPTED to that recipient's key and signed by the sender
///         (zetaphy-neuro/ai/browser/signal.js). The contract never reads the
///         payload: it only bounds it.
///
///         Nothing is stored but a rate counter: messages live in event logs.
///         "Expiry" is a field readers enforce (block time + at most MAX_TTL); the
///         log itself stays on chain forever, so payloads must be encrypted or
///         harmless (an announce reveals a session key, a topic and a time).
///
///         Limits: payload 1..MAX_PAYLOAD bytes; expiresAt in (now, now + MAX_TTL];
///         each sender at most MAX_PER_WINDOW posts per WINDOW seconds. A sender
///         address costs nothing to make, so the rate limit only bounds one key;
///         what bounds a flood is gas (testnet coins come from the faucet, which
///         is rate-limited per internet address) and readers' own caps.
///
///         No owner, no funds, no upgrade, nothing to govern.
contract SignalBoard {
    uint256 public constant MAX_PAYLOAD = 2048;
    uint256 public constant MAX_TTL = 600;
    uint256 public constant WINDOW = 60;
    uint256 public constant MAX_PER_WINDOW = 12;

    struct Rate {
        uint64 windowStart;
        uint32 count;
    }

    mapping(address => Rate) public rate;

    /// @param topic what the message is about (readers filter on it)
    /// @param to recipient's peer id (16 bytes, left-aligned) or 0 for everyone on the topic
    event Signal(bytes32 indexed topic, bytes32 indexed to, address indexed from, uint64 expiresAt, bytes payload);

    error NoTopic();
    error PayloadSize();
    error BadExpiry();
    error RateLimited();

    function post(bytes32 topic, bytes32 to, uint64 expiresAt, bytes calldata payload) external {
        if (topic == bytes32(0)) revert NoTopic();
        if (payload.length == 0 || payload.length > MAX_PAYLOAD) revert PayloadSize();
        if (expiresAt <= block.timestamp || expiresAt > block.timestamp + MAX_TTL) revert BadExpiry();
        Rate memory r = rate[msg.sender];
        if (block.timestamp >= uint256(r.windowStart) + WINDOW) {
            r.windowStart = uint64(block.timestamp);
            r.count = 0;
        }
        if (r.count >= MAX_PER_WINDOW) revert RateLimited();
        r.count += 1;
        rate[msg.sender] = r;
        emit Signal(topic, to, msg.sender, expiresAt, payload);
    }

    /// @notice Posts left for `who` in the current window.
    function remaining(address who) external view returns (uint256) {
        Rate memory r = rate[who];
        if (block.timestamp >= uint256(r.windowStart) + WINDOW) return MAX_PER_WINDOW;
        return MAX_PER_WINDOW - r.count;
    }
}

contracts/SimpleMultisig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title SimpleMultisig: k-of-n owners for ZETAPHY admin roles (testnet)
/// @notice Holds governance of BridgeGuard / BridgeAirlock / StableGateway so
///         that no single key can change limits, prices or lanes. Any owner
///         proposes a call; it runs once `threshold` owners confirmed it.
///         Owners and the threshold change only through the multisig itself.
///         Changing them (setOwners) starts a new owner epoch: every proposal
///         made under an older owner set can no longer be confirmed or
///         executed (SM-1: a removed owner's confirmation must not count, and a
///         lowered threshold must not apply to old proposals). Re-propose it.
///         On mainnet prefer an audited Safe; this is small on purpose.
contract SimpleMultisig {
    struct Proposal {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint8 confirmations;
    }

    address[] public owners;
    mapping(address => bool) public isOwner;
    uint8 public threshold;
    Proposal[] public proposals;
    mapping(uint256 => mapping(address => bool)) public confirmed;
    uint256 public ownersEpoch;                      // bumped by every setOwners
    mapping(uint256 => uint256) public proposalEpoch; // proposal id -> owner epoch it was made in

    event Proposed(uint256 indexed id, address indexed by, address to, uint256 value);
    event Confirmed(uint256 indexed id, address indexed by);
    event Revoked(uint256 indexed id, address indexed by);
    event Executed(uint256 indexed id);

    error NotOwner();
    error BadConfig();
    error Done();
    error Twice();
    error NotEnough();
    error CallFailed(bytes reason);
    error Stale();

    constructor(address[] memory owners_, uint8 threshold_) {
        _setOwners(owners_, threshold_);
    }

    receive() external payable {}

    modifier onlyOwner() { if (!isOwner[msg.sender]) revert NotOwner(); _; }

    function propose(address to, uint256 value, bytes calldata data) external onlyOwner returns (uint256 id) {
        id = proposals.length;
        proposals.push(Proposal(to, value, data, false, 0));
        proposalEpoch[id] = ownersEpoch;
        emit Proposed(id, msg.sender, to, value);
        _confirm(id);
    }

    function confirm(uint256 id) external onlyOwner { _confirm(id); }

    function revoke(uint256 id) external onlyOwner {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (!confirmed[id][msg.sender]) revert NotEnough();
        confirmed[id][msg.sender] = false;
        p.confirmations -= 1;
        emit Revoked(id, msg.sender);
    }

    function execute(uint256 id) external onlyOwner returns (bytes memory) {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (proposalEpoch[id] != ownersEpoch) revert Stale();
        if (p.confirmations < threshold) revert NotEnough();
        p.executed = true;
        (bool ok, bytes memory ret) = p.to.call{value: p.value}(p.data);
        if (!ok) revert CallFailed(ret);
        emit Executed(id);
        return ret;
    }

    /// Change owners / threshold: only as a proposal executed by the multisig.
    function setOwners(address[] calldata owners_, uint8 threshold_) external {
        if (msg.sender != address(this)) revert NotOwner();
        for (uint256 i = 0; i < owners.length; i++) isOwner[owners[i]] = false;
        _setOwners(owners_, threshold_);
        ownersEpoch += 1;   // older proposals (and their confirmations) are void
    }

    function ownerCount() external view returns (uint256) { return owners.length; }
    function proposalCount() external view returns (uint256) { return proposals.length; }

    function _confirm(uint256 id) private {
        Proposal storage p = proposals[id];
        if (p.executed) revert Done();
        if (proposalEpoch[id] != ownersEpoch) revert Stale();
        if (confirmed[id][msg.sender]) revert Twice();
        confirmed[id][msg.sender] = true;
        p.confirmations += 1;
        emit Confirmed(id, msg.sender);
    }

    function _setOwners(address[] memory owners_, uint8 threshold_) private {
        if (threshold_ < 2 || threshold_ > owners_.length || owners_.length > 20) revert BadConfig();
        delete owners;
        for (uint256 i = 0; i < owners_.length; i++) {
            address o = owners_[i];
            if (o == address(0) || isOwner[o]) revert BadConfig();
            isOwner[o] = true;
            owners.push(o);
        }
        threshold = threshold_;
    }
}

contracts/StableGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IERC20Permit {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external;
}

interface INeuroJobs {
    function requestFor(address refundTo, bytes32 chain, string calldata target) external payable returns (uint256);
    function getJob(uint256 id) external view returns (address requester, uint64 created, uint8 status, bytes32 chain,
        string memory target, uint256 fee, bytes32 result, uint8 commits, uint8 reveals, address[3] memory seat);
    function FAIL_BURN_BPS() external view returns (uint16);
    function credit(address) external view returns (uint256);
    function withdraw() external;
}

/// ZetaphyOracle's consumer surface: a USD price (18 decimals) or a revert.
interface IPriceOracle {
    function price(address asset) external view returns (uint256 value, uint256 updatedAt);
}

/// @title StableGateway: use the Neuro network paying only in a stablecoin
/// @notice A user who holds a stablecoin but no ZETAPHY signs a job request.
///         Anyone (a "relayer") submits it and pays the gas; in the same
///         transaction the gateway takes the user's stablecoin (the cost of
///         the ZETAPHY fee, plus the relayer's tip) and pays the job fee in
///         ZETAPHY from its own reserve.
///         Price: ZetaphyOracle.price(zetaAsset) (ZETAPHY in USD, guarded: TWAP of
///         the DEX, Pyth, deviation, staleness, circuit breaker), and for each
///         accepted stablecoin either its own oracle price or a $1 peg. When the
///         oracle has no valid price the request reverts (PriceUnavailable, with
///         the oracle's reason): never a silently wrong price.
///         TESTNET FALLBACK: a fixed price per token (stablecoin units per 1
///         ZETAPHY), used ONLY while governance switched testnetFixedPrices on
///         (TestnetFixedPricesSet event; priceSource() says so). It is not a
///         market price; it exists for testnet bring-up before the oracle has a
///         TWAP window, and is off by default.
///         Refunds stay in the paying currency (SG-1): the gateway is the job's
///         requester, so when a job fails or expires NeuroJobs credits the
///         ZETAPHY refund to the gateway (back into the reserve), and
///         `refund(jobId)` pays the user the same share of the stablecoin it
///         paid (cost x (1 - NeuroJobs' fail burn)). The reserve is never a
///         stablecoin -> ZETAPHY exchange.
///         Roles: the owner (the ZetaphyTimelock) sets everything and moves funds;
///         guardians (named by the owner) may pause requests at once.
contract StableGateway {
    INeuroJobs public immutable jobs;
    address public owner;
    mapping(address => bool) public guardian;
    bool public paused;

    IPriceOracle public oracle;
    /// The asset id of ZETAPHY in the oracle (the DEX's wrapped ZETAPHY).
    address public zetaAsset;

    struct TokenConfig {
        bool accepted;
        bool oraclePriced;   // false: counted as $1 (a USD stablecoin)
        uint8 decimals;
    }
    mapping(address => TokenConfig) public tokens;

    /// TESTNET ONLY: stablecoin base units per 1 ZETAPHY (1e18 wei), used only while testnetFixedPrices is on.
    bool public testnetFixedPrices;
    mapping(address => uint256) public testnetFixedPrice;
    mapping(address => uint256) public nonces;

    /// What each gateway-paid job cost its user, for the stablecoin refund of a failed job.
    struct PaidJob { address user; address token; uint128 cost; bool refunded; }
    mapping(uint256 => PaidJob) public paidJobs;
    uint8 private constant JOB_FAILED = 3; // NeuroJobs.Status.Failed

    bytes32 public constant REQUEST_TYPEHASH = keccak256(
        "JobRequest(address user,address token,bytes32 chain,string target,uint256 fee,uint256 tip,uint256 maxCost,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    struct JobRequest {
        address user;
        address token;
        bytes32 chain;
        string target;
        uint256 fee;      // ZETAPHY (wei) the job pays
        uint256 tip;      // stablecoin units to the relayer
        uint256 maxCost;  // the most stablecoin the user agrees to spend (cost + tip)
        uint256 nonce;
        uint256 deadline;
    }

    struct Permit { uint256 value; uint256 deadline; uint8 v; bytes32 r; bytes32 s; }

    event OracleSet(address oracle, address zetaAsset);
    event TokenSet(address indexed token, bool accepted, bool oraclePriced, uint8 decimals);
    event TestnetFixedPricesSet(bool on);
    event TestnetFixedPriceSet(address indexed token, uint256 pricePerZeta);
    event Paid(uint256 indexed jobId, address indexed user, address indexed token, uint256 cost, uint256 tip, address relayer);
    event OwnerChanged(address owner);
    event GuardianSet(address indexed who, bool on);
    event Paused(address indexed by);
    event Unpaused();
    event Refunded(uint256 indexed jobId, address indexed user, address indexed token, uint256 amount);

    error NotOwner();
    error NotGuardian();
    error GatewayPaused();
    error Expired();
    error BadNonce();
    error BadSignature();
    error NotAccepted();
    error TooExpensive();
    error ReserveLow();
    error NoPriceSource();
    error PriceUnavailable(bytes reason);
    error NotRefundable();

    constructor(INeuroJobs jobs_) {
        jobs = jobs_;
        owner = msg.sender;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    receive() external payable {} // ZETAPHY reserve top-up

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    function setOwner(address o) external onlyOwner {
        owner = o;
        emit OwnerChanged(o);
    }

    function setGuardian(address who, bool on) external onlyOwner {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// A guardian (or the owner) stops new requests at once; only the owner restarts them.
    function pause() external {
        if (!guardian[msg.sender] && msg.sender != owner) revert NotGuardian();
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused();
    }

    function setOracle(IPriceOracle o, address zetaAsset_) external onlyOwner {
        oracle = o;
        zetaAsset = zetaAsset_;
        emit OracleSet(address(o), zetaAsset_);
    }

    /// Accept (or stop accepting) a stablecoin; oraclePriced: its own oracle price, else $1.
    function setToken(address token, bool accepted, bool oraclePriced, uint8 decimals) external onlyOwner {
        require(decimals <= 30, "decimals");
        tokens[token] = TokenConfig(accepted, oraclePriced, decimals);
        emit TokenSet(token, accepted, oraclePriced, decimals);
    }

    /// TESTNET ONLY: switch the fixed prices on (they replace the oracle) or off.
    function setTestnetFixedPrices(bool on) external onlyOwner {
        testnetFixedPrices = on;
        emit TestnetFixedPricesSet(on);
    }

    /// TESTNET ONLY: stablecoin units per 1 ZETAPHY, used only while testnetFixedPrices is on.
    function setTestnetFixedPrice(address token, uint256 price) external onlyOwner {
        testnetFixedPrice[token] = price;
        emit TestnetFixedPriceSet(token, price);
    }

    /// Stablecoin proceeds go to the treasury the operator names.
    function sweep(address token, address to, uint256 amount) external onlyOwner {
        require(IERC20Permit(token).transfer(to, amount), "transfer failed");
    }

    function withdrawReserve(address payable to, uint256 amount) external onlyOwner {
        (bool ok,) = to.call{value: amount}("");
        require(ok, "transfer failed");
    }

    /// Where quote() takes its price from.
    function priceSource() external view returns (string memory) {
        if (testnetFixedPrices) return "TESTNET FIXED PRICE (set by governance, not a market price)";
        if (address(oracle) == address(0)) return "none";
        return "ZetaphyOracle";
    }

    /// Stablecoin cost of a job fee, rounded up.
    function quote(address token, uint256 fee) public view returns (uint256) {
        TokenConfig memory t = tokens[token];
        if (!t.accepted) revert NotAccepted();
        if (testnetFixedPrices) {
            uint256 p = testnetFixedPrice[token];
            if (p == 0) revert NotAccepted();
            return (fee * p + 1e18 - 1) / 1e18;
        }
        if (address(oracle) == address(0)) revert NoPriceSource();
        uint256 zetaUsd = _price(zetaAsset);
        uint256 tokenUsd = t.oraclePriced ? _price(token) : 1e18;
        // fee (18 decimals) x ZETAPHY's USD price / the token's USD price, in the token's units, rounded up
        uint256 usd = fee * zetaUsd;                       // USD x 1e36
        uint256 den = tokenUsd * 1e18;
        return (usd * (10 ** uint256(t.decimals)) + den - 1) / den;
    }

    function _price(address asset) private view returns (uint256 v) {
        try oracle.price(asset) returns (uint256 value, uint256) { v = value; } catch (bytes memory reason) { revert PriceUnavailable(reason); }
        if (v == 0) revert PriceUnavailable("");
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function hashRequest(JobRequest calldata q) public view returns (bytes32) {
        return keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(), keccak256(abi.encode(
            REQUEST_TYPEHASH, q.user, q.token, q.chain, keccak256(bytes(q.target)), q.fee, q.tip, q.maxCost, q.nonce, q.deadline))));
    }

    /// The user already approved this gateway for the stablecoin.
    function request(JobRequest calldata q, bytes calldata sig) external returns (uint256) {
        return _request(q, sig);
    }

    /// Same, with an EIP-2612 permit so the user needs no approve transaction (no gas at all).
    function requestWithPermit(JobRequest calldata q, bytes calldata sig, Permit calldata p) external returns (uint256) {
        // A failed permit is fine if an allowance already exists (e.g. someone front-ran the permit).
        try IERC20Permit(q.token).permit(q.user, address(this), p.value, p.deadline, p.v, p.r, p.s) {} catch {}
        return _request(q, sig);
    }

    function _request(JobRequest calldata q, bytes calldata sig) private returns (uint256 jobId) {
        if (paused) revert GatewayPaused();
        if (block.timestamp > q.deadline) revert Expired();
        if (q.nonce != nonces[q.user]) revert BadNonce();
        if (_recover(hashRequest(q), sig) != q.user) revert BadSignature();
        nonces[q.user] = q.nonce + 1;

        uint256 cost = quote(q.token, q.fee);
        if (cost + q.tip > q.maxCost) revert TooExpensive();
        if (address(this).balance < q.fee) revert ReserveLow();

        require(IERC20Permit(q.token).transferFrom(q.user, address(this), cost), "payment failed");
        if (q.tip > 0) require(IERC20Permit(q.token).transferFrom(q.user, msg.sender, q.tip), "tip failed");
        // the gateway is the requester: a failed job's ZETAPHY refund comes back to the reserve (SG-1)
        jobId = jobs.requestFor{value: q.fee}(address(this), q.chain, q.target);
        paidJobs[jobId] = PaidJob(q.user, q.token, uint128(cost), false);
        emit Paid(jobId, q.user, q.token, cost, q.tip, msg.sender);
    }

    /// A gateway-paid job failed (or expired unanswered): anyone may refund its user in the stablecoin it
    /// paid, the same share NeuroJobs refunds (cost minus the fail burn). The ZETAPHY NeuroJobs credited
    /// to the gateway is pulled back into the reserve.
    function refund(uint256 jobId) external returns (uint256 amount) {
        PaidJob storage p = paidJobs[jobId];
        if (p.user == address(0) || p.refunded) revert NotRefundable();
        p.refunded = true; // before any call (a revert below undoes it)
        (address requester, , uint8 status, , , , , , , ) = jobs.getJob(jobId);
        if (requester != address(this) || status != JOB_FAILED) revert NotRefundable();
        amount = (uint256(p.cost) * (10_000 - jobs.FAIL_BURN_BPS())) / 10_000;
        if (jobs.credit(address(this)) != 0) jobs.withdraw();
        emit Refunded(jobId, p.user, p.token, amount);
        if (amount > 0) require(IERC20Permit(p.token).transfer(p.user, amount), "refund failed");
    }

    function _recover(bytes32 digest, bytes calldata sig) private pure returns (address) {
        if (sig.length != 65) revert BadSignature();
        bytes32 r = bytes32(sig[0:32]);
        bytes32 s = bytes32(sig[32:64]);
        uint8 v = uint8(sig[64]);
        if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) revert BadSignature();
        address a = ecrecover(digest, v, r, s);
        if (a == address(0)) revert BadSignature();
        return a;
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes("ZETAPHY StableGateway")), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/StarkLightClient.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// StarkVerifier's interface (contracts/StarkVerifier.sol; same structs).
interface IStarkLCVerifier {
    struct Pin {
        bytes32 root;
        uint8 logN;
        uint8 logBlowup;
    }

    struct Result {
        uint8 kind;
        uint64 height;
        bytes32 hash;
        uint8 nextLogN;
        uint8 nextLogBlowup;
        uint256 S;
        uint256 T;
        uint256 U;
        uint256 C;
        uint8 mode;
        uint256 revealed;
        uint256 revealsOffset;
        bytes32 revealsHash;
        bytes message;
        bool ok;
        bool pqMajority;
    }

    function verify(bytes calldata proof, Pin calldata pin, bytes calldata chainId, uint256 minSigBits, uint256 minStarkBits)
        external view returns (Result memory);
}

/// @title StarkLightClient: ZETAPHY finality on Ethereum from STARK light-client proofs (prototype)
/// @notice Holds ZETAPHY's validator set by its 32-byte set root, starting from a pinned genesis set,
///         and accepts:
///           - block proofs: "block H with hash X was signed by more than the chain's threshold of
///             the current set" (3S > 2T - 3U), plus the header's app_hash (state root) proven
///             against X (CometBFT header Merkle tree, field 10 of 14);
///           - handoff proofs: "the current set (more than 2/3 of ALL its power) signed the root of
///             the next epoch's set".
///         The STARK (validator-set accounting) is verified completely on chain by StarkVerifier at
///         submission. ML-DSA-44 signature validity is NOT proven by the Stage A STARK; it is covered:
///           - `submitChecked`: every revealed signature (modes all/sample) is verified now by the
///             ML-DSA verifier contract `mldsa`, and the claim is final at once (no trust; costs one
///             ML-DSA verification per revealed signer, millions of gas each in Solidity today);
///           - `submit` (optimistic): the claim waits `challengeWindow`; anyone who shows that one
///             revealed signature does not verify (`challenge`, a single non-interactive check)
///             rejects the claim and takes the submitter's bond. Trust: one honest watcher and
///             Ethereum liveness during the window;
///           - mode `none` (no reveals): only `trustedProver` may post it, and it is trusted for ML-DSA
///             validity (stated, not hidden). trustedProver = 0 disables mode none.
///         Two different final hashes for one height (or two set roots for one epoch) prove that more
///         than 1/3 of the stake equivocated: the client freezes (no app hash is served any more).
///         No admin: every parameter is fixed at deployment.
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract StarkLightClient {
    enum Status { None, Pending, Final, Rejected }

    struct Claim {
        uint8 kind;          // 0 block, 1 handoff
        Status status;
        uint8 mode;          // 0 none, 1 sample, 2 all
        uint8 nextLogN;
        uint8 nextLogBlowup;
        uint64 epoch;        // the set the proof was checked against
        uint64 height;       // block height, or the next epoch (handoff)
        uint64 submittedAt;
        address submitter;
        uint256 bond;
        bytes32 hash;        // block hash, or the next set root
        bytes32 appHash;     // blocks: the header's app_hash
        bytes32 revealsHash; // keccak256(G0, K0, G1, K1, ...) of the revealed rows
        bytes32 messageHash; // keccak256 of the message validators signed
    }

    IStarkLCVerifier public immutable verifier;
    /// ML-DSA-44 verifier: staticcall(pk[1312] || sig[2420] || message) returns uint256(1) when valid.
    address public immutable mldsa;
    uint64 public immutable challengeWindow;
    uint256 public immutable bond;
    uint256 public immutable minSigBits;
    uint256 public immutable minStarkBits;
    address public immutable trustedProver;
    bytes public chainId;

    uint64 public epoch;
    bytes32 public setRoot;
    uint8 public setLogN;
    uint8 public setLogBlowup;
    bool public frozen;

    Claim[] private claims;
    mapping(uint64 => bytes32) public finalBlockHash;
    mapping(uint64 => bytes32) public finalAppHash;
    mapping(uint64 => bytes32) public epochRoot;

    event Submitted(uint256 indexed id, uint8 kind, uint64 height, bytes32 hash, uint8 mode, uint256 revealed);
    event Challenged(uint256 indexed id, uint256 reveal, address challenger);
    event Finalized(uint256 indexed id, uint8 kind, uint64 height, bytes32 hash);
    event EpochAdvanced(uint64 epoch, bytes32 root);
    event Equivocation(uint256 indexed id, uint64 height, bytes32 known, bytes32 other);

    error Frozen();
    error WrongBond();
    error RuleFails();
    error WrongEpoch();
    error NoMajority();
    error BadAppHash();
    error ModeNotAllowed();
    error NotPending();
    error WindowOpen();
    error WindowClosed();
    error BadDispute();
    error SignatureValid();
    error SignatureInvalid(uint256 reveal);
    error Unknown();

    constructor(
        IStarkLCVerifier verifier_,
        address mldsa_,
        bytes memory chainId_,
        bytes32 genesisRoot,
        uint8 genesisLogN,
        uint8 genesisLogBlowup,
        uint64 challengeWindow_,
        uint256 bond_,
        uint256 minSigBits_,
        uint256 minStarkBits_,
        address trustedProver_
    ) {
        require(minStarkBits_ >= 80 && minSigBits_ >= 80 && challengeWindow_ > 0, "params");
        verifier = verifier_;
        mldsa = mldsa_;
        chainId = chainId_;
        setRoot = genesisRoot;
        setLogN = genesisLogN;
        setLogBlowup = genesisLogBlowup;
        epochRoot[0] = genesisRoot;
        challengeWindow = challengeWindow_;
        bond = bond_;
        minSigBits = minSigBits_;
        minStarkBits = minStarkBits_;
        trustedProver = trustedProver_;
    }

    // ------------------------------------------------------------------ submitting

    /// Optimistic: the STARK is checked now; signatures can be disputed for `challengeWindow`.
    /// `appHash` and its 4 header aunts are needed for block proofs (ignored for handoffs).
    function submit(bytes calldata proof, bytes32 appHash, bytes32[4] calldata aunts) external payable returns (uint256 id) {
        if (msg.value != bond) revert WrongBond();
        IStarkLCVerifier.Result memory r = _check(proof, appHash, aunts);
        id = _store(r, appHash, Status.Pending);
    }

    /// Final at once: every revealed ML-DSA-44 signature is verified now (modes all / sample).
    function submitChecked(bytes calldata proof, bytes32 appHash, bytes32[4] calldata aunts) external returns (uint256 id) {
        IStarkLCVerifier.Result memory r = _check(proof, appHash, aunts);
        if (r.mode == 0) revert ModeNotAllowed();
        uint256 off = r.revealsOffset;
        for (uint256 j = 0; j < r.revealed; j++) {
            uint256 sig = off + j * 3960 + 228;
            if (!_mldsaValid(proof[sig + 2420:sig + 2420 + 1312], proof[sig:sig + 2420], r.message)) revert SignatureInvalid(j);
        }
        id = _store(r, appHash, Status.Final);
        _apply(id);
    }

    function _check(bytes calldata proof, bytes32 appHash, bytes32[4] calldata aunts) private view returns (IStarkLCVerifier.Result memory r) {
        if (frozen) revert Frozen();
        bool trusted = trustedProver != address(0) && msg.sender == trustedProver;
        r = verifier.verify(proof, IStarkLCVerifier.Pin(setRoot, setLogN, setLogBlowup), chainId, trusted ? 0 : minSigBits, minStarkBits);
        if (r.mode == 0 && !trusted) revert ModeNotAllowed();
        if (r.kind == 0) {
            if (!r.ok) revert RuleFails();
            if (appHashRoot(appHash, aunts) != r.hash) revert BadAppHash();
        } else {
            if (r.height != epoch + 1) revert WrongEpoch();
            if (!r.pqMajority) revert NoMajority();
        }
    }

    function _store(IStarkLCVerifier.Result memory r, bytes32 appHash, Status status) private returns (uint256 id) {
        id = claims.length;
        claims.push(Claim({
            kind: r.kind, status: status, mode: r.mode, nextLogN: r.nextLogN, nextLogBlowup: r.nextLogBlowup,
            epoch: epoch, height: r.height, submittedAt: uint64(block.timestamp), submitter: msg.sender,
            bond: status == Status.Pending ? msg.value : 0, hash: r.hash, appHash: r.kind == 0 ? appHash : bytes32(0),
            revealsHash: r.revealsHash, messageHash: keccak256(r.message)
        }));
        emit Submitted(id, r.kind, r.height, r.hash, r.mode, r.revealed);
    }

    // ------------------------------------------------------------------ disputes and finality

    /// Anyone, during the window: reveal j of claim `id` is not a valid ML-DSA-44 signature.
    /// digests: (G, K) of every revealed row, as in the proof (their keccak is the claim's revealsHash);
    /// sig and pk: the revealed signature and key (from the submission's calldata); message: what was signed.
    function challenge(uint256 id, uint256 j, bytes32[] calldata digests, bytes calldata sig, bytes calldata pk, bytes calldata message) external {
        Claim storage c = claims[id];
        if (c.status != Status.Pending) revert NotPending();
        if (block.timestamp >= c.submittedAt + challengeWindow) revert WindowClosed();
        if (keccak256(abi.encodePacked(digests)) != c.revealsHash || 2 * j + 1 >= digests.length) revert BadDispute();
        if (keccak256(message) != c.messageHash || sig.length != 2420 || pk.length != 1312) revert BadDispute();
        if (_digest31("zetaphy/starklc/sig\x00", sig) != uint256(digests[2 * j]) || _digest31("zetaphy/starklc/pk\x00", pk) != uint256(digests[2 * j + 1])) revert BadDispute();
        if (_mldsaValid(pk, sig, message)) revert SignatureValid();
        c.status = Status.Rejected;
        uint256 b = c.bond;
        c.bond = 0;
        emit Challenged(id, j, msg.sender);
        if (b > 0) {
            (bool ok, ) = msg.sender.call{ value: b }("");
            require(ok, "bond");
        }
    }

    /// Anyone, after the window: the claim becomes final (and the bond goes back).
    function finalize(uint256 id) external {
        Claim storage c = claims[id];
        if (c.status != Status.Pending) revert NotPending();
        if (block.timestamp < c.submittedAt + challengeWindow) revert WindowOpen();
        c.status = Status.Final;
        _apply(id);
        uint256 b = c.bond;
        c.bond = 0;
        if (b > 0) {
            (bool ok, ) = c.submitter.call{ value: b }("");
            require(ok, "bond");
        }
    }

    function _apply(uint256 id) private {
        Claim storage c = claims[id];
        if (c.kind == 0) {
            bytes32 known = finalBlockHash[c.height];
            if (known != bytes32(0) && known != c.hash) { frozen = true; emit Equivocation(id, c.height, known, c.hash); return; }
            finalBlockHash[c.height] = c.hash;
            finalAppHash[c.height] = c.appHash;
        } else {
            bytes32 known = epochRoot[c.height];
            if (known != bytes32(0)) {
                if (known != c.hash) { frozen = true; emit Equivocation(id, c.height, known, c.hash); }
                return;
            }
            if (c.epoch != epoch || c.height != epoch + 1) revert WrongEpoch();
            epoch = c.height;
            setRoot = c.hash;
            setLogN = c.nextLogN;
            setLogBlowup = c.nextLogBlowup;
            epochRoot[c.height] = c.hash;
            emit EpochAdvanced(c.height, c.hash);
        }
        emit Finalized(id, c.kind, c.height, c.hash);
    }

    // ------------------------------------------------------------------ reading

    /// The final app hash of ZETAPHY block `height` (the state after block height - 1).
    function appHashAt(uint64 height) external view returns (bytes32 h) {
        if (frozen) revert Frozen();
        h = finalAppHash[height];
        if (h == bytes32(0)) revert Unknown();
    }

    function getClaim(uint256 id) external view returns (Claim memory) {
        return claims[id];
    }

    function claimCount() external view returns (uint256) {
        return claims.length;
    }

    /// CometBFT header hash from app_hash (field 10 of 14) and its aunts (bottom-up): the
    /// leaf is the protobuf BytesValue 0x0a 0x20 || app_hash, then 4 levels of the simple tree.
    function appHashRoot(bytes32 app, bytes32[4] calldata a) public pure returns (bytes32 h) {
        h = sha256(abi.encodePacked(uint8(0), uint8(0x0a), uint8(0x20), app));
        h = sha256(abi.encodePacked(uint8(1), h, a[0]));
        h = sha256(abi.encodePacked(uint8(1), a[1], h));
        h = sha256(abi.encodePacked(uint8(1), h, a[2]));
        h = sha256(abi.encodePacked(uint8(1), a[3], h));
    }

    function _mldsaValid(bytes memory pk, bytes memory sig, bytes memory message) private view returns (bool) {
        if (mldsa == address(0)) return false;
        (bool ok, bytes memory ret) = mldsa.staticcall(abi.encodePacked(pk, sig, message));
        return ok && ret.length == 32 && abi.decode(ret, (uint256)) == 1;
    }

    function _digest31(bytes memory tag, bytes calldata b) private pure returns (uint256) {
        return uint256(sha256(abi.encodePacked(tag, b))) >> 8;
    }
}

contracts/StarkVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title StarkVerifier: the ZETAPHY STARK light-client verifier (proof format v1) on the EVM
/// @notice A line-by-line port of zetaphy-network/src/starklc/verifier.js (DEEP-ALI + FRI over the
///         Stark252 field, SHA-256 Merkle commitments and Fiat-Shamir), using the SHA-256 precompile
///         (0x02) for every hash and the modexp precompile (0x05) for inversions. Stateless: it
///         takes the proof bytes exactly as `encodeProof` writes them and the pinned set
///         { root, logN, logBlowup }, and returns what was proven, or reverts ProofRejected(code).
///
///         What it does NOT do: verify ML-DSA-44 signatures. For revealed rows (modes `all` and
///         `sample`) it checks that each revealed signature and key hash to the committed G and K
///         values (so they are the certificate's signature and the set's key) and returns
///         `revealsHash` = keccak256(G0, K0, G1, K1, ...) and the signed message, so the caller
///         (StarkLightClient) can check the signatures itself or let anyone dispute one during a
///         challenge window. Mode `none` reveals nothing: the prover is trusted for ML-DSA validity.
///         Testnet prototype, not audited. See docs/future/trustless-bridge.md.
contract StarkVerifier {
    uint256 internal constant P = 0x800000000000011000000000000000000000000000000000000000000000001;
    uint256 internal constant R256 = 0x7fffffffffffdf0ffffffffffffffffffffffffffffffffffffffffffffffe1; // 2^256 mod P
    uint256 internal constant INV2 = 0x400000000000008800000000000000000000000000000000000000000000001;
    uint256 internal constant INV3 = 0x2aaaaaaaaaaaab0555555555555555555555555555555555555555555555556;
    uint256 internal constant COSET = 3;
    uint256 internal constant REVEAL = 4 + 7 * 32 + 2420 + 1312; // u32 row, 7 fields, signature, key
    uint256 internal constant SIG = 2420;

    /// Reasons, in the order they are checked (also what the JS verifier's messages say):
    /// 1 malformed/trailing bytes/non-canonical field   2 not the pinned set's size or blowup
    /// 3 another chain   4 weak STARK parameters   5 public sums out of range
    /// 6 constraints do not hold at z   7 reveals out of order/range   8 samples wrong
    /// 9 revealed count != C (mode all)   10 unexpected reveals (mode none)
    /// 11 revealed row is not a signer   12 key is not the set's   13 signature is not the committed one
    /// 14 too few signature-check bits   15 FRI shape   16 proof of work missing
    /// 17 trace openings   18 set openings (wrong set root)   19 composition openings
    /// 20 FRI layer openings   21 FRI folding   22 FRI final polynomial
    error ProofRejected(uint256 code);

    struct Pin {
        bytes32 root;
        uint8 logN;
        uint8 logBlowup;
    }

    struct Result {
        uint8 kind;            // 0 block, 1 handoff
        uint64 height;         // block height, or the next epoch for a handoff
        bytes32 hash;          // block hash, or the next set root for a handoff
        uint8 nextLogN;
        uint8 nextLogBlowup;
        uint256 S;
        uint256 T;
        uint256 U;
        uint256 C;
        uint8 mode;            // 0 none, 1 sample, 2 all
        uint256 revealed;
        uint256 revealsOffset; // where the reveals start in the proof bytes (row u32, 7 fields, sig, key)
        bytes32 revealsHash;   // keccak256 of (G, K) per revealed row, in order
        bytes message;         // the bytes the validators signed (voteMessage / handoff message)
        bool ok;               // the chain's rule 3S > 2T - 3U
        bool pqMajority;       // 3S > 2T
    }

    /// Everything about one verification (calldata offsets are absolute).
    struct V {
        uint256 b; uint256 end;
        uint256 logBlowup; uint256 queries; uint256 grind; uint256 logFinalDeg; uint256 logN;
        uint256 N; uint256 L; uint256 half;
        uint256 stmt; uint256 stmtLen; uint256 chain; uint256 chainLen;
        uint256 S; uint256 T; uint256 U; uint256 C; uint256 mode; uint256 k;
        bytes32 traceRoot; bytes32 qRoot; uint256 ood;
        uint256 rev; uint256 nRev; uint256 samp; uint256 nSamp;
        uint256 fri; uint256 nFri; uint256 fin; uint256 nFin; uint256 nonce;
        uint256 nq; uint256 tl; uint256 sl; uint256 ql;
        uint256 tp; uint256 tpN; uint256 sp; uint256 spN; uint256 qp; uint256 qpN;
        uint256 layers;
        bytes32 setRoot; bytes32 st; uint256 ctr;
        uint256 z; uint256 wN; uint256 wL;
        uint256[] alphas; uint256[] gammas; uint256[] betas; uint256[] idx;
        uint256[] pts; uint256[] gsum;
    }

    // ------------------------------------------------------------------ entry point

    /// @param minSigBits the least signature-check security accepted (0 accepts mode none)
    /// @param minStarkBits the least conjectured STARK security (queries * logBlowup + grinding)
    function verify(bytes calldata proof, Pin calldata pin, bytes calldata chainId, uint256 minSigBits, uint256 minStarkBits)
        external view returns (Result memory r)
    {
        V memory v;
        uint256 b;
        assembly { b := proof.offset }
        v.b = b;
        v.end = b + proof.length;
        v.setRoot = pin.root;
        _parse(v);
        if (v.logN != pin.logN || v.logBlowup != pin.logBlowup) revert ProofRejected(2);
        if (keccak256(proof[v.chain - b:v.chain - b + v.chainLen]) != keccak256(chainId)) revert ProofRejected(3);
        if (v.queries * v.logBlowup + v.grind < minStarkBits || v.logFinalDeg > 10 || v.queries < 1 || v.grind > 40) revert ProofRejected(4);
        if (v.S >= 1 << 100 || v.T >= 1 << 100 || v.U >= 1 << 100 || v.C >= 1 << 100) revert ProofRejected(5);

        r.message = _message(v);
        _transcriptToOod(v, r.message);
        _checkComposition(v);
        (r.revealsHash) = _reveals(v, minSigBits);
        _deepAndFri(v);

        r.kind = uint8(_u(v.stmt, 1));
        r.height = uint64(_u(v.stmt + 2 + v.chainLen, 8));
        r.hash = bytes32(_w(v.stmt + 10 + v.chainLen));
        r.nextLogN = uint8(_u(v.stmt + 42 + v.chainLen, 1));
        r.nextLogBlowup = uint8(_u(v.stmt + 43 + v.chainLen, 1));
        (r.S, r.T, r.U, r.C) = (v.S, v.T, v.U, v.C);
        r.mode = uint8(v.mode);
        r.revealed = v.nRev;
        r.revealsOffset = v.rev - b;
        int256 need = 2 * int256(v.T) - 3 * int256(v.U);
        r.ok = need < 0 || 3 * int256(v.S) > need;
        r.pqMajority = 3 * v.S > 2 * v.T;
    }

    // ------------------------------------------------------------------ parsing

    function _parse(V memory v) private pure {
        unchecked {
            uint256 c = v.b;
            if (v.end - v.b < 64 || _u(c, 5) != 0x5a534c4301) revert ProofRejected(1); // "ZSLC" v1
            c += 5;
            (v.logBlowup, v.queries, v.grind, v.logFinalDeg, v.logN) = (_u(c, 1), _u(c + 1, 1), _u(c + 2, 1), _u(c + 3, 1), _u(c + 4, 1));
            if (v.logN < 3 || v.logN > 20 || v.logBlowup < 1 || v.logBlowup > 6) revert ProofRejected(1);
            v.N = 1 << v.logN;
            v.L = v.N << v.logBlowup;
            v.half = v.L / 2;
            c += 5;
            v.stmt = c;
            uint256 kind = _u(c, 1);
            v.chainLen = _u(c + 1, 1);
            v.chain = c + 2;
            c = v.chain + v.chainLen + 8 + 32;
            if (kind > 1 || (kind == 0 && _u(c, 2) != 0)) revert ProofRejected(1);
            c += 2;
            v.stmtLen = c - v.stmt;
            (v.S, v.T, v.U, v.C) = (_f(c), _f(c + 32), _f(c + 64), _f(c + 96));
            c += 128;
            v.mode = _u(c, 1);
            v.k = _u(c + 1, 2);
            if (v.mode > 2) revert ProofRejected(1);
            c += 3;
            v.traceRoot = bytes32(_w(c));
            v.qRoot = bytes32(_w(c + 32));
            c += 64;
            v.ood = c;
            c += 15 * 32;
            v.nRev = _u(c, 2);
            v.rev = c + 2;
            c = v.rev + v.nRev * REVEAL;
            v.nSamp = _u(c, 2);
            v.samp = c + 2;
            c = v.samp + 2 * v.nSamp;
            v.nFri = _u(c, 1);
            v.fri = c + 1;
            c = v.fri + 32 * v.nFri;
            v.nFin = _u(c, 1);
            v.fin = c + 1;
            c = v.fin + 32 * v.nFin;
            v.nonce = _u(c, 8);
            c += 8;
            v.nq = _u(c, 2);
            c += 2;
            v.tl = c; c += v.nq * 12 * 32;
            v.sl = c; c += v.nq * 8 * 32;
            v.ql = c; c += v.nq * 2 * 32;
            v.tpN = _u(c, 2); v.tp = c + 2; c = v.tp + 32 * v.tpN;
            v.spN = _u(c, 2); v.sp = c + 2; c = v.sp + 32 * v.spN;
            v.qpN = _u(c, 2); v.qp = c + 2; c = v.qp + 32 * v.qpN;
            v.layers = c;
            for (uint256 i = 0; i < v.nFri; i++) {
                if (c > v.end) revert ProofRejected(1);
                c += 2 + _u(c, 2) * 64;
                c += 2 + _u(c, 2) * 32;
            }
            if (c != v.end) revert ProofRejected(1);
        }
    }

    /// The bytes validators sign: "zetaphy/pq-vote\0" chain "\0" u64 height hash (a block), or
    /// "zetaphy/pq-setroot\0" chain "\0" u64 epoch root logN logBlowup (a handoff).
    function _message(V memory v) private pure returns (bytes memory) {
        uint256 kind = _u(v.stmt, 1);
        bytes memory chain = _cd(v.chain, v.chainLen);
        bytes memory rest = _cd(v.chain + v.chainLen, 40); // u64 height, hash
        if (kind == 0) return abi.encodePacked("zetaphy/pq-vote\x00", chain, "\x00", rest);
        return abi.encodePacked("zetaphy/pq-setroot\x00", chain, "\x00", rest, _cd(v.chain + v.chainLen + 40, 2));
    }

    // ------------------------------------------------------------------ transcript replay

    function _transcriptToOod(V memory v, bytes memory message) private view {
        v.st = sha256("zetaphy/starklc/v1\x00proof");
        bytes memory head = abi.encodePacked(
            uint8(1), uint8(v.logBlowup), uint8(v.queries), uint8(v.grind), uint8(v.logFinalDeg), uint8(v.logN),
            v.setRoot, _cd(v.stmt, v.stmtLen), message);
        head = abi.encodePacked(head, v.S, v.T, v.U, v.C, uint8(v.mode), uint64(v.k));
        _absorbMem(v, head);
        _absorb32(v, v.traceRoot);
        v.alphas = new uint256[](18);
        for (uint256 i = 0; i < 18; i++) v.alphas[i] = _field(v);
        _absorb32(v, v.qRoot);
        uint256 cosetPowL = _pow(COSET, v.L);
        uint256 z = _field(v);
        while (z == 0 || _pow(z, v.N) == 1 || _pow(z, v.L) == cosetPowL) z = _field(v);
        v.z = z;
        v.wN = _root(v.logN);
        v.wL = _root(v.logN + v.logBlowup);
        for (uint256 i = 0; i < 15; i++) _f(v.ood + 32 * i);
        _absorbCd(v, v.ood, 15 * 32);
    }

    function _checkComposition(V memory v) private view {
        uint256 o = v.ood;
        uint256[] memory a = v.alphas;
        uint256 z = v.z;
        uint256 wLast = _pow(v.wN, v.N - 1);
        uint256 acc = mulmod(addmod(_compAll(o, a), mulmod(_compTrans(o, a), _sub(z, wLast), P), P), _inv(_sub(_pow(z, v.N), 1)), P);
        uint256 invFirst = _inv(_sub(z, 1));
        uint256 invLast = _inv(_sub(z, wLast));
        // first row: CS, CT, CU, CC = 0
        for (uint256 j = 0; j < 4; j++) acc = addmod(acc, mulmod(a[9 + j], mulmod(_w(o + 64 + 32 * j), invFirst, P), P), P);
        // last row: CS = S, CT = T, CU = U, CC = C, P = 0
        acc = addmod(acc, mulmod(a[13], mulmod(_sub(_w(o + 64), v.S), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[14], mulmod(_sub(_w(o + 96), v.T), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[15], mulmod(_sub(_w(o + 128), v.U), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[16], mulmod(_sub(_w(o + 160), v.C), invLast, P), P), P);
        acc = addmod(acc, mulmod(a[17], mulmod(_w(o + 416), invLast, P), P), P);
        if (acc != _w(o + 448)) revert ProofRejected(6);
    }


    /// Row constraints B(B-1), (1-B)G, BZ, Z(Z-1), ZK at z, mixed with alpha 0..4.
    function _compAll(uint256 o, uint256[] memory a) private pure returns (uint256 x) {
        uint256 B = _w(o);
        uint256 Z = _w(o + 384);
        x = mulmod(a[0], mulmod(B, addmod(B, P - 1, P), P), P);
        x = addmod(x, mulmod(a[1], mulmod(addmod(1, P - B, P), _w(o + 32), P), P), P);
        x = addmod(x, mulmod(a[2], mulmod(B, Z, P), P), P);
        x = addmod(x, mulmod(a[3], mulmod(Z, addmod(Z, P - 1, P), P), P), P);
        x = addmod(x, mulmod(a[4], mulmod(Z, _w(o + 352), P), P), P);
    }

    /// Transitions CS'=CS+BP, CT'=CT+P, CU'=CU+ZP, CC'=CC+B at z, mixed with alpha 5..8.
    function _compTrans(uint256 o, uint256[] memory a) private pure returns (uint256 y) {
        uint256 B = _w(o);
        uint256 Pw = _w(o + 416);
        y = mulmod(a[5], _sub(_sub(_w(o + 192), _w(o + 64)), mulmod(B, Pw, P)), P);
        y = addmod(y, mulmod(a[6], _sub(_sub(_w(o + 224), _w(o + 96)), Pw), P), P);
        y = addmod(y, mulmod(a[7], _sub(_sub(_w(o + 256), _w(o + 128)), mulmod(_w(o + 384), Pw, P)), P), P);
        y = addmod(y, mulmod(a[8], _sub(_sub(_w(o + 288), _w(o + 160)), B), P), P);
    }

    // ------------------------------------------------------------------ signature reveals

    function _reveals(V memory v, uint256 minSigBits) private view returns (bytes32 revealsHash) {
        unchecked {
            uint256 n = v.nRev;
            for (uint256 i = 0; i < n; i++) {
                uint256 row = _u(v.rev + i * REVEAL, 4);
                if (row >= v.N - 1 || (i > 0 && row <= _u(v.rev + (i - 1) * REVEAL, 4))) revert ProofRejected(7);
            }
            if (v.mode == 1) {
                if (v.k != v.nSamp) revert ProofRejected(8);
                bool[] memory used = new bool[](n);
                uint256 bound = v.S == 0 ? 1 : v.S;
                for (uint256 j = 0; j < v.k; j++) {
                    uint256 r = _below(v, bound);
                    uint256 ri = _u(v.samp + 2 * j, 2);
                    if (ri >= n) revert ProofRejected(8);
                    uint256 base = v.rev + ri * REVEAL + 4;
                    if (!(_f(base + 64) <= r && r < _f(base + 96))) revert ProofRejected(8);
                    used[ri] = true;
                }
                for (uint256 i = 0; i < n; i++) if (!used[i]) revert ProofRejected(8);
            } else if (v.mode == 2) {
                if (n != v.C) revert ProofRejected(9);
            } else if (n != 0 || v.nSamp != 0) {
                revert ProofRejected(10);
            }
            bytes memory digests = new bytes(64 * n);
            bytes memory rb = new bytes(232 * n);
            for (uint256 i = 0; i < n; i++) {
                uint256 base = v.rev + i * REVEAL;
                uint256 vals = base + 4;
                for (uint256 j = 0; j < 7; j++) _f(vals + 32 * j);
                if (_w(vals) != 1) revert ProofRejected(11);
                uint256 sigOff = vals + 224;
                uint256 K = _w(vals + 160);
                uint256 G = _w(vals + 32);
                if (_digest31("zetaphy/starklc/pk\x00", sigOff + SIG, 1312) != K) revert ProofRejected(12);
                if (_digest31("zetaphy/starklc/sig\x00", sigOff, SIG) != G) revert ProofRejected(13);
                assembly {
                    mstore(add(add(digests, 32), mul(i, 64)), G)
                    mstore(add(add(digests, 64), mul(i, 64)), K)
                    let d := add(add(rb, 32), mul(i, 232))
                    mstore(d, shl(192, shr(224, calldataload(base)))) // u64(row)
                    calldatacopy(add(d, 8), vals, 224)
                }
            }
            revealsHash = keccak256(digests);
            _absorbMem(v, rb);

            // signature-check security
            int256 need = 2 * int256(v.T) - 3 * int256(v.U);
            if (v.mode == 2 || need <= 0 || minSigBits == 0) return revealsHash;
            if (v.mode == 0 || 3 * v.S <= uint256(need)) revert ProofRejected(14);
            // k * (log2(3S) - log2(need)) >= minSigBits, with a lower bound in 1/65536 bits
            uint256 hi = _log2q(3 * v.S);
            uint256 lo = _log2q(uint256(need)) + 2;
            if (hi <= lo || v.k * (hi - lo) < minSigBits << 16) revert ProofRejected(14);
        }
    }

    // ------------------------------------------------------------------ DEEP + FRI

    function _deepAndFri(V memory v) private view {
        uint256 groups = 2 + 2 * v.nRev;
        uint256 terms = 15 + 7 * v.nRev;
        v.gammas = new uint256[](terms);
        for (uint256 i = 0; i < terms; i++) v.gammas[i] = _field(v);
        uint256 m = v.logN > v.logFinalDeg ? v.logN - v.logFinalDeg : 0;
        if (v.nFri != (m > 0 ? m - 1 : 0) || v.nFin != v.N >> m) revert ProofRejected(15);
        v.betas = new uint256[](m);
        for (uint256 i = 0; i < m; i++) {
            v.betas[i] = _field(v);
            if (i + 1 < m) _absorb32(v, bytes32(_w(v.fri + 32 * i)));
        }
        for (uint256 i = 0; i < v.nFin; i++) _f(v.fin + 32 * i);
        _absorbCd(v, v.fin, 32 * v.nFin);
        if (v.grind > 0) {
            bytes32 h = sha256(abi.encodePacked(v.st, uint64(v.nonce)));
            if (uint256(h) >> (256 - v.grind) != 0) revert ProofRejected(16);
        }
        _absorbMem(v, abi.encodePacked(uint64(v.nonce)));
        _queryIndices(v);

        _openings(v);
        // DEEP group points and their constant parts
        v.pts = new uint256[](groups);
        v.gsum = new uint256[](groups);
        _groups(v);
        (uint256[] memory a0, uint256[] memory a1) = _deepValues(v, groups);
        _fri(v, m, a0, a1);
    }

    /// Merkle openings of the trace, the pinned set and Q at the query positions.
    function _openings(V memory v) private view {
        unchecked {
            uint256 depth = v.logN + v.logBlowup - 1;
            uint256 nq = v.idx.length;
            if (v.nq != nq) revert ProofRejected(1);
            if (!_verifyMany(v.traceRoot, depth, v.idx, _leafHashes(v.tl, 384, nq), v.tp, v.tpN)) revert ProofRejected(17);
            if (!_verifyMany(v.setRoot, depth, v.idx, _leafHashes(v.sl, 256, nq), v.sp, v.spN)) revert ProofRejected(18);
            if (!_verifyMany(v.qRoot, depth, v.idx, _leafHashes(v.ql, 64, nq), v.qp, v.qpN)) revert ProofRejected(19);
        }
    }

    /// f0(x) and f0(-x) at every query (one batched inversion per query).
    function _deepValues(V memory v, uint256 groups) private view returns (uint256[] memory a0, uint256[] memory a1) {
        unchecked {
            uint256 nq = v.idx.length;
            a0 = new uint256[](nq);
            a1 = new uint256[](nq);
            uint256[] memory den = new uint256[](2 * groups);
            for (uint256 q = 0; q < nq; q++) {
                uint256 x = mulmod(COSET, _pow(v.wL, v.idx[q]), P);
                for (uint256 g = 0; g < groups; g++) {
                    den[g] = _sub(x, v.pts[g]);
                    den[groups + g] = _sub(P - x, v.pts[g]);
                }
                _batchInv(den);
                uint256 t = v.tl + q * 384;
                uint256 s = v.sl + q * 256;
                uint256 ql = v.ql + q * 64;
                for (uint256 i = 0; i < 12; i++) _f(t + 32 * i);
                for (uint256 i = 0; i < 8; i++) _f(s + 32 * i);
                a0[q] = _deepAt(v, t, s, _f(ql), den, 0);
                a1[q] = _deepAt(v, t + 192, s + 128, _f(ql + 32), den, groups);
            }
        }
    }

    function _groups(V memory v) private pure {
        unchecked {
            uint256[] memory gm = v.gammas;
            uint256 o = v.ood;
            uint256 s;
            // z: B G CS CT CU CC, A K Z P, Q
            for (uint256 j = 0; j < 11; j++) s = addmod(s, mulmod(gm[j], _w(o + (j < 6 ? 32 * j : j < 10 ? 320 + 32 * (j - 6) : 448)), P), P);
            v.pts[0] = v.z;
            v.gsum[0] = s;
            s = 0;
            // z * wN: CS CT CU CC of the next row
            for (uint256 j = 0; j < 4; j++) s = addmod(s, mulmod(gm[11 + j], _w(o + 192 + 32 * j), P), P);
            v.pts[1] = mulmod(v.z, v.wN, P);
            v.gsum[1] = s;
            for (uint256 i = 0; i < v.nRev; i++) {
                uint256 base = v.rev + i * REVEAL;
                uint256 row = _u(base, 4);
                uint256 vals = base + 4; // B G CS CSn A K P
                uint256 gb = 15 + 7 * i;
                s = mulmod(gm[gb], _w(vals), P);
                s = addmod(s, mulmod(gm[gb + 1], _w(vals + 32), P), P);
                s = addmod(s, mulmod(gm[gb + 2], _w(vals + 64), P), P);
                s = addmod(s, mulmod(gm[gb + 3], _w(vals + 128), P), P);
                s = addmod(s, mulmod(gm[gb + 4], _w(vals + 160), P), P);
                s = addmod(s, mulmod(gm[gb + 5], _w(vals + 192), P), P);
                uint256 w = _pow(v.wN, row);
                v.pts[2 + 2 * i] = w;
                v.gsum[2 + 2 * i] = s;
                v.pts[3 + 2 * i] = mulmod(w, v.wN, P);
                v.gsum[3 + 2 * i] = mulmod(gm[gb + 6], _w(vals + 96), P);
            }
        }
    }

    /// The DEEP composition at one point: t (6 fields) and s (4 fields) at calldata offsets, q.
    function _deepAt(V memory v, uint256 t, uint256 s, uint256 q, uint256[] memory den, uint256 d0) private pure returns (uint256 acc) {
        uint256[] memory gm = v.gammas;
        uint256[] memory gs = v.gsum;
        uint256 num;
        unchecked {
            for (uint256 j = 0; j < 6; j++) num = addmod(num, mulmod(gm[j], _w(t + 32 * j), P), P);
            for (uint256 j = 0; j < 4; j++) num = addmod(num, mulmod(gm[6 + j], _w(s + 32 * j), P), P);
            num = addmod(num, mulmod(gm[10], q, P), P);
            acc = mulmod(_sub(num, gs[0]), den[d0], P);
            num = 0;
            for (uint256 j = 0; j < 4; j++) num = addmod(num, mulmod(gm[11 + j], _w(t + 64 + 32 * j), P), P);
            acc = addmod(acc, mulmod(_sub(num, gs[1]), den[d0 + 1], P), P);
            acc = addmod(acc, _deepReveals(v, [_w(t), _w(t + 32), _w(t + 64), _w(s), _w(s + 32), _w(s + 96)], den, d0), P);
        }
    }

    /// The reveal groups of the DEEP sum: c = B, G, CS, A, K, P at the point.
    function _deepReveals(V memory v, uint256[6] memory c, uint256[] memory den, uint256 d0) private pure returns (uint256 acc) {
        uint256[] memory gm = v.gammas;
        uint256[] memory gs = v.gsum;
        uint256 n = v.nRev;
        assembly {
            let g := add(gm, add(32, mul(15, 32)))     // gammas[15]
            let s := add(gs, 96)                        // gsum[2]
            let d := add(den, add(32, shl(5, add(d0, 2)))) // den[d0 + 2]
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                let num := mulmod(mload(g), mload(c), P)
                num := addmod(num, mulmod(mload(add(g, 32)), mload(add(c, 32)), P), P)
                num := addmod(num, mulmod(mload(add(g, 64)), mload(add(c, 64)), P), P)
                num := addmod(num, mulmod(mload(add(g, 96)), mload(add(c, 96)), P), P)
                num := addmod(num, mulmod(mload(add(g, 128)), mload(add(c, 128)), P), P)
                num := addmod(num, mulmod(mload(add(g, 160)), mload(add(c, 160)), P), P)
                acc := addmod(acc, mulmod(addmod(num, sub(P, mload(s)), P), mload(d), P), P)
                let one := mulmod(mload(add(g, 192)), mload(add(c, 64)), P)
                acc := addmod(acc, mulmod(addmod(one, sub(P, mload(add(s, 32))), P), mload(add(d, 32)), P), P)
                g := add(g, 224)
                s := add(s, 64)
                d := add(d, 64)
            }
        }
    }

    /// FRI state: the current domain off * <w> of `size` points, and the next layer's offset.
    struct F { uint256 off; uint256 offInv; uint256 w; uint256 size; uint256 lay; uint256[] pos; uint256[] a0; uint256[] a1; }

    function _fri(V memory v, uint256 m, uint256[] memory a0, uint256[] memory a1) private view {
        F memory f = F(COSET, INV3, v.wL, v.L, v.layers, v.idx, a0, a1);
        for (uint256 k2 = 0; k2 < m; k2++) {
            uint256[] memory folded = _fold(f, v.betas[k2]);
            if (k2 + 1 < m) _layer(v, f, k2, folded);
            else {
                for (uint256 q = 0; q < folded.length; q++) {
                    if (_evalFinal(v, mulmod(f.off, _pow(f.w, f.pos[q]), P)) != folded[q]) revert ProofRejected(22);
                }
            }
        }
        if (m == 0) {
            for (uint256 q = 0; q < f.pos.length; q++) {
                uint256 x = mulmod(COSET, _pow(v.wL, f.pos[q]), P);
                if (_evalFinal(v, x) != f.a0[q] || _evalFinal(v, P - x) != f.a1[q]) revert ProofRejected(22);
            }
        }
    }

    /// One fold: (a0 + a1)/2 + beta (a0 - a1)/(2x), then the domain is squared.
    function _fold(F memory f, uint256 beta) private pure returns (uint256[] memory folded) {
        unchecked {
            uint256 cnt = f.pos.length;
            folded = new uint256[](cnt);
            for (uint256 q = 0; q < cnt; q++) {
                uint256 xInv = mulmod(f.offInv, _pow(f.w, f.size - f.pos[q]), P);
                uint256 odd = mulmod(mulmod(_sub(f.a0[q], f.a1[q]), INV2, P), xInv, P);
                folded[q] = addmod(mulmod(addmod(f.a0[q], f.a1[q], P), INV2, P), mulmod(beta, odd, P), P);
            }
            f.off = mulmod(f.off, f.off, P);
            f.offInv = mulmod(f.offInv, f.offInv, P);
            f.w = mulmod(f.w, f.w, P);
            f.size >>= 1;
        }
    }

    /// The committed layer k2 + 1 opens at the folded positions and holds the folded values.
    function _layer(V memory v, F memory f, uint256 k2, uint256[] memory folded) private view {
        unchecked {
            uint256 h2 = f.size >> 1;
            uint256[] memory np = _uniqueMod(f.pos, h2);
            uint256 n = _u(f.lay, 2);
            uint256 leaves = f.lay + 2;
            if (n != np.length) revert ProofRejected(20);
            uint256 pn = _u(leaves + 64 * n, 2);
            if (!_verifyMany(bytes32(_w(v.fri + 32 * k2)), _log2(h2), np, _leafHashes(leaves, 64, n), leaves + 64 * n + 2, pn)) revert ProofRejected(20);
            for (uint256 q = 0; q < folded.length; q++) {
                uint256 j = _indexOf(np, f.pos[q] % h2);
                if (_f(leaves + 64 * j + (f.pos[q] >= h2 ? 32 : 0)) != folded[q]) revert ProofRejected(21);
            }
            f.a0 = new uint256[](n);
            f.a1 = new uint256[](n);
            for (uint256 j = 0; j < n; j++) { f.a0[j] = _f(leaves + 64 * j); f.a1[j] = _f(leaves + 64 * j + 32); }
            f.pos = np;
            f.lay = leaves + 64 * n + 2 + 32 * pn;
        }
    }

    function _evalFinal(V memory v, uint256 x) private pure returns (uint256 r) {
        unchecked {
            for (uint256 i = v.nFin; i > 0; i--) r = addmod(mulmod(r, x, P), _w(v.fin + 32 * (i - 1)), P);
        }
    }

    function _queryIndices(V memory v) private view {
        unchecked {
            uint256 want = v.queries < v.half ? v.queries : v.half;
            uint256[] memory out = new uint256[](want);
            uint256 n = 0;
            while (n < want) {
                uint256 x = _below(v, v.half);
                uint256 i = 0;
                while (i < n && out[i] < x) i++;
                if (i < n && out[i] == x) continue;
                for (uint256 j = n; j > i; j--) out[j] = out[j - 1];
                out[i] = x;
                n++;
            }
            v.idx = out;
        }
    }

    // ------------------------------------------------------------------ Merkle

    function _leafHashes(uint256 off, uint256 len, uint256 n) private view returns (bytes32[] memory out) {
        unchecked {
            out = new bytes32[](n);
            for (uint256 i = 0; i < n; i++) out[i] = _leafCd(off + i * len, len);
        }
    }

    /// starklc hash.js verifyMany: sorted unique indices, the sibling hashes not computable from
    /// the opened leaves, level by level, left to right (proof at calldata `p`, `pn` nodes).
    function _verifyMany(bytes32 root, uint256 depth, uint256[] memory ind, bytes32[] memory leaves, uint256 p, uint256 pn)
        private view returns (bool)
    {
        unchecked {
            uint256 n = ind.length;
            if (n == 0 || n != leaves.length) return false;
            uint256[] memory ci = new uint256[](n);
            bytes32[] memory ch = new bytes32[](n);
            for (uint256 k = 0; k < n; k++) {
                if (ind[k] >= 1 << depth || (k > 0 && ind[k] <= ind[k - 1])) return false;
                ci[k] = ind[k];
                ch[k] = leaves[k];
            }
            uint256 used = 0;
            for (uint256 lvl = 0; lvl < depth; lvl++) {
                uint256 m = 0;
                for (uint256 k = 0; k < n; k++) {
                    uint256 i = ci[k];
                    bytes32 parent;
                    if (i & 1 == 0 && k + 1 < n && ci[k + 1] == i + 1) {
                        parent = _node(ch[k], ch[k + 1]);
                        k++;
                    } else {
                        if (used >= pn) return false;
                        bytes32 sib = bytes32(_w(p + 32 * used));
                        used++;
                        parent = i & 1 == 1 ? _node(sib, ch[k]) : _node(ch[k], sib);
                    }
                    ci[m] = i >> 1;
                    ch[m] = parent;
                    m++;
                }
                n = m;
            }
            return used == pn && n == 1 && ci[0] == 0 && ch[0] == root;
        }
    }

    function _node(bytes32 l, bytes32 r) private view returns (bytes32 h) {
        assembly {
            let fp := mload(0x40)
            mstore8(fp, 1)
            mstore(add(fp, 1), l)
            mstore(add(fp, 33), r)
            if iszero(staticcall(gas(), 2, fp, 65, 0, 32)) { revert(0, 0) }
            h := mload(0)
        }
    }

    function _leafCd(uint256 off, uint256 len) private view returns (bytes32 h) {
        assembly {
            let fp := mload(0x40)
            mstore8(fp, 0)
            calldatacopy(add(fp, 1), off, len)
            if iszero(staticcall(gas(), 2, fp, add(len, 1), 0, 32)) { revert(0, 0) }
            h := mload(0)
        }
    }

    function _digest31(bytes memory tag, uint256 off, uint256 len) private view returns (uint256 d) {
        assembly {
            let fp := mload(0x40)
            let tl := mload(tag)
            mcopy(fp, add(tag, 32), tl)
            calldatacopy(add(fp, tl), off, len)
            if iszero(staticcall(gas(), 2, fp, add(tl, len), 0, 32)) { revert(0, 0) }
            d := shr(8, mload(0))
        }
    }

    // ------------------------------------------------------------------ transcript

    function _absorbMem(V memory v, bytes memory data) private view {
        bytes32 s = v.st;
        bytes32 out;
        assembly {
            let fp := mload(0x40)
            let len := mload(data)
            mstore(fp, s)
            mcopy(add(fp, 32), add(data, 32), len)
            if iszero(staticcall(gas(), 2, fp, add(len, 32), 0, 32)) { revert(0, 0) }
            out := mload(0)
        }
        v.st = out;
        v.ctr = 0;
    }

    function _absorbCd(V memory v, uint256 off, uint256 len) private view {
        bytes32 s = v.st;
        bytes32 out;
        assembly {
            let fp := mload(0x40)
            mstore(fp, s)
            calldatacopy(add(fp, 32), off, len)
            if iszero(staticcall(gas(), 2, fp, add(len, 32), 0, 32)) { revert(0, 0) }
            out := mload(0)
        }
        v.st = out;
        v.ctr = 0;
    }

    function _absorb32(V memory v, bytes32 x) private pure {
        v.st = sha256(abi.encodePacked(v.st, x));
        v.ctr = 0;
    }

    function _squeeze(V memory v) private view returns (uint256 h) {
        bytes32 s = v.st;
        uint256 c = v.ctr;
        assembly {
            let fp := mload(0x40)
            mstore(fp, s)
            mstore(add(fp, 32), shl(224, c))
            if iszero(staticcall(gas(), 2, fp, 36, 0, 32)) { revert(0, 0) }
            h := mload(0)
        }
        v.ctr = c + 1;
    }

    /// A uniform field element: 512 bits reduced mod p.
    function _field(V memory v) private view returns (uint256) {
        uint256 hi = _squeeze(v);
        uint256 lo = _squeeze(v);
        return addmod(mulmod(hi, R256, P), lo % P, P);
    }

    /// A uniform integer in [0, n): 512 bits reduced mod n.
    function _below(V memory v, uint256 n) private view returns (uint256) {
        uint256 hi = _squeeze(v);
        uint256 lo = _squeeze(v);
        uint256 r = addmod(type(uint256).max % n, 1, n);
        return addmod(mulmod(hi, r, n), lo % n, n);
    }

    // ------------------------------------------------------------------ field

    function _sub(uint256 a, uint256 b) private pure returns (uint256) {
        return addmod(a, P - b, P);
    }

    function _pow(uint256 b, uint256 e) private pure returns (uint256 r) {
        unchecked {
            r = 1;
            while (e > 0) {
                if (e & 1 == 1) r = mulmod(r, b, P);
                b = mulmod(b, b, P);
                e >>= 1;
            }
        }
    }

    function _modexp(uint256 b, uint256 e) private view returns (uint256 r) {
        assembly {
            let fp := mload(0x40)
            mstore(fp, 32)
            mstore(add(fp, 32), 32)
            mstore(add(fp, 64), 32)
            mstore(add(fp, 96), b)
            mstore(add(fp, 128), e)
            mstore(add(fp, 160), P)
            if iszero(staticcall(gas(), 5, fp, 192, 0, 32)) { revert(0, 0) }
            r := mload(0)
        }
    }

    function _inv(uint256 a) private view returns (uint256) {
        if (a == 0) revert ProofRejected(6);
        return _modexp(a, P - 2);
    }

    /// A primitive 2^k-th root of unity: 3^((p-1) / 2^k).
    function _root(uint256 k) private view returns (uint256) {
        return _modexp(COSET, (P - 1) >> k);
    }

    /// Montgomery batch inversion in place (zeros are refused).
    function _batchInv(uint256[] memory xs) private view {
        uint256 n = xs.length;
        uint256[] memory pre = new uint256[](n);
        uint256 acc = 1;
        assembly {
            let x := add(xs, 32)
            let q := add(pre, 32)
            for { let i := 0 } lt(i, n) { i := add(i, 1) } {
                mstore(add(q, shl(5, i)), acc)
                acc := mulmod(acc, mload(add(x, shl(5, i))), P)
            }
        }
        uint256 ia = _inv(acc);
        assembly {
            let x := add(xs, 32)
            let q := add(pre, 32)
            for { let i := n } gt(i, 0) { i := sub(i, 1) } {
                let o := shl(5, sub(i, 1))
                let t := mulmod(mload(add(q, o)), ia, P)
                ia := mulmod(ia, mload(add(x, o)), P)
                mstore(add(x, o), t)
            }
        }
    }

    // ------------------------------------------------------------------ small helpers

    function _uniqueMod(uint256[] memory pos, uint256 h) private pure returns (uint256[] memory out) {
        unchecked {
            uint256[] memory tmp = new uint256[](pos.length);
            uint256 n = 0;
            for (uint256 q = 0; q < pos.length; q++) {
                uint256 x = pos[q] % h;
                uint256 i = 0;
                while (i < n && tmp[i] < x) i++;
                if (i < n && tmp[i] == x) continue;
                for (uint256 j = n; j > i; j--) tmp[j] = tmp[j - 1];
                tmp[i] = x;
                n++;
            }
            out = new uint256[](n);
            for (uint256 i = 0; i < n; i++) out[i] = tmp[i];
        }
    }

    function _indexOf(uint256[] memory a, uint256 x) private pure returns (uint256) {
        unchecked {
            for (uint256 i = 0; i < a.length; i++) if (a[i] == x) return i;
            revert ProofRejected(21);
        }
    }

    function _log2(uint256 x) private pure returns (uint256 r) {
        unchecked {
            while (x > 1) { x >>= 1; r++; }
        }
    }

    /// floor(log2(x) * 65536), a lower bound (x > 0).
    function _log2q(uint256 x) private pure returns (uint256 r) {
        unchecked {
            uint256 n = _log2(x);
            r = n << 16;
            uint256 y = n >= 127 ? x >> (n - 127) : x << (127 - n);
            for (uint256 bit = 1 << 15; bit > 0; bit >>= 1) {
                y = (y * y) >> 127;
                if (y >= 1 << 128) { r += bit; y >>= 1; }
            }
        }
    }

    function _u(uint256 off, uint256 nbytes) private pure returns (uint256 v) {
        assembly { v := shr(sub(256, mul(8, nbytes)), calldataload(off)) }
    }

    function _w(uint256 off) private pure returns (uint256 v) {
        assembly { v := calldataload(off) }
    }

    /// A canonical field element at `off` (or ProofRejected(1)).
    function _f(uint256 off) private pure returns (uint256 v) {
        assembly { v := calldataload(off) }
        if (v >= P) revert ProofRejected(1);
    }

    function _cd(uint256 off, uint256 len) private pure returns (bytes memory out) {
        out = new bytes(len);
        assembly { calldatacopy(add(out, 32), off, len) }
    }
}

contracts/TestStable.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestStable: testnet-only stand-in for USDC / USDT on ZETAPHY testnet
/// @notice Worthless by design. Anyone can take 1,000 from the faucet once a
///         day. Real USDC arrives only through the bridge in stage 3.
///         ERC-20 + EIP-2612 permit, 6 decimals like USDC/USDT.
contract TestStable {
    string public name;
    string public symbol;
    uint8 public constant decimals = 6;
    uint256 public constant FAUCET_AMOUNT = 1_000 * 10 ** 6;
    uint256 public constant FAUCET_EVERY = 1 days;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public nonces;
    mapping(address => uint256) public lastFaucet;

    bytes32 public constant PERMIT_TYPEHASH =
        keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)");
    uint256 private immutable _chainId;
    bytes32 private immutable _domain;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory name_, string memory symbol_) {
        name = name_;
        symbol = symbol_;
        _chainId = block.chainid;
        _domain = _buildDomain();
    }

    function faucet() external {
        _drip(msg.sender);
    }

    /// Lets a relay pay the gas for someone who has no ZETAPHY yet.
    function faucetTo(address to) external {
        _drip(to);
    }

    function _drip(address to) private {
        require(to != address(0), "to zero");
        require(block.timestamp >= lastFaucet[to] + FAUCET_EVERY, "faucet: once a day");
        lastFaucet[to] = block.timestamp;
        totalSupply += FAUCET_AMOUNT;
        balanceOf[to] += FAUCET_AMOUNT;
        emit Transfer(address(0), to, FAUCET_AMOUNT);
    }

    function DOMAIN_SEPARATOR() public view returns (bytes32) {
        return block.chainid == _chainId ? _domain : _buildDomain();
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _move(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            require(a >= value, "allowance");
            allowance[from][msg.sender] = a - value;
        }
        _move(from, to, value);
        return true;
    }

    function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
        require(block.timestamp <= deadline, "permit: expired");
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR(),
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))));
        require(uint256(s) <= 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0, "permit: bad s");
        address signer = ecrecover(digest, v, r, s);
        require(signer != address(0) && signer == owner, "permit: bad signature");
        allowance[owner][spender] = value;
        emit Approval(owner, spender, value);
    }

    function _move(address from, address to, uint256 value) private {
        require(to != address(0), "to zero");
        uint256 b = balanceOf[from];
        require(b >= value, "balance");
        unchecked { balanceOf[from] = b - value; }
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _buildDomain() private view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256(bytes(name)), keccak256(bytes("1")), block.chainid, address(this)));
    }
}

contracts/ThreatRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

interface IRunners {
    function workers(address) external view returns (uint128 bond, uint64 unbondAt, bool active, uint32 agreed, uint32 rejected);
}

/// The parts of NeuroIdentity (ERC-8004 identity registry) this registry reads:
/// who has claimed the identity of a target ("eip155:<id>:0x<lowercase hex>").
interface IIdentityOwners {
    function agentOfTarget(bytes32 caip10Hash) external view returns (uint256);
    function ownerOf(uint256 agentId) external view returns (address);
}

/// @title ThreatRegistry: Neuro's immune system (stage 4)
/// @notice A flag here states a reproducible fact about code, not guilt: what
///         the code can do, or did in a reproducible test (Reason), with the
///         evidence that shows it (a Neuro reportHash or the hash of another
///         reproducible report, plus a short URI). Active, bonded NeuroJobs
///         runners with a track record vote to flag a key. At QUORUM distinct
///         votes the key is flagged, and every Neuro instance that reads this
///         registry warns about it, on every chain. A flag is cleared the same
///         way (QUORUM votes to clear).
///
///         Keys:
///           - a code fingerprint (Neuro's fp1: sha256 of the code with
///             addresses/immutables masked), so every copy of the code is found
///           - codeKey(h):         EVM code with extcodehash h on ZETAPHY
///           - addressKey(id, a):  address a on the chain with EVM id `id`
///         voteBatch lets a runner vote on a fingerprint together with the code
///         hashes and addresses it found for it, in one tx (one evidence for the
///         batch); each key still needs its own quorum. BridgeAirlock / BridgeGuard
///         hold (and, once enforced, refuse) flagged sources and recipients, and
///         the ZETAPHY wallet refuses to sign calls to code with an enforced flag.
///
///         Evidence: every flag vote carries one (reportHash != 0, uri at most
///         MAX_URI bytes); every vote's evidence is in its Voted event, and the
///         evidence of the round's first flag vote (the one whose reason the flag
///         shows) is stored: evidenceOf(key).
///
///         Right of reply: the parties behind a key may post responses (at most
///         MAX_RESPONSE bytes each) that wallets show next to the flag, each with
///         its author's address. Responses are kept per (key, author): an author
///         changes or removes (empty text) only its own, never another's; at most
///         MAX_RESPONSES per key (a new author past that replaces the oldest one,
///         never the governance-assigned responder's). responseAt(key, i) lists
///         them: the governance-assigned responder's first, then newest first;
///         responseOf(key) is responseAt(key, 0).
///         Who may answer for a key (respond / appeal, `mayAnswer`):
///           - addressKey(block.chainid, a) for an address a on ZETAPHY: a itself or,
///             for a contract, its current owner();
///           - addressKey(id, a) on any EVM chain (and on ZETAPHY): the owner of
///             the claimed ERC-8004 identity of "eip155:<id>:<a>" in NeuroIdentity
///             (optional: `identity`, zero = off);
///           - codeKey(h) and fp1 keys: ONLY the responder governance assigned to
///             the key (`responder`). Anyone can deploy a contract with the same
///             code and an owner() of their choosing, so code and fingerprint keys
///             have no on-chain owner to ask;
///           - any key: once governance assigned a responder, only it may answer
///             for that key (setResponder(key, 0) gives address keys back to the
///             routes above). Others' existing responses stay until their authors
///             remove them.
///         A response never changes the flag.
///
///         Appeal: whoever may answer for a flagged key (mayAnswer: so for code and
///         fp1 keys only their assigned responder) may appeal(key), paying
///         `appealBond` (appeals are off until governance sets a community fund).
///         That opens an appeal round, voted with voteAppeal, by runners who
///         neither voted for the flag nor backed it (voted/backed of the round that
///         set it, `flagRound`): fresh eyes. The appellant cannot vote in it.
///           - QUORUM appeal votes to clear: the flag is cleared, the bond is
///             refunded, and each runner who set the flag gets a strike
///             (`strikes`, a public record only: see below).
///           - QUORUM appeal votes to keep: the flag stands; the bond goes to the
///             community fund (not to the voters, so reviewers gain nothing by
///             keeping a flag).
///           - Neither within `appealWindow`: anyone may expireAppeal; the bond is
///             refunded (nobody reviewed it: not the appellant's fault).
///           - The flag cleared otherwise meanwhile (the normal clear vote,
///             governance protecting the key): the bond is refunded.
///         Funds are never pushed inside these calls: refunds are credited
///         (`owed`, taken with withdraw) and the fund's share with payFund, so
///         a failing receiver cannot block a vote. payFund pays the last non-zero
///         community fund governance set (`fundPayee`), so turning appeals off
///         (fund = 0) never sends kept bonds to address(0). Strikes slash nothing: the
///         runners' bonds are in NeuroJobs, and an automatic penalty would let a
///         colluding appeal quorum silence honest runners; governance and the
///         runners' tools can read them.
///
///         Checks on the runners (a small quorum must not freeze bridges or wallets):
///           - Warning, hold and enforcement. isFlagged / is*Flagged answer at
///             once (Neuro warns, the wallet shows a warning). is*Held answer true
///             once a flag is `holdDelay` old (a governance knob, e.g. 10 minutes,
///             below enforceDelay), or at once when it is fast (below) or a guardian
///             or governance called holdNow(key). Things that only HOLD (reversible:
///             BridgeAirlock's release, BridgeGuard's inbound queue and outbound)
///             read those, so two runners alone cannot freeze anyone's bridging
///             at once: governance and guardians get holdDelay to look. is*Enforced
///             answer true only once a flag is `enforceDelay` old; everything that
///             REFUSES (BridgeAirlock's ThreatFlagged, NeuroLane watchers, the
///             wallet's refusal) reads those.
///             What ends a hold: the flag cleared (QUORUM clear votes, or an upheld
///             appeal) or governance protecting the key. Nothing else does: a
///             source-chain LockBox has no refund path, so a held transfer waits
///             in BridgeAirlock (and a held mint in BridgeGuard's queue) until then.
///           - Fast lane. A flag is enforced at once (no enforceDelay) when
///             `fastQuorum` distinct runners stand behind it (a supermajority,
///             governance's knob, default 2 x quorum; runners can still add
///             their vote to a flag that is already standing), or when
///             governance or a guardian calls enforceNow(key) (which holds at once
///             too). Clearing (same quorum) or protecting the key lifts it as before.
///           - Protected keys. Governance (the chain's gov module through
///             MsgEVMCall, or a multisig) can protect keys, e.g. the bridge's
///             own contracts and code hashes or a common token's code. A
///             protected key cannot be flagged; protecting a flagged key clears it.
contract ThreatRegistry {
    IRunners public immutable runners;
    uint8 public immutable quorum;
    uint32 public immutable minAgreed; // verdicts a runner must have had accepted to vote

    /// What the code does, or did in a reproducible test. Never a claim about intent.
    enum Reason {
        None,
        CannotSellInSimulation,   // a simulated buy worked, the sell failed or returned almost nothing
        UnlimitedMint,            // an address can mint new tokens without a cap
        OwnerCanBlockTransfers,   // an owner/admin can stop holders from transferring or selling
        OwnerCanMoveHolderFunds,  // an owner/admin can move or burn tokens or funds held by others
        SameNameAsKnownToken,     // same name/symbol as a known token, at a different address
        SweepsApprovedTokens,     // in a test, moved tokens approved to it to an address the holder did not choose
        Other                     // another code fact: see the evidence
    }

    struct Entry {
        bool flagged;
        Reason reason;
        uint64 updatedAt;
        uint32 round;        // bumps on every flag/clear so old votes stop counting
        uint8 votes;
        bool fast;           // enforced at once (fastQuorum or enforceNow)
        uint8 support;       // distinct runners behind the standing flag
        uint64 fastAt;       // when it went fast
    }

    struct Evidence {
        bytes32 reportHash;  // Neuro reportHash, or the hash of another reproducible report
        address by;          // the runner who gave it
        uint64 at;
        string uri;          // where the report can be read (at most MAX_URI bytes)
    }

    struct Response {
        address by;
        uint64 at;
        uint256 chainId;     // the subject answered for (0: a governance-assigned responder)
        address account;
        string text;         // at most MAX_RESPONSE bytes
    }

    struct Appeal {
        address appellant;   // zero: no appeal open
        uint64 openedAt;
        uint32 flagRound;    // the round that set the flag: its voters and backers may not vote
        uint8 clearVotes;
        uint8 keepVotes;
        uint128 bond;
    }

    bytes16 private constant HEX = "0123456789abcdef";
    uint256 public constant MAX_URI = 200;
    uint256 public constant MAX_RESPONSE = 500;
    uint256 public constant MAX_RESPONSES = 8;     // per key
    uint256 public constant MAX_APPEAL_BOND = 1000 ether;
    uint64 public constant MIN_APPEAL_WINDOW = 1 days;
    uint64 public constant MAX_APPEAL_WINDOW = 90 days;

    mapping(bytes32 => Entry) public entries;
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public voted;
    /// Runners who backed a standing flag after it was set (fast lane); kept apart
    /// from `voted`, which stays exactly the quorum that set it (ThreatReports pays those).
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public backed;
    bytes32[] public flaggedList;
    mapping(bytes32 => Evidence) private _evidence;
    /// Flag voters per round (at most quorum each): the runners an upheld appeal strikes.
    mapping(bytes32 => mapping(uint32 => address[])) private _flaggers;

    /// The chain's gov module (MsgEVMCall) or a multisig.
    address public governance;
    /// Seconds a flag waits before the is*Enforced views (which block) report it.
    uint64 public enforceDelay;
    uint64 public constant MAX_ENFORCE_DELAY = 30 days;
    /// Keys governance vouched for: never flagged.
    mapping(bytes32 => bool) public protectedKey;
    /// Distinct flag votes that enforce a standing flag at once (0: off).
    uint8 public fastQuorum;
    /// Guardians (set by governance) may enforceNow / holdNow; they cannot flag, clear or protect.
    mapping(address => bool) public guardian;
    /// Seconds a flag waits before the is*Held views (which hold bridging) report it.
    uint64 public holdDelay;
    /// A guardian's (or governance's) holdNow: the flag's round it holds at once, and when.
    struct HoldNow { uint32 round; uint64 at; }
    mapping(bytes32 => HoldNow) public heldNow;

    // ---- right of reply and appeal ----
    IIdentityOwners public identity;               // zero: the identity route is off
    mapping(bytes32 => address) public responder;  // governance-assigned; exclusive once set
    mapping(bytes32 => mapping(address => Response)) private _responses; // per (key, author)
    mapping(bytes32 => address[]) private _authors;                      // authors with a response, least recently updated first
    uint128 public appealBond;
    uint64 public appealWindow = 14 days;
    address public communityFund;                  // zero: appeals off
    address public fundPayee;                      // the last non-zero communityFund: where payFund sends
    mapping(bytes32 => Appeal) public appeals;
    mapping(bytes32 => uint32) public appealCount; // appeal ids per key, from 1
    mapping(bytes32 => mapping(uint32 => mapping(address => bool))) public appealVoted;
    mapping(address => uint32) public strikes;
    mapping(address => uint256) public owed;       // refunds, taken with withdraw()
    uint256 public fundOwed;                       // the community fund's share, sent with payFund()

    // ---- held pending review: vaccine matches (ImmuneVaccines, docs/future/immune-score.md) ----
    /// The ImmuneVaccines contract (governance sets it; zero: off). It may only HOLD a key pending review
    /// (is*Held), for at most MAX_REVIEW_HOLD, never flag or enforce it, and never a protected key.
    address public vaccines;
    uint64 public constant MAX_REVIEW_HOLD = 14 days;
    struct ReviewHold { bytes32 vaccine; uint64 from; uint64 until; }
    mapping(bytes32 => ReviewHold) public reviewHold;

    event Voted(bytes32 indexed fingerprint, address indexed runner, bool flag, Reason reason, bytes32 reportHash, string uri);
    event Flagged(bytes32 indexed fingerprint, Reason reason);
    event Cleared(bytes32 indexed fingerprint);
    event Protected(bytes32 indexed key, bool on);
    event EnforceDelaySet(uint64 delay);
    event GovernanceSet(address governance);
    event Supported(bytes32 indexed key, address indexed runner, uint8 support, bytes32 reportHash);
    event FastEnforced(bytes32 indexed key, address indexed by);
    event FastQuorumSet(uint8 fastQuorum);
    event GuardianSet(address indexed who, bool on);
    event Responded(bytes32 indexed key, address indexed by, uint256 chainId, address account, string text);
    event ResponderSet(bytes32 indexed key, address responder);
    event IdentitySet(address identity);
    event AppealsSet(uint128 bond, uint64 window, address fund);
    event Appealed(bytes32 indexed key, uint32 indexed id, address indexed appellant, uint128 bond);
    event AppealVoted(bytes32 indexed key, uint32 indexed id, address indexed runner, bool clear, bytes32 reportHash, string uri);
    event AppealClosed(bytes32 indexed key, uint32 indexed id, uint8 outcome); // 1 cleared, 2 kept, 3 expired, 4 flag cleared otherwise
    event Struck(address indexed runner, bytes32 indexed key, uint32 strikes);
    event Paid(address indexed to, uint256 amount);
    event HoldDelaySet(uint64 delay);
    event HeldNow(bytes32 indexed key, address indexed by);
    event VaccinesSet(address vaccines);
    event ReviewHeld(bytes32 indexed key, bytes32 indexed vaccine, uint64 until);
    event ReviewReleased(bytes32 indexed key, address indexed by);

    error NotRunner();
    error AlreadyVoted();
    error NoChange();
    error NotGovernance();
    error ProtectedKey(bytes32 key);
    error NotGuardian();
    error NotFlagged();
    error NoEvidence();
    error TooLong();
    error NotResponder();
    error AppealsOff();
    error BadBond(uint256 bond);
    error AppealOpen();
    error NoAppeal();
    error AppealExpired();
    error NotYet();
    error NotFresh();
    error PayFailed();
    error NoFund();
    error NotVaccines();

    constructor(IRunners runners_, uint8 quorum_, uint32 minAgreed_, address governance_, uint64 enforceDelay_) {
        require(quorum_ >= 2, "quorum");
        require(governance_ != address(0), "governance");
        require(enforceDelay_ <= MAX_ENFORCE_DELAY, "delay");
        runners = runners_;
        quorum = quorum_;
        minAgreed = minAgreed_;
        governance = governance_;
        enforceDelay = enforceDelay_;
        fastQuorum = quorum_ > 127 ? 255 : quorum_ * 2;
        holdDelay = enforceDelay_ >= 20 minutes ? 10 minutes : enforceDelay_ / 2;
    }

    modifier onlyGov() { if (msg.sender != governance) revert NotGovernance(); _; }

    function setGovernance(address g) external onlyGov {
        require(g != address(0), "governance");
        governance = g;
        emit GovernanceSet(g);
    }

    /// Applies to flags already standing too (they are measured from when they were set).
    function setEnforceDelay(uint64 d) external onlyGov {
        require(d <= MAX_ENFORCE_DELAY, "delay");
        require(holdDelay == 0 || d > holdDelay, "holdDelay"); // holds start before enforcement
        enforceDelay = d;
        emit EnforceDelaySet(d);
    }

    /// Seconds before a flag holds bridging (is*Held), unless fast or held now.
    /// Below enforceDelay (or 0: a flag holds at once). Applies to standing flags too.
    function setHoldDelay(uint64 d) external onlyGov {
        require(d == 0 || d < enforceDelay, "holdDelay");
        holdDelay = d;
        emit HoldDelaySet(d);
    }

    /// Fast lane: this many distinct runners behind a flag enforce it at once.
    /// Above quorum (a supermajority), or 0 to turn the fast lane off.
    function setFastQuorum(uint8 f) external onlyGov {
        require(f == 0 || f > quorum, "fastQuorum");
        fastQuorum = f;
        emit FastQuorumSet(f);
    }

    function setGuardian(address who, bool on) external onlyGov {
        guardian[who] = on;
        emit GuardianSet(who, on);
    }

    /// NeuroIdentity, for the identity route of the right of reply (zero: off).
    function setIdentity(IIdentityOwners i) external onlyGov {
        identity = i;
        emit IdentitySet(address(i));
    }

    /// The only party that may answer for `key` (zero: the on-chain routes again).
    function setResponder(bytes32 key, address who) external onlyGov {
        responder[key] = who;
        emit ResponderSet(key, who);
    }

    /// Appeal bond, window and the community fund that keeps bonds of appeals
    /// that confirmed the flag. A zero fund turns appeals off (open ones still
    /// close normally); a new bond applies to new appeals only.
    function setAppeals(uint128 bond, uint64 window, address fund) external onlyGov {
        require(bond <= MAX_APPEAL_BOND, "bond");
        require(window >= MIN_APPEAL_WINDOW && window <= MAX_APPEAL_WINDOW, "window");
        appealBond = bond;
        appealWindow = window;
        communityFund = fund;
        if (fund != address(0)) fundPayee = fund;
        emit AppealsSet(bond, window, fund);
    }

    /// Governance or a guardian enforces a standing flag at once (money moving
    /// now). Only a flag the runners' quorum already set; protected keys can
    /// never be flagged, so never enforced either.
    function enforceNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast) revert NoChange();
        _fast(e, key);
    }

    /// Governance or a guardian holds a standing flag at once (no holdDelay):
    /// bridging of its party stops now, as reversible as any hold. Only a flag
    /// the runners' quorum already set; it ends with the flag (clear / protect).
    function holdNow(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender]) revert NotGuardian();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (e.fast || heldNow[key].round == e.round) revert NoChange();
        heldNow[key] = HoldNow(e.round, uint64(block.timestamp));
        emit HeldNow(key, msg.sender);
    }

    /// Governance names the ImmuneVaccines contract (zero turns review holds off; standing ones run out).
    function setVaccines(address v) external onlyGov {
        vaccines = v;
        emit VaccinesSet(v);
    }

    /// ImmuneVaccines: `key` (a contract whose code matches a confirmed exploit's vaccine) is held pending review
    /// for `duration` (<= MAX_REVIEW_HOLD). A hold only: the is*Held views report it (bridging of that party is
    /// held, reversibly); it never flags and never enforces. Protected keys are never held (false).
    function holdForReview(bytes32 key, bytes32 vaccine, uint64 duration) external returns (bool) {
        if (msg.sender != vaccines || msg.sender == address(0)) revert NotVaccines();
        if (duration == 0 || duration > MAX_REVIEW_HOLD) revert NoChange();
        if (protectedKey[key]) return false;
        uint64 until = uint64(block.timestamp) + duration;
        ReviewHold storage h = reviewHold[key];
        if (h.until > block.timestamp && h.until >= until) return true; // a longer hold stands
        reviewHold[key] = ReviewHold(vaccine, h.until > block.timestamp ? h.from : uint64(block.timestamp), until);
        emit ReviewHeld(key, vaccine, until);
        return true;
    }

    /// The review is done (governance or a guardian looked: nothing to hold), or the vaccine behind it was retired
    /// (ImmuneVaccines). A real problem is FLAGGED by the runners' quorum, as any other.
    function releaseReview(bytes32 key) external {
        if (msg.sender != governance && !guardian[msg.sender] && (msg.sender != vaccines || vaccines == address(0))) revert NotGuardian();
        if (reviewHold[key].until <= block.timestamp) revert NoChange();
        delete reviewHold[key];
        emit ReviewReleased(key, msg.sender);
    }

    /// Is `key` held pending review right now (and by which vaccine, until when)?
    function underReview(bytes32 key) public view returns (bool held, bytes32 vaccine, uint64 until) {
        ReviewHold storage h = reviewHold[key];
        if (h.until <= block.timestamp || protectedKey[key]) return (false, bytes32(0), 0);
        return (true, h.vaccine, h.until);
    }

    function _fast(Entry storage e, bytes32 key) private {
        e.fast = true;
        e.fastAt = uint64(block.timestamp);
        emit FastEnforced(key, msg.sender);
    }

    /// Protect (or unprotect) keys. Protecting clears a flag at once and drops
    /// any votes in progress; unprotecting does not flag anything back.
    function setProtected(bytes32[] calldata keys, bool on) external onlyGov {
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            protectedKey[k] = on;
            emit Protected(k, on);
            if (!on) continue;
            if (reviewHold[k].until != 0) delete reviewHold[k];
            Entry storage e = entries[k];
            if (e.flagged || e.votes != 0) {
                bool was = e.flagged;
                _reset(e, k);
                e.round += 1;
                e.updatedAt = uint64(block.timestamp);
                if (was) emit Cleared(k);
            }
        }
    }

    /// keccak256 of empty code: every account without code has it, so it is never a threat.
    bytes32 public constant EMPTY_CODEHASH = 0xc5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470;

    /// The key under which EVM code with this extcodehash is flagged.
    function codeKey(bytes32 codeHash) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.code", codeHash));
    }

    /// The key under which an address on a given chain (EVM chain id) is flagged.
    function addressKey(uint256 chainId, address who) public pure returns (bytes32) {
        return keccak256(abi.encode("zetaphy.threat.address", chainId, who));
    }

    function _checkRunner() private view {
        (, , bool active, uint32 agreed, uint32 rejected) = runners.workers(msg.sender);
        if (!active || agreed < minAgreed || rejected > agreed) revert NotRunner();
    }

    function _checkEvidence(bool required, bytes32 reportHash, string calldata uri) private pure {
        if (required && reportHash == bytes32(0)) revert NoEvidence();
        if (bytes(uri).length > MAX_URI) revert TooLong();
    }

    /// Vote to flag (flag = true, with a reason and its evidence) or to clear
    /// (flag = false; evidence optional). `fingerprint` is any key: a fp1
    /// fingerprint, codeKey(..) or addressKey(..).
    function vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && protectedKey[fingerprint]) revert ProtectedKey(fingerprint);
        if (!_vote(fingerprint, flag, reason, reportHash, uri)) revert NoChange();
    }

    /// One runner's votes on several keys at once, e.g. a fingerprint plus the
    /// code hashes and addresses of its copies, with one evidence for the batch.
    /// Keys already in that state, or already voted on by this runner this
    /// round, are skipped (not an error), so the same list can be sent again as
    /// copies are found. Protected keys are skipped when flagging. On a key
    /// already flagged, a flag vote adds this runner's support (toward
    /// fastQuorum) once.
    function voteBatch(bytes32[] calldata keys, bool flag, Reason reason, bytes32 reportHash, string calldata uri) external returns (uint256 counted) {
        _checkRunner();
        _checkEvidence(flag, reportHash, uri);
        if (flag && reason == Reason.None) revert NoChange();
        for (uint256 i = 0; i < keys.length; i++) {
            bytes32 k = keys[i];
            Entry storage e = entries[k];
            if (flag && protectedKey[k]) continue;
            if (flag && e.flagged) { if (_support(e, k, reportHash)) counted++; continue; }
            if (e.flagged == flag || voted[k][e.round][msg.sender]) continue;
            _vote(k, flag, reason, reportHash, uri);
            counted++;
        }
        if (counted == 0) revert NoChange();
    }

    /// A flag vote on a standing flag: one more runner behind it (once per
    /// runner, counting the quorum that set it). False when nothing changed.
    function _support(Entry storage e, bytes32 key, bytes32 reportHash) private returns (bool) {
        if (e.fast || e.support == type(uint8).max) return false;
        uint32 r = e.round - 1; // the round that set the flag
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender]) return false;
        backed[key][r][msg.sender] = true;
        e.support += 1;
        emit Supported(key, msg.sender, e.support, reportHash);
        if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, key);
        return true;
    }

    /// The flag (or the votes in progress) is gone: an open appeal ends with its bond refunded.
    function _reset(Entry storage e, bytes32 key) private {
        e.flagged = false;
        e.reason = Reason.None;
        e.votes = 0;
        e.fast = false;
        e.support = 0;
        e.fastAt = 0;
        delete _evidence[key];
        if (appeals[key].appellant != address(0)) _closeAppeal(key, 4);
    }

    function _vote(bytes32 fingerprint, bool flag, Reason reason, bytes32 reportHash, string calldata uri) private returns (bool) {
        Entry storage e = entries[fingerprint];
        if (flag && reason == Reason.None) return false;
        if (flag && e.flagged) {
            if (voted[fingerprint][e.round - 1][msg.sender] || backed[fingerprint][e.round - 1][msg.sender]) revert AlreadyVoted();
            return _support(e, fingerprint, reportHash);
        }
        if (e.flagged == flag) return false;
        if (voted[fingerprint][e.round][msg.sender]) revert AlreadyVoted();
        voted[fingerprint][e.round][msg.sender] = true;
        e.votes += 1;
        if (flag) {
            _flaggers[fingerprint][e.round].push(msg.sender);
            if (e.reason == Reason.None) { // the round's first flag vote: its reason and evidence are what the flag shows
                e.reason = reason;
                _evidence[fingerprint] = Evidence(reportHash, msg.sender, uint64(block.timestamp), uri);
            }
        }
        emit Voted(fingerprint, msg.sender, flag, reason, reportHash, uri);
        if (e.votes >= quorum) {
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            if (flag) {
                e.flagged = true;
                e.support = e.votes;
                e.votes = 0;
                flaggedList.push(fingerprint);
                emit Flagged(fingerprint, e.reason);
                if (fastQuorum != 0 && e.support >= fastQuorum) _fast(e, fingerprint);
            } else {
                _reset(e, fingerprint);
                emit Cleared(fingerprint);
            }
        }
        return true;
    }

    // ---- right of reply ----

    /// "eip155:<chainId>:0x<lowercase hex>", NeuroIdentity's spelling of an EVM target.
    function _caip10(uint256 chainId, address a) private pure returns (bytes memory out) {
        bytes memory digits = new bytes(78);
        uint256 n = 78;
        uint256 v = chainId;
        do { digits[--n] = bytes1(uint8(48 + v % 10)); v /= 10; } while (v != 0);
        bytes memory id = new bytes(78 - n);
        for (uint256 i = 0; i < id.length; i++) id[i] = digits[n + i];
        bytes memory hexa = new bytes(40);
        uint160 x = uint160(a);
        for (uint256 i = 40; i > 0; i--) { hexa[i - 1] = HEX[x & 15]; x >>= 4; }
        out = abi.encodePacked("eip155:", id, ":0x", hexa);
    }

    /// The claimed owner of the identity of `account` on chain `chainId` (zero: none, unclaimed or off).
    function _identityOwner(uint256 chainId, address account) private view returns (address) {
        IIdentityOwners idr = identity;
        if (address(idr) == address(0)) return address(0);
        try idr.agentOfTarget(keccak256(_caip10(chainId, account))) returns (uint256 agentId) {
            if (agentId == 0) return address(0);
            try idr.ownerOf(agentId) returns (address o) { return o == address(idr) ? address(0) : o; } catch { return address(0); }
        } catch { return address(0); }
    }

    /// The `owner()` of a contract on this chain (zero: none).
    function _ownerOf(address a) private view returns (address) {
        if (a.code.length == 0) return address(0);
        (bool ok, bytes memory r) = a.staticcall{gas: 50_000}(abi.encodeWithSignature("owner()"));
        if (!ok || r.length < 32) return address(0);
        uint256 w = abi.decode(r, (uint256));
        return w >> 160 == 0 ? address(uint160(w)) : address(0);
    }

    /// May `who` answer for `key` as the party behind (chainId, account)? (See the notice.)
    /// Code keys and fp1 keys: only their governance-assigned responder.
    function mayAnswer(bytes32 key, uint256 chainId, address account, address who) public view returns (bool) {
        address r = responder[key];
        if (r != address(0) || chainId == 0) return r != address(0) && who == r;
        if (who == address(0) || key != addressKey(chainId, account)) return false;
        if (chainId == block.chainid && (who == account || who == _ownerOf(account))) return true;
        return who == _identityOwner(chainId, account);
    }

    /// Post or replace msg.sender's own response to the flag on `key`, as the
    /// party behind (chainId, account) (see the notice). Empty text removes
    /// msg.sender's own response (always allowed to its author). Never changes the flag.
    function respond(bytes32 key, uint256 chainId, address account, string calldata text) external {
        if (bytes(text).length > MAX_RESPONSE) revert TooLong();
        Response storage cur = _responses[key][msg.sender];
        bool had = cur.by != address(0);
        if (bytes(text).length == 0) {
            if (!had) revert NoChange();
            emit Responded(key, msg.sender, cur.chainId, cur.account, text);
            delete _responses[key][msg.sender];
            _dropAuthor(key, msg.sender);
            return;
        }
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        if (had) _dropAuthor(key, msg.sender);
        else if (_authors[key].length >= MAX_RESPONSES) _evictOldest(key);
        _authors[key].push(msg.sender);
        _responses[key][msg.sender] = Response(msg.sender, uint64(block.timestamp), chainId, account, text);
        emit Responded(key, msg.sender, chainId, account, text);
    }

    function _dropAuthor(bytes32 key, address who) private {
        address[] storage a = _authors[key];
        uint256 n = a.length;
        for (uint256 i = 0; i < n; i++) {
            if (a[i] != who) continue;
            for (uint256 j = i + 1; j < n; j++) a[j - 1] = a[j]; // keep the order
            a.pop();
            return;
        }
    }

    /// Full: the least recently updated response goes, never the assigned responder's.
    function _evictOldest(bytes32 key) private {
        address[] storage a = _authors[key];
        address keep = responder[key];
        for (uint256 i = 0; i < a.length; i++) {
            if (a[i] == keep) continue;
            address old = a[i];
            delete _responses[key][old];
            _dropAuthor(key, old);
            return;
        }
    }

    /// How many responses `key` has (at most MAX_RESPONSES, plus none).
    function responseCount(bytes32 key) external view returns (uint256) {
        return _authors[key].length;
    }

    /// The i-th response to `key`: the governance-assigned responder's first (if
    /// it posted one), then the others newest first. Past the end: all zero.
    function responseAt(bytes32 key, uint256 i) public view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        address[] storage a = _authors[key];
        address r = responder[key];
        bool rFirst = r != address(0) && _responses[key][r].by != address(0);
        address who;
        if (rFirst && i == 0) who = r;
        else {
            uint256 k = rFirst ? i - 1 : i; // index among the others, newest first
            for (uint256 j = a.length; j > 0; j--) {
                if (rFirst && a[j - 1] == r) continue;
                if (k == 0) { who = a[j - 1]; break; }
                k--;
            }
        }
        if (who == address(0)) return ("", address(0), 0, 0, address(0));
        Response storage x = _responses[key][who];
        return (x.text, x.by, x.at, x.chainId, x.account);
    }

    /// The first response (responseAt(key, 0)): the assigned responder's, else the newest.
    function responseOf(bytes32 key) external view returns (string memory text, address by, uint64 at, uint256 chainId, address account) {
        return responseAt(key, 0);
    }

    /// `who`'s own response to `key` (empty: none).
    function responseBy(bytes32 key, address who) external view returns (string memory text, uint64 at, uint256 chainId, address account) {
        Response storage x = _responses[key][who];
        return (x.text, x.at, x.chainId, x.account);
    }

    /// The evidence of the flag on `key` (of the round's first flag vote; while
    /// a flag round is still open, that vote's). Zero when there is none.
    function evidenceOf(bytes32 key) external view returns (bytes32 reportHash, string memory uri, address by, uint64 at) {
        Evidence storage v = _evidence[key];
        return (v.reportHash, v.uri, v.by, v.at);
    }

    // ---- appeal ----

    /// Appeal the standing flag on `key` as the party behind (chainId, account),
    /// paying exactly appealBond. Opens an appeal round (voteAppeal).
    function appeal(bytes32 key, uint256 chainId, address account) external payable returns (uint32 id) {
        if (communityFund == address(0)) revert AppealsOff();
        Entry storage e = entries[key];
        if (!e.flagged) revert NotFlagged();
        if (appeals[key].appellant != address(0)) revert AppealOpen();
        if (msg.value != appealBond) revert BadBond(appealBond);
        if (!mayAnswer(key, chainId, account, msg.sender)) revert NotResponder();
        id = ++appealCount[key];
        appeals[key] = Appeal(msg.sender, uint64(block.timestamp), e.round - 1, 0, 0, uint128(msg.value));
        emit Appealed(key, id, msg.sender, uint128(msg.value));
    }

    /// A fresh runner's vote in the open appeal on `key`: clear the flag (clear =
    /// true) or keep it, with its own evidence (the reproduction it ran).
    /// Runners who voted for or backed the flag, and the appellant, cannot vote.
    function voteAppeal(bytes32 key, bool clear, bytes32 reportHash, string calldata uri) external {
        _checkRunner();
        _checkEvidence(true, reportHash, uri);
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp >= uint256(a.openedAt) + appealWindow) revert AppealExpired();
        uint32 r = a.flagRound;
        if (voted[key][r][msg.sender] || backed[key][r][msg.sender] || msg.sender == a.appellant) revert NotFresh();
        uint32 id = appealCount[key];
        if (appealVoted[key][id][msg.sender]) revert AlreadyVoted();
        appealVoted[key][id][msg.sender] = true;
        emit AppealVoted(key, id, msg.sender, clear, reportHash, uri);
        if (clear) {
            if (++a.clearVotes < quorum) return;
            address[] storage fl = _flaggers[key][r];
            for (uint256 i = 0; i < fl.length; i++) emit Struck(fl[i], key, ++strikes[fl[i]]);
            _closeAppeal(key, 1);
            Entry storage e = entries[key];
            _reset(e, key);
            e.round += 1;
            e.updatedAt = uint64(block.timestamp);
            emit Cleared(key);
        } else if (++a.keepVotes >= quorum) {
            _closeAppeal(key, 2);
        }
    }

    /// Nobody decided within appealWindow: the bond is refunded, the flag stands.
    function expireAppeal(bytes32 key) external {
        Appeal storage a = appeals[key];
        if (a.appellant == address(0)) revert NoAppeal();
        if (block.timestamp < uint256(a.openedAt) + appealWindow) revert NotYet();
        _closeAppeal(key, 3);
    }

    /// outcome 2 (kept): the bond to the community fund; otherwise refunded.
    function _closeAppeal(bytes32 key, uint8 outcome) private {
        Appeal memory a = appeals[key];
        delete appeals[key];
        if (outcome == 2) fundOwed += a.bond;
        else owed[a.appellant] += a.bond;
        emit AppealClosed(key, appealCount[key], outcome);
    }

    /// Take refunded bonds.
    function withdraw() external {
        uint256 amount = owed[msg.sender];
        owed[msg.sender] = 0;
        _pay(msg.sender, amount);
    }

    /// Send kept bonds to the community fund (anyone may call it): the last
    /// non-zero fund governance set, even after appeals were turned off.
    function payFund() external {
        uint256 amount = fundOwed;
        if (amount == 0) return;
        address to = fundPayee;
        if (to == address(0)) revert NoFund();
        fundOwed = 0;
        _pay(to, amount);
    }

    function _pay(address to, uint256 amount) private {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        if (!ok) revert PayFailed();
        emit Paid(to, amount);
    }

    // ---- warning views: true as soon as the quorum flagged (Neuro warns on these) ----

    function isFlagged(bytes32 fingerprint) public view returns (bool, Reason) {
        Entry storage e = entries[fingerprint];
        return (e.flagged, e.reason);
    }

    /// EVM code with this code hash (extcodehash) is flagged. Empty code never is.
    function isCodeFlagged(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isFlagged(codeKey(codeHash));
    }

    function isAddressFlagged(uint256 chainId, address who) public view returns (bool, Reason) {
        return isFlagged(addressKey(chainId, who));
    }

    /// For contracts on this chain: `who` itself is flagged, or the code at it is.
    function isContractFlagged(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressFlagged(block.chainid, who);
        if (f) return (f, r);
        return isCodeFlagged(who.codehash);
    }

    // ---- hold views: true once the flag is holdDelay old, at once through the fast
    //      lane or holdNow (these hold bridging, reversibly) ----

    /// When a standing flag starts to hold (0: not flagged).
    /// A review hold (vaccine match) counts from when it started, while it lasts.
    function heldFrom(bytes32 key) public view returns (uint64 from) {
        Entry storage e = entries[key];
        (bool review, , ) = underReview(key);
        if (!e.flagged) return review ? reviewHold[key].from : 0;
        from = e.updatedAt + holdDelay;
        if (e.fast && e.fastAt < from) from = e.fastAt;
        HoldNow storage h = heldNow[key];
        if (h.round == e.round && h.at < from) from = h.at;
        if (review && reviewHold[key].from < from) from = reviewHold[key].from;
    }

    /// Held: a standing flag past holdDelay (or fast, or holdNow), or a key held pending review (Reason.Other
    /// when only the review holds it).
    function isHeld(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (e.flagged && (e.fast || heldNow[key].round == e.round || block.timestamp >= uint256(e.updatedAt) + holdDelay)) return (true, e.reason);
        (bool review, , ) = underReview(key);
        if (review) return (true, e.flagged ? e.reason : Reason.Other);
        return (false, Reason.None);
    }

    function isCodeHeld(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isHeld(codeKey(codeHash));
    }

    function isAddressHeld(uint256 chainId, address who) public view returns (bool, Reason) {
        return isHeld(addressKey(chainId, who));
    }

    function isContractHeld(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressHeld(block.chainid, who);
        if (f) return (f, r);
        return isCodeHeld(who.codehash);
    }

    // ---- enforcement views: true only once the flag is enforceDelay old, or at once
    //      through the fast lane (these block) ----

    /// When a standing flag starts to be enforced (0: not flagged).
    function enforcedFrom(bytes32 key) public view returns (uint64) {
        Entry storage e = entries[key];
        if (!e.flagged) return 0;
        uint64 normal = e.updatedAt + enforceDelay;
        return e.fast && e.fastAt < normal ? e.fastAt : normal;
    }

    function isEnforced(bytes32 key) public view returns (bool, Reason) {
        Entry storage e = entries[key];
        if (!e.flagged || (!e.fast && block.timestamp < uint256(e.updatedAt) + enforceDelay)) return (false, Reason.None);
        return (true, e.reason);
    }

    function isCodeEnforced(bytes32 codeHash) public view returns (bool, Reason) {
        if (codeHash == bytes32(0) || codeHash == EMPTY_CODEHASH) return (false, Reason.None);
        return isEnforced(codeKey(codeHash));
    }

    function isAddressEnforced(uint256 chainId, address who) public view returns (bool, Reason) {
        return isEnforced(addressKey(chainId, who));
    }

    function isContractEnforced(address who) external view returns (bool, Reason) {
        (bool f, Reason r) = isAddressEnforced(block.chainid, who);
        if (f) return (f, r);
        return isCodeEnforced(who.codehash);
    }

    function flaggedCount() external view returns (uint256) {
        return flaggedList.length;
    }
}
